window.SITE_DATA = Object.assign(window.SITE_DATA || {}, {"symptomDetails":{"auto-repair":{"badge":"부팅","subtitle":"윈도우가 복구 화면으로 계속 돌아오는 경우","intro":["자동 복구 루프는 윈도우가 스스로 문제를 고치려다가 같은 지점에서 다시 멈추는 상태입니다. 화면에는 복구가 진행되는 것처럼 보이지만, 실제로는 부팅 파일, 디스크 상태, 최근 업데이트 중 하나가 막혀 있는 경우가 많습니다.","이 증상은 단순한 소프트웨어 오류처럼 보여도 저장장치 문제와 함께 나타나는 일이 많습니다. 그래서 복구 메뉴를 반복해서 누르기보다, 외장 장치 분리와 부팅 구성 확인을 먼저 하는 편이 효율적입니다.","아래 내용은 어떤 부분을 먼저 확인해야 하는지, 그리고 왜 그 순서로 확인해야 하는지를 함께 설명합니다."],"warnings":["자동 복구 화면이 매번 같은 지점에서 멈춘다.","업데이트 이후부터 시작이 안 된다.","USB, 외장 SSD, SD카드가 꽂혀 있으면 더 자주 실패한다."],"checks":[{"title":"외장 장치부터 분리","why":"외장 저장장치나 USB 허브가 부팅 순서를 흔들거나 복구 환경을 방해할 수 있습니다.","how":"① PC 전원을 끄세요. ② 마우스·키보드를 제외한 모든 USB 장치(외장하드, USB 메모리, 프린터, 카드리더기 등)를 뽑으세요. ③ 이 상태로 PC를 다시 켜세요. ④ 정상적으로 부팅되면 뽑았던 장치를 하나씩만 다시 연결하며 재부팅해 어떤 장치가 복구 루프의 원인인지 찾으세요."},{"title":"복구 메뉴에서 안전 모드 확인","why":"안전 모드가 열리면 윈도우 자체보다 드라이버나 최근 설치 프로그램 쪽 가능성이 높아집니다.","how":"① 자동 복구 화면에서 '고급 옵션'을 클릭하세요. ② '문제 해결' → '고급 옵션' → '시작 설정' → '다시 시작'을 차례로 선택하세요. ③ 재부팅 후 나오는 목록에서 '4' 또는 'F4' 키를 눌러 안전 모드로 진입해보세요. ④ 안전 모드로 정상 진입된다면 Windows 자체는 정상이고 드라이버나 최근 설치 프로그램이 원인일 가능성이 큽니다 — 안전 모드에서 최근 설치한 프로그램을 제거하거나 드라이버를 롤백해보세요. ⑤ 안전 모드로도 진입이 안 된다면 아래 디스크·부팅 정보 점검 항목을 진행하세요."},{"title":"디스크와 부팅 정보 점검","why":"부팅 파일과 저장장치가 모두 정상이어야 자동 복구가 끝까지 진행됩니다.","how":"① 자동 복구 화면에서 '고급 옵션' → '명령 프롬프트'를 선택하세요. ② bootrec /fixmbr 를 입력하고 Enter를 누르세요. ③ 이어서 bootrec /fixboot 를 입력하고 Enter를 누르세요. ④ 이어서 bootrec /rebuildbcd 를 입력하고 Enter를 누르세요(Windows 설치를 찾았다는 메시지가 나오면 Y를 입력). ⑤ 완료 후 chkdsk C: /f 를 입력해 디스크 오류도 함께 확인하세요. ⑥ 명령 프롬프트를 닫고 재부팅해 정상적으로 부팅되는지 확인하세요."},{"title":"최근 변경 내용 되짚기","why":"업데이트 직후나 프로그램 설치 직후라면 원인 추적이 훨씬 빨라집니다.","how":"① 복구 루프가 시작되기 전, 가장 최근에 설치했거나 업데이트한 것이 무엇인지 떠올려보세요(Windows 업데이트, 그래픽 드라이버, 백신 프로그램 등). ② 안전 모드로 진입할 수 있다면, 설정 → Windows Update → 업데이트 기록 → '업데이트 제거'에서 최근 업데이트를 제거해보세요. ③ 최근 설치한 프로그램이 의심된다면 안전 모드에서 '앱 및 기능'을 통해 제거해보세요. ④ 이 정보는 나중에 서비스센터나 전문가에게 문의할 때도 원인을 빠르게 좁히는 데 도움이 됩니다."}],"deeper":[{"heading":"부팅 파일 손상과 업데이트 충돌","text":"자동 복구 루프는 흔히 부팅 파일이 깨졌을 때 보이지만, 실제 현장에서는 업데이트가 끝난 직후에 생기는 경우가 많습니다. 업데이트가 시스템 파일을 건드린 뒤 복구가 반복되면, 같은 화면이 반복되어도 원인은 파일 자체보다 변경 과정일 수 있습니다."},{"heading":"저장장치 오류가 함께 있을 때","text":"디스크가 불안정하면 복구가 시작되더라도 중간에 끊깁니다. SMART 경고, 읽기 오류, 느린 인식이 함께 보이면 윈도우를 다시 설치하기 전에 저장장치를 먼저 점검해야 합니다."}],"decision":[{"heading":"재설치보다 먼저 확인할 것","text":"안전 모드가 열리면 재설치보다 드라이버와 최근 업데이트부터 확인하는 편이 좋습니다. 반대로 안전 모드도 안 들어가면 저장장치와 부팅 파일 쪽 비중을 더 높게 봐야 합니다."},{"heading":"바로 전문가 도움을 고려할 경우","text":"부팅 장치가 불안정하게 잡히거나 SMART 경고가 함께 보이면, 작업을 오래 끌기보다 데이터를 먼저 지키는 방향이 우선입니다."}],"examples":["업데이트 후 재부팅할 때만 복구가 반복됨","외장 SSD를 꽂으면 복구 화면이 더 자주 나타남","안전 모드에만 들어가면 바탕화면까지는 뜸"],"mistakes":["복구 화면만 계속 반복해서 눌러 보는 것","부팅 장치 확인 전에 윈도우 재설치부터 시도하는 것","외장 장치가 꽂힌 상태를 그대로 두는 것"],"faq":[{"q":"바로 재설치해도 되나요?","a":"대부분은 재설치 전에 부팅 파일과 디스크 상태를 먼저 보는 편이 좋습니다. 저장장치 문제라면 재설치 후에도 같은 문제가 반복될 수 있습니다."},{"q":"안전 모드가 열리면 무엇을 봐야 하나요?","a":"최근 설치한 드라이버, 보안 프로그램, 업데이트 기록을 먼저 확인하세요. 이 경우 하드웨어보다 변경 이력이 더 중요한 단서가 됩니다."},{"q":"복구 화면에서 '초기 상태로 되돌리기'를 하면 데이터가 지워지나요?","a":"옵션에 따라 다릅니다. '내 파일 유지'를 선택하면 개인 파일은 남고 앱만 제거되며, '모두 제거'를 선택하면 개인 파일까지 삭제되므로 반드시 확인 후 진행해야 합니다."}]},"bsod-critical-process":{"badge":"블루스크린","subtitle":"부팅 중 중단될 때 원인을 좁히는 페이지","intro":["Critical Process Died는 윈도우가 꼭 필요한 핵심 프로세스를 유지하지 못할 때 나타납니다. 보통은 한 번만 뜨고 끝나지 않고, 재부팅할 때마다 반복되는 경우가 많아 사용자를 가장 불안하게 만드는 증상 중 하나입니다.","원인은 드라이버 충돌, 시스템 파일 손상, 저장장치 오류처럼 서로 겹쳐 보일 수 있습니다. 그래서 단순히 오류 코드만 보는 대신, 최근에 바뀐 부분과 함께 확인해야 실제 원인을 빨리 좁힐 수 있습니다.","이 페이지는 블루스크린이 떴을 때 무엇부터 확인해야 하는지, 그리고 어떤 조합이면 저장장치보다 드라이버 쪽을 먼저 의심해야 하는지 설명합니다."],"warnings":["같은 블루스크린이 부팅마다 반복된다.","업데이트 직후부터 증상이 시작됐다.","안전 모드에서는 조금 더 버틴다."],"checks":[{"title":"최근 드라이버와 보안 프로그램 확인","why":"핵심 프로세스가 종료되는 문제는 드라이버나 커널 훅이 원인일 수 있습니다.","how":"① 블루스크린이 처음 발생한 날짜를 기준으로, 그 무렵 새로 설치했거나 업데이트한 프로그램이 있는지 떠올려 보세요 — 특히 그래픽 드라이버, 메인보드 칩셋 드라이버, 백신·보안 프로그램은 커널(시스템 핵심) 영역에 관여해 블루스크린을 유발하는 대표적인 원인입니다. ② Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행하세요. ③ 왼쪽 트리에서 'Windows 로그' → '시스템'을 클릭하고, 블루스크린이 발생한 시각 근처에 노란색(경고)이나 빨간색(오류) 항목이 있는지 확인하세요 — '원본' 열에 특정 드라이버나 프로그램 이름이 반복해서 보이면 그것이 원인일 가능성이 큽니다. ④ 의심되는 프로그램을 찾았다면 Windows 로고 키를 누르고 '앱 및 기능'을 입력해 들어간 뒤 해당 프로그램을 제거해보고 증상이 재현되는지 확인하세요. ⑤ 최근 설치한 보안 프로그램이 있다면 잠시 사용 중지하거나 제거한 뒤 며칠간 증상이 재현되는지 지켜보세요."},{"title":"디스크 상태와 여유 공간 확인","why":"시스템 파일을 읽지 못하면 같은 블루스크린이 반복됩니다.","how":"① Windows 로고 키를 누르고 '이 PC'를 입력해 실행한 뒤, C 드라이브를 마우스 오른쪽 버튼으로 클릭해 '속성'을 선택하세요. ② 여유 공간이 전체 용량의 10% 미만이라면 공간 부족이 원인일 수 있습니다 — 다운로드 폴더, 휴지통, 사용하지 않는 프로그램을 정리해 공간을 확보하세요. ③ 디스크 자체 손상 여부를 확인하려면 Windows 로고 키를 누르고 'cmd'를 입력한 뒤 검색 결과를 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ④ 명령 프롬프트에 chkdsk C: /f /r 을 입력하고 Enter를 누르세요. 사용 중인 드라이브라 바로 검사할 수 없다는 메시지가 뜨면 Y를 입력하고 Enter를 눌러 다음 재부팅 시 검사를 예약하세요. ⑤ PC를 재부팅하면 파란 화면에서 디스크 검사가 자동으로 진행됩니다(용량에 따라 수십 분 이상 걸릴 수 있으니 검사 중에는 강제 종료하지 마세요). ⑥ SSD라면 제조사의 관리 프로그램(삼성이면 Samsung Magician 등)을 설치해 SSD의 건강 상태(수명, 배드섹터)도 함께 확인하세요."},{"title":"안전 모드에서 재현 여부 확인","why":"안전 모드에서만 버티면 시작 프로그램이나 드라이버 영향이 큽니다.","how":"① Windows 로고 키를 누르고 '설정'을 실행한 뒤 '시스템' → '복구'로 들어가세요. ② '고급 시작'의 '지금 다시 시작'을 클릭하세요. ③ 재부팅 후 나오는 화면에서 '문제 해결' → '고급 옵션' → '시작 설정' → '다시 시작'을 차례로 선택하세요. ④ 다시 뜨는 목록에서 '4' 또는 'F4' 키를 눌러 '안전 모드 사용'으로 부팅하세요. ⑤ 안전 모드는 필수 드라이버와 프로그램만 실행되는 최소 환경입니다. 이 상태에서 며칠간 사용해도 블루스크린이 재현되지 않으면 원인은 특정 드라이버나 시작 프로그램일 가능성이 크고, 안전 모드에서도 그대로 재현된다면 하드웨어(램, 디스크) 쪽 원인을 우선 의심해야 합니다."}],"deeper":[{"heading":"시스템 파일보다 먼저 볼 것","text":"파일 손상만 생각하기 쉽지만, 실제로는 최근 장치 드라이버가 핵심 프로세스와 충돌하는 경우가 많습니다. 특히 그래픽, 저장장치, 네트워크 드라이버가 바뀐 뒤라면 업데이트 복원보다 드라이버 정리가 먼저일 수 있습니다."}],"decision":[{"heading":"같은 코드가 반복될 때","text":"반복되는 코드가 같다면 우연한 충돌보다 특정 드라이버나 저장장치 계열 문제를 먼저 의심하는 편이 맞습니다."},{"heading":"코드가 바뀌어도 불안정할 때","text":"다른 BSOD 코드가 섞여 나오면 메모리와 전원 안정성까지 함께 보는 것이 좋습니다."}],"examples":["게임 실행 뒤 다시 재부팅하면 같은 블루스크린이 뜸","안전 모드에서는 버티지만 일반 부팅에서만 멈춤"],"mistakes":["블루스크린 코드만 보고 바로 재설치하는 것","최근 설치한 보안 프로그램을 빼놓는 것"],"faq":[{"q":"메모리 문제와 어떻게 구분하나요?","a":"메모리 문제는 다른 BSOD 코드와 함께 바뀌어 나타나는 경우가 많고, 블루스크린 자체가 랜덤하게 바뀌기도 합니다. 같은 코드가 반복되면 드라이버나 파일 손상 쪽을 더 먼저 봅니다."},{"q":"블루스크린이 뜬 직후 재부팅하면 저절로 괜찮아지기도 하는데 그냥 둬도 되나요?","a":"한 번으로 끝나지 않고 반복된다면 원인이 남아있는 것이므로, 발생 직후 이벤트 뷰어에서 오류 코드를 기록해 두는 것이 좋습니다."},{"q":"메모리(RAM) 문제인지 어떻게 확인하나요?","a":"Windows 메모리 진단 도구(mdsched.exe)를 실행하면 재부팅 시 자동으로 메모리 검사를 진행할 수 있습니다."}]},"explorer-freeze":{"badge":"탐색기","subtitle":"우클릭과 폴더 열기에서 자주 멈출 때","intro":["탐색기 멈춤은 윈도우 셸이 폴더를 열거나 우클릭 메뉴를 그리는 과정에서 응답을 잃을 때 생깁니다. 파일이 많아서 느린 경우도 있지만, 실제로는 셸 확장, 미리 보기, 네트워크 드라이브 같은 주변 요소가 원인인 경우가 많습니다.","증상이 탐색기에서만 반복된다면 전체 윈도우가 아닌 셸 구성 요소를 먼저 점검하는 것이 좋습니다. 특히 최근 설치한 압축 프로그램, 클라우드 동기화 프로그램, 우클릭 메뉴 추가 도구가 단서가 됩니다.","이 가이드는 폴더 문제와 프로그램 충돌을 구분해 보는 데 초점을 맞춥니다.","원인이 셸 확장인지 아닌지 빠르게 구분하는 방법이 있습니다. Shift를 누른 채 우클릭하면 확장 프로그램이 추가한 항목 없이 기본 메뉴만 뜨는데, 이때는 멈추지 않고 평소처럼 반응한다면 범인은 십중팔구 서드파티 셸 확장입니다. 반대로 Shift+우클릭에서도 똑같이 멈춘다면 탐색기 자체나 시스템 리소스 문제 쪽으로 봐야 합니다."],"warnings":["특정 폴더를 열 때만 멈춘다.","우클릭 메뉴가 뜨기 전에 오래 멈춘다.","미리 보기 창을 켜면 더 느려진다."],"checks":[{"title":"최근 추가한 셸 확장 확인","why":"우클릭 메뉴나 미리 보기 확장은 탐색기와 밀접하게 붙어 있습니다.","how":"① 최근 설치한 압축 프로그램(반디집, 알집 등), 백업 도구, 클라우드 동기화 프로그램(구글 드라이브, 원드라이브 외 추가 설치분), 우클릭 메뉴를 추가하는 유틸리티가 있는지 떠올려 보세요. ② Windows 로고 키를 누르고 '앱 및 기능'을 입력해 들어간 뒤, 설치 날짜순으로 정렬해 최근 설치 항목을 확인하세요. ③ 의심되는 프로그램을 제거한 뒤 재부팅해 탐색기가 정상적으로 동작하는지 확인하세요. ④ 특정 프로그램을 지목하기 어렵다면 파일을 마우스 오른쪽 버튼으로 클릭했을 때 멈추는지, 클릭하지 않을 때는 멈추지 않는지 비교해 우클릭 메뉴 확장 프로그램이 원인인지 좁혀보세요."},{"title":"대용량 폴더와 네트워크 드라이브 분리","why":"느린 경로가 하나만 있어도 전체 탐색기가 멈춘 것처럼 보일 수 있습니다.","how":"① 탐색기가 멈추는 시점이 특정 폴더(파일이 수천 개 이상인 폴더)나 네트워크 드라이브(NAS, 공유폴더)에 들어갈 때인지 확인하세요. ② 해당 네트워크 드라이브의 연결을 끊어보세요 — 파일 탐색기에서 네트워크 드라이브를 마우스 오른쪽 버튼으로 클릭해 '연결 끊기'를 선택합니다. ③ 네트워크 드라이브를 끊은 상태에서 탐색기가 정상적으로 빠르게 동작하면, 네트워크 드라이브의 응답 속도나 연결 상태(공유폴더 접속 오류 등)가 원인입니다. ④ 대용량 폴더가 원인이라면 폴더 안 파일을 하위 폴더로 나눠 정리하거나, 해당 폴더의 '보기' 설정에서 '자세히' 대신 '간단히' 보기로 바꿔 미리 보기 부하를 줄여보세요."},{"title":"썸네일과 미리 보기 확인","why":"이미지나 영상이 많은 폴더는 미리 보기 생성에서 멈추는 경우가 있습니다.","how":"① 파일 탐색기 상단 메뉴에서 '보기' → '미리 보기 창'이 켜져 있다면 꺼보세요(탐색기 창 오른쪽에 파일 내용을 미리 보여주는 패널입니다). ② 이미지나 동영상이 많은 폴더에서 미리 보기 창을 끈 상태로 빠르게 넘어가지는지 비교하세요. ③ 폴더 옵션에서 썸네일 대신 아이콘만 표시하도록 바꾸려면, 파일 탐색기의 '보기' → '옵션' → '폴더 옵션 변경' → '보기' 탭에서 '항상 아이콘 표시, 미리 보기 안 함'에 체크하고 적용하세요. ④ 이 설정 후 멈춤 현상이 사라지면 원인은 이미지·동영상 미리 보기(썸네일) 생성 과정이었던 것으로 확정할 수 있습니다."}],"deeper":[{"heading":"폴더가 아니라 확장 메뉴일 수 있음","text":"같은 폴더라도 우클릭을 할 때만 멈춘다면 파일 자체보다 셸 확장 충돌일 가능성이 높습니다. 탐색기는 정상으로 보이지만, 메뉴를 만드는 확장 프로그램이 뒤에서 시간을 잡아먹는 경우가 있습니다."}],"decision":[{"heading":"특정 폴더만 느릴 때","text":"한 폴더에서만 멈춘다면 셸 확장보다 파일 수, 미리 보기, 네트워크 드라이브 쪽을 먼저 보는 것이 빠릅니다."},{"heading":"우클릭에서만 멈출 때","text":"우클릭 직후에만 멈춘다면 압축 프로그램이나 클라우드 동기화 유틸리티처럼 메뉴를 붙이는 프로그램을 먼저 확인하세요."}],"examples":["특정 폴더에서만 회전 아이콘이 오래 돌아감","오른쪽 클릭 순간 프로그램이 잠시 멈춤"],"mistakes":["파일 개수만 원인으로 단정하는 것","네트워크 드라이브를 계속 연결해 둔 채 확인하는 것"],"faq":[{"q":"재부팅하면 바로 괜찮아지는데 문제 아닌가요?","a":"재부팅 후 잠시 괜찮아지는 것은 셸 확장 충돌에서도 자주 보입니다. 반복된다면 임시 현상으로 넘기지 말고 어떤 폴더나 프로그램에서 시작되는지 봐야 합니다."},{"q":"탐색기가 멈추면 항상 재부팅해야 하나요?","a":"작업 관리자에서 '탐색기' 프로세스만 다시 시작해도 대부분 해결되며, 재부팅 없이 빠르게 복구할 수 있습니다."},{"q":"특정 폴더에서만 멈추는 경우는 원인이 다른가요?","a":"네, 특정 폴더에서만 멈춘다면 해당 폴더 내 파일 인덱싱이나 미리보기 생성 문제일 가능성이 높아 인덱싱 옵션을 점검해야 합니다."}]},"windows-click-unresponsive":{"badge":"Windows 11","subtitle":"부팅 후 몇 분 뒤 마우스는 움직이지만 클릭이 모두 반응하지 않을 때","intro":["마우스 포인터는 움직이고 버튼도 정상적으로 눌리는데, 부팅 후 몇 분이 지나면 창·작업표시줄·바탕화면 어디를 클릭해도 반응하지 않는 증상은 마우스 고장보다 Windows 셸이나 시스템 리소스가 멈춘 경우를 먼저 의심해야 합니다.","작업 관리자나 Ctrl+Alt+Delete 화면이 열리는지에 따라 원인 범위가 달라집니다. 작업 관리자만 열리면 탐색기·특정 프로그램·디스크 지연을 분리할 수 있고, 키보드 단축키까지 모두 반응하지 않으면 저장장치·그래픽 드라이버·메모리·전원 안정성까지 넓혀 확인해야 합니다.","이 증상은 단순히 재부팅하면 잠시 사라질 수 있지만, 같은 시간 뒤 반복된다면 재부팅 직전의 사용률과 이벤트 로그를 남겨야 원인을 놓치지 않습니다. 마우스를 교체해도 동일하다면 입력 장치보다 Windows가 클릭 명령을 처리하는 경로를 확인하는 것이 순서입니다."],"warnings":["마우스 포인터는 움직이지만 모든 창·작업표시줄 클릭이 반응하지 않는다.","Ctrl+Shift+Esc 또는 Ctrl+Alt+Delete는 열리지만 일반 화면만 조작되지 않는다.","부팅 직후에는 정상이고 3~10분 뒤 같은 증상이 반복된다.","멈춘 뒤 디스크 사용률이 100%이거나 팬·저장장치 LED가 계속 바쁘다.","인터넷(Wi-Fi·랜선)이 연결된 상태에서만 재현되고, 연결을 끊으면 멈추지 않는다."],"checks":[{"title":"멈춘 순간 작업 관리자와 단축키 반응 확인","why":"작업 관리자가 열리는지 확인하면 Windows 전체가 멈춘 것인지, 탐색기·특정 프로그램만 멈춘 것인지 나눌 수 있습니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자가 열리는지 확인하세요. ② 열리면 '성능' 탭에서 CPU·메모리·디스크 사용률을 확인하세요. ③ 작업 관리자가 열리지 않으면 Ctrl+Alt+Delete를 눌러 파란 옵션 화면이라도 뜨는지 확인하세요. ④ 이 화면마저 반응하지 않는다면 마우스 클릭 문제가 아니라 시스템 전체가 정지된 상태로 기록하고, 전원 버튼을 4초 이상 눌러 강제 종료 후 재부팅하세요."},{"title":"Windows 탐색기만 다시 시작해 회복되는지 비교","why":"작업표시줄·바탕화면·파일 창은 explorer.exe가 담당하므로 셸만 멈춘 경우 재부팅 없이 회복될 수 있습니다.","how":"① Ctrl+Shift+Esc로 작업 관리자를 여세요(또는 위 방법으로 연 상태 유지). ② '프로세스' 탭에서 'Windows 탐색기'를 찾아 마우스 오른쪽 버튼으로 클릭해 '다시 시작'을 선택하세요. ③ 화면이 잠깐 깜빡이며 작업표시줄·바탕화면이 다시 그려지는지 확인하세요. ④ 이 방법으로 회복된다면 최근 설치한 셸 확장 프로그램(압축 도구, 클라우드 동기화 등), 우클릭 메뉴 추가 프로그램, 미리 보기 구성 요소를 우선 점검하세요."},{"title":"디스크 사용률과 저장장치 이벤트 확인","why":"저장장치 응답 시간이 길어지면 클릭 명령을 처리할 파일·프로필·셸 구성 요소를 읽지 못해 화면 전체가 멈춘 것처럼 보일 수 있습니다.","how":"① 작업 관리자의 '성능' 탭에서 '디스크' 항목을 클릭해 사용률과 '평균 응답 시간'을 확인하세요. ② 응답 시간이 비정상적으로 길다면(수백 ms 이상), Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행한 뒤 'Windows 로그' → '시스템'에서 원본이 'Disk'(이벤트 ID 7, 51, 129, 154), 'Ntfs'(55), 'storport', 'volsnap'으로 표시된 오류가 화면이 멈췄던 시각 근처에 있는지 확인하세요. ③ 이런 오류가 발견되면 디스크 자체의 이상 신호이니, 중요한 파일부터 먼저 다른 저장장치에 백업하세요."},{"title":"그래픽 드라이버 재설정과 오버레이 분리","why":"화면은 보이지만 클릭·창 갱신이 멈추는 경우 DWM·그래픽 드라이버·게임 오버레이 충돌이 입력 처리를 막을 수 있습니다.","how":"① Windows 로고 키 + Ctrl + Shift + B를 동시에 눌렀다가 떼세요(그래픽 드라이버만 재시작하는 단축키입니다). ② 짧은 화면 깜빡임 후 클릭·창 반응이 돌아오는지 확인하세요. ③ Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행한 뒤 'Windows 로그' → '시스템'에서 'Display'(4101), 'nvlddmkm'(153), 'LiveKernelEvent' 항목이 같은 시각에 있는지 확인하세요. ④ 발견되면 그래픽카드 제조사 홈페이지에서 최신 안정 버전 드라이버를 DDU로 클린 재설치하고, Discord·GeForce Experience·Xbox Game Bar 같은 오버레이 프로그램을 꺼둔 상태에서 재현되는지 비교하세요."},{"title":"메모리·커밋과 백그라운드 프로그램 분리","why":"RAM 사용량이 높거나 페이지 파일을 계속 사용하는 프로그램은 일정 시간이 지난 뒤 클릭 지연과 응답 없음으로 이어질 수 있습니다.","how":"① 작업 관리자의 '성능' 탭에서 '메모리' 사용률과 '커밋됨' 수치를 기록하세요. ② 이벤트 뷰어의 'Windows 로그' → '시스템'과 '응용 프로그램'에서 '2004'(Resource-Exhaustion-Detector), 'Application Hang'(1002), 'Application Error'(1000) 항목이 있는지 확인하세요. ③ 브라우저 탭, 게임 런처, 클라우드 동기화·보안 프로그램을 하나씩 종료해가며 어느 것을 껐을 때 증상이 재현되지 않는지 비교하세요."},{"title":"안전 모드와 클린 부팅으로 외부 프로그램 분리","why":"안전 모드에서 같은 시간이 지나도 증상이 없으면 마우스보다 시작 프로그램·서비스·드라이버의 충돌 가능성이 높습니다.","how":"① Windows 로고 키를 누르고 '설정' → '시스템' → '복구' → '지금 다시 시작'으로 안전 모드에 진입하세요(문제 해결 → 고급 옵션 → 시작 설정 → 다시 시작 → F4). ② 안전 모드에서 평소와 같은 시간 동안 사용하며 클릭 멈춤이 재현되는지 확인하세요. ③ 클린 부팅(msconfig 실행 → 서비스 탭 → 'Microsoft 서비스 숨기기' 체크 → 모두 사용 안 함 → 재부팅)으로도 같은 방식으로 비교하세요. ④ 안전 모드에서 정상이라면, 최근 설치한 셸 확장·백신·클라우드·게임 런처·장치 유틸리티를 한 번에 하나씩만 다시 켜며 원인이 되는 프로그램을 찾으세요."},{"title":"인터넷 연결 여부로 재현 여부 확인 후 Secure Boot 업데이트 작업 점검","why":"랜선을 뽑거나 Wi-Fi를 끈 오프라인 상태에서는 멈추지 않고 인터넷에 연결된 상태에서만 3~5분 뒤 멈춘다면, Windows가 주기적으로 실행하는 Secure Boot 인증서 자동 업데이트 작업이 오래된 UEFI 펌웨어에서 계속 실패해 재시도를 반복하는 경우일 수 있습니다. 마이크로소프트가 2026년 공식 문제 해결 가이드로 이 현상을 문서화했습니다.","how":"① 증상이 나타나기 전에 랜선을 뽑거나 Wi-Fi를 꺼서 완전히 오프라인 상태로 만든 뒤, 평소 멈추던 시간(부팅 후 3~5분)이 지나도 정상인지 확인하세요. 오프라인에서는 멈추지 않는다면 이 항목에 해당할 가능성이 큽니다. ② Windows 로고 키를 누르고 '작업 스케줄러'를 입력해 실행하세요. ③ 왼쪽 트리에서 '작업 스케줄러 라이브러리' → 'Microsoft' → 'Windows' → 'PI' 폴더로 이동하세요. ④ 'Secure-Boot-Update' 작업을 클릭하고 하단의 '기록' 탭이나 '마지막 실행 결과' 열에서 오류가 반복되는지 확인하세요. ⑤ PC 또는 메인보드 제조사 홈페이지에서 최신 BIOS/UEFI 펌웨어 업데이트가 있는지 확인하고 설치하세요 — 이것이 근본적인 해결책입니다. ⑥ 당장 펌웨어 업데이트가 어렵다면, 위 작업을 마우스 오른쪽 버튼으로 클릭해 '사용 안 함'으로 임시 비활성화할 수 있지만, 이 경우 Secure Boot 보안 인증서가 최신 상태로 갱신되지 않으므로 임시 조치로만 사용하고 가능한 한 빨리 펌웨어를 업데이트하세요."}],"deeper":[{"heading":"탐색기만 멈춘 경우와 Windows 전체가 멈춘 경우","text":"작업 관리자에서 탐색기만 다시 시작해 회복되면 Windows 셸 문제에 가깝습니다. 반대로 작업 관리자·Ctrl+Alt+Delete·키보드 단축키까지 반응하지 않으면 저장장치 I/O, 그래픽 드라이버, 메모리, 전원 안정성을 함께 확인해야 합니다."},{"heading":"마우스를 바꿔도 같은 이유","text":"다른 마우스에서도 동일하고 포인터 이동은 정상이라면 센서·스위치·USB 포트보다는 클릭 메시지를 받는 Explorer, DWM, 프로그램 창이 응답하지 않는 상태일 가능성이 큽니다. 다른 마우스 테스트는 입력 장치 배제에는 도움이 되지만 시스템 원인을 해결하지는 않습니다."},{"heading":"이벤트 하나만으로 부품을 교체하지 않기","text":"Application Hang 1002는 응답 없음이 기록됐다는 뜻이지 저장장치나 RAM 고장을 확정하지 않습니다. Disk 오류·Display 오류·WHEA·메모리 부족 기록이 같은 시간에 반복되는지 시간대를 맞춰 보아야 합니다."},{"heading":"인터넷 연결 시에만 멈추는 이유 — Secure Boot 인증서 자동 갱신","text":"Windows는 부팅 시와 이후 12시간마다 'Secure-Boot-Update'라는 예약 작업을 실행해 Secure Boot에 필요한 보안 인증서를 최신 상태로 유지합니다. 이 작업이 실행되려면 온라인 상태에서 업데이트 서버와 통신해야 하는데, 오래된 UEFI 펌웨어를 쓰는 일부 구형 PC에서는 인증서 갱신 절차가 계속 실패하면서 같은 작업을 반복 재시도하다가 시스템 자원을 붙잡아 일시적으로 멈추는 것처럼 보일 수 있습니다. 오프라인 상태에서는 이 작업이 업데이트를 시도하지 않아 증상이 재현되지 않는 것이 특징이며, 마이크로소프트가 공식 문제 해결 가이드(KB5085046)로 이 메커니즘을 문서화했습니다."}],"decision":[{"heading":"탐색기 재시작 후 바로 회복될 때","text":"셸 확장·클라우드 동기화·미리 보기·네트워크 드라이브를 우선 의심합니다. windows-explorer-freeze 가이드의 우클릭 메뉴와 폴더 분리 점검을 이어서 진행하세요."},{"heading":"디스크 사용률 100% 또는 Disk 오류가 있을 때","text":"재설치보다 중요한 파일 백업, SMART 상태, SATA·NVMe 연결과 저장장치 펌웨어 확인이 먼저입니다. Disk 154가 반복되면 복구 명령을 반복하기 전에 데이터 보호를 우선하세요."},{"heading":"화면만 멈추거나 Win+Ctrl+Shift+B로 회복될 때","text":"그래픽 드라이버·GPU 온도·보조전원·오버레이 충돌을 우선 확인합니다. 게임 중에만 나타나면 다른 게임과 일반 작업에서도 재현되는지 비교해 하드웨어와 게임 설정을 나눕니다."},{"heading":"단축키도 반응하지 않고 강제 재부팅이 필요할 때","text":"재부팅 후 Kernel-Power 41이나 EventLog 6008이 남는지 확인하고, WHEA·Disk·Display 오류가 직전 시간대에 있었는지 분석합니다. 반복되면 전원·발열·메모리·저장장치 점검을 함께 진행하세요."}],"examples":["부팅 후 5분 정도는 정상인데 파일 창과 작업표시줄 클릭이 모두 멈춤","마우스 포인터는 움직이고 Ctrl+Shift+Esc는 열리지만 바탕화면만 조작되지 않음","디스크 사용률 100%와 Disk 154가 같은 시간에 반복됨","게임 종료 또는 화면 전환 뒤 클릭이 멈추고 Display 4101 또는 nvlddmkm 153이 기록됨","인터넷에 연결된 상태에서만 부팅 후 3~5분 뒤 멈추고, 랜선을 뽑으면 재현되지 않음(구형 PC의 Secure Boot 업데이트 작업)"],"mistakes":["다른 마우스까지 바꿔 본 뒤에도 입력 장치만 계속 교체하는 것","작업 관리자에서 디스크 응답 시간은 보지 않고 사용률만 확인하는 것","Kernel-Power 41 하나만 보고 곧바로 파워서플라이를 교체하는 것","중요 파일 백업 전에 강제 종료와 복구 명령을 반복하는 것","안전 모드·클린 부팅 비교 없이 여러 드라이버와 프로그램을 한꺼번에 바꾸는 것"],"faq":[{"q":"마우스 포인터는 움직이는데 클릭만 안 되면 마우스 고장 아닌가요?","a":"다른 마우스에서도 동일하고 포인터 이동이 정상이라면 마우스보다는 Explorer·DWM·프로그램 창이 클릭 명령을 처리하지 못하는 상태를 먼저 확인하는 것이 좋습니다."},{"q":"재부팅하면 당장은 괜찮아지는데 그냥 사용해도 되나요?","a":"재부팅으로 메모리·셸·드라이버 상태가 초기화된 것일 수 있습니다. 같은 시간이 지난 뒤 반복된다면 증상 시각의 사용률과 이벤트 로그를 저장해 원인을 확인해야 합니다."},{"q":"어떤 이벤트가 가장 중요합니까?","a":"Application Hang 1002는 응답 없음의 기록이고, Disk 154·Display 4101·nvlddmkm 153·WHEA 오류가 같은 시간에 반복되면 저장장치·그래픽·하드웨어 안정성을 더 우선적으로 점검합니다."},{"q":"인터넷을 연결하면 멈추고 끊으면 멈추지 않아요. 랜선 문제인가요?","a":"랜선·와이파이 자체의 고장이 아니라, Windows가 온라인 상태에서만 실행하는 'Secure-Boot-Update' 예약 작업이 오래된 UEFI 펌웨어에서 반복 실패하는 것이 원인일 수 있습니다. 작업 스케줄러에서 이 작업의 실행 기록을 확인하고, PC·메인보드 제조사 홈페이지에서 최신 BIOS/UEFI 펌웨어로 업데이트하는 것이 근본적인 해결책입니다."}]},"printer-add-freeze":{"badge":"프린터","subtitle":"장치 추가 단계가 끝까지 안 갈 때","intro":["프린터 추가 멈춤은 드라이버 설치, 스풀러 서비스, 네트워크 설정이 서로 맞물려 있을 때 자주 생깁니다. 프린터 자체가 아니라 주변 소프트웨어가 멈추는 경우도 많아서 원인이 하나로 보이지 않을 수 있습니다.","특히 회사용 프린터, 무선 프린터, 오래된 제조사 드라이버는 설치 방식 차이 때문에 더 잘 꼬입니다. 그래서 먼저 연결 방식과 기존 장치 정리 여부를 확인해야 합니다.","이 페이지는 프린터를 새로 추가할 때 어디서 막히는지 기준을 나눠 볼 수 있게 구성했습니다."],"warnings":["장치 찾기 화면에서 오래 멈춘다.","같은 프린터를 여러 번 추가하려고 했다.","네트워크 프린터만 유독 안 된다."],"checks":[{"title":"제조사 드라이버부터 확인","why":"기본 드라이버보다 제조사 패키지가 필요한 모델이 있습니다.","how":"① 프린터 뒷면이나 밑면 스티커에서 정확한 모델명을 확인하세요. ② 웹 브라우저에서 '(모델명) 드라이버'로 검색해 제조사(HP, Canon, Epson, 삼성 등) 공식 홈페이지의 다운로드 페이지로 들어가세요. ③ 사용 중인 Windows 버전(10 또는 11)에 맞는 최신 드라이버 설치 파일을 내려받으세요. ④ Windows 기본 '장치 추가' 기능으로 먼저 시도하지 말고, 내려받은 제조사 설치 파일을 실행해 안내에 따라 설치하세요 — 특히 복합기(프린터+스캐너)나 무선 프린터는 제조사 설치 파일이 훨씬 안정적입니다."},{"title":"기존 장치와 스풀러 상태 점검","why":"오래된 프린터 항목이 남아 있으면 추가 단계에서 충돌이 납니다.","how":"① Windows 로고 키를 누르고 '설정'을 실행한 뒤 '블루투스 및 장치' → '프린터 및 스캐너'로 들어가세요. ② 같은 프린터의 오래된 항목이나 '오프라인'으로 표시된 항목이 남아 있다면 클릭해 '제거'를 선택하세요. ③ Windows 로고 키를 누르고 'services.msc'를 입력해 실행하세요. ④ 목록에서 'Print Spooler'를 찾아 더블클릭한 뒤 상태가 '중지됨'이면 '시작'을 클릭하고, 이미 실행 중이면 '중지' 후 다시 '시작'을 눌러 재시작하세요. ⑤ 이후 프린터 추가를 다시 시도하세요."},{"title":"연결 방식 변경","why":"무선 연결이 꼬였는지, USB 연결이 꼬였는지를 구분할 수 있습니다.","how":"① 지금 무선(Wi-Fi)으로 연결을 시도하고 있다면, USB 케이블로 PC와 프린터를 직접 연결해 인식되는지 시험해보세요. ② 반대로 USB로 시도해서 안 된다면, 프린터의 네트워크 설정 메뉴에서 같은 Wi-Fi에 연결한 뒤 무선으로 추가를 시도하세요. ③ 한쪽 방식에서는 정상적으로 인식되고 다른 쪽에서만 안 된다면, 문제가 없는 연결 방식을 우선 사용하고 안 되는 쪽은 케이블 상태나 공유기 설정을 별도로 점검하세요."}],"deeper":[{"heading":"드라이버와 장치 목록이 꼬일 때","text":"프린터는 같은 장치라도 드라이버와 포트가 달라지면 다른 장치처럼 취급됩니다. 그래서 추가가 멈출 때는 본체보다 남아 있는 이전 항목, 포트 설정, 스풀러를 먼저 보는 것이 빠릅니다."}],"decision":[{"heading":"USB는 되는데 네트워크가 안 될 때","text":"유선이나 무선 경로만 문제라면 장치 자체보다 네트워크 등록, 포트, 스풀러를 우선 확인하는 것이 좋습니다."},{"heading":"장치 목록이 계속 남을 때","text":"삭제해도 같은 프린터가 다시 나타난다면 이전 드라이버와 포트를 정리한 뒤 다시 추가해 보세요."}],"examples":["같은 프린터를 삭제해도 다시 추가가 안 됨","무선 프린터 검색에서 계속 멈춤"],"mistakes":["프린터 전원만 여러 번 껐다 켜는 것","드라이버 파일만 다시 받으면 끝난다고 보는 것"],"faq":[{"q":"USB 연결로는 되는데 무선 연결만 안 됩니다.","a":"무선 네트워크 설정이나 포트 등록 문제일 가능성이 높습니다. 장치 자체보다 연결 경로를 먼저 점검하세요."},{"q":"프린터 드라이버를 재설치하면 기존 설정이 사라지나요?","a":"네, 재설치 시 용지함·품질 설정 등 커스텀 설정은 초기화되므로 재설치 전 설정값을 메모해두는 것이 좋습니다."},{"q":"무선 프린터와 유선 프린터는 점검 방법이 다른가요?","a":"무선 프린터는 네트워크 연결 상태를 먼저 확인해야 하고, 유선 프린터는 USB 포트나 케이블 손상 여부를 우선 점검해야 합니다."}]},"gaming-reboot":{"badge":"전원","subtitle":"게임처럼 부하가 걸릴 때만 재부팅될 때","intro":["게임 중 재부팅은 부하가 올라갈 때만 문제를 드러내는 대표적인 증상입니다. 평소에는 멀쩡해 보여도 전원 공급, 온도, 그래픽 드라이버가 한계에 닿으면 갑자기 꺼질 수 있습니다.","이 증상은 소프트웨어보다 하드웨어 신호가 더 강하게 드러나는 편이라, 온도와 파워 용량을 먼저 보는 것이 중요합니다. 특히 업그레이드 이후 시작됐다면 전원과 쿨링 설계를 함께 확인해야 합니다.","아래 항목은 재부팅이 반복되는 원인을 체계적으로 나눠 보는 데 도움이 됩니다.","파워 서플라이는 겉보기에 멀쩡해도 사용 연차가 오래될수록 순간적으로 높은 전력을 요구하는 상황(그래픽카드 부하가 치솟는 순간)에서 전압을 안정적으로 유지하지 못하는 경우가 있습니다. 이런 열화는 평소 사용에는 티가 안 나다가 게임처럼 순간 부하가 큰 작업에서만 드러나기 때문에, 파워가 산 지 3~4년이 넘었다면 정격 용량이 충분해 보여도 노후화 자체를 의심해볼 필요가 있습니다."],"warnings":["게임 실행 직후 또는 몇 분 뒤에만 재부팅된다.","오버클럭을 켜면 더 빨리 꺼진다.","팬 소음과 발열이 급격히 올라간다."],"checks":[{"title":"온도와 전력부터 확인","why":"부하 상황에서만 꺼진다면 발열과 전원 부족 가능성이 큽니다.","how":"① HWiNFO 같은 무료 모니터링 프로그램을 설치해 게임을 실행하며 CPU와 GPU 온도를 지켜보세요. ② 재부팅되는 순간의 온도가 CPU 95도, GPU 90도 이상까지 치솟았는지 확인하세요. ③ 케이스 옆판을 열고 파워서플라이의 정격 출력(W)을 확인해, 사용 중인 CPU·그래픽카드가 요구하는 권장 용량 이상인지 비교하세요. ④ 그래픽카드에 연결된 6핀/8핀 보조전원 케이블이 완전히 꽂혔는지 다시 확인하세요."},{"title":"그래픽 드라이버 재설치","why":"화면 출력 장치가 멈추면 시스템이 전체 재부팅으로 이어질 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정' → '시스템' → '복구'에서 안전 모드로 재부팅하세요(고급 시작 → 지금 다시 시작 → 문제 해결 → 고급 옵션 → 시작 설정 → 다시 시작 → F4). ② 안전 모드에서 'Display Driver Uninstaller(DDU)' 프로그램을 실행해 기존 그래픽 드라이버를 완전히 제거하세요. ③ 재부팅 후 그래픽카드 제조사(NVIDIA/AMD) 공식 홈페이지에서 '안정(Stable/WHQL)' 버전으로 표시된 드라이버를 내려받아 설치하세요(최신 '베타' 버전은 피하세요). ④ 게임을 다시 실행해 재부팅 현상이 사라졌는지 확인하세요."},{"title":"오버클럭/튜닝 해제","why":"불안정한 전압이나 메모리 세팅이 원인일 수 있습니다.","how":"① PC를 재부팅하며 부팅 직후 Delete 또는 F2 키를 연타해 BIOS 화면으로 들어가세요. ② 'Ai Tweaker', 'OC', 'Extreme Tweaker' 등의 메뉴에서 XMP 또는 EXPO 프로파일이 켜져 있다면 'Auto' 또는 'Disabled'로 되돌리세요. ③ CPU나 그래픽카드를 오버클럭하는 별도 프로그램(MSI 애프터버너 등)을 쓰고 있다면 실행해 모든 값을 기본값으로 초기화하세요. ④ 저장 후 재부팅하고 같은 게임을 실행해 재부팅 현상이 줄어드는지 확인하세요."}],"deeper":[{"heading":"게임에서만 멈추는 이유","text":"게임은 CPU, GPU, 메모리, 디스크를 동시에 많이 씁니다. 평소에는 괜찮다가 게임에서만 꺼진다면, 단순 윈도우 문제가 아니라 전력부족이나 냉각 한계가 드러난 것일 수 있습니다."}],"decision":[{"heading":"오버클럭이 켜져 있다면","text":"오버클럭 상태에서만 재부팅된다면 먼저 기본값으로 돌려 안정성부터 확인해야 합니다."},{"heading":"온도는 정상인데 꺼진다면","text":"온도보다 전원 공급이 더 의심되며, 파워 용량과 보조전원 연결 상태를 더 봐야 합니다."}],"examples":["게임 로딩 화면에서 갑자기 꺼짐","부하가 높아질수록 재부팅 빈도 증가"],"mistakes":["게임만 삭제하고 끝내는 것","전원부와 쿨링을 확인하지 않는 것"],"faq":[{"q":"데스크톱인데도 전원 부족이 있나요?","a":"있습니다. 파워 용량이 부족하거나 노후되었거나, 그래픽카드 보조전원이 불안정하면 같은 증상이 날 수 있습니다."},{"q":"재부팅 없이 화면만 꺼졌다가 돌아오는 것도 같은 원인인가요?","a":"전원 공급 문제보다는 그래픽 드라이버 크래시일 가능성이 높으며, 이벤트 뷰어에서 그래픽 드라이버 관련 오류를 확인해야 합니다."},{"q":"그래픽카드를 바꾸지 않고도 확인할 수 있는 방법이 있나요?","a":"전원 공급 장치(PSU)의 여유 용량과 케이블 연결 상태를 먼저 확인하는 것이 비용 없이 점검할 수 있는 방법입니다."}]},"game-lag-fps-drop":{"badge":"게임 성능","subtitle":"재부팅·다운 없이 프레임만 떨어질 때","intro":["게임 렉·프레임 드랍은 재부팅이나 블루스크린과 달리 시스템은 계속 켜져 있고 게임도 종료되지 않은 채 순간적으로 버벅이거나 프레임이 뚝 떨어지는 증상입니다. 원인이 완전히 달라 게임 중 재부팅되는 경우와 구분해서 접근해야 합니다.","가장 먼저 볼 것은 '항상 그런지, 특정 상황에서만 그런지'입니다. 특정 구간이나 특정 게임에서만 반복된다면 그 게임의 최적화 문제일 가능성이 크고, 여러 게임에서 공통으로 나타난다면 드라이버나 백그라운드 프로그램, 발열 쪽을 먼저 봐야 합니다.","온도가 정상인데도 반복된다면 서멀 스로틀링보다는 드라이버나 백그라운드 프로세스 문제일 가능성이 더 높습니다.","프레임 드랍이 그래픽카드 때문인지 CPU 때문인지는 작업 관리자의 성능 탭만으로도 어느 정도 구분할 수 있습니다. 렉이 발생하는 순간 GPU 사용률이 거의 100%에 붙어 있다면 그래픽 설정을 낮추는 것이 직접적인 해결책이고, 반대로 GPU는 여유가 있는데 특정 코어 하나만 100%에 붙어 있다면 게임 자체의 최적화나 백그라운드 프로세스 문제일 가능성이 커 그래픽 설정을 낮춰도 큰 효과가 없을 수 있습니다."],"warnings":["특정 장면이나 특정 시간대에만 순간적으로 프레임이 뚝 떨어진다.","여러 게임에서 공통으로 버벅임이 느껴진다.","재부팅이나 블루스크린 없이 게임만 계속 불안정하다."],"checks":[{"title":"CPU·GPU 사용률·온도 확인","why":"어느 부품이 병목인지, 온도로 인한 스로틀링인지 구분하는 첫 단서입니다.","how":"① 웹 브라우저에서 'HWiNFO' 공식 홈페이지에 접속해 무료 프로그램을 내려받아 설치하세요(또는 Ctrl+Shift+Esc로 작업 관리자를 열어도 기본적인 확인은 가능합니다). ② 게임을 실행하고 프레임이 떨어지는 구간에서 CPU와 GPU 각각의 사용률(%)과 온도를 확인하세요. ③ 둘 중 한쪽만 100%에 가깝다면 그 부품이 병목(성능을 제한하는 원인)입니다. ④ 온도가 CPU 95도, GPU 85~90도 이상으로 치솟은 상태에서 프레임이 떨어진다면 과열로 인한 성능 제한(스로틀링)을 의심하세요."},{"title":"그래픽 드라이버 재설치","why":"손상되거나 오래된 드라이버는 정상 사양에서도 프레임 저하를 일으킬 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정' → '시스템' → '복구'에서 안전 모드로 진입하세요(문제 해결 → 고급 옵션 → 시작 설정 → 다시 시작 → F4). ② 안전 모드에서 'Display Driver Uninstaller(DDU)' 프로그램을 실행해 그래픽 드라이버를 완전히 제거하세요. ③ 재부팅 후 그래픽카드 제조사(NVIDIA/AMD) 공식 홈페이지에서 최신 '안정(Stable)' 버전 드라이버를 내려받아 설치하세요. ④ 게임을 다시 실행해 프레임이 개선됐는지 확인하세요."},{"title":"전원 옵션·전원 관리 모드 확인","why":"절전 위주 설정이면 부하가 걸려도 성능이 자동으로 제한됩니다.","how":"① Windows 로고 키를 누르고 '전원 모드'를 입력해 실행한 뒤 '균형' 또는 '최고의 성능'으로 설정하세요. ② 바탕화면을 우클릭해 'NVIDIA 제어판'(또는 'AMD Software')을 여세요. ③ NVIDIA라면 '3D 설정 관리' → '전원 관리 모드'를 '최대 성능 선호'로 바꾸세요. ④ AMD라면 '성능' 탭에서 전원 설정을 '고성능'으로 바꾸세요. ⑤ 게임을 다시 실행해 프레임이 개선됐는지 확인하세요."},{"title":"백그라운드 프로그램 정리","why":"오버레이·동기화 프로그램이 게임과 자원을 나눠 쓰면서 순간적인 버벅임을 유발할 수 있습니다.","how":"① 게임을 실행하기 전에 Discord, 브라우저, 클라우드 동기화 프로그램(원드라이브, 구글 드라이브 등)을 모두 종료하세요. ② Discord를 계속 쓴다면 설정 → '오버레이'에서 인게임 오버레이를 꺼보세요. ③ 이 상태에서 같은 구간을 플레이해 버벅임이 줄었는지 비교하세요. ④ 특정 프로그램을 껐을 때 확실히 개선된다면 그 프로그램이 원인이므로, 게임할 때는 미리 종료하는 습관을 들이세요."},{"title":"AMD X3D CPU라면 코어 스케줄링 확인","why":"7900X3D·7950X3D·9900X3D·9950X3D처럼 CCD 두 개 중 하나에만 3D V-Cache가 달린 듀얼 CCD CPU는 Windows가 게임 스레드를 캐시 없는 CCD로 잘못 배정하면 사양과 무관하게 프레임이 뚝뚝 끊깁니다. 7800X3D·9800X3D처럼 CCD가 하나뿐인 X3D는 이 문제에 해당하지 않습니다. 최상급 그래픽카드를 쓰는데도 원인을 못 찾을 때 특히 의심해야 합니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행한 뒤 '시스템 장치'에서 'AMD' 관련 항목을 확인하거나, AMD 공식 홈페이지에서 최신 칩셋 드라이버를 내려받아 설치하세요. ② Windows 로고 키를 누르고 '서비스'를 입력해 실행한 뒤 '3D V-Cache Performance Optimizer' 서비스를 찾아 '시작됨(실행 중)' 상태인지 확인하세요. ③ Xbox Game Bar를 꺼뒀다면(설정 → 게임 → Xbox Game Bar) 다시 켜세요 — 이 기능이 꺼져 있으면 Windows가 게임을 인식하지 못해 코어 배정이 잘못될 수 있습니다. ④ 설정 후 재부팅하고 게임을 다시 실행해 프레임 끊김이 줄었는지 확인하세요."}],"deeper":[{"heading":"특정 게임만 vs 여러 게임 공통","text":"특정 게임에서만 반복된다면 그 게임의 설정이나 최적화 패치 문제일 가능성이 크고, 여러 게임에서 공통으로 나타난다면 드라이버·백그라운드·발열처럼 시스템 전체에 걸친 원인을 먼저 봐야 합니다."},{"heading":"온도는 정상인데 반복될 때","text":"서멀 스로틀링이 아니라면 드라이버 손상이나 백그라운드 프로세스가 순간적으로 자원을 점유했을 가능성이 더 높습니다. 이벤트 뷰어에서 같은 시각에 다른 프로세스가 실행됐는지 확인해보세요."},{"heading":"사양은 최상급인데 원인을 못 찾을 때","text":"그래픽카드·CPU 모두 상위 라인인데도 특정 게임에서 프레임이 반복해서 떨어진다면 부품 자체보다 AMD X3D CPU의 듀얼 CCD 구조를 의심해볼 차례입니다. 게임 스레드가 V-Cache 없는 CCD로 배정되면 체감 성능이 눈에 띄게 떨어지며, 이는 사양 문제가 아니라 스케줄링 문제라 부품을 바꿔도 해결되지 않습니다."}],"decision":[{"heading":"온도가 높게 유지될 때","text":"쿨링 상태를 먼저 점검하고, 그래도 반복되면 그래픽 옵션을 낮춰 부하 자체를 줄여보세요."},{"heading":"온도는 정상인데 반복될 때","text":"드라이버 재설치와 백그라운드 프로그램 정리를 우선 시도하세요."},{"heading":"특정 게임에서만 반복될 때","text":"그 게임의 설정·커뮤니티에서 알려진 최적화 방법을 먼저 확인하세요."}],"examples":["평소엔 괜찮다가 특정 맵이나 전투 장면에서만 프레임이 뚝 떨어짐","여러 게임에서 공통으로 순간적인 버벅임이 반복됨"],"mistakes":["재부팅·다운되는 증상과 같은 원인으로 단정하는 것","원인 구분 없이 그래픽 옵션만 계속 낮추는 것","온도가 정상인데도 무조건 쿨링 문제로 단정하는 것"],"faq":[{"q":"특정 게임에서만 렉이 걸려요.","a":"그 게임의 설정이나 최적화 패치 문제일 가능성이 큽니다. 다른 게임에서도 같은 증상이 나타나는지 먼저 비교해보세요."},{"q":"온도는 정상인데도 프레임이 떨어져요.","a":"서멀 스로틀링보다는 그래픽 드라이버 손상이나 백그라운드 프로그램이 원인일 가능성이 더 높습니다."},{"q":"노트북인데 전원을 연결해도 렉이 걸려요.","a":"일부 노트북은 배터리 사용 중 전원 관리 모드가 자동으로 절전으로 바뀝니다. 전원 연결 상태에서도 전원 옵션이 고성능인지 다시 확인하세요."},{"q":"사양이 확실히 충분한데도 특정 게임에서만 프레임이 떨어져요.","a":"7900X3D·7950X3D·9900X3D·9950X3D 같은 AMD 듀얼 CCD X3D CPU를 쓴다면 코어 스케줄링 문제일 수 있습니다. (7800X3D·9800X3D처럼 CCD가 하나뿐인 모델은 해당하지 않습니다.) AMD 칩셋 드라이버 최신화, 3D V-Cache Performance Optimizer 서비스 실행 여부, Xbox Game Bar 활성화 상태를 확인하세요. 그래도 반복되면 Process Lasso로 게임 프로세스를 V-Cache CCD에 고정하는 방법도 있습니다."}],"communityCases":[{"title":"RTX 5080 · 9950X3D 최상급 사양인데도 계속된 프레임 드랍","summary":"그래픽카드와 CPU 모두 최상위 라인이라 부품 문제를 의심할 이유가 없었지만, 특정 게임에서 프레임이 계속 뚝뚝 떨어졌던 사례입니다. 온도와 사용률은 모두 정상 범위였고, 드라이버 재설치와 백그라운드 프로그램 정리로도 나아지지 않았습니다.","insight":"9950X3D는 CCD 하나에만 3D V-Cache가 달려 있어, Windows가 게임 스레드를 캐시 없는 CCD로 배정하면 사양과 무관하게 프레임이 떨어집니다. AMD 칩셋 드라이버 최신화와 3D V-Cache Performance Optimizer 서비스, Xbox Game Bar 활성화로 코어 배정이 정상화되면서 해결됐습니다."}]},"no-display":{"badge":"화면","subtitle":"전원은 들어오는데 화면이 안 뜰 때","intro":["화면 미출력은 모니터 문제처럼 보여도 실제로는 케이블, 그래픽카드, 메모리 접촉 문제인 경우가 많습니다. 전원이 돌아가는 소리는 나지만 화면만 검다면 출력 경로를 차례대로 확인해야 합니다.","이 증상은 단순히 선 하나만 바꿔보는 것으로 끝나지 않습니다. 입력 소스, 그래픽 포트, 램 재장착, 내장그래픽 여부를 함께 확인해야 원인을 좁힐 수 있습니다.","부팅음이 들리는지, 팬은 도는지, LED가 어떻게 바뀌는지 같이 보면 더 빨리 판단할 수 있습니다.","메인보드에 스피커(POST 스피커)가 연결되어 있다면 삑 소리 패턴이 가장 확실한 단서입니다. 짧게 한 번 울리고 끝나면 POST 자체는 정상 통과한 것이라 그래픽 신호 전달 쪽(케이블, 포트) 문제일 가능성이 크고, 길게 반복되거나 특정 패턴이 반복된다면 램이나 그래픽카드가 메인보드에 아예 인식되지 않는 초기 단계 문제입니다. 스피커가 없다면 메인보드의 디버그 LED나 숫자 코드로 같은 정보를 확인할 수 있는 경우도 많습니다."],"warnings":["팬은 돌지만 화면만 검다.","모니터 입력을 바꿔도 반응이 없다.","램을 빼면 경고음이 나오는데 꽂으면 조용하다.","부팅음이나 메신저 알림(카카오톡 PC 로그인 등)은 오는데 화면만 계속 안 나온다."],"checks":[{"title":"완전 방전 후 최소 장치로 부팅","why":"USB 허브·외장 저장장치·프린터가 초기 장치 검사를 방해하거나, 잔류 전원 때문에 POST 상태가 꼬일 수 있습니다.","how":"① PC와 모니터의 전원을 모두 끄세요. ② PC 뒷면에서 전원 케이블을 완전히 뽑으세요(멀티탭 스위치만 끄지 말고 케이블 자체를 뽑아야 합니다). ③ 케이스의 전원 버튼을 10초 정도 눌러 남은 전기를 방전하세요. ④ 키보드와 모니터 케이블을 제외한 나머지 USB 장치(마우스는 남겨도 무방), USB 허브, 외장 저장장치, 프린터, 카드리더기 등을 모두 뽑으세요. ⑤ 전원 케이블을 다시 꽂고 전원 버튼을 눌러 부팅하세요. ⑥ 화면이 정상적으로 나오면, 껐던 장치를 하나씩만 다시 연결하며 재부팅해 어떤 장치가 원인인지 찾으세요."},{"title":"모니터가 그래픽카드 포트에 연결되어 있는지 확인","why":"그래픽카드가 별도로 있는데 모니터를 메인보드(내장그래픽) 포트에 꽂아두면, BIOS 화면까지는 나오다가 Windows가 부팅되며 출력이 그래픽카드로 넘어가 화면이 꺼집니다. 부팅 관련 알림(사운드, 메신저 PC 로그인 알림 등)이 정상적으로 온다면 이미 Windows가 부팅된 것이므로 이 경우일 가능성이 가장 높습니다.","how":"① 본체 뒷면을 보면 포트가 두 군데로 나뉘어 있습니다 — 메인보드 자체에 있는 포트(케이스 위쪽, 메인보드 백패널 부분)와 별도 그래픽카드에 있는 포트(케이스 아래쪽, 카드가 꽂힌 슬롯 위치)입니다. ② 그래픽카드가 설치된 PC라면 반드시 아래쪽 그래픽카드 포트에 모니터를 연결해야 합니다 — 위쪽 메인보드 포트에 꽂으면 대부분 아예 신호가 나오지 않거나 BIOS 화면까지만 나옵니다. ③ 모니터 케이블(HDMI 또는 DisplayPort)을 그래픽카드 쪽 포트로 옮겨 꽂고 모니터의 입력 소스도 해당 포트에 맞게 선택하세요. ④ 다시 전원을 켜서 화면이 나오는지 확인하세요."},{"title":"안전 모드로 부팅해 그래픽 드라이버·해상도 원인 확인","why":"BIOS는 기본 해상도로만 출력하지만, Windows가 로그인되면서 그래픽 드라이버가 실제 해상도·주사율을 적용합니다. 이때 케이블이나 모니터가 처리할 수 없는 조합이 적용되면 화면 신호만 끊기고 Windows 자체는 백그라운드에서 계속 정상 동작합니다.","how":"① 화면이 안 나오는 상태에서 PC 전원을 켠 뒤, Windows 로고가 뜨기 전(또는 부팅 시도 직후) 강제로 전원 버튼을 3~4초 눌러 껐다가 다시 켜세요. 이 과정을 2~3번 반복하면 Windows가 '자동 복구' 모드로 진입합니다. ② 파란 화면에서 '고급 옵션'을 선택하세요. ③ '문제 해결' → '고급 옵션' → '시작 설정' → '다시 시작'을 차례로 선택하세요. ④ 재부팅 후 나오는 목록에서 '4' 또는 'F4' 키를 눌러 '안전 모드 사용'을 선택하세요(그래픽 문제 진단에는 네트워크 없는 기본 안전 모드로 충분합니다). ⑤ 안전 모드에서 화면이 정상적으로 나오면 원인은 그래픽 드라이버입니다. Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ⑥ '디스플레이 어댑터' 항목을 펼쳐 그래픽카드를 마우스 오른쪽 버튼으로 클릭한 뒤 '디바이스 제거'를 선택하고, '이 장치의 드라이버 소프트웨어 삭제' 체크박스가 있다면 체크하세요. ⑦ 재부팅하면 Windows가 기본 드라이버로 다시 잡습니다. 이후 제조사(NVIDIA/AMD/Intel) 사이트에서 최신 드라이버를 다시 내려받아 설치하세요."},{"title":"케이블과 입력 소스 확인","why":"모니터 입력이 잘못되거나 케이블이 느슨해도 같은 증상입니다.","how":"① 모니터 전면이나 측면의 버튼(또는 리모컨)으로 OSD 메뉴를 열어 '입력 소스(Input Source)' 메뉴로 들어가세요. ② 현재 연결한 케이블 단자와 모니터에서 선택된 입력 소스가 일치하는지 확인하세요(예: HDMI 1에 케이블을 꽂았는데 모니터는 HDMI 2나 DP를 보고 있으면 화면이 안 나옵니다). ③ 케이블을 완전히 뽑았다가 딸깍 소리가 나도록 다시 꽂아 접촉 상태를 확인하세요. ④ 여유가 있다면 다른 HDMI/DP 케이블로 교체해 케이블 자체의 불량 여부도 확인하세요."},{"title":"모니터 자체 메뉴와 다른 기기 확인","why":"모니터의 OSD 메뉴도 보이지 않는지, 다른 기기에서는 정상인지 비교하면 모니터 자체와 PC 출력 문제를 분리할 수 있습니다.","how":"① 케이블을 연결한 상태에서 모니터 버튼(또는 리모컨)을 눌러 OSD(화면 설정) 메뉴가 뜨는지 확인하세요. ② OSD 메뉴 자체가 뜨지 않으면 모니터 전원이나 모니터 고장 쪽을 의심해야 합니다 — 모니터 전원 케이블과 콘센트를 바꿔보세요. ③ OSD 메뉴는 정상적으로 뜨는데 PC 화면 신호만 없다면 모니터는 정상이고 PC 쪽(케이블, 그래픽카드, 출력 설정)이 원인입니다. ④ 가능하다면 같은 모니터를 노트북이나 다른 PC에 연결해 화면이 나오는지 비교하세요 — 다른 기기에서는 정상이면 모니터 문제가 아니라 PC 쪽 문제로 확정할 수 있습니다."},{"title":"Num Lock으로 Windows 부팅 여부 확인","why":"키보드 LED가 반응하면 Windows는 시작됐지만 영상 출력만 실패했을 가능성이 있고, LED도 반응하지 않으면 POST 단계부터 멈췄을 가능성이 있습니다.","how":"① 키보드를 PC 본체에 직접 연결하세요(무선 키보드보다 유선 키보드가 확실합니다). ② PC를 켠 뒤 화면이 안 나오는 상태에서 키보드의 Num Lock 키를 눌러보세요. ③ Num Lock 표시등(LED)이 켜지거나 꺼지며 반응하면 Windows는 정상적으로 부팅된 것이고, 문제는 화면 출력(그래픽 드라이버, 케이블, 해상도) 쪽으로 좁혀집니다 — 위의 '안전 모드로 부팅' 항목을 진행하세요. ④ Num Lock 키를 눌러도 LED가 전혀 반응하지 않으면 Windows가 부팅되기 전, 즉 POST(전원 인가 자체 테스트) 단계에서 멈춘 것입니다 — 이 경우 RAM, 그래픽카드, 전원 공급, 메인보드 쪽 하드웨어 원인을 확인해야 합니다."},{"title":"그래픽카드와 메모리 재장착","why":"접촉 불량은 전원은 들어와도 출력만 안 되는 상황을 만듭니다.","how":"① PC 전원을 끄고 전원 케이블을 완전히 뽑으세요. ② 케이스 옆판을 열고 그래픽카드를 슬롯에서 완전히 분리하세요(카드 뒤쪽 고정 나사와 슬롯 옆의 고정 클립을 먼저 풀어야 합니다). ③ 그래픽카드의 금색 단자 부분을 마른 천이나 지우개로 가볍게 닦아낸 뒤, PCIe 슬롯에 딸깍 소리가 나도록 다시 꽂고 고정 나사를 조이세요. ④ 그래픽카드에 별도 보조전원 케이블(6핀/8핀)이 필요하다면 완전히 꽂혔는지 다시 한번 눌러 확인하세요. ⑤ 같은 방식으로 RAM도 슬롯에서 완전히 뺐다가 양쪽 끝 고정 클립이 딸깍 잠기도록 다시 꽂으세요. ⑥ 램이 여러 개라면 한 개씩만 꽂아서 부팅을 시도해 특정 램이나 슬롯이 문제인지 확인할 수 있습니다."},{"title":"내장그래픽으로 분리 테스트","why":"그래픽카드가 원인인지 메인보드/메모리 쪽인지 구분할 수 있습니다.","how":"① CPU에 내장그래픽이 있는 모델(인텔 대부분, AMD는 'G' 표기 모델)인지 먼저 확인하세요. ② PC 전원을 끄고, 모니터 케이블을 그래픽카드 포트가 아닌 메인보드 자체의 영상 출력 포트(케이스 위쪽)로 옮겨 꽂으세요. ③ 전원을 켜서 화면이 나오는지 확인하세요. ④ 내장그래픽으로는 화면이 정상적으로 나온다면 원인은 그래픽카드(카드 고장, 슬롯 접촉 불량, 보조전원 문제) 쪽으로 확정할 수 있습니다. ⑤ 내장그래픽으로도 화면이 안 나온다면 메인보드나 CPU, 메모리 등 더 근본적인 원인을 의심해야 합니다."},{"title":"디버그 LED로 멈춘 단계 확인","why":"메인보드에 디버그 LED가 있다면 추측 없이 CPU/램/그래픽카드/부팅장치 중 어디서 멈췄는지 바로 알 수 있습니다.","how":"① 메인보드에 디버그 LED가 있는지 먼저 확인하세요 — 보통 24핀 전원 커넥터 근처나 CPU 소켓 옆, 램 슬롯 주변에 CPU / DRAM / VGA / BOOT라고 적힌 작은 4개의 표시등이 있습니다(모든 메인보드에 있는 기능은 아니며, 보급형 메인보드에는 없을 수 있습니다). ② PC 전원을 켠 뒤 어느 LED에 불이 켜진 채로 멈추는지 관찰하세요. ③ CPU LED에서 멈추면 CPU 장착 상태나 CPU 자체를, DRAM LED에서 멈추면 램 장착 상태를, VGA LED에서 멈추면 그래픽카드를, BOOT LED에서 멈추면 저장장치나 부팅 설정을 우선 점검하세요. ④ 해당 부품을 재장착해도 같은 LED에서 계속 멈춘다면 그 부품 자체의 고장이거나, 서비스센터·전문 수리점에 점검을 맡기는 것이 안전합니다."},{"title":"BIOS 설정 변경 뒤라면 CMOS 초기화 검토","why":"오버클럭·XMP·부팅 모드·저장장치 설정을 바꾼 직후라면 잘못된 펌웨어 설정이 화면 출력이나 POST를 막을 수 있습니다.","how":"① 가능하다면 문제가 생기기 전 BIOS 화면을 스마트폰으로 촬영해 두거나, 최근에 어떤 설정(오버클럭, XMP, 부팅 순서 등)을 바꿨는지 기억을 정리해 두세요. ② PC 전원을 끄고 전원 케이블을 완전히 뽑으세요. ③ 메인보드 설명서(또는 제조사 홈페이지)에서 'Clear CMOS' 방법을 확인하세요 — 대부분 메인보드에 위치한 작은 배터리(CR2032 동전 모양)를 5분 정도 뺐다가 다시 끼우거나, 'CLR_CMOS'라고 표시된 점퍼/버튼을 사용하는 방식입니다. ④ 초기화 후 전원을 다시 연결하고 부팅해 화면이 나오는지 확인하세요. ⑤ 화면이 정상적으로 나오면 BIOS로 들어가(부팅 직후 Delete 또는 F2 키 연타) UEFI/Legacy 모드, AHCI/RAID 저장장치 모드, 부팅 순서, 날짜와 시간이 올바르게 설정됐는지 다시 확인하고 저장 후 재부팅하세요."}],"deeper":[{"heading":"화면은 안 뜨는데 부팅은 되는 경우","text":"화면이 없다고 해서 항상 메인보드 고장은 아닙니다. 그래픽카드 출력 문제나 메모리 접촉 때문에 화면만 안 나오는 경우도 많아, 교차 테스트가 중요합니다."},{"heading":"Num Lock도 반응하지 않는 경우","text":"키보드 LED와 Ctrl+Alt+Delete가 모두 반응하지 않으면 Windows가 정상적으로 시작됐다고 보기 어렵습니다. 이때는 모니터 교체보다 POST 단계의 DRAM·VGA LED, 비프음, 최소 장치 부팅을 먼저 확인하세요."},{"heading":"디버그 LED(Q-LED, EZ Debug LED)로 점검하는 방법","text":"요즘 메인보드 대부분은 24핀 전원 커넥터나 CPU 소켓·램 슬롯 근처에 CPU, DRAM, VGA, BOOT라고 표시된 4개의 디버그 LED(제조사에 따라 ASUS는 Q-LED, MSI는 EZ Debug LED, GIGABYTE는 Status LED로 부름)를 갖추고 있습니다. 정상적으로 부팅될 때는 전원을 켜는 순간 이 LED들이 CPU → DRAM → VGA → BOOT 순서로 빠르게 깜빡이다가 모두 꺼집니다. 만약 특정 LED가 꺼지지 않고 계속 켜진 채로 멈춰 있다면, 그 단계에서 POST(자체 검사)가 실패했다는 뜻입니다: CPU LED면 CPU 장착 상태나 CPU 자체 결함, DRAM LED면 램 미장착·접촉 불량·불량 모듈, VGA LED면 그래픽카드 미장착·접촉 불량·고장, BOOT LED면 부팅 가능한 저장장치를 찾지 못했다는 의미입니다. 정확한 LED 위치와 순서는 메인보드마다 조금씩 달라 제품 설명서를 함께 참고하는 것이 가장 정확합니다."},{"heading":"BIOS 화면은 나오는데 Windows가 뜨면 꺼지는 이유","text":"BIOS·POST 화면은 그래픽 드라이버 없이 아주 기본적인 해상도(예: 640x480, 800x600)로만 출력됩니다. Windows에 로그인하는 순간 그래픽 드라이버가 로드되면서 모니터의 실제 해상도·주사율로 전환하는데, 이때 케이블 대역폭(예: 고주사율 모니터에 오래된 DP·HDMI 케이블)이나 모니터가 지원하지 않는 조합이 적용되면 신호 자체가 끊깁니다. 이 경우 화면만 안 보일 뿐 Windows는 백그라운드에서 정상적으로 계속 실행되므로, 소리·메신저 알림 같은 다른 동작은 평소와 똑같이 이어집니다. 안전 모드로 부팅해 화면이 돌아오는지 확인하면 이 원인인지 바로 구분할 수 있습니다."}],"decision":[{"heading":"부팅음이나 메신저 알림은 오는데 화면만 안 나올 때","text":"Windows가 이미 부팅됐다는 뜻이므로 메인보드·메모리 고장 가능성은 낮습니다. 그래픽카드가 있다면 모니터 케이블을 그래픽카드 포트로 옮겨 연결하는 것부터 확인하고, 포트를 옮겨도 안 되면 안전 모드로 부팅해 그래픽 드라이버·해상도 문제인지 확인하세요."},{"heading":"팬은 도는데 화면만 없을 때","text":"전원 반응은 있고 경고음도 없다면 케이블과 출력 포트부터 확인하고, 그 다음 그래픽카드 재장착으로 넘어가세요."},{"heading":"OSD는 보이고 다른 PC에서도 정상일 때","text":"모니터 자체 메뉴와 다른 기기 출력이 정상이라면 모니터 고장보다 현재 PC의 포트·케이블·그래픽카드·메모리 순서로 점검하는 것이 합리적입니다."},{"heading":"경고음이 있을 때","text":"비프음이 난다면 메모리 접촉이 원인일 가능성이 높아, 램 교차 테스트가 더 우선입니다."},{"heading":"디버그 LED가 있는 메인보드일 때","text":"케이블·재장착을 하나씩 시도하기 전에 디버그 LED부터 확인하면, 어느 부품을 먼저 점검해야 하는지 순서를 크게 줄일 수 있습니다. DRAM이나 VGA에서 멈춰 있다면 해당 부품의 재장착·교차 테스트부터 우선하세요."}],"examples":["전원 LED는 켜지는데 로고도 안 보임","한 번은 뜨고 재부팅 후부터 안 뜸","디버그 LED가 DRAM에서 계속 켜진 채로 멈춰 있음"],"mistakes":["모니터만 계속 바꾸는 것","램이나 그래픽카드 접촉 점검을 빼는 것","메인보드에 디버그 LED가 있는데도 확인하지 않고 부품을 하나씩 무작정 다시 꽂아보는 것"],"faq":[{"q":"본체에서 경고음이 나는데도 화면이 안 뜹니다.","a":"경고음이 있다면 메모리나 그래픽 초기화가 문제일 가능성이 큽니다. 메모리 재장착부터 확인하는 것이 좋습니다."},{"q":"모니터 전원 LED는 켜져 있는데 화면만 안 나오면 모니터 문제인가요?","a":"다른 PC나 케이블로 교차 테스트를 해보면 모니터와 본체 중 어느 쪽 문제인지 구분할 수 있습니다."},{"q":"Num Lock 불빛도 바뀌지 않습니다.","a":"Windows가 시작되지 않고 POST 단계에서 멈췄을 가능성이 있습니다. USB 장치를 모두 분리한 최소 구성으로 부팅하고, DRAM·VGA 디버그 LED와 비프음을 확인하세요."},{"q":"CMOS 배터리를 바로 빼도 되나요?","a":"바로 분리하기보다 메인보드 설명서의 Clear CMOS 방법을 우선 사용하세요. BitLocker를 쓰는 Windows라면 복구 키를 확보하고, BIOS 설정과 저장장치 모드를 기록한 뒤 진행하는 것이 안전합니다."},{"q":"그래픽카드를 뺐다 끼워도 될까요?","a":"전원을 완전히 차단한 뒤 정전기 방지 조치를 하고 진행해야 하며, 익숙하지 않다면 무리해서 시도하지 않는 것이 안전합니다."},{"q":"디버그 LED가 어디 있는지 모르겠어요.","a":"보통 24핀 메인 전원 커넥터 옆이나 CPU 소켓·램 슬롯 근처에 CPU·DRAM·VGA·BOOT 4글자가 작게 표시되어 있습니다. 정확한 위치는 메인보드 모델명으로 제조사 홈페이지의 사용 설명서(메뉴얼)를 검색해 확인하는 것이 가장 정확합니다."},{"q":"디버그 LED가 아예 없는 메인보드도 있나요?","a":"네, 보급형 메인보드 중에는 디버그 LED가 없는 모델도 많습니다. 이 경우 케이블·재장착 점검을 순서대로 진행하거나, 스피커(비프음)를 연결해 경고음 패턴으로 원인을 구분하는 방법을 대신 사용하세요."}],"communityCases":[{"title":"그래픽카드 교체로 해결한 사례","summary":"케이블 교체, 램 재장착, 내장그래픽 분리 테스트까지 다 해봐도 화면이 나오지 않던 사례가 있습니다. 그래픽카드를 다른 PC에 꽂아봤더니 그 PC에서도 출력이 되지 않아 그래픽카드 자체의 고장으로 확인됐고, 새 그래픽카드로 교체한 뒤 정상적으로 화면이 나왔습니다.","insight":"케이블·슬롯·메모리 점검을 모두 마쳤는데도 화면이 안 나온다면, 그래픽카드를 다른 PC에서 테스트해 보거나 다른 그래픽카드를 임시로 꽂아 교차 확인하는 것이 원인을 확정하는 가장 빠른 방법입니다."}]},"dual-monitor-dp-not-detected":{"badge":"디스플레이","subtitle":"듀얼 모니터 중 한 대만 보이지 않을 때","intro":["한 대는 정상인데 두 번째 모니터만 감지되지 않는다면, PC 전체의 화면 미출력과는 점검 순서가 다릅니다. HDMI·DP 등 연결 방식과 관계없이 각 모니터·케이블·포트를 단독으로 시험한 결과와 두 대를 함께 연결한 결과를 비교해야 합니다.","두 화면을 각각 연결하면 정상인데 동시에 연결할 때만 실패하는 경우에는 케이블 불량보다 해상도·주사율·도킹 스테이션의 대역폭 또는 MST 설정을 먼저 의심하는 편이 빠릅니다.","그래픽카드나 모니터를 바로 교체하기 전에 입력 소스, 직접 연결, Windows 확장 모드, 절전 복귀 후 재현 여부를 순서대로 기록하세요."],"warnings":["모니터 전원은 켜지지만 '신호 없음'만 표시된다.","두 모니터는 각각 정상인데 함께 연결하면 한 대가 사라진다.","절전 복귀나 드라이버 업데이트 뒤부터 두 번째 화면이 감지되지 않는다."],"checks":[{"title":"문제가 나는 연결 경로를 고정","why":"두 번째 모니터라는 이유만으로 모니터 자체 불량이라고 판단할 수 없습니다.","how":"① 두 모니터를 모두 뽑고, 모니터 A만 그래픽카드의 특정 DP 포트에 연결해 화면이 나오는지 확인하세요. ② 같은 케이블과 포트에 이번엔 모니터 B를 연결해 화면이 나오는지 확인하세요. ③ 두 모니터를 서로 다른 포트에도 바꿔가며 연결해보고, 어느 조합(어떤 모니터+어떤 케이블+어떤 포트)에서 실패하는지 메모지에 표로 기록하세요. ④ 이 기록을 보면 모니터 자체 문제인지, 특정 케이블·포트 문제인지 좁힐 수 있습니다."},{"title":"입력 소스와 직접 연결 확인","why":"모니터 OSD의 입력 소스가 다르거나 허브·변환 젠더가 중간에 있으면 감지가 실패할 수 있습니다.","how":"① 인식이 안 되는 모니터의 전면 버튼(또는 리모컨)으로 OSD 메뉴를 열어 '입력 소스'로 들어가세요. ② 실제로 연결한 포트(DP 또는 HDMI)와 모니터가 보고 있는 입력 소스가 일치하는지 확인하고, 다르다면 맞게 바꾸거나 'Auto'로 설정하세요. ③ 도킹 스테이션, KVM 스위치, USB 허브, 변환 젠더 등을 거쳐 연결하고 있다면 모두 제거하고 그래픽카드 포트에 케이블을 직접 연결해보세요. ④ 직접 연결했을 때 정상적으로 인식되면 중간 장치(도킹, 허브, 젠더)가 원인입니다."},{"title":"Windows 확장 모드와 감지 실행","why":"케이블 신호는 들어왔지만 Windows가 복제 모드 또는 이전 화면 구성을 유지하는 경우가 있습니다.","how":"① 두 모니터를 모두 연결한 상태에서 Windows 로고 키 + P를 누르세요. ② 방향키로 '확장'을 선택하고 Enter를 누르세요. ③ Windows 로고 키를 누르고 '디스플레이 설정'을 입력해 실행하세요. ④ 아래로 스크롤해 '여러 디스플레이' 항목에서 '감지' 버튼을 클릭하세요(이 버튼이 Windows에게 다시 한번 연결된 모니터를 찾아보라고 지시합니다). ⑤ 두 모니터가 모두 인식되면 화면 배치도(사각형 두 개)에서 실제 책상 위 배치와 같은 위치로 드래그해 옮긴 뒤 '적용'을 클릭하세요."},{"title":"해상도·주사율을 낮춰 동시 출력 시험","why":"고해상도·고주사율 두 대, HDR, DSC 또는 MST 환경은 연결 장치의 대역폭 한계가 드러날 수 있습니다.","how":"① 디스플레이 설정에서 각 모니터를 선택하고 '고급 디스플레이'로 들어가세요. ② 새로고침 빈도를 60Hz로, 해상도를 모니터의 기본(권장) 해상도보다 한 단계 낮춰 설정하세요. ③ HDR이 켜져 있다면 꺼보세요. ④ 이 상태로 두 모니터를 함께 연결해 정상적으로 인식되는지 확인하세요. ⑤ 낮춘 설정에서는 정상 작동한다면, 케이블 규격이나 그래픽카드·도킹 스테이션의 대역폭 한계가 원인이므로 더 높은 규격의 케이블(DP 1.4, HDMI 2.1 등)로 교체하는 것을 고려하세요."},{"title":"절전 해제와 그래픽 드라이버 분리","why":"절전 복귀·업데이트 직후의 인식 실패는 포트 고장보다 드라이버 또는 전원 상태 전환 문제일 수 있습니다.","how":"① PC와 두 모니터를 모두 완전히 종료하세요. ② PC와 모니터의 전원 케이블을 모두 뽑고 1분 이상 기다리세요(잔여 전원을 완전히 방전시키기 위함입니다). ③ 전원 케이블을 다시 연결하고, 주 모니터(평소 쓰는 메인 화면)부터 먼저 연결해 PC를 켜세요. ④ 정상 부팅된 뒤 두 번째 모니터 케이블을 연결하세요. ⑤ Windows 로고 키를 누르고 '장치 관리자'를 입력해 '디스플레이 어댑터'에 오류 표시가 있는지 확인하고, 있다면 제조사 최신 드라이버로 업데이트하거나 최근 업데이트 이후 문제가 생겼다면 이전 드라이버로 롤백해 비교하세요."},{"title":"노트북 도킹·MST 환경 확인","why":"USB-C 포트마다 영상 출력(DP Alt Mode) 지원이 다르고, 도킹 스테이션은 별도 전원과 MST 대역폭이 필요할 수 있습니다.","how":"① 노트북 제조사 홈페이지에서 정확한 모델명으로 검색해 사용 중인 USB-C 포트가 영상 출력(DP Alt Mode 또는 Thunderbolt)을 지원하는 포트인지 확인하세요(충전 전용 포트인 경우가 있습니다). ② 도킹 스테이션을 쓰고 있다면 도킹 스테이션 자체의 전원 어댑터가 콘센트에 연결되어 있는지 확인하세요(전원 없이는 다중 모니터 출력이 안 되는 도킹이 많습니다). ③ 도킹을 거치지 않고 모니터 한 대를 노트북의 영상 출력 지원 USB-C(또는 HDMI) 포트에 직접 연결해 정상적으로 나오는지 확인하세요. ④ 직접 연결했을 때 정상이라면 도킹 스테이션 자체의 문제이므로 도킹 제조사에 문의하거나 다른 도킹으로 교체를 고려하세요."}],"deeper":[{"heading":"각각은 되는데 두 대를 함께 연결하면 안 될 때","text":"두 모니터와 케이블이 각각 단독으로 정상이라면 물리 고장보다 동시 출력 조건을 우선 확인하세요. 먼저 두 화면의 주사율·해상도·HDR을 낮추고, 도킹·MST 허브 없이 직접 연결합니다. 정상으로 바뀌면 그래픽카드 또는 도킹 스테이션의 출력 사양과 케이블 규격을 맞춰야 합니다."},{"heading":"한 DP 경로에서만 항상 안 될 때","text":"같은 모니터를 다른 케이블·다른 그래픽카드 포트에 연결해 결과를 바꾸면 원인을 좁힐 수 있습니다. 특정 케이블에서만 실패하면 케이블, 특정 포트에서만 실패하면 그래픽카드·모니터의 해당 포트, 특정 모니터에서만 실패하면 입력 설정 또는 모니터 포트를 우선 점검하세요."}],"decision":[{"heading":"두 모니터가 각각은 정상일 때","text":"해상도·주사율을 낮춘 동시 연결과 직접 연결을 먼저 비교하세요. 도킹 또는 MST 허브를 뺐을 때 해결되면 해당 장치의 전원·펌웨어·지원 사양을 확인하는 순서가 맞습니다."},{"heading":"한 모니터가 다른 PC에서도 DP로만 안 나올 때","text":"모니터 DP 입력 또는 케이블 문제 가능성이 큽니다. HDMI가 정상이라는 사실만으로 DP 입력이 정상이라는 뜻은 아니므로, 정상 DP 케이블과 다른 PC로 교차 테스트하세요."},{"heading":"절전·업데이트 뒤부터 시작됐을 때","text":"완전 종료 후 재연결하고 Windows 확장 모드와 그래픽 드라이버를 점검하세요. 최근 드라이버를 바꾼 직후라면 이전 버전 복원으로 증상 변화를 확인한 뒤 한 가지 변경만 유지합니다."}],"examples":["HDMI 또는 DP 모니터 한 대는 나오지만 보조 모니터만 '신호 없음'으로 표시됨","165Hz 두 대를 연결하면 한 화면이 사라지지만 60Hz에서는 두 대가 모두 표시됨","노트북 도킹 스테이션에 두 대를 연결했을 때만 감지가 안 되고, 한 대 직접 연결은 정상임"],"mistakes":["모니터 두 대와 케이블 두 개를 한 번에 바꿔 원인을 기록하지 않는 것","입력 소스와 Windows 키 + P의 복제·확장 모드를 확인하지 않는 것","도킹·허브를 그대로 둔 채 그래픽카드 고장으로 단정하는 것","드라이버·BIOS·모니터 설정을 동시에 바꿔 어떤 조치가 영향을 줬는지 알 수 없게 하는 것"],"faq":[{"q":"HDMI로는 나오는데 DP만 안 나오면 그래픽카드 고장인가요?","a":"아닙니다. DP 케이블, 모니터 DP 입력, 그래픽카드의 특정 DP 포트, 입력 소스 설정을 각각 교차 테스트해야 합니다. HDMI 정상 여부는 PC 전체 출력이 살아 있다는 단서일 뿐입니다."},{"q":"두 화면이 나오지만 같은 화면만 복제됩니다.","a":"Windows 키 + P에서 '확장'을 선택하고 설정 > 시스템 > 디스플레이에서 화면 배열과 주 모니터를 지정하세요."},{"q":"고주사율 설정에서만 두 번째 모니터가 사라집니다.","a":"대역폭 또는 연결 장치 사양 문제일 수 있습니다. 두 모니터를 60Hz로 낮춰 정상 여부를 확인한 뒤, 케이블 규격과 그래픽카드·도킹 스테이션의 동시 출력 사양을 비교하세요."}]},"nvme-delay":{"badge":"저장장치","subtitle":"부팅이 느리거나 SSD 인식이 늦을 때","intro":["NVMe 인식 지연은 부팅 초기에 저장장치가 늦게 잡히거나 아예 한 번씩 놓치는 상황에서 보입니다. SSD 자체가 느린 것이 아니라 슬롯, 펌웨어, 전원 관리가 얽혀 있는 경우가 많습니다.","이 증상은 체감 속도 문제처럼 보여도 실제로는 부팅 안정성과 연결됩니다. 그래서 저장장치 상태와 메인보드 설정을 같이 봐야 합니다.","특정 재부팅에서만 느리다면 접촉, 발열, 펌웨어 순으로 확인하는 것이 좋습니다."],"warnings":["첫 부팅만 유난히 오래 걸린다.","재부팅하면 가끔 SSD가 늦게 잡힌다.","윈도우 들어가서도 디스크가 잠시 멈춘 듯하다."],"checks":[{"title":"SMART와 건강 상태 확인","why":"읽기 실패와 지연은 디스크 상태의 초기 신호일 수 있습니다.","how":"① 제조사 관리 프로그램(삼성 SSD면 Samsung Magician, 그 외는 CrystalDiskInfo 같은 무료 프로그램)을 설치하세요. ② 프로그램을 실행해 디스크의 건강 상태(정상/주의/경고)와 온도, 재할당된 섹터 수를 확인하세요. ③ 온도가 70도를 넘거나 상태가 '주의'·'경고'로 표시된다면 지연의 원인일 가능성이 큽니다. <a href=\"ssd-smart-health-guide.html\">실제 확인 방법과 결과 해석 보기 →</a>"},{"title":"슬롯과 케이블 교차 확인","why":"NVMe 슬롯 접촉이나 SATA 케이블 문제로도 지연이 생깁니다.","how":"① PC 전원을 끄고 케이스를 열어 NVMe M.2 슬롯 위 나사를 풀고 SSD를 완전히 분리하세요. ② 슬롯과 SSD의 금색 단자를 마른 천으로 가볍게 닦은 뒤 다시 꽂고 나사를 조이세요. ③ 메인보드에 M.2 슬롯이 여러 개라면 다른 슬롯에 꽂아 지연이 줄어드는지 비교하세요. ④ SATA 방식 SSD/HDD라면 SATA 데이터 케이블과 전원 케이블을 다른 것으로 교체해 비교하세요."},{"title":"BIOS 저장장치 모드 확인","why":"인식 모드나 부팅 순서가 꼬이면 시작이 늦어질 수 있습니다.","how":"① PC를 재부팅하며 부팅 직후 Delete 또는 F2 키를 연타해 BIOS 화면으로 들어가세요. ② 'Storage Configuration' 또는 'SATA Mode' 메뉴에서 'AHCI'로 설정되어 있는지 확인하세요('RAID'나 'IDE'로 잘못 설정되어 있으면 지연이 생길 수 있습니다). ③ 'Boot' 메뉴에서 부팅 순서 1번이 실제 Windows가 설치된 디스크로 지정되어 있는지 확인하세요(다른 디스크나 USB가 먼저 지정되어 있으면 부팅 시작이 늦어질 수 있습니다). ④ 저장 후 재부팅해 지연이 개선됐는지 확인하세요."}],"deeper":[{"heading":"디스크가 늦게 잡히는 이유","text":"저장장치가 느리다는 말은 실제 성능보다 초기 인식이나 전원 관리가 불안정하다는 뜻일 때가 많습니다. 같은 SSD라도 슬롯 위치, 발열, 펌웨어 버전에 따라 증상이 달라질 수 있습니다."}],"decision":[{"heading":"SMART가 정상일 때","text":"건강 수치가 좋아도 첫 부팅만 늦다면 슬롯 접촉이나 BIOS 설정 쪽을 먼저 보세요."},{"heading":"부팅마다 증상이 바뀔 때","text":"가끔 잡히고 가끔 놓친다면 저장장치 자체보다 초기 전원 공급과 연결 상태를 더 의심해야 합니다."}],"examples":["부팅 첫 화면에서 오래 멈춤","재부팅할 때만 디스크가 늦게 보임"],"mistakes":["윈도우만 재설치하고 저장장치는 그대로 두는 것","온도와 슬롯 상태를 같이 보지 않는 것"],"faq":[{"q":"SMART가 정상인데도 지연이 있습니다.","a":"그렇다면 슬롯 접촉, 펌웨어, 전원 관리 설정을 더 봐야 합니다. 건강 수치만으로는 초기 인식 문제를 놓칠 수 있습니다."},{"q":"SSD 펌웨어 업데이트가 실제로 도움이 되나요?","a":"제조사에서 배포하는 펌웨어 업데이트에는 인식 지연이나 호환성 버그 수정이 포함되는 경우가 많아 도움이 될 수 있습니다."},{"q":"M.2 슬롯 위치에 따라 속도가 달라지나요?","a":"메인보드에 따라 특정 M.2 슬롯이 CPU가 아닌 칩셋을 경유해 대역폭을 공유하는 경우가 있어, 설명서에서 권장 슬롯을 확인하는 것이 좋습니다."}],"communityCases":[{"title":"SSD 교체로 해결한 사례","summary":"슬롯을 바꾸고 BIOS 저장장치 모드까지 다시 설정해도 부팅 때마다 인식이 불규칙하게 늦어지던 사례가 있습니다. SMART 수치는 계속 정상으로 나왔지만, 다른 SSD로 교체하자 지연이 완전히 사라져 기존 SSD 컨트롤러의 노후화나 결함으로 추정됐습니다.","insight":"SMART가 정상이라고 해서 지연의 원인에서 완전히 배제할 수는 없습니다. 슬롯·케이블·BIOS 설정을 모두 확인했는데도 반복된다면, 여유 SSD로 교체 테스트를 해보는 것이 좋습니다."}]},"usb-not-detected":{"badge":"USB","subtitle":"USB 장치가 아예 안 잡힐 때","intro":["USB 미인식은 포트가 물리적으로 손상됐을 수도 있지만, 전력 부족이나 드라이버 문제처럼 소프트웨어적인 원인도 섞여 있습니다. 그래서 단순히 다른 기기를 꽂아보는 것보다 더 넓게 봐야 합니다.","특히 허브, 전면 포트, 외장 하드처럼 전원 요구가 큰 장치에서 더 자주 나타납니다. 같은 장치가 다른 포트에서는 되는지부터 확인하면 원인을 빠르게 좁힐 수 있습니다.","이 증상은 장치 관리자 상태와 물리 포트를 함께 보아야 합니다."],"warnings":["특정 포트만 안 된다.","허브를 끼우면 더 자주 끊긴다.","장치 관리자에는 잠깐 보였다가 사라진다."],"checks":[{"title":"다른 포트와 허브 제거","why":"물리 포트 문제인지 전력 문제인지 가장 먼저 가를 수 있습니다.","how":"① USB 허브를 사용 중이라면 허브를 거치지 않고 장치를 PC 본체의 USB 포트에 직접 꽂아보세요. ② 본체 뒷면(메인보드 직결 포트, 더 안정적)과 앞면 포트를 각각 바꿔가며 꽂아 인식되는지 비교하세요. ③ 특정 포트에서만 인식이 안 된다면 해당 포트 자체의 접촉 불량이나 고장일 수 있으니 다른 정상 포트를 사용하세요."},{"title":"장치 관리자 확인","why":"인식은 했지만 드라이버가 실패한 경우가 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② USB 장치를 연결한 상태에서 목록을 살펴보고, 이름 옆에 노란색 느낌표가 붙은 '알 수 없는 장치'나 '기타 장치' 항목이 있는지 확인하세요. ③ 해당 장치를 마우스 오른쪽 버튼으로 클릭해 '드라이버 업데이트' → '드라이버 자동 검색'을 선택해 Windows가 드라이버를 찾도록 하세요. ④ 그래도 안 되면 장치를 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택한 뒤 장치를 뽑았다 다시 꽂아 Windows가 처음부터 다시 인식하게 하세요. ⑤ 제조사가 명확한 장치(외장하드, 프린터 등)라면 제조사 홈페이지에서 전용 드라이버를 내려받아 설치하세요."},{"title":"전력과 절전 설정 점검","why":"USB 절전 옵션이 장치를 끊어 버리는 경우가 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② 'USB(Universal Serial Bus) 컨트롤러' 항목을 펼치고, 'USB 루트 허브'로 시작하는 각 항목을 더블클릭하세요. ③ '전원 관리' 탭에서 '전력을 절약하기 위해 컴퓨터에서 이 장치를 끌 수 있음' 체크박스가 있다면 모두 해제하세요. ④ Windows 로고 키를 누르고 '전원 및 절전 설정'을 입력해 들어간 뒤 '전원 관련 추가 설정' → '고급 전원 관리 설정 변경'을 클릭하세요. ⑤ 목록에서 'USB 설정' → 'USB 선택적 절전 설정'을 찾아 '사용 안 함'으로 바꾸고 저장하세요."}],"deeper":[{"heading":"전력보다 드라이버일 수도 있음","text":"외장 HDD나 캡처 장치처럼 전력을 많이 쓰는 장치일수록 포트 문제처럼 보이지만, 실제로는 드라이버와 전원 관리 설정이 원인인 경우도 많습니다."}],"decision":[{"heading":"다른 PC에서는 잘 될 때","text":"장치 자체는 정상일 가능성이 높고, 현재 PC의 절전 설정이나 드라이버 문제를 먼저 봐야 합니다."},{"heading":"허브를 쓰고 있을 때","text":"허브를 거칠수록 전력과 신호가 흔들릴 수 있으니, 먼저 본체 직결 테스트를 해보세요."}],"examples":["외장 SSD는 되는데 USB 메모리만 안 됨","전면 포트는 안 되고 후면 포트는 정상"],"mistakes":["포트만 바꾸고 장치 관리자를 안 보는 것","허브를 계속 거친 상태로 테스트하는 것"],"faq":[{"q":"다른 PC에서는 되는데 내 PC에서만 안 됩니다.","a":"그렇다면 포트, 전원 관리, 드라이버 설정 쪽 가능성이 큽니다. 장치 자체보다 현재 PC 설정을 먼저 보세요."},{"q":"USB 허브를 거치면 인식이 더 잘 안 되나요?","a":"허브를 거치면 전력 공급이 부족해질 수 있으므로, 문제가 있다면 본체 포트에 직접 연결해 재현 여부를 확인하는 것이 좋습니다."},{"q":"특정 포트에서만 인식이 안 되는 경우는 무엇을 확인해야 하나요?","a":"해당 포트가 USB 2.0인지 3.0인지, 장치관리자에서 해당 포트 컨트롤러에 오류 표시(느낌표)가 있는지 확인해야 합니다."}]},"update-fail-loop":{"badge":"업데이트","subtitle":"업데이트가 반복 실패하고 다시 시도될 때","intro":["업데이트 반복 실패는 다운로드 자체가 안 되는 경우도 있지만, 설치 단계에서만 계속 되돌아가는 경우가 더 흔합니다. 이럴 때는 서버 문제로 넘기기보다 캐시, 권한, 남은 공간부터 보는 편이 빠릅니다.","업데이트 기록에 같은 코드가 반복되면 윈도우 구성요소가 막혀 있을 가능성이 높습니다. 반대로 코드가 바뀌며 실패한다면 디스크 여유나 보안 정책, 서비스 충돌도 같이 봐야 합니다.","이 페이지는 업데이트가 어디서 반복되는지에 따라 점검 순서를 나눠서 설명합니다.","업데이트가 실패할 때마다 Windows는 원인과 무관하게 우선 이전 상태로 롤백부터 시도합니다. 이 롤백 자체는 정상 동작이지만, 재부팅 후 '업데이트 구성 중' 화면이 유독 오래 유지되다가 롤백된다면 시스템 파일이나 구성 요소 저장소 손상 쪽 가능성이 커집니다. 반대로 롤백이 빠르게 끝나고 곧바로 실패 알림이 뜬다면 다운로드나 네트워크 단계에서 걸린 것이라 원인이 다릅니다."],"warnings":["같은 업데이트를 여러 번 다시 시도한다.","재부팅 후에도 바로 실패가 반복된다.","디스크 공간이 거의 없거나 임시 파일이 많다."],"checks":[{"title":"업데이트 기록과 코드 확인","why":"반복되는 실패는 같은 구성요소가 계속 막히고 있다는 신호입니다.","how":"① Windows 로고 키를 누르고 '업데이트 기록 보기'를 입력해 실행하세요. ② 반복적으로 실패하는 업데이트의 이름(KB로 시작하는 번호)과 오류 코드를 메모하세요. ③ 오류 코드가 안 보인다면 Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행한 뒤 'Windows 로그' → '시스템'에서 'WindowsUpdateClient'라는 원본으로 표시된 오류 항목을 찾아 오류 코드를 확인하세요."},{"title":"임시 파일과 캐시 정리","why":"업데이트 캐시가 손상되면 같은 파일을 계속 다시 받다가 실패할 수 있습니다.","how":"① Windows 로고 키를 누르고 'services.msc'를 입력해 실행하세요. ② 'Windows Update' 서비스를 찾아 마우스 오른쪽 버튼으로 클릭해 '중지'를 선택하세요. ③ Windows 로고 키를 누르고 '이 PC'를 입력해 C 드라이브 → Windows → SoftwareDistribution 폴더로 이동하세요. ④ 폴더 안의 'Download' 폴더를 열어 내용물을 전부 선택(Ctrl+A)해 삭제하세요(폴더 자체는 남겨둡니다). ⑤ 다시 services.msc로 돌아가 'Windows Update' 서비스를 '시작'으로 재개하세요. ⑥ 설정 → Windows Update에서 '업데이트 확인'을 눌러 다시 시도하세요."},{"title":"보안 프로그램과 정책 확인","why":"업데이트가 보안 프로그램이나 회사 정책에 막히는 경우도 있습니다.","how":"① 백신이나 보안 프로그램을 사용 중이라면, 프로그램을 열어 실시간 감시를 일시적으로(예: 10분간) 꺼보세요. ② 이 상태에서 설정 → Windows Update → '업데이트 확인'을 다시 시도해 정상적으로 설치되는지 확인하세요. ③ 회사·학교 PC라면 그룹 정책으로 특정 업데이트가 관리자에 의해 차단되어 있을 수 있습니다 — 이 경우 IT 담당자에게 문의하는 것이 정확합니다. ④ 개인 PC에서 위 방법으로 해결됐다면, 보안 프로그램의 실시간 감시를 다시 켜두세요(꺼둔 채로 계속 사용하면 안 됩니다)."}],"deeper":[{"heading":"실패 코드보다 패턴이 더 중요할 때","text":"같은 코드가 반복되면 캐시와 서비스 문제일 가능성이 높고, 매번 다른 코드가 나오면 공간 부족이나 전원 끊김, 정책 충돌처럼 바깥 조건을 더 봐야 합니다."},{"heading":"업데이트가 부팅 문제를 남길 때","text":"실패 후 재부팅이 되지 않으면 자동 복구 루프로 이어질 수 있으므로, 단순히 다시 누르기보다 복구 지점을 남겨두고 상태를 확인하는 것이 좋습니다."}],"decision":[{"heading":"같은 코드가 계속 뜰 때","text":"업데이트 파일이나 서비스가 꼬였을 가능성이 높아 초기화와 캐시 정리를 먼저 해야 합니다."},{"heading":"다른 코드가 번갈아 뜰 때","text":"디스크 공간, 전원 안정성, 백신/보안 정책처럼 외부 조건을 함께 확인하세요."}],"examples":["설치 100% 직후에 되돌아가며 실패","업데이트 기록에 같은 번호가 여러 번 남음"],"mistakes":["실패 코드 없이 재시도만 반복하는 것","공간이 부족한데도 큰 파일을 그대로 두는 것"],"faq":[{"q":"업데이트를 일시 중지했다가 다시 하면 나아지나요?","a":"일시적으로 나아질 수는 있지만, 같은 패턴이 반복되면 캐시나 서비스 문제를 다시 봐야 합니다."},{"q":"업데이트를 계속 재시도하면 언젠가 성공하나요?","a":"일부는 재시도만으로 해결되지만, 반복 실패한다면 문제 해결사나 구성 요소 정리 없이는 같은 오류가 계속될 가능성이 높습니다."},{"q":"업데이트 대기 중인 상태에서 강제 종료해도 되나요?","a":"설치 진행 중 강제 종료는 시스템 파일 손상 위험이 있으므로, 진행률이 멈춘 것이 확실할 때만 재부팅하는 것이 안전합니다."}]},"win11-upgrade-blocked":{"badge":"업그레이드","subtitle":"윈도우 10에서 11로 업그레이드가 시작되지 않거나 도중에 막힐 때","intro":["윈도우 11 업그레이드가 안 되는 경우는 크게 두 가지입니다. 하나는 '이 PC에서 Windows 11을 실행할 수 없습니다' 같은 메시지와 함께 업그레이드 자체가 시작되지 않는 경우이고, 다른 하나는 다운로드·설치는 진행되다가 특정 단계에서 되돌아가는 경우입니다.","첫 번째는 대부분 하드웨어 요구사항(TPM 2.0, 보안 부팅, 지원 CPU 목록) 중 하나를 충족하지 못해서 발생하고, 두 번째는 저장공간 부족이나 드라이버·주변기기 호환성 문제인 경우가 많습니다.","이 페이지는 어느 단계에서 막히는지에 따라 확인할 항목을 나눠서 설명합니다."],"warnings":["설정에서 업그레이드 항목 자체가 보이지 않는다.","PC 상태 확인 앱이 '이 PC는 Windows 11을 실행할 수 없습니다'라고 표시한다.","다운로드 후 설치가 특정 %에서 되돌아간다."],"checks":[{"title":"PC 상태 확인 앱으로 정확한 사유 확인","why":"업그레이드가 막히는 이유가 TPM인지 CPU인지 저장공간인지에 따라 대응 방법이 완전히 다릅니다.","how":"① 웹 브라우저에서 마이크로소프트 공식 홈페이지의 'Windows 11 사양' 페이지에 접속해 'PC 상태 확인' 앱을 내려받으세요. ② 내려받은 설치 파일을 실행해 앱을 설치하세요. ③ 앱을 실행하고 '지금 확인' 버튼을 클릭하세요. ④ 결과 화면에 '이 PC는 Windows 11을 실행할 수 없습니다'라는 문구와 함께 구체적인 미충족 항목(TPM, 보안 부팅, CPU, 저장공간 등)이 표시됩니다 — 이 항목을 확인해야 아래 어떤 방법을 시도해야 할지 알 수 있습니다."},{"title":"TPM 2.0과 보안 부팅 설정 확인","why":"TPM이 메인보드에 있어도 BIOS/UEFI에서 비활성화되어 있으면 미지원으로 표시됩니다.","how":"① PC를 재부팅하면서 부팅 직후 Delete, F2, F10 중 메인보드 제조사에 맞는 키를 빠르게 연타해 BIOS/UEFI 화면으로 들어가세요(화면 하단에 어떤 키인지 안내가 나오는 경우가 많습니다). ② 'Security' 또는 'Advanced' 메뉴에서 'TPM', 'PTT'(인텔), 'fTPM'(AMD) 항목을 찾아 '사용(Enabled)'으로 바꾸세요. ③ 같은 메뉴 근처의 'Secure Boot' 항목도 '사용(Enabled)'으로 바꾸세요(Secure Boot를 켜려면 부팅 모드가 'UEFI'여야 하며 'Legacy' 모드면 먼저 UEFI로 바꿔야 할 수 있습니다). ④ 변경 사항을 저장하고 종료(보통 F10)한 뒤 재부팅하세요. ⑤ 다시 PC 상태 확인 앱을 실행해 조건이 충족됐는지 확인하세요."},{"title":"저장공간과 파티션 방식 확인","why":"업그레이드는 기존 시스템을 보관하면서 진행되므로 평소보다 훨씬 많은 여유 공간이 필요합니다.","how":"① Windows 로고 키를 누르고 '이 PC'를 입력해 C 드라이브의 여유 공간이 64GB 이상인지 확인하세요. 부족하다면 다운로드 폴더, 휴지통, 사용하지 않는 프로그램을 정리하세요. ② Windows 로고 키를 누르고 'msinfo32'를 입력해 실행하세요. ③ '시스템 요약' 화면에서 'BIOS 모드' 항목을 확인하세요 — 'UEFI'면 정상이고 'Legacy'로 표시되면 MBR 방식이라 변환이 필요합니다. ④ MBR→GPT 변환은 디스크의 모든 데이터에 영향을 줄 수 있는 민감한 작업이므로, 중요한 파일을 먼저 백업한 뒤 마이크로소프트 공식 지원 문서의 'MBR2GPT' 도구 안내를 그대로 따르거나, 자신이 없다면 전문 업체·지인에게 도움을 요청하는 것이 안전합니다."}],"deeper":[{"heading":"CPU가 지원 목록에 없을 때","text":"TPM과 보안 부팅을 모두 켜도 안 된다면 CPU 세대가 Microsoft의 공식 지원 목록(대략 8세대 이후 인텔, Ryzen 2000 시리즈 이후)에 없는 경우입니다. 이 경우 레지스트리 우회로 설치는 가능하지만 이후 업데이트 지원이 제한될 수 있어 신중해야 합니다."},{"heading":"설치가 특정 %에서 되돌아갈 때","text":"요구사항은 충족했는데 설치 도중 실패하고 이전 버전으로 롤백된다면, 대개 호환되지 않는 드라이버나 주변기기, 또는 손상된 업데이트 캐시가 원인입니다. 미디어 만들기 도구로 설치 파일을 새로 받아 시도하면 캐시 문제는 배제할 수 있습니다."}],"decision":[{"heading":"TPM·CPU 요구사항 미충족일 때","text":"BIOS에서 TPM/Secure Boot를 켜는 것으로 해결되면 그대로 진행하고, CPU 자체가 목록에 없다면 우회 설치보다 현재 버전(윈도우 10)을 지원 종료 시점까지 유지하는 것도 합리적인 선택입니다."},{"heading":"요구사항은 충족했는데 설치가 실패할 때","text":"저장공간을 늘리고 미디어 만들기 도구로 재시도해 보고, 특정 드라이버(그래픽, 저장장치 컨트롤러)를 최신 버전으로 업데이트한 뒤 다시 시도하세요."}],"examples":["설정 > Windows 업데이트에 업그레이드 항목 자체가 나타나지 않음","PC 상태 확인 앱에 'TPM 2.0을 지원하지 않습니다' 표시","설치 진행률이 60~70%대에서 이전 버전으로 되돌아감"],"mistakes":["TPM/CPU 요구사항을 확인하지 않고 무작정 우회 설치부터 시도하는 것","저장공간을 확인하지 않고 설치 파일부터 반복 다운로드하는 것","설치 실패 후 롤백 로그를 확인하지 않고 같은 방법을 반복하는 것"],"faq":[{"q":"TPM 2.0이 없는 PC에서도 꼭 설치해야 하나요?","a":"필수는 아닙니다. Microsoft가 명시한 요구사항이므로, 없는 상태에서 우회 설치하면 이후 업데이트나 지원에서 제한이 있을 수 있다는 점을 감안해야 합니다."},{"q":"메인보드에 TPM이 있는데도 인식이 안 됩니다.","a":"많은 메인보드가 TPM 관련 기능(Intel PTT, AMD fTPM)을 기본적으로 꺼둔 상태로 출고됩니다. BIOS/UEFI의 보안 또는 고급 설정 메뉴에서 활성화 여부를 확인하세요."},{"q":"업그레이드 대신 새로 설치하면 문제가 해결되나요?","a":"하드웨어 요구사항 미충족이 원인이라면 새로 설치해도 같은 검사에 걸립니다. 다만 캐시나 드라이버 충돌이 원인이었다면 미디어 만들기 도구로 새로 설치하는 편이 더 확실할 수 있습니다."}]},"gpu-not-detected":{"badge":"그래픽","subtitle":"장착한 그래픽카드가 인식되지 않을 때","intro":["그래픽카드를 새로 달았거나 케이스를 옮긴 뒤 화면이 아예 안 나오거나, 장치 관리자에는 보이는데 성능이 내장 그래픽 수준밖에 안 나오는 경우가 대표적인 '인식 안 됨' 증상입니다.","가장 흔한 원인은 거창한 고장이 아니라 슬롯 접촉 불량이나 보조전원 연결 실수입니다. 드라이버 문제로 넘어가기 전에 물리적 연결부터 확인하는 것이 순서입니다.","이 페이지는 화면이 아예 안 나오는 경우와, 화면은 나오지만 장치 관리자에서 제대로 인식이 안 되는 경우를 나눠서 설명합니다."],"warnings":["모니터 케이블을 메인보드가 아닌 그래픽카드 포트에 꽂았는데도 화면이 안 나온다.","장치 관리자에 그래픽카드가 느낌표나 알 수 없는 장치로 표시된다.","카드를 장착한 뒤 성능이 내장 그래픽 수준으로만 나온다."],"checks":[{"title":"카드 재장착 및 슬롯 교체","why":"PCIe 슬롯 접촉 불량이 가장 흔한 원인이며, 카드를 완전히 분리했다가 다시 장착하는 것만으로 해결되는 경우가 많습니다.","how":"① PC 전원을 끄고 전원 케이블을 완전히 뽑으세요. ② 케이스 옆판을 열고 그래픽카드 뒤쪽 고정 나사와 슬롯 옆 고정 클립을 풀어 카드를 완전히 분리하세요. ③ PCIe 슬롯 안에 먼지나 이물질이 있는지 손전등으로 확인하고, 있다면 캔에어로 불어내세요. ④ 카드의 금색 단자 부분을 마른 천으로 가볍게 닦은 뒤 슬롯에 딸깍 소리가 나도록 다시 꽂고 나사를 조이세요. ⑤ 메인보드에 PCIe 슬롯이 여러 개(x16 슬롯이 2개 이상)라면, 다른 슬롯에 꽂아 인식되는지도 비교해보세요."},{"title":"보조전원 케이블 확인","why":"6핀·8핀 보조전원이 절반만 꽂히거나 연결되지 않으면 카드가 부팅되지 않거나 불안정하게 인식됩니다.","how":"① PC 전원을 끄고 케이스 옆판을 여세요. ② 그래픽카드 옆면(보통 위쪽)에 꽂힌 6핀 또는 8핀 보조전원 케이블을 찾으세요. ③ 커넥터를 완전히 뽑았다가 딸깍 소리가 나며 걸림쇠가 잠기는 느낌이 들 때까지 다시 꽂으세요. ④ 카드가 8핀+6핀처럼 여러 커넥터를 요구하는 모델이라면 모든 커넥터가 빠짐없이 꽂혔는지 하나씩 확인하세요. ⑤ 파워서플라이 쪽 끝도 동일하게 다시 꽂아 양쪽 모두 확실히 연결됐는지 확인하세요."},{"title":"장치 관리자에서 인식 상태 확인","why":"화면은 내장 그래픽으로 나오더라도 장치 관리자에서 카드 자체는 확인할 수 있어 소프트웨어 문제인지 하드웨어 문제인지 구분됩니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '디스플레이 어댑터' 항목을 펼치세요. ③ 그래픽카드 이름이 정상적으로 보이는지, 옆에 노란색 느낌표나 검은색 화살표(비활성화 표시)가 있는지 확인하세요. ④ 목록에 그래픽카드 이름 자체가 없고 내장 그래픽만 보인다면 아직 하드웨어 단계에서 인식되지 않은 것이니 위의 재장착·보조전원 항목을 다시 확인하세요. ⑤ 이름은 보이는데 느낌표가 있다면 드라이버 문제이니 아래 항목을 진행하세요."},{"title":"드라이버 완전 제거 후 재설치","why":"이전 그래픽카드 드라이버가 남아 있으면 새 카드와 충돌해 인식에 실패할 수 있습니다.","how":"① 웹 브라우저에서 'Display Driver Uninstaller(DDU)' 공식 홈페이지에 접속해 프로그램을 내려받으세요. ② Windows 로고 키를 누르고 '설정' → '시스템' → '복구' → '고급 시작'의 '지금 다시 시작'을 클릭하세요. ③ '문제 해결' → '고급 옵션' → '시작 설정' → '다시 시작'을 차례로 선택한 뒤 '4' 또는 'F4' 키를 눌러 안전 모드로 부팅하세요. ④ 안전 모드에서 DDU를 실행하고, 제조사(NVIDIA/AMD/Intel)를 선택한 뒤 '지우기 및 다시 시작' 버튼을 클릭하세요. ⑤ 재부팅 후 제조사 공식 홈페이지에서 그래픽카드 모델에 맞는 최신 드라이버를 내려받아 새로 설치하세요."}],"deeper":[{"heading":"화면이 아예 안 나올 때","text":"모니터 케이블을 그래픽카드 포트에 꽂았는데도 신호가 없다면 카드 장착 상태나 보조전원을 먼저 의심해야 합니다. 메인보드 포트에 꽂으면 화면이 나온다면 카드가 인식되지 않고 있다는 뜻입니다."},{"heading":"장치 관리자에는 보이는데 성능이 이상할 때","text":"카드 자체는 인식되지만 드라이버가 제대로 로드되지 않으면 3D 성능이 크게 떨어지거나 특정 프로그램에서만 인식하지 못하는 경우가 있습니다. 이때는 드라이버 재설치가 우선입니다."}],"decision":[{"heading":"물리적 연결 문제일 때","text":"재장착과 보조전원 확인으로 해결되면 그대로 사용하면 되고, 다른 슬롯에서는 인식되는데 특정 슬롯에서만 안 된다면 메인보드 슬롯 자체의 문제일 수 있습니다."},{"heading":"연결은 정상인데 계속 안 될 때","text":"다른 시스템에서도 같은 카드가 인식되지 않는다면 카드 자체의 고장 가능성이 높으므로 재설치보다 카드 교차 테스트를 우선하세요."}],"examples":["그래픽카드 장착 직후 화면이 아예 안 나옴","장치 관리자에 그래픽카드가 느낌표와 함께 표시됨","다른 PC에 꽂았을 때도 인식되지 않음"],"mistakes":["보조전원 연결 확인 없이 드라이버부터 재설치하는 것","모니터 케이블이 메인보드 포트에 꽂혀 있는 걸 모르고 카드 고장으로 단정하는 것","카드 재장착 전에 운영체제부터 재설치하는 것"],"faq":[{"q":"화면은 나오는데 게임 성능이 너무 낮아요. 이것도 인식 안 된 건가요?","a":"네, 그래픽카드가 아닌 내장 그래픽으로 출력되고 있을 가능성이 높습니다. 모니터 케이블이 그래픽카드 포트에 꽂혀 있는지, 장치 관리자에 카드가 정상 표시되는지 확인하세요."},{"q":"다른 그래픽카드를 안 써봤는데 고장인지 어떻게 알 수 있나요?","a":"같은 슬롯에서 다른 카드가 정상 인식되면 슬롯은 정상이고 원래 카드가 의심됩니다. 반대로 다른 카드도 같은 증상이면 슬롯이나 보조전원, 파워서플라이 쪽을 더 봐야 합니다."},{"q":"장치 관리자에는 정상으로 뜨는데 그래픽카드 팬이 안 돌아요. 고장인가요?","a":"대부분 고장이 아닙니다. 최신 그래픽카드는 온도가 낮을 때(보통 50~60도 이하) 팬을 완전히 멈추는 제로팬(0-RPM) 기능이 있어, 평소나 가벼운 작업에서는 팬이 안 도는 것이 정상입니다. 게임 등 부하가 걸렸을 때도 계속 안 돈다면 그때는 팬 고장을 의심하세요."}]},"laptop-external-monitor-flicker":{"badge":"노트북·외부 모니터","subtitle":"노트북에 연결한 외부 모니터가 반복해서 깜빡일 때","intro":["노트북의 내장 화면은 정상인데 HDMI·DisplayPort·USB-C로 연결한 외부 모니터만 깜빡인다면 마우스나 노트북 화면 패널보다 영상 신호 경로를 먼저 확인해야 합니다. 케이블, 포트, 변환 젠더, 도킹 스테이션, 주사율 설정이 서로 맞지 않을 때 화면이 잠깐 검게 변하거나 신호 없음으로 바뀔 수 있습니다.","특히 도킹 스테이션에 모니터 두 대를 연결하거나 고해상도·고주사율·HDR을 함께 사용할 때는 개별 장치가 지원하더라도 노트북 포트와 도킹 장치의 전체 대역폭을 초과할 수 있습니다. 한 대씩 연결했을 때와 두 대를 동시에 연결했을 때를 비교하면 이 문제를 빠르게 구분할 수 있습니다.","이 가이드는 외부 모니터 자체의 고장으로 단정하기 전에 직접 연결, 기본 주사율, 드라이버, 도킹 환경을 순서대로 나누어 확인하는 방법을 설명합니다."],"warnings":["내장 화면은 정상인데 외부 모니터만 1~2초씩 검게 변한다.","노트북을 움직이거나 케이블을 건드릴 때 깜빡임 빈도가 달라진다.","도킹 스테이션 또는 USB-C 허브를 통할 때만 증상이 나타난다.","두 대를 연결할 때만 화면이 끊기고 한 대는 정상이다."],"checks":[{"title":"도킹 장치를 빼고 노트북에 직접 연결","why":"직접 연결에서 정상이라면 모니터보다 도킹 스테이션, 허브 전원, MST 또는 USB-C 영상 출력 경로를 먼저 의심할 수 있습니다.","how":"① 도킹 스테이션, KVM 스위치, USB 허브를 모두 제거하세요. ② 모니터 케이블을 노트북의 HDMI, DP, 또는 영상 출력을 지원하는 USB-C 포트에 직접 연결하세요(어느 포트가 영상 출력을 지원하는지 노트북 제조사 홈페이지에서 모델명으로 확인하세요 — 일부 USB-C 포트는 충전 전용입니다). ③ 이 상태로 최소 10분 이상 사용하며 깜빡임이 재현되는지 관찰하세요. ④ 직접 연결에서는 안정적이라면 도킹·허브·MST 대역폭 쪽 문제로 확정할 수 있습니다."},{"title":"케이블·포트·입력 소스 교차 확인","why":"케이블 규격이나 특정 포트의 접촉 문제가 있으면 화면 전체가 꺼지지 않고 짧은 신호 끊김으로 나타날 수 있습니다.","how":"① 다른 정상 작동이 확인된 HDMI 또는 DP 케이블로 교체해보세요. ② 모니터의 다른 입력 포트(HDMI2 등)로도 바꿔 연결해보세요. ③ 노트북에 출력 포트가 여러 개라면 다른 포트로도 바꿔 시험하세요. ④ USB-C to HDMI 같은 변환 젠더를 사용 중이라면, 젠더 없이 케이블 규격이 맞는 포트로 직접 연결해 비교하세요(젠더 자체가 원인인 경우가 흔합니다)."},{"title":"해상도·주사율·HDR을 기본값으로 낮추기","why":"고주사율과 HDR, 가변 주사율은 케이블·포트·도킹 장치가 감당해야 하는 대역폭을 높입니다.","how":"① 바탕화면을 우클릭해 '디스플레이 설정'을 열고 외부 모니터를 선택하세요. ② '고급 디스플레이'로 들어가 새로고침 빈도를 60Hz로 낮추세요. ③ 해상도를 모니터의 기본(권장) 해상도로 설정하세요. ④ HDR 옵션이 켜져 있다면 끄고, 가변 주사율(FreeSync/G-Sync) 옵션도 꺼보세요. ⑤ 이 상태로 안정적이라면, 설정을 하나씩(주사율→해상도→HDR 순으로) 다시 올려보며 어느 지점에서 다시 깜빡이는지 한계를 찾으세요."},{"title":"그래픽 드라이버와 전원 모드 확인","why":"노트북은 배터리·전원 연결 상태에 따라 내장 GPU와 외장 GPU를 전환할 수 있어 드라이버 충돌이나 화면 재초기화가 발생할 수 있습니다.","how":"① 전원 어댑터를 연결한 상태에서 증상이 나타나는지, 배터리로만 작동할 때는 어떤지 각각 비교하세요. ② Windows 로고 키를 누르고 '장치 관리자'를 입력해 '디스플레이 어댑터'에 내장그래픽(Intel/AMD)과 외장그래픽(NVIDIA 등) 두 개가 모두 정상적으로 표시되는지 확인하세요. ③ 각 그래픽 드라이버를 제조사 홈페이지 또는 노트북 제조사 지원 페이지에서 최신 버전으로 업데이트하세요. ④ 화면이 깜빡이거나 꺼질 때 Windows 로고 키 + Ctrl + Shift + B를 눌러 화면이 복구되는지 확인하고, 복구된다면 그래픽 드라이버 재설정으로 일시 완화되는 문제임을 기록해두세요."},{"title":"이벤트 뷰어에서 그래픽 오류 확인","why":"화면 깜빡임 시각과 이벤트 기록이 일치하면 케이블만이 아니라 그래픽 드라이버 재설정 또는 GPU 출력 문제가 함께 있었는지 판단할 수 있습니다.","how":"① Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행하세요. ② 'Windows 로그' → '시스템'을 클릭하세요. ③ 화면이 깜빡였던 시각을 기억해두고, 그 시각 근처에 원본이 'Display'(이벤트 ID 4101)이거나 'nvlddmkm'(153), 'amdwddmg'로 표시된 경고·오류가 있는지 확인하세요. ④ 이런 기록이 발견됐다고 해서 바로 그래픽카드 고장으로 단정하지 말고, 위에서 진행한 케이블 교체·주사율 낮추기 비교 결과와 함께 종합적으로 판단하세요."},{"title":"한 대·두 대 출력과 안전 모드 비교","why":"한 대만 연결하면 정상이고 두 대에서만 깜빡이면 모니터 자체보다 MST·도킹 대역폭 또는 그래픽 출력 조합의 문제일 가능성이 높습니다.","how":"① 모니터를 하나씩 단독으로 연결해 각각 정상적인지 확인하세요. ② 두 모니터를 동시에 연결했을 때만 증상이 나타나는지 비교하세요. ③ Windows 로고 키를 누르고 '설정' → '시스템' → '복구' → '지금 다시 시작'으로 안전 모드에 진입해(문제 해결 → 고급 옵션 → 시작 설정 → 다시 시작 → F4) 같은 증상이 재현되는지 확인하세요. ④ 안전 모드에서는 정상이라면 그래픽 드라이버, 게임 오버레이 프로그램, 노트북 제조사의 화면 관리 유틸리티(색 관리, 자동 밝기 조절 등)를 하나씩 꺼보며 원인을 좁히세요."}],"deeper":[{"heading":"외부 모니터만 깜빡이고 내장 화면은 정상인 경우","text":"노트북 패널 자체의 고장보다는 외부 출력 경로의 문제일 가능성이 높습니다. 동일 모니터를 다른 PC에 연결하고, 같은 노트북에 다른 모니터를 연결해 모니터·케이블·노트북 중 어디를 따라 증상이 이동하는지 확인하세요."},{"heading":"도킹 스테이션에서만 발생하는 경우","text":"도킹 장치의 전원 어댑터가 부족하거나 펌웨어·MST 드라이버가 오래된 경우, 모니터가 잠깐씩 재협상하면서 깜빡일 수 있습니다. 도킹 전원을 연결하고 펌웨어를 확인한 뒤 모니터 한 대와 60Hz 설정으로 다시 시험하세요."},{"heading":"게임이나 영상 재생에서만 발생하는 경우","text":"전체 화면 전환, VRR, HDR, 오버레이가 그래픽 출력 모드를 바꾸면서 발생할 수 있습니다. 창 모드와 기본 주사율에서 비교하고 Discord·Xbox Game Bar·GPU 오버레이를 잠시 끈 뒤 재현 여부를 확인하세요."}],"decision":[{"heading":"케이블을 바꾸면 해결될 때","text":"기존 케이블의 규격·손상·접촉 문제가 원인일 가능성이 큽니다. 고해상도·고주사율을 사용한다면 모니터와 노트북 양쪽이 지원하는 규격의 인증 케이블을 사용하세요."},{"heading":"60Hz·직접 연결에서만 안정될 때","text":"도킹 스테이션이나 연결 경로의 대역폭·펌웨어·전원 조건이 한계였을 가능성이 높습니다. 두 모니터의 해상도와 주사율 조합, USB-C 영상 출력 사양을 확인하세요."},{"heading":"다른 케이블·포트·모니터에서도 계속될 때","text":"그래픽 드라이버, 노트북의 영상 출력 포트, GPU 전원·보드 문제까지 범위를 넓혀야 합니다. 화면 깜빡임 시각의 이벤트 기록과 노트북 제조사 진단 도구 결과를 함께 보관해 점검을 요청하세요."}],"examples":["USB-C 도킹 스테이션에 연결한 144Hz 모니터가 몇 초마다 검게 변함","HDMI 직접 연결은 정상인데 USB-C 변환 젠더를 사용하면 깜빡임","모니터 두 대를 연결할 때만 한쪽 화면이 반복해서 끊김"],"mistakes":["외부 모니터만 깜빡이는데 노트북 패널이나 마우스부터 교체하는 것","케이블과 도킹 환경을 그대로 둔 채 그래픽 드라이버만 반복 설치하는 것","지원 사양을 확인하지 않고 해상도·주사율·HDR을 동시에 최대로 설정하는 것"],"faq":[{"q":"노트북 HDMI는 정상인데 USB-C 모니터만 깜빡입니다.","a":"USB-C 포트의 DP Alt Mode 지원 여부, 케이블 규격, 허브·변환 젠더의 영상 대역폭을 먼저 확인하세요. USB-C가 충전·데이터만 지원하고 영상 출력을 지원하지 않는 노트북도 있습니다."},{"q":"모니터를 60Hz로 낮추면 괜찮아집니다.","a":"고주사율 설정을 처리하는 케이블·포트·도킹 장치의 대역폭 또는 호환성 문제 가능성이 높습니다. 직접 연결과 적합한 케이블로 확인한 뒤 지원 가능한 주사율을 사용하세요."},{"q":"외부 모니터 깜빡임이 그래픽카드 고장인가요?","a":"그것만으로는 확정할 수 없습니다. 다른 케이블·포트·모니터와 기본 주사율을 비교하고, 내장 화면까지 함께 깜빡이는지와 Display·그래픽 드라이버 이벤트가 반복되는지를 함께 확인해야 합니다."}]},"screen-flicker":{"badge":"그래픽","subtitle":"화면이 지지직거리며 깜빡이거나 떨릴 때","intro":["화면이 지지직거리는 듯 깜빡이는 증상은 화면이 아예 안 나오는 것과 달리, 정상적으로 보이다가 순간적으로 어두워지거나 줄무늬가 지나가는 증상입니다. 원인은 소프트웨어(드라이버·주사율)와 하드웨어(케이블·패널) 양쪽에 걸쳐 있습니다.","가장 먼저 구분해야 할 것은 특정 프로그램에서만 발생하는지, 바탕화면에서도 발생하는지입니다. 특정 프로그램에서만 발생하면 드라이버·주사율 문제일 가능성이 크고, 항상 발생하면 케이블이나 하드웨어 쪽 비중이 높아집니다.","이 페이지는 소프트웨어 설정부터 하드웨어 점검까지 순서대로 안내합니다."],"warnings":["특정 게임이나 영상 재생 중에만 깜빡인다.","바탕화면에서도 항상 깜빡이거나 줄무늬가 보인다.","케이블을 건드리면 깜빡임이 심해지거나 사라진다."],"checks":[{"title":"그래픽 드라이버 업데이트 또는 롤백","why":"드라이버 버전에 따라 특정 프로그램에서 깜빡임이 발생하는 알려진 문제가 있을 수 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '디스플레이 어댑터'에서 그래픽카드를 더블클릭한 뒤 '드라이버' 탭을 클릭하세요. ③ 증상이 최근 드라이버 업데이트 직후 시작됐다면 '이전 드라이버로 롤백' 버튼을 클릭하세요. ④ 롤백 옵션이 없다면 반대로, 그래픽카드 제조사(NVIDIA/AMD/Intel) 홈페이지에서 최신 드라이버를 내려받아 설치해보세요. ⑤ 각 방법 후 재부팅해 깜빡임이 사라지는지 비교하세요."},{"title":"NVIDIA 그래픽카드라면 10비트 색상 출력 또는 최신 드라이버로 전환","why":"2026년 8월 말 배포된 NVIDIA 지포스 616.56 드라이버가 일부 모니터에서 순간적으로 화면이 어두워지거나 줄무늬가 보이는 깜빡임 문제를 일으킨 것으로 공식 확인됐습니다. 이후 배포된 616.86·616.92 버전이 상당 부분 고쳤지만, 일부 환경에서는 여전히 남아있을 수 있습니다.","how":"① 그래픽카드 제조사가 NVIDIA인지 확인하세요(작업 관리자 → 성능 탭 → GPU에서 확인 가능). ② NVIDIA 앱(또는 GeForce Experience)을 열어 '드라이버' 탭에서 현재 설치된 드라이버 버전을 확인하세요. ③ 616.92 이상의 최신 버전으로 업데이트하세요. ④ 업데이트 후에도 깜빡이면 바탕화면을 마우스 오른쪽 버튼으로 클릭해 'NVIDIA 제어판'을 열고 '디스플레이' → '해상도 변경'으로 들어가세요. ⑤ '출력 색 농도' 항목을 '10bpc'(10비트)로 바꾸고 적용한 뒤 깜빡임이 사라지는지 확인하세요. ⑥ 그래도 안 되면 Windows 로고 키를 누르고 '디스플레이 설정'에서 'HDR' 항목 아래 색 관리를 Windows가 자동으로 하도록 설정하는 옵션을 켜보세요."},{"title":"주사율 설정 확인","why":"모니터가 지원하지 않는 주사율로 설정되어 있으면 화면이 불안정하게 깜빡일 수 있습니다.","how":"① 바탕화면을 마우스 오른쪽 버튼으로 클릭해 '디스플레이 설정'을 선택하세요. ② 아래로 스크롤해 '고급 디스플레이'(또는 '디스플레이 어댑터 속성')를 클릭하세요. ③ '새로 고침 빈도(Hz)' 항목의 현재 값을 확인하세요. ④ 모니터 제조사 홈페이지나 모니터 박스에서 공식 지원 주사율을 확인해, 현재 설정된 값과 일치하는지 비교하세요. ⑤ 지원하지 않는 값으로 설정되어 있다면 목록에서 공식 지원 주사율(보통 60Hz)로 바꾸세요."},{"title":"영상 케이블 재연결·교체","why":"HDMI·DP 케이블 연결이 헐겁거나 손상되면 신호가 끊기면서 깜빡임으로 나타납니다.","how":"① PC와 모니터 양쪽의 HDMI/DP 케이블을 완전히 뽑았다가 딸깍 소리가 나도록 다시 꽂으세요. ② 케이블이 꺾이거나 눌린 부분이 없는지 육안으로 확인하세요. ③ 여분의 케이블이 있다면 다른 케이블로 교체해 깜빡임이 사라지는지 비교하세요. ④ 다른 포트(HDMI 여러 개 중 다른 번호, 또는 DP 포트)로도 옮겨 연결해 비교하세요."},{"title":"적응형 밝기·절전 설정 끄기","why":"노트북의 자동 밝기 조절 기능이 밝기를 계속 바꾸면서 깜빡이는 것처럼 보일 수 있습니다.","how":"① Windows 로고 키를 누르고 '밝기 및 색'을 입력해 설정 화면을 여세요(노트북 기준). ② '전원 상태에 따라 밝기를 자동으로 변경' 옵션을 꺼보세요. ③ Windows 로고 키를 누르고 '전원 및 절전 설정'을 입력해 들어간 뒤 '전원 관련 추가 설정' → '고급 전원 관리 설정 변경'을 클릭하세요. ④ '디스플레이' 항목을 펼쳐 '적응형 밝기 조정 사용'이 있다면 '사용 안 함'으로 바꾸세요. ⑤ 저장 후 깜빡임이 줄었는지 비교하세요."},{"title":"부하 테스트(FurMark 등)로 하드웨어 결함 확인","why":"안전 모드에서 DDU로 드라이버를 완전히 지우고 재설치했는데도 증상이 똑같이 재현된다면 소프트웨어 문제는 배제된 것이므로, 그래픽카드 자체가 부하를 견디는지 직접 확인해봐야 합니다.","how":"① 무료 프로그램 FurMark를 내려받아 실행하세요. ② 테스트 버튼을 누르기 전, 프로그램 창이 뜨는 순간부터 화면이나 키보드가 멈추는지 먼저 확인하세요. ③ 테스트 버튼을 눌러 실제 부하를 걸었을 때도 화면 신호가 끊기거나 시스템이 멈추는지 확인하세요. ④ 부하를 걸기도 전에 창만 떠도 멈춘다면 온도·전력보다 그래픽카드 자체의 하드웨어 결함일 가능성이 매우 높습니다. ⑤ 증상이 나타나는 순간을 스마트폰으로 촬영해두면 이후 수리 접수 시 판단에 도움이 됩니다."}],"deeper":[{"heading":"2026년 8월 말 NVIDIA 드라이버 업데이트 직후부터 깜빡인다면","text":"NVIDIA 지포스 616.56 드라이버(2026년 8월 말 배포)가 일부 모니터에서 짧은 검은 화면·흰 화면 깜빡임, 밝기 급변, 색 왜곡을 일으키는 문제가 다수 보고되며 NVIDIA가 공식적으로 후속 수정을 배포했습니다. 616.86 핫픽스가 브라우저 깜빡임과 원격 데스크톱 검은 화면 문제를 먼저 고쳤고, 2026년 9월 9일 배포된 616.92(WHQL 정식 버전)에서 남은 깜빡임 문제도 반영됐습니다. 증상이 시작된 시점이 그래픽 드라이버 업데이트와 겹친다면 최신 버전으로 업데이트하거나, 그래도 남아있다면 NVIDIA 제어판에서 출력 색 농도를 10비트로 바꾸는 것이 가장 많이 확인된 임시 해결책입니다."},{"heading":"특정 프로그램에서만 깜빡일 때","text":"게임이나 특정 앱에서만 깜빡인다면 해당 프로그램의 전체 화면 최적화 설정이나 그래픽 드라이버의 특정 기능(가변 주사율 등)과 충돌하는 경우가 많습니다."},{"heading":"노트북 화면 자체의 문제일 때","text":"외부 모니터에 연결했을 때는 문제가 없고 노트북 내장 화면에서만 깜빡인다면 디스플레이 패널이나 연결 케이블(플렉스 케이블) 노후화를 의심해야 합니다."},{"heading":"DDU 클린 재설치 후에도 똑같이 재현될 때","text":"안전 모드에서 DDU(Display Driver Uninstaller)로 기존 드라이버 잔여 파일까지 완전히 지운 뒤 재설치했는데도 증상이 동일하게 재현된다면, 드라이버 손상이나 설정 문제일 가능성은 사실상 배제됩니다. 이 상태에서 FurMark 같은 부하 테스트 프로그램을 실행했을 때 부하를 걸기도 전에 프로그램 창만 떠도 화면과 키보드가 함께 멈춘다면, 그래픽카드가 3D 그래픽 컨텍스트 자체를 감당하지 못하는 상태라는 뜻이라 하드웨어 결함 쪽에 무게가 실립니다."}],"decision":[{"heading":"설정 변경으로 해결될 때","text":"주사율 조정이나 적응형 밝기를 끄는 것으로 해결되면 소프트웨어·설정 문제였던 것이므로 그대로 사용하면 됩니다."},{"heading":"케이블 교체로도 해결되지 않을 때","text":"다른 케이블, 다른 포트에서도 계속 깜빡인다면 모니터나 그래픽카드, 노트북 패널 자체의 하드웨어 점검이 필요합니다."},{"heading":"FurMark 실행 직후 즉시 멈출 때","text":"부하 테스트를 시작하기도 전에, 프로그램을 켜자마자 화면과 키보드가 함께 멈춘다면 발열이나 전원 문제보다 그래픽카드 자체의 결함일 가능성이 매우 높습니다. 다른 그래픽카드로 교차 테스트하거나 교체를 검토하세요."}],"examples":["게임 실행 중에만 화면이 순간적으로 어두워짐","노트북 화면 각도를 바꾸면 깜빡임이 심해짐","외부 모니터 연결 시에는 문제없음"],"mistakes":["주사율 설정을 확인하지 않고 바로 모니터 교체를 고려하는 것","케이블 상태를 점검하지 않고 드라이버만 계속 재설치하는 것"],"faq":[{"q":"노트북 화면 각도를 바꾸면 깜빡임이 심해지는데 왜 그런가요?","a":"화면과 본체를 잇는 연결 케이블이 눌리거나 헐거워졌을 가능성이 있습니다. 이 경우 소프트웨어 문제가 아니라 하드웨어 점검(서비스센터 방문)이 필요합니다."},{"q":"외부 모니터는 괜찮은데 노트북 화면만 깜빡여요.","a":"그래픽카드나 드라이버보다 노트북 자체의 디스플레이 패널이나 연결부 쪽 문제일 가능성이 높습니다."}]},"activation-error":{"badge":"정품 인증","subtitle":"윈도우 정품 인증이 안 되거나 오류가 반복될 때","intro":["정품 인증 오류는 크게 두 가지 상황으로 나뉩니다. 이전에 정상적으로 인증되어 있었는데 하드웨어를 교체한 뒤 인증이 풀린 경우와, 처음부터 제품 키나 라이선스 자체에 문제가 있는 경우입니다.","메인보드를 교체했다면 디지털 라이선스가 이전 하드웨어 정보에 묶여 있어서 자동으로 재인증되지 않는 경우가 가장 흔합니다. 이때는 제품 키를 새로 입력하는 것보다 Microsoft 계정 연결 여부를 먼저 확인하는 것이 빠릅니다.","이 페이지는 정확한 오류 코드를 먼저 확인한 뒤, 상황별로 점검 순서를 나눠서 설명합니다."],"warnings":["설정 > 정품 인증 화면에 오류 코드나 '해당 없음'이 표시된다.","최근 메인보드나 CPU를 교체한 적이 있다.","같은 제품 키로 다른 PC에서도 윈도우를 설치한 적이 있다."],"checks":[{"title":"정확한 오류 코드 확인","why":"오류 코드에 따라 원인이 완전히 다르기 때문에, '안 된다'는 상태보다 정확한 코드를 먼저 확인해야 합니다.","how":"① Windows 로고 키를 누르고 '정품 인증'을 입력해 실행하세요(또는 설정 → 시스템 → 정품 인증). ② 화면에 표시되는 오류 코드(예: 0x803F7001, 0xC004F034 등)와 문구를 그대로 스마트폰으로 촬영하거나 메모해 두세요. ③ 화면 아래쪽에 'Windows 버전' 정보(Home/Pro 등)도 함께 확인해 메모하세요 — 오류 코드에 따라 원인과 해결 방법이 완전히 다르므로, 이후 검색하거나 문의할 때도 이 코드가 있어야 정확한 안내를 받을 수 있습니다."},{"title":"정품 인증 문제 해결사 실행","why":"Microsoft가 제공하는 문제 해결사가 흔한 원인(하드웨어 변경, 라이선스 불일치)을 자동으로 진단해줍니다.","how":"① Windows 로고 키를 누르고 '정품 인증'을 입력해 설정 화면을 여세요. ② '문제 해결' 버튼(파란색 링크로 표시됨)을 클릭하세요 — 이 버튼은 정품 인증에 실패했을 때만 나타납니다. ③ 화면에 뜨는 안내 문구를 하나씩 읽고 그대로 따라가세요(예: '최근 하드웨어를 변경했나요?' 같은 질문에 상황에 맞게 답합니다). ④ Microsoft 계정으로 로그인하라는 안내가 나오면 이전에 이 PC에서 사용하던 Microsoft 계정으로 로그인하세요. ⑤ 완료 후 정품 인증 화면으로 돌아가 상태가 '활성화됨'으로 바뀌었는지 확인하세요."},{"title":"Microsoft 계정 연결 여부 확인","why":"디지털 라이선스가 Microsoft 계정에 연결되어 있으면 하드웨어를 교체해도 문제 해결사를 통해 재인증이 가능합니다.","how":"① Windows 로고 키를 누르고 '설정'을 실행한 뒤 '계정' → '사용자 정보'로 들어가 현재 Microsoft 계정으로 로그인되어 있는지 확인하세요('로컬 계정'으로 표시되면 아직 Microsoft 계정이 아닙니다). ② 로컬 계정이라면 같은 화면에서 '대신 Microsoft 계정으로 로그인'을 클릭해 계정을 연결하세요(이 PC를 정품 인증했던 적이 있는 계정이어야 합니다). ③ 계정을 연결한 뒤 설정 → 시스템 → 정품 인증으로 가서 상태가 바뀌었는지 확인하세요. ④ 이전에 하드웨어(메인보드 등)를 교체했다면, 정품 인증 문제 해결사 화면에서 '이 장치에서 최근 하드웨어를 변경했습니다' 항목을 선택해 재인증을 진행하세요."},{"title":"네트워크·DNS 연결 확인","why":"인증 서버에 연결하지 못하면 정상적인 라이선스도 일시적으로 인증되지 않은 것처럼 표시될 수 있습니다.","how":"① 웹 브라우저로 아무 사이트나 접속해 인터넷이 정상적으로 되는지 먼저 확인하세요. ② Windows 로고 키를 누르고 '설정'을 실행한 뒤 '네트워크 및 인터넷'에서 연결 상태를 확인하세요. ③ DNS 문제가 의심되면(다른 사이트는 되는데 특정 서비스만 안 되는 경우), 네트워크 어댑터 속성에서 DNS 서버 주소를 8.8.8.8(구글) 또는 1.1.1.1(클라우드플레어)로 수동 설정해보세요. ④ 회사망이나 공용 와이파이를 쓰고 있다면 방화벽이 Microsoft 인증 서버 접속을 막고 있을 수 있으니, 가능하면 가정용 네트워크에서 다시 시도해보세요."}],"deeper":[{"heading":"하드웨어 교체 후 인증이 풀렸을 때","text":"메인보드 교체는 윈도우 입장에서 '다른 PC'로 인식되는 가장 큰 변경입니다. Microsoft 계정에 라이선스가 연결되어 있었다면 문제 해결사에서 '최근 이 장치의 하드웨어를 변경했습니다'를 선택해 재인증할 수 있습니다."},{"heading":"제품 키 자체에 문제가 있을 때","text":"중고 PC나 저가로 구매한 키의 경우, 이미 다른 기기에서 사용 중이거나 볼륨 라이선스(기업용)여서 개인 재설치에 사용할 수 없는 경우가 있습니다. 이 경우 문제 해결사로는 해결되지 않습니다."}],"decision":[{"heading":"하드웨어 변경이 원인일 때","text":"Microsoft 계정 연결과 문제 해결사만으로 대부분 해결됩니다. 별도로 제품 키를 다시 구매할 필요는 없습니다."},{"heading":"문제 해결사로도 안 될 때","text":"제품 키의 출처(정식 구매 여부)를 다시 확인해야 하며, 특히 저가로 구매한 키라면 유효성 자체를 의심해야 합니다."}],"examples":["메인보드 교체 후 정품 인증이 '해당 없음'으로 표시됨","설치 직후부터 특정 오류 코드와 함께 인증이 안 됨","인터넷에 연결되어 있는데도 인증 서버 연결 오류가 뜸"],"mistakes":["오류 코드를 확인하지 않고 무작정 제품 키를 재입력하는 것","Microsoft 계정 연결 여부를 확인하지 않고 재설치부터 시도하는 것","출처가 불분명한 제품 키의 유효성을 의심하지 않는 것"],"faq":[{"q":"메인보드만 바꿨는데 왜 인증이 풀리나요?","a":"윈도우의 디지털 라이선스는 하드웨어 정보(특히 메인보드)를 기준으로 활성화 상태를 기억합니다. 메인보드가 바뀌면 다른 PC로 인식되어 재인증이 필요합니다."},{"q":"Microsoft 계정에 연결해두지 않았으면 어떻게 하나요?","a":"이 경우 문제 해결사의 자동 재인증이 어려울 수 있어, 정품 제품 키를 가지고 있다면 직접 입력하거나 Microsoft 고객센터 문의가 필요할 수 있습니다."}]},"printer-offline":{"badge":"프린터","subtitle":"이미 설치된 프린터가 오프라인으로 표시될 때","intro":["이 증상은 프린터를 처음 설치하는 과정에서 막히는 것과는 다릅니다. 어제까지 잘 되던 프린터가 갑자기 '오프라인'으로 표시되거나 인쇄 대기열에서 진행되지 않는 경우입니다.","가장 흔한 원인은 인쇄 스풀러 서비스가 멈췄거나, 프린터가 절전 모드로 들어가 연결이 끊긴 경우입니다. 드라이버를 재설치하기 전에 이 두 가지부터 확인하면 대부분 빠르게 해결됩니다.","네트워크 프린터(와이파이)와 USB 직결 프린터는 원인이 조금씩 다르므로 연결 방식에 따라 나눠서 확인하는 것이 좋습니다."],"warnings":["프린터 상태 표시가 '오프라인'으로 바뀌어 있다.","인쇄를 눌러도 대기열에만 쌓이고 진행되지 않는다.","프린터 전원은 켜져 있는데 컴퓨터에서 연결이 안 된 것처럼 표시된다."],"checks":[{"title":"인쇄 스풀러 서비스 재시작","why":"인쇄 작업을 관리하는 스풀러 서비스가 멈추면 프린터가 정상이어도 오프라인으로 표시됩니다.","how":"① Windows 로고 키를 누르고 'services.msc'를 입력한 뒤 Enter를 누르세요. ② 목록에서 아래로 스크롤해 'Print Spooler'를 찾으세요. ③ 더블클릭해 속성 창을 열고 '서비스 상태'가 '중지됨'이면 '시작' 버튼을 클릭하세요. ④ 이미 실행 중이라면 '중지' 버튼을 눌러 완전히 멈춘 뒤 다시 '시작' 버튼을 눌러 재시작하세요. ⑤ '시작 유형'이 '자동'으로 되어 있는지도 확인하고 '확인'을 눌러 저장하세요. ⑥ 프린터가 다시 온라인으로 표시되는지 확인하세요."},{"title":"프린터 전원·연결 상태 확인","why":"프린터가 절전 모드에 들어갔거나 와이파이·USB 연결이 끊기면 오프라인으로 표시됩니다.","how":"① 프린터 전원 버튼을 눌러 완전히 껐다가 10초 후 다시 켜세요. ② 네트워크(Wi-Fi) 프린터라면 프린터 자체의 화면이나 버튼으로 들어가 현재 연결된 Wi-Fi 이름이 PC와 같은 공유기인지 확인하세요. ③ USB로 연결한 프린터라면 케이블이 양쪽 다 확실히 꽂혀 있는지 확인하고, 가능하면 다른 USB 포트나 케이블로 바꿔 연결해보세요. ④ 프린터가 절전 모드에 들어가 있다면 프린터의 아무 버튼이나 눌러 깨운 뒤 PC에서 다시 인식되는지 확인하세요."},{"title":"기본 프린터로 다시 설정","why":"오프라인 모드로 잘못 전환되어 있거나 다른 프린터가 기본으로 설정되어 있으면 인쇄가 엉뚱한 곳으로 전송될 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정'을 실행한 뒤 '블루투스 및 장치' → '프린터 및 스캐너'로 들어가세요. ② 상단에 '기본 프린터를 Windows에서 관리' 옵션이 켜져 있다면 꺼서, 원하는 프린터를 직접 기본으로 지정할 수 있게 하세요. ③ 사용할 프린터를 클릭해 '기본값으로 설정'을 선택하세요. ④ 해당 프린터를 클릭해 열리는 화면에서 '인쇄 대기열 열기'를 선택한 뒤, 상단 메뉴의 '프린터'에서 '오프라인으로 프린터 사용' 항목에 체크가 되어 있다면 클릭해 체크를 해제하세요."},{"title":"프린터 드라이버 재설치","why":"드라이버가 최근 업데이트와 충돌하면 정상 연결 상태에서도 오프라인으로 오인식될 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정' → '블루투스 및 장치' → '프린터 및 스캐너'로 들어가세요. ② 문제가 있는 프린터를 클릭해 '제거'를 선택하세요. ③ 제조사(HP, Canon, Epson, 삼성 등) 공식 홈페이지에서 정확한 모델명으로 검색해 최신 드라이버 설치 파일을 내려받으세요. ④ 내려받은 설치 파일을 실행해 화면 안내에 따라 프린터를 다시 추가하세요. ⑤ 재설치 후에도 오프라인으로 표시되면 위의 '인쇄 스풀러 서비스 재시작' 항목을 다시 한번 진행하세요."}],"deeper":[{"heading":"네트워크(와이파이) 프린터일 때","text":"공유기를 재시작했거나 프린터의 IP 주소가 바뀌면 컴퓨터가 이전 주소로 계속 연결을 시도해 오프라인으로 표시될 수 있습니다. 프린터 속성의 포트 설정에서 IP 주소가 현재와 일치하는지 확인하세요."},{"heading":"USB 직결 프린터일 때","text":"USB 포트나 케이블 접촉 불량도 같은 증상을 만듭니다. 다른 USB 포트에 꽂아보고, 허브를 거치지 않고 본체에 직접 연결해 재현 여부를 확인하세요."}],"decision":[{"heading":"스풀러 재시작으로 해결될 때","text":"일시적인 서비스 오류였던 것이므로 그대로 사용하면 되지만, 반복된다면 스풀러를 자동 재시작하도록 서비스 복구 옵션을 설정해두면 편합니다."},{"heading":"IP·연결 문제로 반복될 때","text":"네트워크 프린터라면 공유기에서 프린터에 고정 IP를 할당해두면 IP 변경으로 인한 오프라인 표시를 예방할 수 있습니다."}],"examples":["공유기를 재시작한 뒤부터 프린터가 오프라인으로 표시됨","인쇄 대기열에 문서가 쌓이기만 하고 출력되지 않음","다른 PC에서는 정상 인쇄되는데 이 PC에서만 오프라인으로 뜸"],"mistakes":["스풀러 서비스 상태를 확인하지 않고 드라이버부터 재설치하는 것","네트워크 프린터의 IP 주소 변경 가능성을 확인하지 않는 것","오프라인 프린터 사용 옵션이 켜져 있는 걸 모르고 계속 재부팅만 하는 것"],"faq":[{"q":"프린터는 정상인데 왜 컴퓨터에서만 오프라인으로 뜨나요?","a":"인쇄 스풀러 서비스 문제이거나, 컴퓨터가 기억하고 있는 프린터 주소(IP 또는 포트)가 실제와 달라졌을 가능성이 높습니다."},{"q":"다른 PC에서는 잘 되는데 제 PC에서만 안 됩니다.","a":"이 경우 프린터 자체보다 해당 PC의 스풀러 서비스나 드라이버, 저장된 포트 설정 문제일 가능성이 큽니다."}]},"ms-account-login-fail":{"badge":"계정","subtitle":"Microsoft 계정으로 로그인이 안 되거나 반복 실패할 때","intro":["이 증상은 윈도우 정품 인증 문제와는 다릅니다. 정품 인증은 되어 있지만 Microsoft 계정 자체에 로그인이 안 되거나, 로그인 화면에서 비밀번호를 입력해도 계속 튕기는 경우입니다.","가장 먼저 확인할 것은 이 PC만의 문제인지, 계정 자체의 문제인지 구분하는 것입니다. 웹브라우저에서 같은 계정으로 로그인해보면 범위를 빠르게 좁힐 수 있습니다.","이 페이지는 계정 자체 문제와 PC(윈도우) 쪽 문제로 나눠서 점검 순서를 설명합니다."],"warnings":["로그인 화면에서 비밀번호를 입력해도 계속 실패한다.","2단계 인증 코드가 오지 않거나 인증 후에도 로그인이 안 된다.","웹브라우저에서는 같은 계정으로 정상 로그인된다."],"checks":[{"title":"웹브라우저에서 로그인 시도","why":"브라우저에서 정상 로그인되면 계정 자체는 문제없고 윈도우(이 PC) 쪽 설정이 원인이라는 뜻입니다.","how":"① 스마트폰이나 다른 PC의 웹 브라우저에서 account.microsoft.com 에 접속하세요. ② 로그인이 안 되는 계정의 이메일과 비밀번호로 로그인을 시도하세요. ③ 정상적으로 로그인된다면 계정 자체(비밀번호, 잠금 등)는 문제가 없는 것이므로, 원인은 이 PC(Windows)의 설정 쪽입니다 — 아래 항목들을 이어서 확인하세요. ④ 웹에서도 로그인이 안 된다면 '비밀번호 찾기'로 비밀번호를 재설정하거나, 계정 자체에 보안 문제(이상 로그인 감지 등)가 있는지 화면 안내를 확인하세요."},{"title":"시스템 시간·시간대 확인","why":"PC의 시간이 실제 시간과 크게 어긋나면 보안 인증 절차가 실패해 로그인이 막힐 수 있습니다.","how":"① 화면 오른쪽 아래 시계를 클릭한 뒤 '날짜 및 시간 설정'을 선택하세요. ② '시간 자동 설정'과 '시간대 자동 설정'이 모두 켜져 있는지 확인하세요. ③ 꺼져 있었다면 켠 뒤, 화면에 표시되는 날짜·시간·시간대가 실제와 맞는지 확인하세요. ④ 자동 설정을 켰는데도 시간이 틀리다면 '지금 동기화' 버튼을 눌러 강제로 맞추세요. ⑤ 시간을 맞춘 뒤 Microsoft 계정으로 다시 로그인을 시도하세요."},{"title":"자격 증명 관리자 캐시 삭제","why":"이전에 저장된 로그인 정보가 바뀐 비밀번호와 충돌하면 계속 로그인에 실패할 수 있습니다.","how":"① Windows 로고 키를 누르고 '자격 증명 관리자'를 입력해 실행하세요. ② 'Windows 자격 증명' 탭을 클릭하세요. ③ 목록에서 이름에 'MicrosoftAccount' 또는 로그인 중인 계정 이메일이 포함된 항목을 찾으세요. ④ 해당 항목을 클릭해 펼친 뒤 '제거'를 클릭하세요. ⑤ PC를 재시작한 뒤 Microsoft 계정으로 다시 로그인해 최신 비밀번호가 정상 반영되는지 확인하세요."},{"title":"Microsoft 서비스 상태 확인","why":"Microsoft 쪽 서비스 장애로 일시적으로 로그인이 안 되는 경우도 있어, PC 문제가 아닐 수도 있습니다.","how":"① 스마트폰이나 다른 기기로 웹 브라우저를 열어 'Microsoft 365 상태' 또는 'Microsoft 서비스 상태'를 검색하세요. ② 마이크로소프트 공식 서비스 상태 페이지에서 로그인·인증 서비스에 장애 표시가 있는지 확인하세요. ③ 장애가 표시되어 있다면 PC 문제가 아니므로, 몇 시간 뒤 다시 시도하며 해결을 기다리세요. ④ 장애 표시가 없다면 위의 시간 설정, 자격 증명 삭제 항목을 먼저 확인하고, 그래도 안 되면 Microsoft 계정 자체의 비밀번호를 재설정해보세요."}],"deeper":[{"heading":"2단계 인증 문제일 때","text":"인증 앱의 시간이 PC와 어긋나 있으면 코드가 계속 틀린 것으로 처리될 수 있습니다. 인증 앱과 PC 모두 자동 시간 동기화를 켜두면 대부분 해결됩니다."},{"heading":"계정 보안 확인이 뜰 때","text":"평소와 다른 위치·기기에서 로그인을 시도하면 Microsoft가 추가 본인 확인을 요구할 수 있습니다. 이 경우 등록된 이메일이나 전화번호로 코드를 받아 진행해야 합니다."}],"decision":[{"heading":"브라우저에서도 로그인이 안 될 때","text":"계정 자체의 문제이므로 Microsoft 계정 복구 절차를 진행해야 하며, PC 설정을 바꿔도 해결되지 않습니다."},{"heading":"브라우저에서는 되는데 PC에서만 안 될 때","text":"시간 동기화와 자격 증명 캐시부터 확인하고, 그래도 안 되면 윈도우에서 계정을 제거한 뒤 다시 추가하는 것을 고려하세요."}],"examples":["비밀번호는 맞는데 로그인 화면에서 계속 튕김","2단계 인증 코드를 입력해도 다시 로그인 화면으로 돌아감","웹브라우저의 Microsoft 계정 페이지에서는 정상 로그인됨"],"mistakes":["시스템 시간이 맞는지 확인하지 않고 비밀번호만 계속 재설정하는 것","브라우저에서 먼저 확인하지 않고 바로 PC를 초기화하는 것"],"faq":[{"q":"비밀번호를 새로 설정했는데도 계속 로그인이 안 됩니다.","a":"PC에 저장된 이전 로그인 정보(자격 증명 캐시)가 남아있을 수 있습니다. 자격 증명 관리자에서 관련 항목을 정리한 뒤 다시 시도해 보세요."},{"q":"2단계 인증 코드가 계속 틀렸다고 나옵니다.","a":"인증 앱과 PC의 시간이 어긋나 있을 가능성이 높습니다. 두 기기 모두 자동 시간 동기화가 켜져 있는지 확인하세요."}]},"update-network-broken":{"badge":"업데이트","subtitle":"윈도우 업데이트 이후 인터넷·네트워크가 안 될 때","intro":["이 증상은 와이파이가 가끔 끊기는 것과는 다릅니다. 업데이트를 설치하고 재부팅한 직후부터 인터넷이 아예 안 되거나, 장치 관리자에 있던 네트워크 어댑터 자체가 사라진 것처럼 보이는 경우입니다.","가장 흔한 원인은 업데이트가 네트워크 드라이버를 기본 드라이버로 되돌리거나, 서드파티 드라이버와 호환되지 않는 버전으로 덮어쓰는 경우입니다. 유선(이더넷)과 무선(와이파이) 중 어느 쪽이 안 되는지에 따라 확인 순서가 달라집니다.","이 페이지는 장치 관리자에서 어댑터가 보이는지 여부를 기준으로 원인을 나눠서 설명합니다."],"warnings":["업데이트·재부팅 직후부터 인터넷이 전혀 안 된다.","장치 관리자의 네트워크 어댑터 목록에 있던 항목이 사라졌다.","다른 기기는 같은 공유기에 정상 연결된다."],"checks":[{"title":"장치 관리자에서 어댑터 인식 여부 확인","why":"어댑터가 아예 안 보이는지, 느낌표와 함께 남아있는지에 따라 원인과 해결 방법이 완전히 달라집니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '네트워크 어댑터' 항목을 펼치세요. ③ 이더넷(유선)이나 Wi-Fi(무선) 어댑터 이름이 정상적으로 보이는지 확인하세요. ④ 이름 옆에 노란색 느낌표가 있거나, '네트워크 어댑터' 항목이 아닌 '기타 장치'에 '알 수 없는 장치'로 표시되어 있다면 드라이버가 제대로 설치되지 않은 것입니다. ⑤ 아예 목록에 아무 항목도 없다면 어댑터 자체가 인식되지 않는 더 심각한 상태이니 아래 항목들을 순서대로 진행하세요."},{"title":"네트워크 어댑터 드라이버 롤백 또는 재설치","why":"업데이트가 설치한 새 드라이버가 문제라면, 이전 버전으로 되돌리거나 제조사 드라이버로 재설치하는 것이 가장 빠른 해결책입니다.","how":"① 장치 관리자에서 문제의 네트워크 어댑터를 더블클릭하세요. ② '드라이버' 탭을 클릭했을 때 '이전 드라이버로 롤백' 버튼이 활성화되어 있다면 클릭하세요(업데이트 직후 문제가 생겼을 때 가장 빠른 해결책입니다). ③ 버튼이 회색으로 비활성화되어 있다면(이전 드라이버 정보가 없는 경우), 대신 노트북 제조사나 메인보드 제조사 홈페이지에서 정확한 모델명으로 검색해 최신 랜카드/Wi-Fi 드라이버를 내려받으세요(이 작업은 인터넷이 되는 다른 기기나 스마트폰 테더링으로 진행해야 할 수 있습니다). ④ 내려받은 드라이버 설치 파일을 실행해 재설치하고 재부팅하세요."},{"title":"네트워크 스택 초기화","why":"드라이버는 정상인데 설정 값이 꼬여 있으면 winsock·IP 스택 초기화로 해결되는 경우가 많습니다.","how":"① Windows 로고 키를 누르고 'cmd'를 입력한 뒤 검색 결과를 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② netsh winsock reset 을 입력하고 Enter를 누르세요. ③ 이어서 netsh int ip reset 을 입력하고 Enter를 누르세요. ④ 명령 실행 후 화면에 재부팅하라는 안내가 나오면 PC를 재시작하세요. ⑤ 재부팅 후 인터넷 연결이 복구됐는지 확인하세요."},{"title":"VPN·보안 프로그램 임시 비활성화","why":"VPN이나 보안 소프트웨어의 네트워크 필터 드라이버가 업데이트와 충돌하면 정상 어댑터도 연결에 실패할 수 있습니다.","how":"① 회사 VPN이나 별도 보안 프로그램(넷 필터링 기능이 있는 백신 등)을 설치해 사용 중인지 떠올려 보세요. ② Windows 로고 키를 누르고 '앱 및 기능'을 입력해 들어간 뒤, 해당 VPN 프로그램을 찾아 '제거'하거나, 프로그램 자체의 설정에서 '연결 끊기'를 실행하세요. ③ 제거·비활성화 후 재부팅해 인터넷 연결이 정상으로 돌아오는지 확인하세요. ④ 정상으로 돌아오면 해당 프로그램이 원인이 확실하므로, 필요하다면 프로그램의 최신 버전을 다시 설치해보거나 제작사에 호환성 문의를 하세요."}],"deeper":[{"heading":"어댑터 자체가 사라졌을 때","text":"장치 관리자에 어댑터가 아예 없다면 드라이버 설정보다 드라이버 자체가 제거된 경우입니다. '숨겨진 장치 표시'를 켜서 회색으로 남아있는 항목이 있는지 확인하고, 있다면 제거 후 재부팅해 자동 재설치를 유도하세요."},{"heading":"유선은 되는데 무선만 안 될 때","text":"이더넷은 정상인데 와이파이만 안 된다면 무선 어댑터 드라이버 문제일 가능성이 높고, 반대로 둘 다 안 된다면 네트워크 스택 전체나 보안 소프트웨어 쪽 문제일 가능성이 큽니다."}],"decision":[{"heading":"드라이버 롤백·재설치로 해결될 때","text":"업데이트가 배포한 드라이버 자체가 문제였던 것이므로, 이후 자동 업데이트로 드라이버가 다시 덮어써지지 않도록 드라이버 자동 업데이트를 잠시 차단해두는 것도 방법입니다."},{"heading":"그래도 해결되지 않을 때","text":"해당 업데이트를 제거(이전 버전으로 롤백)한 뒤 재현 여부를 확인하고, 같은 업데이트에서 다른 사용자들도 같은 문제를 보고했는지 확인하세요."}],"examples":["업데이트 후 재부팅하니 와이파이 목록 자체가 안 보임","장치 관리자에 '알 수 없는 장치'로 네트워크 어댑터가 표시됨","유선 랜은 되는데 와이파이만 계속 연결 안 됨으로 표시됨"],"mistakes":["어댑터가 실제로 사라졌는지 확인하지 않고 공유기부터 재설정하는 것","드라이버 롤백을 시도하지 않고 바로 윈도우를 재설치하는 것","VPN·보안 프로그램의 영향을 배제하지 않고 하드웨어 고장으로 단정하는 것"],"faq":[{"q":"업데이트 제거(롤백)를 하면 인터넷이 다시 되나요?","a":"네트워크 드라이버 자체가 업데이트로 바뀐 경우라면 업데이트 제거로 이전 상태로 돌아가 해결되는 경우가 많습니다. 다만 이후 같은 업데이트가 다시 설치되지 않도록 임시로 차단해두는 것이 좋습니다."},{"q":"다른 기기는 같은 와이파이에 잘 연결되는데 제 PC만 안 됩니다.","a":"공유기 문제가 아니라 이 PC의 네트워크 드라이버나 어댑터 자체의 문제일 가능성이 높습니다. 장치 관리자에서 어댑터 상태부터 확인하세요."}]},"startup-slow":{"badge":"부팅","subtitle":"바탕화면이 뜨기까지 시간이 길어질 때","intro":["부팅 속도 저하는 전원이 켜지는 것과 윈도우가 완전히 준비되는 것을 분리해서 봐야 합니다. 전원은 바로 켜지는데 바탕화면만 늦다면 시작 프로그램, 디스크, 로그인 후 실행 항목이 더 중요합니다.","특정 업데이트나 프로그램을 넣은 뒤부터 느려졌다면, 단순한 체감 저하가 아니라 시작 단계에서 기다리는 항목이 늘어났을 수 있습니다.","이 증상은 부팅 실패와 달리 결국은 들어가지만 오래 걸린다는 점이 핵심입니다."],"warnings":["전원은 켜지는데 로그인 후 오래 멈춘다.","바탕화면이 뜬 뒤에도 한동안 아이콘이 안 보인다.","재부팅할 때마다 걸리는 시간이 조금씩 다르다."],"checks":[{"title":"시작 프로그램 정리","why":"부팅 직후 동시에 올라오는 항목이 많으면 체감이 크게 느려집니다.","how":"① Windows 로고 키를 누르고 '작업 관리자'를 입력해 실행하세요(또는 Ctrl+Shift+Esc). ② 상단의 '시작프로그램' 탭을 클릭하세요. ③ '시작 시 영향' 열이 '높음'으로 표시된 항목들을 확인하세요 — 카카오톡, 클라우드 동기화 앱, 게임 런처 등이 대표적입니다. ④ 당장 필요하지 않은 항목을 마우스 오른쪽 버튼으로 클릭해 '사용 안 함'을 선택하세요(프로그램을 삭제하는 것이 아니라 자동 실행만 막는 것이므로 필요할 때 직접 실행하면 됩니다). ⑤ 재부팅해 부팅 속도가 개선됐는지 확인하세요."},{"title":"디스크 지연 확인","why":"저장장치가 느리면 로그인 단계부터 전체가 늦어집니다.","how":"① Windows 로고 키를 누르고 '이 PC'를 입력해 실행한 뒤, C 드라이브(주로 SSD)를 마우스 오른쪽 버튼으로 클릭해 '속성' → '도구' 탭 → '검사'를 눌러 오류 여부를 확인하세요. ② SSD라면 제조사 관리 프로그램(삼성 SSD면 Samsung Magician 등)을 설치해 건강 상태와 남은 수명을 확인하세요. ③ HDD(하드디스크)를 쓰고 있다면 SSD보다 부팅이 원래 느릴 수 있습니다 — 예산이 된다면 부팅 드라이브만 SSD로 교체하는 것이 체감 속도 개선에 가장 효과적입니다. ④ 로그인 화면이 뜬 뒤 바탕화면이 나타나기까지 유독 오래 걸린다면, 디스크 자체보다 시작 프로그램이 몰려서 뜨는 경우가 많으니 위 항목의 시작 프로그램 정리를 먼저 시도하세요."},{"title":"업데이트 후 변화 확인","why":"부팅 스크립트나 드라이버가 바뀌면 로그인 뒤 지연이 생길 수 있습니다.","how":"① 증상이 시작된 시점이 특정 Windows 업데이트나 드라이버 설치 직후인지 떠올려 보세요. ② Windows 로고 키를 누르고 '업데이트 기록 보기'를 입력해 실행하면 최근 설치된 업데이트 날짜를 확인할 수 있습니다. ③ 업데이트 직후부터 느려졌다면, 설정 → Windows Update → 업데이트 기록 → '업데이트 제거'에서 최근 업데이트를 제거해보고 속도가 되돌아오는지 확인하세요. ④ 그래픽·칩셋 드라이버를 최근 업데이트했다면, 장치 관리자에서 해당 드라이버를 이전 버전으로 롤백('드라이버' 탭 → '이전 드라이버로 롤백')해 비교해보세요."}],"deeper":[{"heading":"로그인 전과 후를 구분하기","text":"전원 버튼을 누른 직후가 느린지, 로그인한 뒤가 느린지에 따라 원인이 달라집니다. 로그인 후만 느리면 프로그램과 서비스 비중이 더 높습니다."}],"decision":[{"heading":"로그인 후만 느릴 때","text":"자동 실행 항목과 백그라운드 동기화 프로그램을 먼저 줄여 보세요."},{"heading":"전원 켠 직후부터 느릴 때","text":"저장장치 인식이나 BIOS 초기화 쪽을 먼저 확인하는 편이 맞습니다."}],"examples":["암호 입력 후 바탕화면이 1분 이상 늦게 뜸","작업표시줄이 한참 뒤에야 반응함"],"mistakes":["부팅 지연을 그냥 체감 문제로 넘기는 것","시작 프로그램을 전혀 보지 않는 것"],"faq":[{"q":"안전 모드에서는 빠른데 일반 부팅만 느립니다.","a":"이 경우는 시작 프로그램이나 드라이버 충돌 가능성이 더 높습니다."},{"q":"시작 프로그램을 모두 꺼도 괜찮나요?","a":"보안 프로그램이나 드라이버 관련 항목은 남겨두고, 불필요한 업데이트 도우미나 알림 프로그램 위주로 끄는 것이 안전합니다."},{"q":"SSD로 교체하면 부팅 속도가 확실히 빨라지나요?","a":"HDD 대비 부팅 속도가 크게 개선되는 경우가 많지만, 시작 프로그램이 지나치게 많다면 SSD로 바꿔도 지연이 남을 수 있습니다."}]},"taskbar-freeze":{"badge":"작업표시줄","subtitle":"시작 메뉴와 알림 영역이 멈출 때","intro":["작업표시줄 멈춤은 탐색기 셸이 화면 아래쪽 UI를 그리다가 응답을 잃는 현상입니다. 일반적인 창은 열리지만 시작 메뉴나 알림 영역만 멈추는 경우가 많아, 전체 윈도우보다 셸 구성 문제로 보는 편이 맞습니다.","최근 설치한 시작 메뉴 수정 도구, 우클릭 확장, 스킨 변경 도구가 있으면 더 의심해야 합니다.","증상이 자주 풀렸다 다시 멈춘다면 임시 캐시와 셸 확장을 함께 봐야 합니다."],"warnings":["시작 메뉴를 눌러도 바로 안 열린다.","오른쪽 알림 아이콘이 늦게 반응한다.","탐색기는 살아 있는데 작업표시줄만 굳는다."],"checks":[{"title":"탐색기 재시작","why":"작업표시줄은 탐색기와 같이 움직이므로 셸만 재시작해도 풀릴 수 있습니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요(작업표시줄이 멈춰 있어도 이 단축키는 대부분 작동합니다). ② '프로세스' 탭에서 'Windows 탐색기'를 찾아 마우스 오른쪽 버튼으로 클릭하고 '다시 시작'을 선택하세요. ③ 화면이 잠깐 깜빡이며 작업표시줄과 바탕화면이 다시 그려집니다. ④ 재시작 후에도 같은 증상이 바로 반복되면 아래 항목(셸 확장, 업데이트)을 이어서 확인하세요."},{"title":"최근 셸 확장 확인","why":"메뉴를 붙이는 프로그램이 응답을 잡아먹는 경우가 많습니다.","how":"① 최근에 설치한 프로그램 중 마우스 오른쪽 클릭 메뉴를 추가하는 것들(압축 프로그램, 클라우드 동기화, 화면 꾸미기 도구, 시작 메뉴 커스터마이징 도구 등)을 떠올려 보세요. ② Windows 로고 키를 누르고 '앱 및 기능'을 입력해 들어간 뒤, 의심되는 프로그램을 제거하세요. ③ 제거 후 재부팅해 작업표시줄이 정상적으로 동작하는지 확인하세요. ④ 특정 프로그램을 지목하기 어렵다면, 최근 1~2주 사이에 설치한 프로그램 목록을 '앱 및 기능'에서 설치 날짜순으로 정렬해 확인하세요."},{"title":"업데이트와 로그 확인","why":"업데이트 후 셸 구성 파일이 꼬이면 같은 증상이 반복됩니다.","how":"① 증상이 시작된 날짜가 Windows 업데이트 직후인지 확인하세요 — Windows 로고 키를 누르고 '업데이트 기록 보기'를 입력해 최근 설치 날짜를 확인할 수 있습니다. ② 업데이트 직후부터 시작됐다면 설정 → Windows Update → 업데이트 기록 → '업데이트 제거'에서 최근 업데이트를 제거해보고 증상이 사라지는지 확인하세요. ③ Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행한 뒤 'Windows 로그' → '응용 프로그램'에서 explorer.exe 관련 오류가 반복되는지 확인하면 원인을 더 구체적으로 좁힐 수 있습니다."}],"deeper":[{"heading":"탐색기 전체와 작업표시줄은 다를 수 있음","text":"창 탐색이 괜찮은데 아래 메뉴만 멈춘다면 전체 윈도우 문제보다 셸 확장이나 시작 메뉴 컴포넌트를 먼저 보는 것이 맞습니다."}],"decision":[{"heading":"시작 메뉴만 멈출 때","text":"시작 메뉴 관련 앱이나 셸 확장이 원인일 수 있어, 최근 설치한 인터페이스 도구부터 빼보세요."},{"heading":"알림 영역만 늦을 때","text":"네트워크, 보안, 동기화 아이콘이 뒤늦게 뜨면 백그라운드 서비스 지연을 함께 봐야 합니다."}],"examples":["작업표시줄이 회색으로 멈췄다가 풀림","시작 메뉴가 누를 때마다 5초 이상 지연"],"mistakes":["탐색기만 재시작하고 원인을 끝낸다고 보는 것","최근 설치 프로그램을 빼놓는 것"],"faq":[{"q":"작업표시줄이 멈추면 재부팅만 해야 하나요?","a":"재부팅이 임시로 풀어줄 수는 있지만, 반복되면 셸 확장과 업데이트 기록을 먼저 보는 것이 좋습니다."},{"q":"작업표시줄만 멈추고 다른 프로그램은 정상 작동하는데 재부팅해야 하나요?","a":"탐색기(explorer.exe) 프로세스만 재시작하면 재부팅 없이 복구되는 경우가 많습니다."},{"q":"알림 영역 아이콘이 사라지는 것도 같은 문제인가요?","a":"네, 작업표시줄 관련 프로세스가 불안정할 때 함께 나타나는 증상으로, 탐색기 재시작으로 함께 해결되는 경우가 많습니다."}]},"wifi-disconnect":{"badge":"네트워크","subtitle":"무선이 자꾸 끊기거나, 유선인데도 인터넷이 안 될 때","intro":["와이파이 끊김은 공유기 신호 문제처럼 보여도 실제로는 드라이버와 절전 설정이 더 큰 원인일 수 있습니다. 같은 장소에서만 끊기는지, 다른 네트워크에서도 끊기는지 구분하면 방향이 빨라집니다.","특히 노트북에서는 전원 모드 변화만으로도 무선 어댑터가 잠깐씩 내려갈 수 있습니다. 이럴 때는 신호 세기보다 절전 옵션을 먼저 봐야 합니다.","끊김이 몇 초마다 반복되는지, 아니면 특정 시간대에만 생기는지도 중요한 단서입니다.","랜선을 꽂은 유선 연결인데도 인터넷이 안 된다면 원인이 완전히 다릅니다. 작업표시줄에 '인터넷 없음'이 뜨지만 IP 주소는 정상적으로 할당받은 경우가 많은데, 이때는 무선 드라이버나 절전 설정이 아니라 공유기·모뎀 쪽 문제이거나 랜카드 드라이버 손상, DNS 설정 문제일 가능성이 큽니다.","반면 IP 주소조차 받지 못하고 '네트워크 케이블이 연결되어 있지 않습니다'라는 메시지가 뜬다면 앞의 경우와는 전혀 다른 원인입니다. 랜케이블 자체 불량, 포트 접촉 불량, 또는 방·기숙사·사무실을 옮긴 직후라면 벽면 랜포트가 아직 인터넷 회선에 연결되지 않았을 가능성부터 확인해야 합니다."],"warnings":["몇 분마다 연결이 끊겼다 다시 붙는다.","유선은 괜찮은데 무선만 불안정하다.","절전 후에 더 자주 끊긴다.","랜선을 꽂았는데도 인터넷에 연결할 수 없다고 뜬다.","IP는 정상적으로 할당받았는데 웹사이트가 열리지 않는다.","'네트워크 케이블이 연결되어 있지 않습니다'라는 메시지가 뜨며 IP 자체를 받지 못한다."],"checks":[{"title":"무선 드라이버 점검","why":"어댑터 드라이버가 불안정하면 연결이 살아나도 금방 끊길 수 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '네트워크 어댑터' 항목을 펼쳐 Wi-Fi 어댑터(보통 이름에 'Wireless'나 'Wi-Fi'가 포함됨)를 찾으세요. ③ 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택하세요('드라이버 소프트웨어 삭제' 체크박스가 있다면 함께 체크). ④ 상단 메뉴의 '동작' → '하드웨어 변경 사항 검색'을 클릭해 Windows가 기본 드라이버로 다시 잡게 하세요. ⑤ 노트북 제조사(삼성, LG 등) 홈페이지의 지원 페이지에서 정확한 모델명으로 검색해 최신 무선랜 드라이버를 내려받아 설치하면 더 안정적입니다."},{"title":"전원 관리와 절전 해제","why":"절전 전환이 어댑터를 끊어 버리면 불안정하게 보입니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '네트워크 어댑터'에서 Wi-Fi 어댑터를 더블클릭하세요. ③ '전원 관리' 탭을 클릭하고 '전력을 절약하기 위해 컴퓨터에서 이 장치를 끌 수 있음' 체크박스를 해제한 뒤 '확인'을 누르세요. ④ Windows 로고 키를 누르고 '전원 및 절전 설정'을 입력해 들어간 뒤 '전원 관련 추가 설정' → '고급 전원 관리 설정 변경'을 클릭하세요. ⑤ 목록에서 '무선 어댑터 설정' → '전원 절약 모드'를 펼쳐 '최대 성능'으로 바꾸고 저장하세요."},{"title":"공유기/채널과 거리 확인","why":"신호 간섭이나 채널 충돌도 반복 끊김을 만듭니다.","how":"① 스마트폰이나 다른 기기를 같은 Wi-Fi에 연결해 같은 위치에서도 끊기는지 비교해보세요 — 다른 기기는 멀쩡하면 PC 쪽(어댑터, 드라이버) 원인일 가능성이 크고, 여러 기기가 다 같이 끊기면 공유기 쪽 문제일 가능성이 큽니다. ② 공유기와의 거리를 좁혀보거나 벽·전자레인지 등 전파를 방해하는 장애물을 피해 재현되는지 확인하세요. ③ 공유기 관리 페이지(보통 192.168.0.1 또는 192.168.1.1)에 접속해 Wi-Fi 채널을 자동이 아닌 수동으로, 주변에서 덜 쓰는 채널(2.4GHz는 1/6/11번)로 바꿔보세요. ④ 여유가 있다면 공유기를 재부팅(전원을 뽑았다가 10초 후 다시 연결)해 보세요."},{"title":"유선 연결: IP 재할당과 DNS 초기화","why":"IP는 받았지만 게이트웨이·DNS 응답이 없어 실제 인터넷 접속만 안 되는 경우가 흔합니다.","how":"① Windows 로고 키를 누르고 'cmd'를 입력한 뒤 검색 결과를 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② ipconfig /release 를 입력하고 Enter를 눌러 현재 IP를 반납하세요. ③ 이어서 ipconfig /renew 를 입력하고 Enter를 눌러 새 IP를 받으세요. ④ 그래도 인터넷이 안 되면 ipconfig /flushdns 를 입력하고 Enter를 눌러 DNS 캐시를 초기화하세요. ⑤ 마지막으로 PC를 재부팅해 변경 사항이 완전히 적용되도록 하세요."},{"title":"유선 연결: 케이블·포트·랜카드 구분","why":"같은 케이블·포트에서 다른 기기도 안 되면 공유기·모뎀 쪽 문제이고, 그 기기만 안 되면 랜카드나 드라이버 쪽 문제입니다.","how":"① 지금 쓰는 랜케이블과 공유기(또는 벽면) 포트에 스마트폰(랜-USB 어댑터가 있다면)이나 다른 노트북 등 다른 기기를 연결해 정상적으로 인터넷이 되는지 확인하세요. ② 다른 기기에서도 안 되면 케이블이나 공유기·포트 쪽 문제이므로 케이블을 바꾸거나 다른 포트로 옮겨 연결하세요. ③ 다른 기기에서는 정상인데 이 PC에서만 안 되면 랜카드나 드라이버 문제입니다 — Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행한 뒤 '네트워크 어댑터'에서 유선 랜카드를 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거' 후 재부팅해 드라이버를 다시 잡아보세요."},{"title":"유선 연결: IP조차 못 받을 때 케이블·벽면 포트 확인","why":"'네트워크 케이블이 연결되어 있지 않습니다'는 IP 할당 이전 단계, 즉 물리적 연결 자체가 안 된 상태입니다. IP·DNS 설정을 아무리 고쳐도 해결되지 않습니다.","how":"① 화면 오른쪽 아래 네트워크 아이콘에 마우스를 올려 '네트워크 케이블이 연결되어 있지 않습니다' 문구가 뜨는지 확인하세요. ② 랜케이블 양쪽 끝(PC 쪽, 공유기 또는 벽면 포트 쪽)이 딸깍 소리가 나도록 완전히 꽂혀 있는지 다시 확인하세요. ③ 다른 랜케이블로 교체해 케이블 자체의 단선 여부를 확인하세요. ④ 같은 벽면 랜포트나 공유기 포트에 다른 기기를 연결해도 안 되는지 확인하세요 — 다른 기기도 안 되면 포트 자체가 아직 개통되지 않았거나 고장 난 것입니다. ⑤ 기숙사·신축 사무실 등 새로 입주한 곳이라면 관리실이나 인터넷 통신사에 연락해 해당 포트가 개통(회선 연결)되어 있는지 확인을 요청하세요."}],"deeper":[{"heading":"무선만 끊기고 유선은 안정적일 때","text":"네트워크 전체보다 무선 어댑터와 전원 관리가 우선 의심 대상입니다. 같은 인터넷 회선이라도 무선 전용 문제일 수 있습니다."},{"heading":"무선과 유선, 어디서부터 다르게 봐야 하는가","text":"무선은 신호·드라이버·절전처럼 '연결 자체가 끊기는' 문제가 중심이지만, 유선은 케이블을 꽂은 상태에서 'IP는 받았는데 인터넷만 안 되는' 경우가 많습니다. 무선 어댑터 설정을 아무리 고쳐도 유선 문제는 해결되지 않으니, 먼저 작업표시줄 네트워크 아이콘에서 유선(이더넷)과 무선 중 어느 쪽 아이콘에 느낌표나 X가 떠 있는지부터 확인하세요."}],"decision":[{"heading":"절전 후에만 끊길 때","text":"전원 관리 옵션이 원인일 가능성이 높아 드라이버 설정을 먼저 점검하세요."},{"heading":"어느 장소에서든 끊길 때","text":"공유기보다 무선 어댑터 자체나 드라이버를 더 우선해서 봐야 합니다."},{"heading":"유선인데 IP는 받았지만 인터넷이 안 될 때","text":"ipconfig /release·/renew·/flushdns로 IP·DNS를 재할당받고, 다른 기기로 같은 포트를 테스트해 공유기·모뎀 문제인지 랜카드 문제인지 구분하세요."}],"examples":["유튜브를 보다 갑자기 끊김","잠깐 화면을 끄면 다시 연결이 불안정해짐","랜선을 새로 꽂았는데 '인터넷 액세스 없음'으로 표시됨"],"mistakes":["공유기만 재부팅하고 끝내는 것","절전 옵션을 안 보는 것","유선 문제인데 무선 어댑터 드라이버만 재설치해보는 것"],"faq":[{"q":"다른 기기는 멀쩡한데 내 PC만 끊깁니다.","a":"그렇다면 공유기보다 PC의 무선 드라이버와 전원 설정을 먼저 보세요."},{"q":"유선으로 바꾸면 확실히 해결되나요?","a":"무선 신호나 드라이버 문제가 원인이라면 유선 연결로 우회할 수 있지만, 근본 원인 해결을 원한다면 무선 드라이버와 공유기 설정을 점검해야 합니다."},{"q":"공유기를 재부팅하면 왜 일시적으로 좋아지나요?","a":"공유기 내부 메모리나 연결 세션이 초기화되며 일시적으로 안정화되지만, 원인이 남아있다면 재발할 수 있습니다."},{"q":"유선랜인데 IP는 받아오는데 인터넷만 안 됩니다.","a":"게이트웨이나 DNS 응답이 없는 경우입니다. ipconfig /release·/renew로 IP를 다시 받고 ipconfig /flushdns로 DNS 캐시를 초기화해보세요. 그래도 안 되면 공유기·모뎀 쪽 문제일 가능성이 큽니다."},{"q":"'네트워크 케이블이 연결되어 있지 않습니다'라고 뜨는데 랜선은 분명히 꽂혀 있습니다.","a":"Windows가 물리적 신호 자체를 감지하지 못하는 상태로, IP·DNS 설정과는 무관합니다. 케이블을 다른 것으로 바꾸거나 다른 포트에 꽂아보고, 같은 벽면 랜포트에서 다른 기기도 안 되는지 확인하세요. 방을 옮긴 직후라면 벽면 포트 자체가 아직 개통되지 않았을 수 있습니다."}],"communityCases":[{"title":"무선랜카드 교체로 해결한 사례","summary":"드라이버 재설치, 절전 옵션 해제, 공유기 채널 변경까지 다 해봐도 몇 분마다 연결이 끊기던 사례가 있습니다. 다른 기기는 같은 공유기에서 안정적으로 연결됐고, 결국 내장 무선랜카드 자체의 결함으로 확인되어 M.2 무선랜카드를 새 제품으로 교체한 뒤 끊김이 사라졌습니다.","insight":"드라이버와 전원 설정을 다 점검했는데도 유독 이 PC에서만 반복된다면, 같은 공유기에서 다른 기기는 안정적인지 먼저 비교해보고 무선랜카드 자체의 하드웨어 결함도 의심해볼 필요가 있습니다."}]},"overheat-shutdown":{"badge":"전원","subtitle":"부하가 걸리면 갑자기 꺼질 때","intro":["과열로 전원이 꺼지는 문제는 팬이 돈다고 끝이 아닙니다. 먼지, 써멀 상태, 방열판 접촉, 전원부 온도가 함께 영향을 줍니다.","특히 게임, 영상 인코딩, 압축 해제처럼 부하가 걸릴 때만 꺼진다면 온도와 전력 공급을 같이 봐야 합니다.","재부팅 직후에는 멀쩡한데 조금 쓰다 꺼진다면 냉각 능력이 부족할 가능성이 큽니다."],"warnings":["소음이 커지고 나서 꺼진다.","여름철이나 실내 온도가 높을 때 더 심하다.","부하가 낮을 때는 괜찮다."],"checks":[{"title":"온도 로그 확인","why":"부하 직전의 최고 온도가 중요합니다.","how":"① HWiNFO 또는 HWMonitor 같은 무료 온도 모니터링 프로그램을 내려받아 설치하세요(공식 홈페이지에서 받으세요). ② 프로그램을 실행한 상태로 평소 PC가 꺼지던 작업(게임, 영상 편집 등)을 그대로 진행하세요. ③ HWiNFO를 쓴다면 'Sensors' 창에서 CPU Package와 GPU Temperature 항목의 'Max' 값을 확인하세요 — 이 값이 실제로 PC가 꺼지기 직전 도달했던 최고 온도입니다. ④ CPU가 95~100도, GPU가 90도 이상까지 치솟은 뒤 꺼진다면 냉각 문제일 가능성이 크고, 온도가 그 정도까지 오르지 않았는데도 꺼진다면 전원부(파워서플라이) 쪽 원인을 더 의심해야 합니다."},{"title":"먼지와 쿨링 상태 점검","why":"먼지와 막힌 통풍구는 냉각 효율을 크게 떨어뜨립니다.","how":"① PC 전원을 끄고 전원 케이블을 뽑으세요. ② 케이스 옆판을 열고 CPU 쿨러(방열판+팬)와 그래픽카드 팬에 먼지가 두껍게 쌓여 있는지 눈으로 확인하세요 — 팬 날개나 방열판 사이가 회색 먼지로 막혀 있으면 냉각 효율이 크게 떨어집니다. ③ 캔에어(압축공기 스프레이)를 이용해 팬과 방열판, 케이스 앞뒤의 흡기·배기 통풍구에 쌓인 먼지를 불어내세요(팬 날개가 빨리 돌지 않도록 손가락으로 살짝 고정한 채 뿌리는 것이 좋습니다). ④ CPU 쿨러 팬이 실제로 잘 돌아가는지(전원을 켠 상태에서) 육안으로 확인하세요 — 팬이 안 돌거나 느리게 돈다면 팬 고장이나 케이블 연결 불량입니다. ⑤ 케이스 앞면이 막혀 있거나 벽에 바짝 붙여 놓았다면 통풍이 될 수 있도록 최소 10cm 이상 공간을 띄워 배치하세요."},{"title":"전원부와 파워 용량 확인","why":"온도처럼 보여도 전원 공급이 꺼지는 경우가 있습니다.","how":"① 케이스 옆면이나 파워서플라이 본체에 붙은 스티커에서 정격 출력(W, 와트)을 확인하세요. ② 사용 중인 CPU와 그래픽카드의 권장 파워 용량을 제조사 홈페이지나 검색으로 확인하고, 현재 파워 용량이 이보다 낮거나 여유가 별로 없는지 비교하세요 — 특히 고사양 그래픽카드를 나중에 추가한 경우 기존 파워로는 부족할 수 있습니다. ③ 그래픽카드에 필요한 보조전원 케이블(6핀/8핀)이 파워서플라이에서 완전히 꽂혀 있는지 다시 확인하세요. ④ 파워 용량이 부족하거나 사용 연수가 5년을 넘었다면(전해 캐패시터 노후화로 순간 출력이 떨어질 수 있음), 더 높은 정격 출력의 새 파워서플라이로 교체하는 것을 고려하세요."}],"deeper":[{"heading":"꺼지는 시점이 매번 비슷한가","text":"비슷한 부하에서 늘 꺼진다면 쿨링 한계가 가까운 것이고, 들쭉날쭉하면 전원부나 접촉 상태도 함께 의심해야 합니다."}],"decision":[{"heading":"온도 기록이 높게 잡힐 때","text":"냉각 문제로 보고 팬, 써멀, 통풍부터 손보는 편이 맞습니다."},{"heading":"온도는 정상인데 꺼질 때","text":"파워나 메인보드 전원부, 보조전원 연결 상태를 더 봐야 합니다."}],"examples":["게임 로딩 중 전원이 바로 꺼짐","인코딩 시작 후 10분쯤 지나면 꺼짐"],"mistakes":["팬만 돌면 쿨링이 충분하다고 보는 것","전원 문제를 아예 제외하는 것"],"faq":[{"q":"온도는 낮은데도 꺼집니다.","a":"그렇다면 파워, 메인보드 전원부, 보조전원 연결 상태를 먼저 확인하세요."},{"q":"그냥 방치하면 하드웨어가 고장 나나요?","a":"과열로 인한 강제 종료가 반복되면 부품 수명에 영향을 줄 수 있어, 방치하지 말고 쿨링 상태를 점검하는 것이 좋습니다."},{"q":"노트북과 데스크탑의 점검 방법이 다른가요?","a":"노트북은 통풍구 먼지와 받침대 사용 여부를, 데스크탑은 케이스 팬 배치와 서멀 그리스 상태를 우선 점검해야 합니다."}],"communityCases":[{"title":"CPU 쿨러 교체로 해결한 사례","summary":"먼지 청소와 서멀 그리스 재도포까지 했는데도 특정 부하(인코딩, 게임)에서 반복적으로 전원이 꺼지던 사례가 있습니다. 온도 로그를 보니 부하가 걸리자마자 순식간에 임계 온도까지 치솟았고, 오래된 쿨러의 히트파이프 성능이 저하된 것으로 확인되어 새 쿨러로 교체한 뒤 온도가 안정되며 재발하지 않았습니다.","insight":"먼지 청소와 서멀 재도포로도 온도가 잡히지 않는다면, 쿨러 자체(특히 오래 사용한 히트파이프 방식)의 냉각 성능 저하를 의심해볼 필요가 있습니다."}]},"amd-cpu-cooler-pressure-no-post":{"badge":"CPU 쿨러 / 조립","subtitle":"쿨러 장착 뒤 CPU·DRAM LED에서 멈출 때","intro":["발열 관리를 위해 사제 공랭 또는 수랭 쿨러를 사용하는 PC에서 쿨러를 장착한 뒤 전원은 들어오지만 화면이 나오지 않고 POST가 끝나지 않는다면, CPU 고장으로 바로 단정하기보다 장착 과정에서 달라진 조건을 먼저 되돌려 봐야 합니다. 이 증상은 특정 CPU에만 한정된 공식 결함이라기보다, 소켓 종류와 관계없이 쿨러 장착 키트와 조임 상태가 맞지 않을 때 일부 시스템에서 관찰될 수 있는 조립 관련 문제입니다.","CPU 쿨러는 방열판을 CPU에 밀착시키는 부품이므로 적정한 압력이 필요합니다. 그러나 잘못된 스페이서나 백플레이트를 사용하거나 한쪽 나사를 먼저 끝까지 조이면 메인보드가 불균일하게 휘고, 소켓 접촉 또는 메모리 초기화 상태에 영향을 줄 가능성이 있습니다. 이 설명은 가능한 작동 원리를 정리한 것이며 특정 CPU나 쿨러의 공통 결함을 뜻하지 않습니다.","가장 중요한 단서는 쿨러 장착 전에는 정상 부팅됐는지, CPU와 DRAM 중 어느 디버그 LED에서 멈추는지, RAM 한 개만 사용해도 같은지입니다. 증상을 재현하려고 쿨러를 느슨하게 둔 채 장시간 사용하면 냉각이 불안정해질 수 있으므로 진단 뒤에는 반드시 올바른 장착 상태로 복구해야 합니다."],"warnings":["쿨러 교체 직후부터 화면이 나오지 않는다.","CPU 또는 DRAM 디버그 LED가 계속 켜진다.","나사를 조금 풀면 부팅되지만 다시 조이면 POST가 멈춘다.","특정 RAM 슬롯이나 메모리 채널만 인식되지 않는다."],"checks":[{"title":"디버그 LED와 변경 시점 기록","why":"CPU LED와 DRAM LED는 점검 시작 위치를 크게 줄여 줍니다.","how":"① 쿨러를 교체하기 전 정상 부팅되던 상태였는지 확인하고, 교체 직후부터 증상이 시작됐는지 기록하세요. ② 부팅 시도 시 스피커(부저)가 있다면 비프음이 몇 번 울리는지 세어보고, 메인보드 설명서에서 그 비프음 패턴이 의미하는 오류를 확인하세요. ③ CPU 쿨러 팬과 케이스 팬이 전원을 넣었을 때 실제로 도는지 육안으로 확인하세요. ④ 메인보드에 디버그 LED(CPU/DRAM/VGA/BOOT로 표시된 4개 표시등)가 있다면 전원을 켠 뒤 어느 LED에 불이 켜진 채로 멈추는지 확인하고 기록해두세요 — 이 정보가 이후 점검 순서를 정하는 핵심 단서입니다."},{"title":"AM4·AM5 장착 부품 대조","why":"소켓에 맞지 않는 스페이서와 백플레이트는 높이와 압력을 바꿉니다.","how":"① 사용 중인 CPU 쿨러의 정확한 모델명을 확인하고, 제조사 공식 홈페이지에서 해당 모델의 설명서(매뉴얼) PDF를 내려받으세요. ② 설명서에서 현재 메인보드 소켓(AM4 또는 AM5)에 맞는 브래킷과 스페이서 부품이 정확히 무엇인지 확인하세요(AM4용과 AM5용 부품이 겉보기에 비슷해도 다른 경우가 많습니다). ③ 스페이서(나사 기둥)의 색상이나 각인된 표시가 설명서에 나온 소켓별 지정과 일치하는지 대조하세요. ④ AM5는 메인보드에 기본 장착된 백플레이트를 그대로 재사용해야 하는 쿨러가 많으니, 설명서에서 '기본 백플레이트 재사용 여부'를 반드시 확인하세요 — 임의로 다른 백플레이트로 바꾸면 높이가 맞지 않아 압력 문제가 생깁니다."},{"title":"소켓과 CPU 접점 검사","why":"쿨러를 교체하면서 CPU가 들리거나 핀·접점에 이물질이 생길 수 있습니다.","how":"① PC 전원 케이블을 완전히 뽑으세요. ② CPU를 소켓에서 조심스럽게 분리하세요(레버를 들어 올린 뒤 CPU 가장자리를 잡고 수직으로 들어냅니다). ③ 밝은 조명 아래서(스마트폰 손전등 활용 추천) AM4라면 CPU 밑면의 핀이 휘거나 부러진 곳이 없는지, AM5라면 소켓 안쪽의 얇은 핀들이 휘어있지 않은지 자세히 살펴보세요. ④ CPU 윗면(접점 부분)에 서멀 그리스가 묻어 있지 않은지, 이물질이 끼어있지 않은지 확인하고 필요하면 이소프로필 알코올을 묻힌 무형광 천으로 가볍게 닦으세요. ⑤ 이상이 없다면 조심스럽게 CPU를 다시 소켓에 정확한 방향(소켓과 CPU의 삼각형 표시를 맞춰)으로 장착하고 레버를 눌러 고정하세요."},{"title":"대각선으로 균등 재장착","why":"한쪽을 먼저 끝까지 조이면 방열판 압력과 보드 휨이 한 방향에 집중됩니다.","how":"① 기존 서멀 그리스를 이소프로필 알코올과 무형광 천으로 CPU와 쿨러 밑면 양쪽 모두 깨끗이 닦아내세요. ② CPU 중앙에 쌀알 크기(약 완두콩 크기) 정도의 새 서멀 그리스를 짜세요. ③ 쿨러를 CPU 위에 올리고, 고정 나사 네 개를 한 번에 하나씩 끝까지 조이지 말고, 대각선 순서(예: 왼쪽 위 → 오른쪽 아래 → 오른쪽 위 → 왼쪽 아래)로 조금씩(한 바퀴씩) 번갈아 조이세요. ④ 나사가 '더 이상 안 돌아간다'는 느낌(정지 지점)이 들면 그 이상 억지로 힘을 주어 조이지 마세요 — 스프링 나사는 정지 지점까지가 정상 압력입니다."},{"title":"공식 수치가 있으면 토크 드라이버 사용","why":"여러 볼트를 끝까지 조이지 않고 같은 체결력으로 맞춰야 하는 제조사 지정 방식이라면, 손으로 푼 회전 수보다 토크 드라이버가 균일하고 재현 가능합니다.","how":"① 쿨러 설명서에 구체적인 목표 토크 수치(예: 'N·cm' 단위)가 명시되어 있는지 먼저 확인하세요 — 대부분의 스프링 나사식 쿨러는 이런 수치가 없고 '정지 지점까지 조이기'가 정답이므로, 이 항목은 설명서에 수치가 명시된 특수한 경우에만 해당합니다. ② 목표 토크가 명시되어 있다면, 그 수치에 맞는 저토크 드라이버(토크 스크루드라이버)를 준비하세요. ③ 네 나사를 대각선 순서로 조금씩 번갈아 돌리며 모두 같은 목표 토크값에 도달하도록 맞추세요. ④ 스프링 나사가 원래 끝까지 눌러 고정되도록 설계된 제품이라면, 임의로 덜 조이거나 토크 수치를 낮게 해석해 헐겁게 두지 마세요 — 이는 오히려 압력 부족을 유발합니다."},{"title":"CMOS 초기화와 RAM 한 개 테스트","why":"메모리 훈련 실패와 장착 압력 문제를 나누는 데 도움이 됩니다.","how":"① PC 전원을 끄고 케이블을 뽑으세요. ② 메인보드의 CMOS 배터리(동전 모양)를 5분간 뺐다가 다시 끼우거나, 'CLR_CMOS' 점퍼/버튼으로 초기화하세요. ③ 램이 여러 개 꽂혀 있다면 모두 뽑고, 메인보드 설명서에서 '싱글 채널 권장 슬롯'(보통 A2 또는 2번 슬롯)을 확인해 램 한 개만 그 슬롯에 꽂으세요. ④ 전원을 켜서 디버그 LED가 CPU와 DRAM 단계를 통과해 VGA나 BOOT 단계로 넘어가는지 확인하세요. ⑤ 이 상태에서도 통과하지 못한다면 메모리 문제가 아니라 CPU 장착이나 쿨러 압력 문제로 좁혀집니다."},{"title":"장착 키트 또는 쿨러 교차 확인","why":"느슨하게 해야만 부팅된다면 정상적인 해결 상태가 아닙니다.","how":"① 지금 쓰고 있는 브래킷·스페이서·백플레이트가 서로 다른 세대(예: 이전 소켓용 부품과 새 소켓용 부품을 섞어 쓰는 경우)의 부품이 섞여 있지 않은지 다시 확인하세요. ② 제조사 홈페이지에서 현재 소켓에 맞는 최신 장착 키트를 별도로 구매하거나 무상 교체 신청(제조사에 따라 지원)을 알아보세요. ③ 가능하다면 다른 정상 작동이 확인된 쿨러(예: 기본 번들 쿨러)로 교체해 부팅되는지 비교하세요. ④ 헐겁게 조여야만 부팅되는 상태가 계속된다면 정상적인 해결책이 아니므로, 부품을 교체하거나 전문 조립 업체에 점검을 맡기는 것을 권장합니다."}],"deeper":[{"heading":"AM4와 AM5에서 확인할 차이","text":"AM4 시스템은 쿨러 종류에 따라 메인보드 기본 백플레이트를 재사용하며, 고정 나사를 풀면 뒤쪽 백플레이트가 움직일 수 있습니다. AM5는 소켓 구조와 백플레이트 고정 방식이 다르므로 AM4용 부품을 임의로 혼용하면 안 됩니다. 항상 해당 쿨러의 소켓별 설명서를 우선하세요."},{"heading":"CPU LED와 DRAM LED가 번갈아 켜질 때","text":"AMD 플랫폼은 초기 부팅과 CMOS 초기화 뒤 메모리 훈련에 시간이 걸릴 수 있습니다. 잠깐 LED가 바뀌는 것은 정상일 수 있지만 수분 이상 같은 단계에 머물거나 매번 실패하면 RAM 한 개, 기본 설정, 올바른 장착 상태로 다시 비교해야 합니다."},{"heading":"토크 수치를 그대로 따라 하면 안 되는 이유","text":"Noctua는 자사 NM-ALS1 AMD 장착 바 나사와 쿨러를 장착 바에 고정하는 스프링 나사에 최대 0.6 N·m를 안내합니다. 이는 목표 토크가 아니라 넘지 말아야 할 자사 부품의 최대값입니다. 여러 볼트를 끝까지 조이지 않는 방식이 제조사 설명서에 허용되고 목표 토크가 따로 제시된 경우에는 저토크 드라이버로 각 볼트를 대각선 순서로 같은 값에 맞추는 것이 손으로 같은 회전 수만큼 푸는 것보다 정확합니다. 그러나 공식 목표값이 없다면 임의로 낮춘 토크를 영구 설정으로 사용하지 마세요."},{"heading":"문제가 쿨러 장착에서 시작됐는지 확인하는 방법","text":"부품을 한꺼번에 바꾸면 원인을 찾기 어렵습니다. 쿨러를 바꾸기 전 마지막으로 정상 부팅한 상태, 새 쿨러를 장착한 직후의 LED, 나사를 조금 조절했을 때의 변화, RAM 한 개 테스트 결과를 순서대로 기록하세요. 쿨러를 다시 올바르게 장착했을 때만 문제가 사라지는지 확인하면 소켓·메모리·전원 문제와 장착 압력 문제를 구분하는 데 도움이 됩니다."},{"heading":"장착 키트 호환성을 확인하는 기준","text":"쿨러 포장에 AM4·AM5 또는 여러 소켓 이름이 함께 적혀 있어도 모든 브래킷이 같은 방식으로 설치되는 것은 아닙니다. 쿨러 모델의 개정판, 메인보드 소켓, 백플레이트 두께, 스페이서 높이와 나사 길이를 함께 확인해야 합니다. 중고 쿨러나 누락된 나사 세트는 비슷해 보이는 부품을 섞지 말고 제조사에서 맞는 키트를 받아 사용하세요."},{"heading":"재부팅 후 온도까지 확인해야 하는 이유","text":"화면이 나오고 윈도우가 시작되었다고 장착 문제가 해결된 것은 아닙니다. BIOS 하드웨어 모니터나 메인보드 유틸리티에서 유휴 온도와 짧은 부하 때의 온도 상승을 확인하고, 쿨러 팬·펌프 RPM과 CPU_FAN 또는 AIO_PUMP 연결도 점검하세요. 온도가 비정상적으로 빠르게 오르거나 팬이 멈추면 전원을 끄고 정상 장착 상태를 다시 확인해야 합니다."}],"decision":[{"heading":"올바르게 재장착하니 정상 부팅될 때","text":"CPU 결함보다 장착 부품 조합이나 불균일한 조임이 원인이었을 가능성이 큽니다. 온도와 안정성을 확인한 뒤 정상 장착 상태를 유지하세요."},{"heading":"스프링 나사를 조인 뒤 문제가 생길 때","text":"쿨러 제조사가 허용 토크 범위나 목표값을 안내했다면 모든 스프링 나사를 먼저 균일하게 풀고, 토크 드라이버를 제조사 범위 안에 설정한 뒤 대각선 순서로 같은 값까지 조금씩 조여 비교할 수 있습니다. 공식 범위가 없다면 토크를 임의로 낮추지 말고 장착 키트·스페이서와 쿨러 호환성을 다시 확인하세요."},{"heading":"토크 드라이버가 없을 때의 임시 비교","text":"제조사 설명서에 위반되지 않는 범위에서만, 모든 스프링 나사를 같은 기준으로 조인 뒤 1/4바퀴씩 대각선 순서로 균일하게 풀어 부팅 여부를 비교할 수 있습니다. 1/2바퀴 이상 풀어야만 부팅되면 정상 해결로 보지 말고 즉시 원래 상태로 되돌린 뒤 장착 키트·쿨러 호환성을 점검하세요. 회전량은 실제 토크가 아니므로 이 방법을 최종 체결 기준으로 사용하지 마세요."},{"heading":"RAM 한 개에서는 부팅되지만 두 개에서 실패할 때","text":"RAM 자체, 슬롯, 메모리 설정과 CPU 소켓 접촉을 함께 봐야 합니다. 모듈과 슬롯을 하나씩 바꿔 같은 채널에서만 실패하는지 확인하세요."},{"heading":"다른 정상 쿨러에서도 CPU LED가 멈출 때","text":"소켓 핀, CPU, 메인보드 또는 전원 공급 문제까지 범위를 넓혀 교차 테스트하거나 전문 점검을 받는 편이 안전합니다."}],"examples":["기본 쿨러에서는 부팅되지만 새 공랭 쿨러 장착 뒤 CPU LED에서 멈춤","네 모서리 중 한쪽을 먼저 끝까지 조인 뒤 DRAM LED가 꺼지지 않음","쿨러 교체 후 특정 RAM 슬롯만 인식되지 않음","나사를 풀면 부팅되지만 정상 체결하면 다시 화면이 나오지 않음"],"mistakes":["특정 CPU에서만 발생하는 공통 결함이라고 단정하는 것","쿨러를 느슨하게 둔 상태를 영구 해결책으로 사용하는 것","AM4와 AM5의 백플레이트·스페이서를 임의로 혼용하는 것","제조사 지침이 다른 토크 수치를 모든 쿨러에 적용하는 것","쿨러 없이 전원을 켜거나 핀을 금속 도구로 억지로 펴는 것"],"faq":[{"q":"발열 관리를 위해 사제 쿨러를 장착하는 과정에서 나타날 수 있는 문제인가요?","a":"쿨러 교체 직후 일부 조립 환경에서 나타날 수 있지만, 특정 CPU 전용 결함으로 확인된 것은 아닙니다. CPU 종류보다 쿨러 장착 부품, 메인보드, 조임 방식과 소켓 접촉 상태를 함께 확인해야 합니다."},{"q":"나사를 조금 풀면 부팅되는데 그대로 써도 되나요?","a":"권장하지 않습니다. 냉각면 접촉이 부족해 과열될 수 있습니다. 원인을 확인하는 짧은 진단으로만 사용하고, 올바른 장착 키트로 재설치하거나 쿨러를 교체하세요."},{"q":"CPU LED가 켜졌으면 CPU가 고장난 건가요?","a":"아닙니다. CPU 전원, 소켓 접촉, BIOS 지원, 메모리 초기화와 장착 상태 때문에도 CPU LED에서 멈출 수 있으므로 LED 하나만으로 부품 고장을 확정하면 안 됩니다."},{"q":"얼마나 세게 조여야 하나요?","a":"현재 쿨러 제조사의 설명서를 따라 대각선으로 조금씩 균등하게 조이세요. 예를 들어 Noctua는 일부 AMD 장착 나사와 스프링 나사에 최대 0.6 N·m를 안내하지만 다른 브랜드의 공통값은 아닙니다. 공식 수치가 있다면 저토크 드라이버를 사용할 수 있고, 수치가 없다면 정지 지점을 넘겨 억지로 조이지 마세요."}]},"sound-not-working":{"badge":"오디오","subtitle":"소리가 전혀 안 나거나 장치가 바뀔 때","intro":["소리 문제는 스피커가 고장난 것처럼 보여도 실제로는 출력 장치 선택이 바뀌었거나 드라이버가 꼬인 경우가 많습니다. 이어폰과 스피커, HDMI 오디오가 서로 바뀌어 들어가면 소리가 사라진 것처럼 느껴질 수 있습니다.","오디오가 아예 안 들리는지, 특정 앱에서만 안 들리는지도 구분해야 합니다. 앱 문제와 시스템 문제는 점검 순서가 다릅니다.","설정 화면에서 보이는 출력 장치와 실제 연결된 장치를 맞춰 보는 것이 첫걸음입니다."],"warnings":["볼륨은 켜져 있는데 소리만 없다.","이어폰을 꽂으면 장치가 바뀐다.","앱마다 들리거나 안 들리는 패턴이 다르다."],"checks":[{"title":"출력 장치 확인","why":"기본 출력이 바뀌면 소리가 사라진 것처럼 보입니다.","how":"① 화면 오른쪽 아래 작업 표시줄에서 스피커 아이콘을 클릭하세요. ② 스피커 아이콘 옆의 위쪽 화살표(또는 이름 부분)를 클릭하면 현재 연결된 여러 출력 장치 목록이 나옵니다(예: 스피커, 헤드폰, 모니터의 HDMI 오디오 등). ③ 실제로 소리를 듣고 싶은 장치(스피커나 이어폰)를 목록에서 선택하세요 — 모니터를 HDMI로 연결한 경우 Windows가 자동으로 모니터 스피커를 기본 출력으로 바꿔버리는 경우가 흔합니다. ④ 원하는 장치를 선택한 뒤에도 소리가 안 나면 볼륨이 0으로 되어 있지 않은지, 음소거 아이콘이 켜져 있지 않은지 함께 확인하세요."},{"title":"오디오 드라이버 점검","why":"장치가 잡히지 않으면 드라이버 문제일 수 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '사운드, 비디오 및 게임 컨트롤러' 항목을 펼쳐 오디오 장치 이름 옆에 노란색 느낌표나 아래쪽 화살표(비활성화 표시)가 있는지 확인하세요. ③ 문제가 있는 장치를 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택하세요('드라이버 소프트웨어 삭제' 체크박스가 있다면 함께 체크). ④ 상단 메뉴에서 '동작' → '하드웨어 변경 사항 검색'을 클릭하면 Windows가 기본 드라이버로 장치를 다시 잡습니다. ⑤ 여전히 소리가 안 나면 노트북 제조사(삼성, LG 등) 또는 메인보드 제조사(ASUS, MSI, 기가바이트 등) 홈페이지의 '지원/다운로드' 페이지에서 정확한 모델명을 검색해 오디오 드라이버(보통 Realtek)를 내려받아 설치하세요."},{"title":"포트와 앱별 재현 확인","why":"헤드폰 단자나 특정 앱만 문제인지 나누면 원인이 좁혀집니다.","how":"① 이어폰이나 스피커를 본체 앞면 포트와 뒷면 포트에 각각 꽂아보며 소리가 나는지 비교하세요 — 앞면 포트만 안 되는 경우 케이스 내부 오디오 케이블이 메인보드에 제대로 연결되지 않은 경우가 흔합니다(케이스 옆판을 열어 'HD AUDIO' 또는 'AAFP' 케이블이 메인보드에 꽂혀 있는지 확인하세요). ② 유튜브, 음악 앱, 게임 등 서로 다른 프로그램에서 각각 소리가 나는지 확인하세요 — 특정 앱에서만 소리가 안 나면 해당 앱의 자체 음량 설정이나 출력 장치 설정 문제입니다. ③ Windows 로고 키를 누르고 '볼륨 믹서 설정'을 입력해 실행하면 앱별로 개별 음량이 0으로 되어 있지 않은지 확인할 수 있습니다."}],"deeper":[{"heading":"장치는 보이는데 소리만 없을 때","text":"출력 장치가 보인다고 끝이 아닙니다. 음소거, 앱 볼륨, 향상 기능 충돌이 함께 있으면 실제로는 아무 소리도 안 날 수 있습니다."}],"decision":[{"heading":"장치가 자꾸 바뀔 때","text":"기본 출력 장치 설정과 연결 포트를 다시 맞추세요."},{"heading":"특정 앱만 안 들릴 때","text":"시스템 전체보다 앱별 볼륨과 오디오 출력 지정 문제를 먼저 확인해야 합니다."}],"examples":["유튜브는 안 들리는데 시스템 소리는 들림","모니터를 바꾸면 소리 출력이 사라짐"],"mistakes":["볼륨 아이콘만 보고 끝내는 것","출력 장치가 바뀐 사실을 놓치는 것"],"faq":[{"q":"이어폰을 꽂았는데도 소리가 안 납니다.","a":"기본 출력 장치와 장치 인식 상태를 먼저 확인하고, 다른 포트로도 시험해 보세요."},{"q":"재생 장치가 여러 개면 소리가 안 날 수도 있나요?","a":"네, 기본 재생 장치가 실제 사용 중인 장치와 다르게 지정되어 있으면 소리가 나지 않을 수 있어 기본 장치 설정을 확인해야 합니다."},{"q":"드라이버를 재설치하면 이전 설정이 사라지나요?","a":"이퀄라이저나 음향 효과 등 커스텀 설정은 초기화될 수 있으므로, 재설치 전 설정을 기록해두는 것이 좋습니다."}]},"sleep-resume-fail":{"badge":"절전","subtitle":"절전에서 복귀할 때 화면이 멈추거나 오류가 날 때","intro":["절전 복귀 실패는 단순한 화면 꺼짐과 다릅니다. 잠자기 상태에서 돌아오는 순간 전원 관리 드라이버가 장치를 다시 깨우지 못하면 화면이 멈추거나 블루스크린으로 이어질 수 있습니다.","이 증상은 노트북과 데스크톱 모두에서 보이지만, USB 장치나 네트워크 어댑터가 많은 환경에서 더 자주 드러납니다. 그래서 복귀 직후에만 재현되는지, 연결 장치를 바꾸면 나아지는지를 먼저 봐야 합니다.","절전은 잘 들어가는데 복귀만 안 되는지, 아니면 아예 재부팅까지 이어지는지 구분하면 원인을 더 빨리 좁힐 수 있습니다."],"warnings":["절전 후 화면이 검은 채 멈춘다.","복귀 직후 블루스크린이 뜬다.","USB나 네트워크 장치를 꽂으면 더 심해진다."],"checks":[{"title":"절전 직후 재현 여부","why":"바로 깨어날 때만 문제면 전원 상태 전환이 핵심입니다.","how":"① Windows 로고 키를 누르고 전원 버튼 아이콘을 눌러 '절전'을 선택하세요. ② 절전 모드로 들어간 직후(1분 이내) 마우스를 흔들거나 키보드를 눌러 바로 깨워보고 정상적으로 복귀하는지 확인하세요. ③ 이번에는 10분 이상 절전 상태로 오래 둔 뒤 같은 방식으로 깨워보고 결과를 비교하세요. ④ 바로 깨울 때만 문제가 생기면 화면 출력 전환(대기→활성) 과정의 문제이고, 오래 둔 뒤에만 문제가 생기면 딥슬립·하이버네이션 관련 전원 설정 쪽 원인일 가능성이 큽니다."},{"title":"최근 연결 장치 제거","why":"USB 허브, 도킹 스테이션, 네트워크 장치가 복귀를 방해할 수 있습니다.","how":"① 최근에 새로 연결한 USB 허브, 도킹 스테이션, 외장 랜카드, 프린터 등이 있는지 떠올려보세요. ② 그 장치들을 모두 뽑은 상태에서 절전 후 복귀가 정상적으로 되는지 다시 시험해보세요. ③ 정상적으로 복귀되면 장치를 하나씩만 다시 연결하며 재시험해 어떤 장치가 원인인지 찾으세요. ④ 원인 장치를 찾았다면 장치 관리자에서 해당 장치를 더블클릭해 '전원 관리' 탭의 '이 장치로 인해 컴퓨터의 대기 모드를 종료할 수 있음' 체크박스를 해제해보세요."},{"title":"전원 관리와 BIOS 설정","why":"깊은 절전 설정이 복귀 실패를 더 자주 만듭니다.","how":"① Windows 로고 키를 누르고 '전원 및 절전 설정'을 입력해 들어간 뒤 '전원 관련 추가 설정' → '고급 전원 관리 설정 변경'을 클릭하세요. ② '절전' 항목을 펼쳐 '하이브리드 절전 사용'과 '최대 절전 모드 이후' 옵션을 확인하고, 문제가 반복되면 '하이브리드 절전 사용'을 '해제'로 바꿔보세요. ③ PC를 재부팅해 부팅 직후 Delete 또는 F2 키를 연타해 BIOS 화면으로 들어가세요. ④ BIOS 안에서 'ErP', 'Deep Sleep', 'S3/S4 State' 같은 절전 관련 항목을 찾아 활성화되어 있다면 비활성화로 바꿔보세요(메인보드 제조사·모델에 따라 메뉴 이름과 위치가 다르니, 메인보드 설명서에서 정확한 명칭을 확인하는 것이 정확합니다). ⑤ 변경 후 저장(보통 F10)하고 재부팅해 절전·복귀가 안정적인지 다시 확인하세요."}],"deeper":[{"heading":"블루스크린과 그냥 멈춤을 구분하기","text":"복귀 직후 화면이 멈추는지, 아니면 특정 코드와 함께 블루스크린이 나는지에 따라 보는 항목이 달라집니다. 0x0000009F가 보이면 전원 상태 전환 드라이버 쪽 가능성을 더 높게 봐야 합니다."},{"heading":"노트북과 데스크톱의 차이","text":"노트북은 배터리와 전원 절전 정책이, 데스크톱은 USB 장치와 네트워크 어댑터가 더 큰 변수가 될 수 있습니다."}],"decision":[{"heading":"절전 후에만 멈출 때","text":"전원 관리 드라이버와 주변 장치의 절전 설정을 먼저 점검하세요."},{"heading":"복귀 직후 블루스크린이 뜰 때","text":"최근 장치 드라이버와 0x0000009F 같은 전원 상태 오류를 함께 확인해야 합니다."}],"examples":["절전은 되는데 깨우면 화면이 검은 채 멈춤","잠깐 후에 0x0000009F 블루스크린이 뜸"],"mistakes":["강제 종료만 반복하는 것","절전 설정을 전혀 안 보는 것"],"faq":[{"q":"절전만 문제고 재부팅은 괜찮습니다.","a":"그렇다면 저장장치보다 전원 상태 전환 드라이버나 주변 장치 쪽 가능성이 높습니다."},{"q":"절전 모드를 아예 쓰지 않는 게 나을까요?","a":"완전히 끄기보다는 원인을 점검해 해결하는 것이 배터리·전력 절약 측면에서 유리하며, 절전을 끄는 것은 임시방편으로만 권장합니다."},{"q":"그래픽 드라이버 문제인지는 어떻게 확인하나요?","a":"이벤트 뷰어에서 절전 복귀 시점에 그래픽 드라이버 관련 오류(예: 0x0000009F)가 기록되어 있는지 확인하면 원인을 좁힐 수 있습니다."}]},"gpu-coil-whine":{"badge":"소음","subtitle":"게임이나 고사양 작업 중 그래픽카드에서 고주파 소음이 날 때","intro":["게임 중 그래픽카드에서 \"삐-\" 또는 \"지지직\" 하는 고주파 소음이 들리면 고장부터 의심하기 쉽지만, 대부분은 코일 위스파(coil whine)라고 불리는 정상적인 전기적 현상입니다. 전류가 그래픽카드 인덕터(코일)를 지나며 코일이 미세하게 진동해 나는 소리로, 정도의 차이만 있을 뿐 거의 모든 그래픽카드에서 어느 정도는 발생합니다.","관건은 이 소음이 \"정상 범위\"인지, 아니면 \"점검이 필요한 신호\"인지를 구분하는 것입니다. 소음만 있고 성능·화면에 다른 이상이 전혀 없다면 대부분 신경 쓰지 않아도 되는 수준이고, 최근 들어 갑자기 커졌거나 다른 증상이 동반된다면 점검 대상입니다.","특히 프레임이 매우 높게 나오는 가벼운 게임(로딩 화면, 메뉴 화면 등)에서 GPU가 초당 수백 프레임을 그리려고 하면서 부하가 순간적으로 튈 때 소음이 더 크게 들리는 경우가 흔합니다."],"warnings":["소음이 최근 들어 눈에 띄게 커졌다.","소음과 함께 성능 저하나 화면 깨짐이 나타난다.","소음과 함께 재부팅이나 블랙아웃이 동반된다."],"checks":[{"title":"발생 조건 좁히기","why":"항상 나는지, 특정 상황에서만 나는지에 따라 정상 범위 여부가 갈립니다.","how":"① 소음이 심하게 나는 상황(주로 fps가 매우 높게 나오는 가벼운 게임이나 벤치마크)을 재현해보세요. ② 게임 내 설정이나 NVIDIA 제어판/AMD Software에서 프레임 제한(FPS Cap)을 60~120 정도로 설정하세요. ③ 같은 상황을 다시 실행해 소음이 줄어드는지 비교하세요. ④ 프레임을 제한했을 때 소음이 확실히 줄어든다면, 이는 고장이 아니라 높은 전력 변화에 따른 정상적인 코일 소음일 가능성이 큽니다."},{"title":"동반 증상 확인","why":"소음 단독이면 대부분 정상, 다른 증상이 겹치면 점검 대상입니다.","how":"① 소음이 날 때 게임 프레임이 갑자기 떨어지거나 끊기는지 확인하세요. ② 화면에 깨짐, 줄무늬, 이상한 색이 나타나는지 확인하세요. ③ 소음과 함께 PC가 재부팅되거나 블루스크린이 뜨는 일이 있는지 확인하세요. ④ 소음 외에 이런 증상이 전혀 없다면 대부분 정상적인 코일 소음이며 특별한 조치가 필요 없습니다. 다른 증상이 함께 있다면 하드웨어 점검이 필요하니 서비스센터 문의를 고려하세요."},{"title":"소음 위치 구분","why":"코일 소음과 팬 소음은 원인과 대응이 다릅니다.","how":"① 아무 작업도 하지 않는 유휴 상태(바탕화면만 보고 있을 때)에서도 소리가 나는지 확인하세요. ② 케이스 옆판을 열고 귀를 가까이 대(전원이 켜진 상태에서 손은 넣지 마세요) 소리가 그래픽카드의 팬 쪽에서 나는지, 카드 기판(회로) 쪽에서 나는 '삐-' 또는 '지지직' 소리인지 구분하세요. ③ 팬을 손으로 살짝 멈춰본 뒤(전원을 끈 상태에서만, 회전 중인 팬에 손을 대지 마세요) 그래도 소리가 나는지 비교하면 코일 소음과 팬 소음을 구분하는 데 도움이 됩니다."},{"title":"언더볼팅·파워 리밋으로 완화 시도","why":"전류 변화 폭을 줄이면 코일 진동과 소음이 함께 줄어드는 경우가 많습니다.","how":"① 웹 브라우저에서 'MSI 애프터버너' 공식 홈페이지에 접속해 무료 프로그램을 내려받아 설치하세요. ② 프로그램을 실행하고 'Power Limit(파워 리밋)' 슬라이더를 기본값에서 10~20% 정도 낮추세요. ③ 오른쪽 아래 체크(적용) 버튼을 눌러 설정을 적용하세요. ④ 소음이 나던 게임을 다시 실행해 소음이 줄었는지 비교하세요(성능이 약간 떨어질 수 있다는 점은 감안하세요)."}],"deeper":[{"heading":"코일 위스파는 왜 생기나요","text":"전류가 인덕터(코일)를 통과할 때 코일 내부의 도선이 자기장의 영향으로 미세하게 진동하면서 소리가 납니다. 특히 전력 변화가 빠르고 클수록(높은 fps, GPU 부하 급변) 더 크게 들립니다. 카드 설계나 개체별 편차에 따라 소음 정도가 다를 수 있습니다."},{"heading":"전원 공급과의 관계","text":"파워서플라이의 효율이 낮거나 전류 리플이 크면 같은 그래픽카드라도 소음이 더 도드라질 수 있습니다. 정격 용량이 넉넉하고 효율 등급이 높은 PSU로 바꾸면 줄어드는 경우가 있습니다."},{"heading":"언더볼팅·파워 리밋으로 소음 줄이기","text":"언더볼팅(코어 전압을 낮추는 것)이나 파워 리밋(전력 사용량 상한을 낮추는 것)을 적용하면 GPU에 흐르는 전류의 변화 폭이 줄어들어 코일 진동과 발열, 팬 소음이 함께 줄어드는 경우가 많습니다. MSI 애프터버너 같은 무료 도구로 코어 전압-클럭 곡선을 낮추거나 파워 리밋 슬라이더를 90% 안팎으로 내려 시험해보세요. 적절한 범위 내의 언더볼팅은 성능 손실이 거의 없거나 미미하면서 소음·발열만 줄이는 경우가 많습니다."},{"heading":"제조사 A/S(무상 교환) 판단 기준","text":"코일 노이즈는 대부분의 제조사가 \"정상적인 전기적 현상\"으로 분류하며, 소음 자체만으로는 성능이나 수명에 영향을 주지 않는다는 이유로 무상 교환·환불 대상에서 제외하는 경우가 많습니다. 특정 데시벨(dB) 수치를 공개적으로 명시한 제조사는 확인되지 않으며, 대신 일부 유통사·서비스센터는 문제 제품을 동일 모델의 정상 제품과 나란히 놓고 일정 거리(예: 약 30cm)에서 비교 청취해 \"확연히 차이가 나는 수준\"인지를 판단하는 방식을 씁니다. 즉 절대적인 dB 기준이 아니라 같은 모델 대비 상대적으로 비정상적으로 심한지가 핵심 판단 기준입니다."}],"decision":[{"heading":"소음만 있고 다른 증상이 없을 때","text":"대부분 정상 범위의 코일 노이즈입니다. 신경 쓰인다면 프레임 제한이나 언더볼팅·파워 리밋 조정으로 불필요한 GPU 부하 변화를 줄이는 정도로 충분합니다."},{"heading":"소음이 갑자기 커지거나 다른 증상이 동반될 때","text":"전원부(VRM) 불량이나 카드 자체의 이상일 수 있으니, 다른 PSU로 교체 테스트를 해보고 개선되지 않으면 제조사 A/S를 고려하세요."},{"heading":"A/S(무상 교환)를 문의하기 전에","text":"코일 노이즈 단독으로는 대부분 무상 교환 대상이 아니므로, 문의 전에 동영상으로 소음을 녹음해두고 성능 저하·화면 이상 등 동반 증상이 있는지 함께 정리해두면 접수·판단이 더 수월합니다. 정확한 처리 기준은 구매처(제조사 또는 유통사)의 공식 A/S 정책을 직접 확인하는 것이 가장 정확합니다."}],"examples":["메뉴 화면처럼 fps가 매우 높게 나올 때만 삐- 소리가 남","특정 게임 로딩 화면에서만 지지직 소리가 잠깐 남"],"mistakes":["소음만으로 바로 카드가 고장났다고 단정하는 것","동반 증상(성능 저하, 화면 깨짐) 없이도 무조건 A/S부터 맡기는 것","특정 데시벨을 넘으면 무조건 무상 교환된다고 확신하는 것 — 그런 공개된 절대 기준은 없습니다"],"faq":[{"q":"코일 노이즈가 있으면 그래픽카드 수명에 영향이 있나요?","a":"일반적인 코일 노이즈는 정상적인 전기적 현상으로, 카드 수명이나 성능에 영향을 주지 않습니다. 다만 소음이 급격히 커지거나 다른 이상 증상이 동반된다면 별개로 점검이 필요합니다."},{"q":"프레임 제한을 걸면 소음이 줄어드나요?","a":"많은 경우 도움이 됩니다. 불필요하게 높은 fps로 GPU에 급격한 부하 변화가 생기는 것을 줄이면 코일 진동도 함께 줄어드는 경향이 있습니다."},{"q":"언더볼팅이나 파워 리밋 조정이 그래픽카드에 무리를 주지 않나요?","a":"적절한 범위 내의 언더볼팅·파워 리밋 하향은 오히려 전압·발열 스트레스를 줄이는 방향이라 카드에 무리를 주지 않습니다. 반대로 전압을 높이는 오버볼팅과는 다르니 혼동하지 마세요."},{"q":"몇 데시벨(dB) 이상이면 제조사에서 무상 교환해주나요?","a":"공개적으로 명시된 절대적인 dB 기준을 두는 제조사는 확인되지 않습니다. 대부분은 코일 노이즈 자체를 정상 현상으로 보고, 동일 모델 대비 \"확연히\" 심한 수준인지를 비교 청취로 판단하는 방식을 씁니다. 정확한 기준은 구매처의 공식 A/S 정책을 직접 문의하는 것이 가장 정확합니다."},{"q":"새로 산 그래픽카드인데 소음이 나면 반품해야 하나요?","a":"코일 노이즈 자체는 대부분의 그래픽카드에서 정도 차이로 나타나는 정상 현상이라 반품 사유가 되기는 어렵습니다. 다만 유독 심하게 거슬리는 수준이라면 판매처의 소음 관련 정책을 확인해보세요."}]},"black-screen-after-login":{"badge":"화면","subtitle":"로그인은 끝났는데 바탕화면이 나타나지 않을 때","intro":["로그인 후 검은 화면은 윈도우가 완전히 부팅되지 않은 상태와 구분해야 합니다. 마우스 포인터가 움직이거나 Ctrl+Alt+Delete 화면이 열린다면 시스템 자체는 작동하고 있지만, 바탕화면을 담당하는 Windows 탐색기나 그래픽 출력 경로가 정상적으로 이어지지 않았을 가능성이 큽니다.","업데이트 직후, 그래픽 드라이버 교체 후, 외부 모니터를 사용한 뒤에 특히 잘 나타납니다. 화면이 검다고 곧바로 저장장치 고장이나 윈도우 재설치를 결정하기보다, 키 입력 반응과 작업 관리자 실행 여부로 소프트웨어 문제인지 먼저 나누는 것이 안전합니다.","Microsoft가 안내하는 그래픽 드라이버 재설정, 화면 출력 모드 확인, 탐색기 재시작 순서에 맞춰 확인하면 데이터에 손대지 않고도 원인을 좁힐 수 있습니다. 각 단계 후 화면이 돌아오는지 확인하고 한 번에 여러 설정을 바꾸지 마세요."],"warnings":["로그인 소리는 들리지만 바탕화면과 작업표시줄이 보이지 않는다.","검은 화면 위에서 마우스 포인터만 움직인다.","외부 모니터를 연결하거나 업데이트한 뒤부터 시작됐다."],"checks":[{"title":"화면과 키 입력 반응 구분","why":"Ctrl+Alt+Delete가 열리면 모니터 신호 단절보다 탐색기나 드라이버 문제일 가능성이 높습니다.","how":"① 화면이 검은 상태에서 Ctrl+Alt+Delete를 눌러보세요. ② 잠금·로그아웃·작업 관리자 등의 옵션이 있는 파란색 보안 화면이 뜨면 Windows는 정상 작동 중이고 화면 출력이나 탐색기만 문제인 것입니다 — 아래 항목들을 이어서 확인하세요. ③ 아무 반응이 없다면 모니터 케이블이 제대로 꽂혀 있는지, 모니터의 입력 소스가 올바른지 먼저 확인하세요."},{"title":"그래픽 드라이버 즉시 재설정","why":"절전 복귀나 업데이트 과정에서 그래픽 드라이버만 멈춘 경우 화면 출력이 다시 살아날 수 있습니다.","how":"① 검은 화면 상태에서 Windows 로고 키 + Ctrl + Shift + B를 동시에 눌렀다가 떼세요. ② 짧은 '삑' 소리가 나거나 화면이 잠깐 깜빡이는 것을 확인하세요(소리가 없어도 진행됩니다). ③ 10초 정도 기다리며 화면이 돌아오는지 확인하세요 — 이 단축키는 그래픽 드라이버만 다시 시작시키는 기능으로, 드라이버가 일시적으로 멈춘 경우 효과가 있습니다."},{"title":"Windows 탐색기 다시 실행","why":"explorer.exe가 시작되지 않으면 로그인은 끝나도 바탕화면, 아이콘, 작업표시줄이 나타나지 않습니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요(검은 화면에서도 대부분 작동합니다). ② '프로세스' 탭에서 'Windows 탐색기(explorer.exe)'가 목록에 있는지 확인하세요. ③ 이미 있다면 선택해 마우스 오른쪽 버튼으로 클릭해 '다시 시작'을 선택하세요. ④ 목록에 없다면 상단 메뉴의 '파일' → '새 작업 실행'을 클릭하고 explorer.exe 를 입력한 뒤 '확인'을 누르세요. ⑤ 바탕화면과 작업표시줄이 다시 나타나는지 확인하세요."},{"title":"출력 모드와 외부 화면 분리","why":"윈도우가 보이지 않는 두 번째 모니터로 화면을 보내고 있을 수 있습니다.","how":"① 외부 모니터나 노트북 도킹 스테이션을 사용 중이라면 모두 뽑아보세요. ② Windows 로고 키 + P를 눌러 화면 출력 모드 목록을 여세요('컴퓨터 화면만', '복제', '확장', '두 번째 화면만' 중 선택). ③ 방향키로 'PC 화면만'(또는 '컴퓨터 화면만')을 선택하고 Enter를 누르세요. ④ 이렇게 하면 노트북 자체 화면이나 연결된 첫 번째 모니터로 화면이 강제로 표시됩니다. ⑤ 케이블을 다른 포트로 옮겨 꽂아 교차로도 확인해보세요."}],"deeper":[{"heading":"안전 모드에서는 정상일 때","text":"안전 모드에서 바탕화면이 정상이라면 그래픽 드라이버, 시작 프로그램, 셸 확장 영향이 큽니다. 최근 그래픽 드라이버를 업데이트했다면 장치 관리자에서 이전 드라이버로 되돌리거나 PC 제조사가 제공한 안정 버전을 설치하는 편이 좋습니다."},{"heading":"검은 화면과 부팅 실패의 차이","text":"제조사 로고부터 아무것도 보이지 않으면 이 가이드보다 화면 미출력 가이드가 맞습니다. 로그인 화면은 보였고 로그인 이후에만 검어졌다면 윈도우 셸과 사용자 환경을 먼저 확인해야 합니다."}],"decision":[{"heading":"탐색기 실행으로 복구될 때","text":"하드웨어 교체보다 시작 프로그램과 손상된 셸 확장을 정리하고 시스템 파일 검사를 진행하세요. 다음 로그인에서도 반복되는지 확인해야 합니다."},{"heading":"화면 깜빡임과 블루스크린이 동반될 때","text":"그래픽 드라이버와 GPU 안정성을 함께 점검하세요. 0x00000116이나 0x000000EA가 기록되면 그래픽 장치 관련 상세 페이지를 우선 확인합니다."}],"examples":["로그인 암호 입력 후 포인터만 보이고 작업표시줄은 나타나지 않음","노트북을 외부 모니터에서 분리한 다음 내장 화면이 검게 유지됨","그래픽 드라이버 업데이트 후 첫 재부팅부터 검은 화면이 반복됨"],"mistakes":["화면이 검다는 이유만으로 바로 윈도우를 초기화하는 것","외부 모니터와 도킹 장치를 연결한 채 원인을 판단하는 것","드라이버를 여러 버전 연속 설치하고 재현 여부를 확인하지 않는 것"],"faq":[{"q":"마우스 포인터가 보이면 그래픽카드는 정상인가요?","a":"기본 출력은 되고 있다는 단서지만 그래픽 드라이버가 완전히 정상이라는 뜻은 아닙니다. 탐색기 실행 여부와 드라이버 재설정 반응을 함께 확인하세요."},{"q":"작업 관리자도 열리지 않으면 어떻게 하나요?","a":"외부 화면과 케이블을 분리한 뒤 복구 환경의 안전 모드로 들어가 보세요. 안전 모드도 보이지 않으면 화면 미출력 가이드에 따라 하드웨어 출력 경로를 확인하는 편이 맞습니다."},{"q":"안전 모드로는 들어가지는데 일반 모드는 검은 화면이면 뭘 의심해야 하나요?","a":"안전 모드에서는 기본 드라이버만 로드되므로, 일반 모드에서만 문제가 생긴다면 그래픽 드라이버나 시작 프로그램 충돌을 우선 의심해야 합니다."}]},"disk-usage-100":{"badge":"성능","subtitle":"디스크가 계속 바쁘고 클릭 반응이 늦을 때","intro":["작업 관리자의 디스크 사용률 100%는 저장 공간이 꽉 찼다는 뜻이 아닙니다. 디스크가 처리할 수 있는 작업 시간이 모두 사용 중이라는 의미로, 전송량이 낮아도 응답이 지연되면 100%로 표시될 수 있습니다. 따라서 숫자 하나만 보고 SSD나 HDD를 바로 교체해서는 안 됩니다.","윈도우 업데이트, 검색 인덱싱, 백신 검사처럼 정상적인 백그라운드 작업도 잠시 사용률을 높입니다. 반면 수십 분 동안 사용률이 내려가지 않고 응답 시간이 길거나 디스크 오류가 기록된다면 저장장치 상태, 메모리 부족, 드라이버 문제를 더 자세히 봐야 합니다.","이 가이드는 어떤 프로세스가 디스크를 사용하는지 확인한 다음, 일시적인 작업인지 반복되는 장애 신호인지 구분하도록 구성했습니다. 중요한 파일이 있는 PC에서 오류가 의심되면 검사보다 백업을 먼저 진행하세요."],"warnings":["전송 속도는 낮은데 활성 시간만 계속 100%다.","프로그램을 열 때 수십 초씩 멈추고 디스크 응답 시간이 크게 오른다.","이벤트 로그에 Disk, Ntfs, storahci 관련 경고가 반복된다."],"checks":[{"title":"사용 프로세스와 지속 시간 확인","why":"업데이트나 백신 검사처럼 원인이 분명한 일시적 사용량은 기다리면 내려가지만, 원인 없는 지속 사용은 추가 점검이 필요합니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ② '프로세스' 탭에서 '디스크' 열 머리글을 클릭해 디스크 사용량이 높은 순서로 정렬하세요. ③ 상위에 있는 프로세스 이름을 기록하고, 이 상태로 약 10분간 화면을 지켜보며 사용률이 시간이 지나도 100%를 유지하는지, 아니면 자연스럽게 내려가는지 관찰하세요. ④ Windows 업데이트나 백신 검사처럼 이유가 짐작되는 작업이면 완료될 때까지 기다려도 됩니다. 원인 없이 계속 100%가 유지된다면 아래 항목들로 더 자세히 확인하세요."},{"title":"리소스 모니터에서 파일 경로 확인","why":"같은 프로세스라도 어떤 파일을 반복해서 읽는지 알아야 업데이트, 동기화, 가상 메모리 문제를 구분할 수 있습니다.","how":"① 작업 관리자의 '성능' 탭 맨 아래 '리소스 모니터 열기'를 클릭하세요(또는 Windows 로고 키를 누르고 '리소스 모니터'를 입력해 실행). ② '디스크' 탭을 클릭하면 각 프로세스가 어떤 파일을 읽고 쓰는지 실시간으로 볼 수 있습니다. ③ '총(바이트/초)'이 높은 프로세스를 찾고, 그 아래 '파일' 열에서 반복적으로 나타나는 경로를 확인하세요 — OneDrive나 구글 드라이브 폴더가 계속 보이면 클라우드 동기화가 원인이고, Windows 업데이트 관련 폴더(WinSxS, SoftwareDistribution)가 보이면 업데이트 설치 작업이 원인입니다. ④ 클라우드 동기화가 원인이라면 해당 프로그램을 잠시 일시 중지해 디스크 사용률이 내려가는지 비교하세요."},{"title":"여유 공간과 메모리 사용량 점검","why":"시스템 드라이브 공간이나 메모리가 부족하면 페이지 파일 사용이 늘어 디스크가 계속 바빠질 수 있습니다.","how":"① Windows 로고 키를 누르고 '저장소 설정'을 입력해 실행하세요. ② C 드라이브의 남은 용량을 확인하고, '임시 파일' 항목에 들어가 다운로드 폴더나 임시 파일을 정리해 여유 공간을 10% 이상 확보하세요. ③ 작업 관리자의 '성능' 탭에서 '메모리' 사용률이 90%를 넘는지 확인하세요. ④ 메모리 사용률이 높다면 '프로세스' 탭에서 메모리를 많이 쓰는 프로그램(주로 브라우저 탭이 많을 때)을 정리하세요 — 메모리가 부족하면 Windows가 디스크의 일부를 가상 메모리로 사용하면서 디스크 사용률이 계속 높게 유지될 수 있습니다."},{"title":"건강 상태와 오류 기록 확인","why":"읽기 재시도나 컨트롤러 오류는 낮은 전송량에서도 활성 시간을 100%로 만들 수 있습니다.","how":"① SSD 제조사의 진단 프로그램(삼성이면 Samsung Magician, 기타는 CrystalDiskInfo 같은 무료 프로그램)을 설치해 디스크의 건강 상태를 확인하세요. ② 상태가 '주의' 또는 '경고'로 표시되거나 재할당된 섹터 수가 계속 늘어난다면 디스크 노후화·고장 초기 신호일 수 있습니다. ③ Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행한 뒤 'Windows 로그' → '시스템'에서 'Disk'나 'Ntfs' 관련 경고·오류가 반복되는지 확인하세요. ④ 위 신호가 있다면 디스크 사용률 문제를 해결하려 하기보다, 중요한 사진·문서·파일부터 먼저 외장하드나 클라우드에 백업해 두세요."}],"deeper":[{"heading":"HDD와 SSD에서 해석이 다른 이유","text":"HDD는 작은 파일을 여러 곳에서 읽을 때 헤드 이동 때문에 쉽게 100%에 도달합니다. SSD는 일반 작업에서 계속 100%가 유지된다면 펌웨어, 열로 인한 속도 저하, 여유 공간 부족, 저장장치 오류를 더 주의해서 봐야 합니다."},{"heading":"서비스를 무작정 끄기 전에","text":"검색 인덱싱이나 SysMain을 영구적으로 끄면 당장은 사용률이 내려가도 검색과 앱 실행 성능이 나빠질 수 있습니다. 먼저 해당 서비스가 실제 원인인지 확인하고, 일시 중지 후 재현 여부를 비교해야 합니다."}],"decision":[{"heading":"특정 프로세스가 분명할 때","text":"앱의 업데이트, 동기화, 캐시 설정을 먼저 조정하세요. 정상 작업이 끝난 뒤에도 같은 프로세스가 계속 디스크를 점유하는지 확인합니다."},{"heading":"프로세스가 없는데 100%일 때","text":"응답 시간, 이벤트 로그, SMART 상태를 우선 확인하세요. 소음이나 멈춤이 동반되는 HDD라면 추가 검사를 반복하기보다 백업이 먼저입니다."}],"examples":["부팅 직후 Windows Update가 끝날 때까지 100%였다가 정상으로 내려감","메모리 사용량이 95%를 넘을 때 페이지 파일 읽기와 쓰기가 급증함","전송량은 1MB/s 미만인데 응답 시간이 수천 ms로 올라가 PC가 멈춤"],"mistakes":["디스크 100%를 저장 공간 100%와 같은 뜻으로 해석하는 것","원인 확인 없이 여러 윈도우 서비스를 한꺼번에 사용 중지하는 것","SMART 경고가 있는데 성능 검사와 재부팅을 계속 반복하는 것"],"faq":[{"q":"부팅 직후 몇 분만 100%인 것도 고장인가요?","a":"업데이트, 백신 검사, 시작 앱이 끝난 뒤 내려간다면 정상 범위일 수 있습니다. 지속 시간과 어떤 프로세스가 사용했는지를 함께 보세요."},{"q":"SSD로 바꾸면 무조건 해결되나요?","a":"HDD의 기계적 지연은 크게 줄어들 수 있지만 메모리 부족, 동기화 앱, 손상된 드라이버가 원인이면 SSD에서도 반복될 수 있습니다. 원인을 먼저 구분하는 편이 좋습니다."},{"q":"디스크 사용량이 100%인데 눈에 보이는 원인 프로세스가 없으면 어떻게 하나요?","a":"리소스 모니터(resmon.exe)의 디스크 탭에서 응답 시간이 긴 프로세스를 확인하면 작업 관리자보다 더 구체적으로 원인을 좁힐 수 있습니다."}]},"bluetooth-not-found":{"badge":"블루투스","subtitle":"장치가 검색 목록에 나타나지 않거나 페어링되지 않을 때","intro":["블루투스 장치 미검색은 PC 어댑터 고장보다 장치가 페어링 모드에 들어가지 않았거나 이미 다른 휴대폰에 연결된 경우가 더 흔합니다. 이어폰과 키보드는 전원이 켜진 상태와 페어링 대기 상태가 다르므로 제조사 안내에 맞는 버튼 조작이 필요합니다.","Windows 11에서는 블루투스 장치 검색 범위 설정에 따라 일부 장치가 목록에 늦게 나타날 수 있습니다. 비행기 모드, 거리, 배터리, 기존 페어링 기록을 먼저 정리한 뒤에도 검색되지 않을 때 드라이버와 서비스를 확인하는 순서가 효율적입니다.","USB 블루투스 동글을 사용한다면 허브 전력 부족과 포트 간섭도 변수입니다. 본체 포트에 직접 연결하고 다른 USB 3.x 장치와 거리를 둔 상태에서 다시 검색해 보세요.","장치가 검색·페어링까지는 잘 됐는데 소리만 나오지 않는다면 전혀 다른 문제입니다. 이 경우 블루투스 연결 자체는 정상이고, Windows의 소리 출력 장치가 여전히 스피커나 다른 장치로 지정되어 있어 소리가 엉뚱한 곳으로 나가는 경우가 대부분입니다."],"warnings":["블루투스 켜기 버튼 자체가 설정에서 사라졌다.","장치는 보이지만 연결을 누르면 바로 실패한다.","절전 복귀 후 어댑터가 장치 관리자에서 사라진다.","연결됨으로 표시되는데도 소리가 전혀 나오지 않는다."],"checks":[{"title":"장치의 페어링 모드 확인","why":"전원만 켜진 장치는 주변 검색에 노출되지 않을 수 있고, 다른 기기에 연결 중이면 PC가 찾지 못합니다.","how":"① 블루투스 장치(이어폰, 키보드 등)가 스마트폰 등 다른 기기에 이미 연결되어 있다면, 그 기기의 블루투스를 잠시 꺼서 연결을 끊으세요. ② 장치의 페어링 버튼을 몇 초간 눌러(장치 설명서 참고) 페어링 모드로 진입시키세요 — 표시등이 빠르게 깜빡이면 페어링 대기 상태입니다. ③ 장치를 PC와 1m 이내로 가깝게 두세요. ④ 이 상태에서 PC의 블루투스 검색을 다시 실행하세요."},{"title":"Windows 검색 범위와 비행기 모드 확인","why":"검색 설정이 제한되어 있거나 비행기 모드가 켜져 있으면 정상 장치도 표시되지 않습니다.","how":"① Windows 로고 키를 누르고 '설정'을 실행한 뒤 '블루투스 및 장치'로 들어가세요. ② 상단의 블루투스 스위치를 껐다가 5초 후 다시 켜세요. ③ 화면 오른쪽 아래(비행기 모양 아이콘)를 클릭해 '비행기 모드'가 켜져 있지 않은지 확인하세요(켜져 있으면 블루투스도 함께 꺼집니다). ④ '장치 추가' → '블루투스'를 클릭하고 목록이 나타날 때까지 몇 초 기다리세요."},{"title":"기존 등록을 삭제하고 다시 연결","why":"오래된 인증 키나 중단된 페어링 기록이 남으면 장치가 보여도 연결에 실패할 수 있습니다.","how":"① 설정 → '블루투스 및 장치'에서 문제의 장치를 찾아 클릭한 뒤 '장치 제거'를 선택하세요. ② 블루투스 장치의 전원을 껐다가 다시 켜세요(가능하면 배터리를 분리했다가 다시 끼우세요). ③ PC도 재시작하세요. ④ 재부팅 후 설정 → '블루투스 및 장치' → '장치 추가'로 처음부터 새로 페어링을 진행하세요."},{"title":"어댑터 드라이버와 절전 설정 점검","why":"Bluetooth 항목이 사라지거나 절전 후 반복된다면 어댑터 드라이버와 전원 관리가 핵심입니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '블루투스' 항목을 펼쳐 어댑터 이름 옆에 노란색 느낌표가 있는지 확인하세요. ③ 어댑터를 더블클릭해 '드라이버' 탭에서 '드라이버 업데이트'를 클릭해보세요. ④ 해결되지 않으면 '디바이스 제거' 후 재부팅해 Windows가 다시 잡도록 하세요. ⑤ 그래도 안 되면 노트북이나 메인보드 제조사 홈페이지에서 정확한 모델명으로 검색해 전용 블루투스 드라이버를 내려받아 설치하세요(Windows 기본 드라이버보다 안정적인 경우가 많습니다)."},{"title":"연결은 됐는데 소리만 안 날 때 출력 장치 확인","why":"블루투스 기기가 연결되어도 Windows의 기본 재생 장치가 자동으로 바뀌지 않으면 소리가 스피커 등 다른 출력으로 계속 나갑니다.","how":"① Windows 로고 키를 누르고 '소리 설정'을 입력해 실행하세요. ② '출력' 항목의 드롭다운 목록을 클릭하세요. ③ 연결한 블루투스 기기 이름을 찾아 선택하세요. ④ 목록에 아예 이름이 없다면 블루투스 연결은 됐지만 오디오 프로필로는 잡히지 않은 것이니, 설정 → 블루투스 및 장치에서 해당 장치를 제거한 뒤 처음부터 다시 페어링해보세요."}],"deeper":[{"heading":"장치가 안 보이는 경우와 연결 실패의 차이","text":"목록에 전혀 보이지 않으면 페어링 모드, 검색 범위, 어댑터 상태를 먼저 봅니다. 목록에는 있지만 연결만 실패하면 기존 등록 정보, 배터리, 다른 기기와의 연결, 지원 프로필 문제를 더 우선해서 확인합니다."},{"heading":"블루투스 버튼이 사라졌을 때","text":"빠른 설정에 버튼이 없는 것과 장치 관리자에서 어댑터 자체가 없는 것은 다릅니다. 장치 관리자에서 보기의 숨김 장치 표시를 확인하고, USB 동글이라면 다른 본체 포트에 직접 연결해 하드웨어 인식 여부를 먼저 판단하세요."}],"decision":[{"heading":"다른 휴대폰에서는 검색될 때","text":"블루투스 장치보다 PC의 검색 설정, 어댑터 드라이버, 기존 페어링 기록을 중심으로 점검하세요."},{"heading":"어떤 기기에서도 검색되지 않을 때","text":"장치가 페어링 모드인지와 배터리 상태를 다시 확인합니다. 초기화 방법이 있는 제품은 제조사 절차에 따라 초기화한 뒤 시험하세요."}],"examples":["이어폰이 휴대폰에 자동 연결되어 PC 검색 목록에는 나타나지 않음","Windows 업데이트 후 Bluetooth 켜기 메뉴와 어댑터가 함께 사라짐","USB 동글을 허브에서 본체 포트로 옮기자 검색이 정상화됨"],"mistakes":["전원이 켜진 상태를 페어링 모드로 착각하는 것","기존 연결 기록을 남긴 채 연결 버튼만 반복해서 누르는 것","노트북 제조사 드라이버를 확인하지 않고 임의 드라이버를 여러 번 설치하는 것"],"faq":[{"q":"블루투스 이어폰이 휴대폰에는 연결되는데 PC에는 안 보입니다.","a":"이어폰이 휴대폰에 이미 연결되어 있을 가능성이 큽니다. 휴대폰 블루투스를 잠시 끄고 이어폰을 명시적으로 페어링 모드에 넣은 뒤 PC에서 다시 검색하세요."},{"q":"업데이트 후 블루투스가 사라졌습니다.","a":"장치 관리자에서 어댑터 상태를 확인하고 드라이버 롤백 또는 PC 제조사 최신 드라이버 설치를 시험하세요. 어댑터가 전혀 보이지 않으면 완전 종료 후 다시 켜는 과정도 필요할 수 있습니다."},{"q":"블루투스 이어폰은 되는데 마우스만 안 잡히는 경우도 같은 원인인가요?","a":"장치별로 드라이버나 프로파일이 다를 수 있어, 특정 장치만 문제라면 해당 장치의 펌웨어·배터리 상태를 우선 점검해야 합니다."},{"q":"블루투스 이어폰이 연결됨으로 뜨는데 소리가 하나도 안 들립니다.","a":"연결 자체는 정상인 경우가 대부분입니다. 설정 > 시스템 > 소리에서 출력 장치가 이어폰이 아니라 스피커 등 다른 장치로 지정되어 있지 않은지 확인하고, 이어폰을 직접 출력 장치로 선택하세요."}]},"app-not-launching":{"badge":"프로그램","subtitle":"앱을 눌러도 반응이 없거나 실행 직후 종료될 때","intro":["앱 실행 불가는 아이콘을 눌러도 아무 반응이 없는 경우, 로고가 잠깐 보인 뒤 닫히는 경우, 오류 창이 나타나는 경우로 나눠야 합니다. 겉보기에는 비슷하지만 실행 파일 차단, 사용자 설정 손상, 필수 구성 요소 누락처럼 원인이 서로 다릅니다.","특정 앱 하나만 열리지 않는다면 윈도우 전체 문제보다 해당 앱의 데이터와 설치 상태를 먼저 확인합니다. 여러 앱이 동시에 열리지 않거나 관리자 도구까지 실행되지 않는다면 계정 권한, 시스템 파일, 보안 프로그램의 차단 기록을 더 주의해서 봐야 합니다.","재설치는 유용한 방법이지만 사용자 데이터와 손상된 설정이 그대로 남거나 필요한 런타임이 빠져 있으면 해결되지 않습니다. 오류 문구와 이벤트 기록을 먼저 남긴 뒤 복구, 초기화, 재설치 순서로 진행하는 편이 안전합니다.","프로그램이 아예 안 뜨는지, 뜨다가 멈추는지도 원인을 가르는 단서입니다. 이벤트 뷰어의 Windows 로그 → 응용 프로그램에서 Application Error(이벤트 1000)가 기록됐다면 실행 도중 충돌한 것이고, Application Hang(이벤트 1002)이 기록됐다면 응답 없음 상태로 멈춘 것이라 원인 계열이 다릅니다. 전자는 손상된 파일이나 호환성 문제, 후자는 응답을 기다리는 외부 리소스(네트워크, 다른 프로세스) 문제일 가능성이 더 큽니다."],"warnings":["실행 직후 오류 창 없이 프로세스가 종료된다.","0x80070005 같은 권한 오류가 함께 표시된다.","여러 앱이 같은 시점부터 동시에 열리지 않는다."],"checks":[{"title":"증상 범위와 오류 문구 기록","why":"앱 하나의 문제인지 계정이나 시스템 전체 문제인지에 따라 점검 방향이 완전히 달라집니다.","how":"① 앱을 실행했을 때 뜨는 오류 창이 있다면 정확한 문구를 스마트폰으로 촬영하거나 메모해 두세요(오류 코드가 있다면 특히 중요합니다). ② Ctrl+Shift+Esc를 눌러 작업 관리자를 열고 '프로세스' 탭에서 앱을 다시 실행해보며 해당 앱 이름이 목록에 잠깐이라도 나타났다가 사라지는지 확인하세요. ③ 메모장, 계산기 같은 Windows 기본 앱도 실행해보고 정상적으로 열리는지 확인하세요 — 기본 앱도 안 열리면 시스템 전체의 문제이고, 특정 앱만 안 열리면 그 앱만의 문제로 범위를 좁힐 수 있습니다."},{"title":"완전 종료 후 일반 권한으로 재실행","why":"백그라운드에 멈춘 프로세스나 업데이트 대기 상태가 새 실행을 막을 수 있습니다.","how":"① Ctrl+Shift+Esc로 작업 관리자를 연 뒤 '프로세스' 탭에서 해당 앱 이름을 찾아 선택하고 '작업 끝내기'를 클릭하세요(백그라운드에 멈춰 있을 수 있습니다). ② PC를 재시작하세요. ③ 재시작 후 바탕화면이나 시작 메뉴에서 앱 아이콘을 더블클릭해 일반적인 방법으로 실행해보세요(관리자 권한으로 실행하지 말고 우선 일반 실행을 시도합니다). ④ 그래도 안 열리면 이번에는 아이콘을 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택해 차이가 있는지 확인하세요."},{"title":"앱 복구와 초기화 구분","why":"복구는 데이터 보존을 우선하지만 초기화는 앱 설정과 로그인 정보를 지울 수 있습니다.","how":"① Windows 로고 키를 누르고 '설치된 앱'(또는 '앱 및 기능')을 입력해 실행하세요. ② 문제가 있는 앱을 찾아 점 3개(⋮) 또는 오른쪽 화살표를 클릭해 '고급 옵션'을 선택하세요. ③ 먼저 '복구' 버튼을 클릭하세요 — 앱의 손상된 파일만 다시 설치하고 로그인 정보나 개인 데이터는 대부분 유지됩니다. ④ 복구로 해결되지 않으면 다시 '고급 옵션'으로 들어가 '초기화' 버튼을 클릭하세요 — 단, 초기화는 앱 안의 설정과 로그인 정보를 모두 지우므로, 중요한 로그인 정보나 라이선스 키가 있다면 미리 확인하거나 백업해 두세요."},{"title":"재설치 전 구성 요소와 차단 기록 확인","why":"Visual C++ 런타임, .NET, 그래픽 구성 요소가 누락됐거나 보안 프로그램이 파일을 격리했다면 앱만 다시 설치해도 반복됩니다.","how":"① Windows 로고 키를 누르고 '이벤트 뷰어'를 입력해 실행한 뒤 'Windows 로그' → '응용 프로그램'에서 앱 실행 시각 근처의 오류를 확인하세요. ② 오류 내용에 '.NET', 'Visual C++', 'vcruntime' 같은 단어가 보이면, 마이크로소프트 공식 홈페이지에서 'Visual C++ 재배포 가능 패키지'와 최신 '.NET Desktop Runtime'을 내려받아 설치하세요. ③ 최근 설치한 백신이나 보안 프로그램이 있다면 해당 프로그램의 '격리소' 또는 '차단 기록'을 확인해 앱 파일이 오탐으로 격리되지 않았는지 확인하세요. ④ 위 사항을 모두 확인한 뒤 앱을 완전히 제거하고, 제작사 공식 홈페이지에서 받은 최신 설치 파일로 다시 설치하세요."}],"deeper":[{"heading":"새 사용자 계정에서 확인하는 이유","text":"새 로컬 계정에서는 앱이 열린다면 윈도우 전체보다 기존 사용자 프로필의 설정, 캐시, 권한 문제가 유력합니다. 이 경우 시스템 초기화보다 앱 설정 폴더와 계정별 시작 항목을 점검하는 것이 부담이 적습니다."},{"heading":"이벤트 뷰어에서 볼 항목","text":"Windows 로그의 응용 프로그램에서 앱 이름과 같은 시간대의 오류를 찾습니다. 오류 모듈 이름이 그래픽 드라이버, 런타임 DLL, 앱 자체 파일 중 무엇인지에 따라 업데이트 또는 재설치 대상을 좁힐 수 있습니다."}],"decision":[{"heading":"앱 하나만 열리지 않을 때","text":"해당 앱의 복구, 캐시, 플러그인, 공식 요구 사항을 먼저 확인하세요. 윈도우 초기화나 광범위한 설정 변경은 뒤로 미루는 편이 좋습니다."},{"heading":"여러 앱과 설정 화면까지 열리지 않을 때","text":"시스템 파일 검사와 새 사용자 계정 시험을 진행하고, 최근 업데이트와 보안 프로그램 변경 이력을 함께 확인하세요."}],"examples":["앱 로고가 1초 정도 나타난 뒤 오류 메시지 없이 닫힘","업데이트 후 특정 플러그인을 사용하는 앱만 실행되지 않음","새 사용자 계정에서는 정상인데 기존 계정에서만 0x80070005가 표시됨"],"mistakes":["오류 메시지를 기록하지 않고 바로 앱을 삭제하는 것","사용자 데이터 위치를 확인하지 않은 채 초기화 버튼을 누르는 것","비공식 설치 파일이나 DLL 다운로드 사이트에서 파일을 덮어쓰는 것"],"faq":[{"q":"관리자 권한으로 실행하면 해결되나요?","a":"권한 문제를 구분하는 일시적인 시험으로는 쓸 수 있지만 항상 관리자 권한으로 실행하는 것은 해결책이 아닙니다. 0x80070005가 반복되면 폴더 권한과 보안 차단 기록을 확인하세요."},{"q":"삭제 후 재설치해도 똑같습니다.","a":"사용자 설정 폴더가 남아 있거나 필수 런타임과 드라이버가 원인일 수 있습니다. 공식 제거 절차, 요구 구성 요소, 이벤트 오류 모듈을 확인한 뒤 다시 설치하세요."},{"q":"관리자 권한으로 실행하면 항상 해결되나요?","a":"권한 문제로 인한 실행 실패는 해결되지만, 파일 손상이나 종속성 누락이 원인이라면 관리자 권한만으로는 해결되지 않을 수 있습니다."}]},"no-power":{"badge":"전원","subtitle":"전원 버튼을 눌러도 거의 반응이 없을 때","intro":["전원 반응 없음은 윈도우 문제가 아니라 가장 하드웨어적인 문제에 가깝습니다. 팬이 아예 돌지 않거나 LED만 잠깐 깜빡이고 꺼진다면 전원 공급, 전면 패널, 메인보드 연결을 먼저 확인해야 합니다.","이 증상은 부품 하나만의 문제로 보이기 쉽지만, 실제로는 24핀 ATX 전원이나 8핀 EPS 전원이 살짝 빠져 있어도 생깁니다. 따라서 부품 교체보다 연결 상태 점검이 먼저입니다.","전원 버튼을 눌렀을 때 소리가 나는지, LED가 반응하는지, 완전 무반응인지부터 정확히 나눠 보세요."],"warnings":["팬이 한 번도 돌지 않는다.","전원 LED가 잠깐만 깜빡인다.","본체에서 전기 냄새나 타는 냄새가 난다."],"checks":[{"title":"전원 케이블과 멀티탭 확인","why":"외부 전원 공급이 끊겨 있으면 아무 반응도 없습니다.","how":"① PC로 가는 전원 케이블이 멀티탭이나 벽면 콘센트에 확실히 꽂혀 있는지 확인하세요. ② 멀티탭을 쓰고 있다면 멀티탭 자체의 전원 스위치가 켜져 있는지, 멀티탭에 다른 전자기기(스탠드, 충전기 등)를 꽂았을 때 정상 작동하는지 확인하세요. ③ PC 본체 뒷면의 파워서플라이(PSU)에도 별도의 전원 스위치(보통 'I/O' 표시, 네모난 스위치)가 있습니다 — 이 스위치가 'O'(꺼짐) 쪽으로 눌려 있지 않은지 확인하고 'I'(켜짐) 쪽으로 눌러주세요. ④ 전원 케이블 자체를 다른 케이블로 교체해 케이블 불량 여부도 확인하세요."},{"title":"24핀과 8핀 재체결","why":"메인보드 전원 연결이 살짝만 느슨해도 부팅이 안 됩니다.","how":"① PC 전원을 끄고 벽면 콘센트에서 전원 케이블을 완전히 뽑으세요. ② 케이스 옆판을 열고 메인보드에 꽂힌 굵은 24핀 케이블(ATX 전원, 메인보드 가장자리에 위치)을 찾으세요. ③ 커넥터를 잡고 딸깍 소리가 나도록 완전히 뽑았다가 다시 단단히 꽂으세요. ④ CPU 옆에 꽂혀 있는 좁고 두꺼운 4핀 또는 8핀 케이블(EPS 전원)도 같은 방식으로 뽑았다가 다시 꽂으세요. ⑤ 두 커넥터 모두 완전히 눌러 꽂았는지(중간에 걸리는 느낌 없이 끝까지 들어갔는지) 손으로 눌러 재확인한 뒤 전원을 연결하고 다시 켜보세요."},{"title":"전면 패널 버튼과 케이스 선 점검","why":"버튼 접점이나 프런트 패널 선이 빠져도 반응이 없습니다.","how":"① PC 전원을 끄고 전원 케이블을 뽑으세요. ② 메인보드 아래쪽 가장자리에서 'PANEL', 'F_PANEL', 'JFP1' 등으로 표시된 작은 핀 뭉치를 찾으세요 — 여기에 케이스 전면 버튼과 연결된 얇은 선들(PWR SW, RESET SW, HDD LED, PWR LED 등)이 꽂혀 있습니다. ③ 'PWR SW' 또는 'PWRBTN'이라고 표시된 커넥터가 제대로 꽂혀 있는지 확인하고, 살짝 흔들리거나 빠져 있다면 메인보드 설명서의 핀 배열도(다이어그램)를 보고 정확한 위치에 다시 꽂으세요. ④ 정확한 핀 위치가 헷갈린다면, 케이스 선을 모두 뽑은 상태에서 드라이버 같은 금속 물체로 PWR SW 핀 두 개를 살짝 접촉시켜 전원이 켜지는지 시험할 수 있습니다(전원이 켜지면 메인보드는 정상이고 케이스 버튼이나 선 쪽 문제로 확정됩니다)."}],"deeper":[{"heading":"PSU 문제와 버튼 문제를 나누기","text":"버튼을 눌렀을 때 LED는 켜지지만 바로 꺼지는 경우와, 아예 무반응인 경우는 보는 순서가 다릅니다. 후자는 파워 연결이나 PSU 자체를 더 먼저 의심해야 합니다."}],"decision":[{"heading":"LED도 안 켜질 때","text":"PSU 스위치, 콘센트, 24핀과 8핀 연결을 먼저 보세요."},{"heading":"잠깐 켜졌다 꺼질 때","text":"전원부나 쇼트 가능성까지 고려해야 하며, 부품 재장착을 조심스럽게 진행해야 합니다."}],"examples":["전원 버튼을 눌러도 팬이 1초도 안 돈다","LED만 잠깐 켜졌다가 바로 꺼짐"],"mistakes":["무작정 파워만 교체하는 것","전면 패널 선을 안 보는 것"],"faq":[{"q":"전원은 들어오는데 화면만 안 뜨는 건가요?","a":"그 경우는 전원 반응 없음과 다릅니다. 이 페이지는 본체가 거의 켜지지 않는 상황을 기준으로 봐야 합니다."},{"q":"전원 버튼 LED가 깜빡이기만 하는 것도 같은 문제인가요?","a":"깜빡임 패턴은 메인보드가 자체 진단 결과를 알리는 신호인 경우가 많아, 메인보드 설명서에서 LED 코드의 의미를 먼저 확인하는 것이 좋습니다."},{"q":"파워서플라이(PSU)만 교체하면 확실히 해결되나요?","a":"PSU 자체 고장이 원인이라면 해결되지만, 메인보드나 CMOS 배터리 문제일 수도 있어 교체 전 다른 원인을 함께 점검하는 것이 좋습니다."}],"communityCases":[{"title":"파워서플라이(PSU) 교체로 해결한 사례","summary":"24핀·8핀을 재체결하고 전면 패널 선까지 다시 연결해도 전원이 전혀 들어오지 않던 사례가 있습니다. 여유분으로 가지고 있던 다른 PSU를 임시로 연결하자 바로 정상적으로 켜져 기존 PSU의 고장으로 확인됐고, 새 제품으로 교체한 뒤 완전히 해결됐습니다.","insight":"케이블 연결과 전면 패널 점검까지 마쳤는데도 완전 무반응이라면, 여유 PSU나 파워 테스터로 교체 테스트를 해보는 것이 원인을 가장 빠르게 좁히는 방법입니다."}]},"browser-not-responding":{"badge":"브라우저","subtitle":"탭이나 창이 멈추거나 응답 없음 상태가 될 때","intro":["브라우저 응답 없음은 운영체제 자체의 오류라기보다 브라우저 프로세스가 메모리나 스크립트 처리에서 막히는 현상입니다. 탭이 많거나 확장 프로그램이 많을수록 재현 빈도가 높아집니다.","Aw, Snap 같은 페이지 크래시 메시지는 브라우저 전체가 아니라 해당 탭의 렌더러 프로세스만 죽은 경우가 많아, 다른 탭이 멀쩡한지부터 확인하는 것이 좋습니다.","같은 증상이 특정 사이트에서만 반복되는지, 아니면 브라우저 전체에서 나타나는지 구분하면 원인을 더 빨리 좁힐 수 있습니다."],"warnings":["탭이나 창을 눌러도 한동안 반응이 없다.","특정 페이지에서 Aw, Snap 오류가 자주 뜬다.","브라우저를 새로 켜도 금방 다시 멈춘다."],"checks":[{"title":"작업 관리자에서 프로세스 종료","why":"브라우저 자체 작업 관리자(Shift+Esc, 크롬 기준)로 어떤 탭이 메모리를 많이 쓰는지 먼저 확인할 수 있습니다.","how":"① 브라우저 안에서 Shift+Esc를 누르면 브라우저 자체 작업 관리자가 열립니다(크롬·엣지 기준). ② 목록에서 'CPU'나 '메모리' 열을 클릭해 정렬하고, 유난히 많은 자원을 쓰는 탭이나 확장 프로그램을 확인하세요. ③ 응답 없는 탭이나 확장 프로그램 항목을 선택하고 하단의 '프로세스 종료' 버튼을 클릭하세요(브라우저 전체를 끄지 않고 문제가 되는 탭만 끌 수 있습니다). ④ 그래도 브라우저 전체가 멈춰 있다면 Ctrl+Shift+Esc로 Windows 작업 관리자를 열어 브라우저 전체를 '작업 끝내기'로 종료한 뒤 다시 실행하세요."},{"title":"확장 프로그램 점검","why":"확장 프로그램 충돌이 응답 없음의 흔한 원인입니다.","how":"① 크롬 기준 주소창에 chrome://extensions 를 입력하고 Enter를 누르세요(엣지는 edge://extensions). ② 각 확장 프로그램 옆의 스위치를 모두 꺼서 비활성화하세요. ③ 브라우저를 재시작해 멈춤 현상이 사라졌는지 확인하세요. ④ 사라졌다면 확장 프로그램을 하나씩만 다시 켜고 그때마다 재시작하며 어떤 확장 프로그램이 원인인지 찾으세요."},{"title":"캐시와 하드웨어 가속 확인","why":"손상된 캐시나 맞지 않는 그래픽 가속 설정이 렌더링 멈춤으로 이어질 수 있습니다.","how":"① 크롬 기준 주소창에 chrome://settings/clearBrowserData 를 입력하고 Enter를 누르세요. ② '캐시된 이미지 및 파일' 항목에 체크하고(로그인 정보를 유지하려면 '비밀번호'와 '자동 완성 정보'는 체크 해제) '데이터 삭제'를 클릭하세요. ③ 주소창에 chrome://settings/system 을 입력해 들어간 뒤 '사용 가능한 경우 하드웨어 가속 사용' 스위치를 꺼보세요. ④ 브라우저를 완전히 종료했다가 다시 실행해 멈춤 현상이 줄었는지 확인하세요."}],"deeper":[{"heading":"탭 크래시와 브라우저 전체 멈춤은 다름","text":"Aw, Snap처럼 탭 하나만 크래시 화면이 뜨는 경우와 브라우저 창 전체가 응답 없음이 되는 경우는 원인이 다를 수 있어, 다른 탭이 정상인지부터 확인해야 합니다."}],"decision":[{"heading":"특정 사이트에서만 반복될 때","text":"해당 사이트의 스크립트나 광고 콘텐츠가 원인일 가능성이 높으므로 확장 프로그램(광고 차단 등) 유무를 함께 확인하세요."},{"heading":"브라우저 전체가 느려질 때","text":"탭 개수, 확장 프로그램, 캐시 상태를 먼저 점검하고 필요하면 새 프로필로 재현 여부를 확인하세요."}],"examples":["탭을 10개 이상 열어두면 브라우저가 멈춘다","뉴스 사이트에서 유독 Aw, Snap 오류가 자주 뜬다"],"mistakes":["재부팅만 반복하고 확장 프로그램은 확인하지 않는 것","탭 개수를 줄이지 않고 캐시만 정리하는 것"],"faq":[{"q":"브라우저를 재설치하면 해결되나요?","a":"재설치 전에 확장 프로그램 비활성화와 캐시 정리부터 시도해 보는 것이 좋습니다. 대부분 이 단계에서 원인이 좁혀집니다."},{"q":"시크릿(비공개) 모드에서는 안 멈추는데 이것도 확장 프로그램 문제인가요?","a":"네, 시크릿 모드는 기본적으로 확장 프로그램이 비활성화되므로 시크릿 모드에서 정상이라면 확장 프로그램 충돌 가능성이 높습니다."},{"q":"새 프로필을 만들면 기존 즐겨찾기가 사라지나요?","a":"새 프로필은 별도로 생성되므로 기존 프로필의 즐겨찾기는 그대로 남으며, 필요하면 나중에 데이터를 옮길 수 있습니다."}]},"install-failure":{"badge":"설치","subtitle":"설치 프로그램이 중간에 멈추거나 오류로 실패할 때","intro":["설치 실패는 프로그램이 실행되지 않는 것과는 다른 문제입니다. Windows Installer 서비스, 이전 설치의 잔여 파일, 권한 문제가 겹치면서 설치 자체가 완료되지 못하는 경우가 대부분입니다.","같은 오류 코드라도 새 프로그램 설치 중인지, 업데이트나 재설치 중인지에 따라 먼저 볼 항목이 달라집니다.","설치 로그(%TEMP% 폴더의 MSI 로그)를 확인하면 정확히 어느 단계에서 멈췄는지 파악하는 데 도움이 됩니다."],"warnings":["설치 진행률이 중간에 멈추고 오류 코드가 뜬다.","다른 설치가 진행 중이라는 메시지가 반복된다.","설치 패키지를 열 수 없다는 메시지가 뜬다."],"checks":[{"title":"Windows Installer 서비스 재시작","why":"이 서비스가 멈춰 있거나 충돌하면 어떤 설치도 정상적으로 끝나지 않습니다.","how":"① Windows 로고 키를 누르고 'services.msc'를 입력해 실행하세요. ② 목록에서 'Windows Installer'를 찾아 더블클릭하세요. ③ '서비스 상태'가 '중지됨'이면 '시작' 버튼을 클릭하고, 이미 실행 중이라면 '중지' 후 다시 '시작'을 눌러 재시작하세요. ④ '시작 유형'을 '수동'으로 두고 '확인'을 눌러 저장하세요. ⑤ 설치 파일을 다시 실행해보세요."},{"title":"이전 설치 잔여 파일 정리","why":"제거되지 않은 이전 버전 파일이 새 설치와 충돌할 수 있습니다.","how":"① Windows 로고 키를 누르고 '설치된 앱'을 입력해 실행하세요. ② 설치하려는 프로그램의 이전 버전이 남아 있다면 선택해 '제거'를 진행하세요. ③ Windows 로고 키를 누르고 '%temp%'를 입력해 Enter를 누르면 임시 파일 폴더가 열립니다 — 이 폴더 안의 파일을 전체 선택해 삭제하세요(사용 중이라 삭제되지 않는 파일은 건너뛰어도 됩니다). ④ PC를 재시작한 뒤 설치 파일을 새로 다시 실행하세요."},{"title":"관리자 권한과 백신 예외","why":"권한 부족이나 백신 프로그램의 차단이 설치 중간에 실패로 이어질 수 있습니다.","how":"① 설치 파일(.exe)을 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② 그래도 실패하면 백신 프로그램을 열어 '예외' 또는 '허용 목록' 메뉴를 찾으세요. ③ 설치 파일이 있는 폴더나 파일 자체를 예외 목록에 추가하세요(공식 홈페이지에서 받은 설치 파일임이 확실할 때만 이 방법을 사용하세요). ④ 다시 관리자 권한으로 설치를 시도하고, 설치가 끝나면 예외 설정을 그대로 둘지 제거할지는 프로그램의 신뢰도에 따라 판단하세요."}],"deeper":[{"heading":"MSI 로그로 실패 지점 확인하기","text":"설치가 반복해서 같은 지점에서 실패한다면 로그 파일에서 어떤 구성 요소나 조건에서 멈추는지 확인하는 것이 가장 정확합니다."}],"decision":[{"heading":"특정 프로그램에서만 실패할 때","text":"해당 프로그램의 종속 구성 요소(런타임, 어셈블리)가 손상되었을 가능성이 높으니 재배포 패키지를 다시 설치해 보세요."},{"heading":"모든 설치에서 반복될 때","text":"Windows Installer 서비스나 시스템 계정 권한 문제일 수 있어 시스템 파일 점검이 먼저입니다."}],"examples":["설치 도중 오류 1603과 함께 진행이 멈춘다","설치 패키지를 열 수 없다는 오류(2502/2503)가 뜬다"],"mistakes":["같은 설치 파일을 원인 확인 없이 반복 실행하는 것","임시 파일 정리 없이 재설치만 반복하는 것"],"faq":[{"q":"설치 오류마다 원인이 다 다른가요?","a":"코드에 따라 세부 원인은 다르지만, Windows Installer 서비스 상태와 잔여 파일 정리는 대부분의 설치 오류에서 공통적으로 먼저 확인할 항목입니다."},{"q":"설치 오류 코드를 몰라도 해결할 수 있나요?","a":"오류 코드가 없어도 관리자 권한 실행, 백신 예외 등록, 임시 파일 정리 같은 공통 조치로 상당수 설치 오류가 해결됩니다."},{"q":"재설치 전에 기존 프로그램을 완전히 지워야 하나요?","a":"이전 설치가 비정상 종료된 경우 잔여 파일이 충돌을 일으킬 수 있어, 제어판의 제거 기능과 함께 남은 폴더를 확인해 정리하는 것이 좋습니다."}]},"game-launch-error":{"badge":"게임 실행","subtitle":"게임 클라이언트나 안티치트가 실행을 막을 때","intro":["게임 실행 오류는 대부분 게임 자체보다 안티치트 드라이버(뱅가드, 이지안티치트, 넷프로텍트 등)나 클라이언트 패치 과정에서 발생합니다. 게임 파일 손상보다 이 계층의 문제가 먼저인 경우가 많습니다.","패치 도중 실패하는지, 실행 자체가 안 되는지, 실행 중 튕기는지에 따라 점검 순서가 달라집니다.","여러 게임이 같은 안티치트를 쓰는 경우, 한 게임에서 문제가 생기면 같은 안티치트를 쓰는 다른 게임도 영향을 받을 수 있습니다."],"warnings":["실행 버튼을 눌러도 게임이 뜨지 않는다.","안티치트 관련 오류 메시지가 뜬다.","패치 중 진행률이 멈추거나 실패한다."],"checks":[{"title":"안티치트 드라이버 재설치","why":"안티치트 드라이버가 손상되거나 최신 상태가 아니면 게임 실행 자체가 막힙니다.","how":"① 게임 실행이 안 되는 정확한 오류 메시지에 '안티치트(anti-cheat)', 'EAC', 'BattlEye' 같은 단어가 있는지 확인하세요. ② 게임 공식 홈페이지의 지원 페이지에서 해당 안티치트 프로그램의 '재설치 도구' 또는 '복구 도구'를 찾아 내려받으세요. ③ 도구를 관리자 권한으로 실행해 안내에 따라 재설치하세요. ④ 게임을 다시 실행해보세요."},{"title":"게임 파일 무결성 검사","why":"패치 도중 손상된 파일이 실행이나 패치 실패로 이어질 수 있습니다.","how":"① 게임 런처(스팀, 배틀넷, 에픽게임즈 런처 등)를 실행하세요. ② 라이브러리에서 해당 게임을 찾아 마우스 오른쪽 버튼으로 클릭하세요(런처마다 메뉴 이름이 다릅니다). ③ '속성' → '로컬 파일' → '게임 파일 무결성 확인'(스팀 기준) 또는 '검사 및 복구'(배틀넷 기준) 항목을 클릭하세요. ④ 검사가 끝날 때까지 기다리세요(손상된 파일이 있으면 자동으로 다시 내려받습니다). ⑤ 완료 후 게임을 다시 실행해보세요."},{"title":"보안 프로그램 예외 등록","why":"백신이나 방화벽이 안티치트 드라이버 설치를 막는 경우가 흔합니다.","how":"① 사용 중인 백신 프로그램(Windows 보안, V3, 알약 등)을 실행하세요. ② '예외 설정' 또는 '허용 목록' 메뉴를 찾으세요(Windows 보안이라면 '바이러스 및 threat 방지' → '설정 관리' → '제외 추가 또는 제거'). ③ 게임이 설치된 폴더 전체를 예외 목록에 추가하세요. ④ 안티치트 프로그램의 실행 파일(EasyAntiCheat.exe, BEService.exe 등)도 개별적으로 추가하세요. ⑤ 게임을 다시 실행해보세요."}],"deeper":[{"heading":"안티치트와 게임 클라이언트 구분하기","text":"안티치트 오류 메시지가 뜬다면 게임 파일보다 드라이버 설치 상태를 먼저 봐야 하며, 게임 자체 재설치는 마지막 단계로 미루는 것이 좋습니다."}],"decision":[{"heading":"설치 직후부터 실행이 안 될 때","text":"안티치트 드라이버가 제대로 설치되지 않았을 가능성이 높으니 재설치 도구를 먼저 사용하세요."},{"heading":"잘 되다가 갑자기 안 될 때","text":"최근 Windows 업데이트나 보안 프로그램 업데이트와 시점이 겹치는지 확인하세요."}],"examples":["라이엇 뱅가드 오류로 발로란트가 실행되지 않는다","이지안티치트 오류로 배틀그라운드가 실행되지 않는다"],"mistakes":["안티치트 상태 확인 없이 게임만 재설치하는 것","백신 예외 등록 없이 재설치를 반복하는 것"],"faq":[{"q":"게임을 완전히 삭제하고 다시 깔아야 하나요?","a":"대부분 안티치트 드라이버 재설치나 파일 무결성 검사로 해결되며, 전체 재설치는 이 단계들을 시도한 뒤에도 안 될 때 고려하는 것이 좋습니다."},{"q":"안티치트 프로그램을 아예 삭제해도 되나요?","a":"안티치트는 게임 실행에 필수적인 경우가 많아 삭제보다는 재설치나 예외 설정으로 접근하는 것이 안전합니다."},{"q":"그래픽 드라이버를 최신 버전으로 유지하면 대부분 해결되나요?","a":"실행 오류의 상당수는 드라이버·백신·안티치트 충돌에서 비롯되므로 드라이버 최신화만으로 해결되지 않는다면 백신 예외 설정을 함께 점검해야 합니다."}]},"game-connection-error":{"badge":"게임 연결","subtitle":"런처나 클라이언트가 서버에 연결하지 못할 때","intro":["게임 서버 연결 오류는 인터넷 연결 자체가 끊긴 것과는 다릅니다. 다른 사이트는 잘 되는데 특정 게임 런처만 서버에 접속하지 못하는 경우가 대부분입니다.","런처 캐시 손상, 방화벽·라우터의 포트 차단, DNS 응답 지연이 흔한 원인입니다. VPN을 쓰고 있다면 그 자체가 연결을 방해할 수도 있습니다.","다른 게임이나 기기에서도 같은 서버에 연결이 안 되는지 확인하면, 내 PC 문제인지 서버 쪽 문제인지 빠르게 구분할 수 있습니다."],"warnings":["런처가 서버에 연결 중에서 멈춘다.","특정 게임에서만 연결 오류가 반복된다.","같은 시간대에 여러 번 재시도해도 실패한다."],"checks":[{"title":"런처 캐시 삭제","why":"손상된 캐시 파일이 연결 시도 자체를 실패하게 만들 수 있습니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 열고, 게임 런처(스팀, 배틀넷 등) 관련 프로세스를 모두 찾아 '작업 끝내기'로 완전히 종료하세요. ② 파일 탐색기에서 해당 런처의 캐시 폴더로 이동하세요(스팀은 보통 설치 폴더 안의 'appcache' 폴더, 배틀넷은 'Battle.net' 폴더 안의 'Cache' 폴더). ③ 캐시 폴더 안의 파일들을 삭제하세요(폴더 자체는 남겨두세요). ④ 런처를 다시 실행해 로그인하고 게임 연결을 시도해보세요."},{"title":"공유기 재시작과 DNS 변경","why":"라우터의 임시 오류나 불안정한 DNS 응답이 연결 실패로 이어질 수 있습니다.","how":"① 공유기의 전원 케이블을 뽑고 10초 정도 기다린 뒤 다시 꽂아 재부팅하세요. ② 공유기가 완전히 재부팅될 때까지 1~2분 기다린 뒤 게임 연결을 다시 시도하세요. ③ 여전히 안 된다면 Windows 로고 키를 누르고 '네트워크 및 인터넷 설정'을 입력해 들어간 뒤 '어댑터 옵션 변경'으로 이동하세요. ④ 사용 중인 네트워크 어댑터를 마우스 오른쪽 버튼으로 클릭해 '속성' → 'IPv4' 선택 → '속성'으로 들어가세요. ⑤ 'DNS 서버 주소 사용'을 선택하고 8.8.8.8과 8.8.4.4(구글 DNS)를 입력한 뒤 저장하고 다시 시도하세요."},{"title":"VPN·공식 서버 상태 확인","why":"VPN이 연결을 방해하거나, 서버 자체 장애일 수 있습니다.","how":"① VPN 프로그램을 사용 중이라면 완전히 종료하거나 연결을 끊으세요. ② 이 상태로 게임 연결을 다시 시도해보세요. ③ 여전히 안 된다면 웹 브라우저에서 게임 이름과 '서버 상태' 또는 'server status'를 검색해 공식 상태 페이지나 공식 SNS 공지를 확인하세요. ④ 서버 점검이나 장애 공지가 있다면 PC 문제가 아니므로 공지된 시간까지 기다리세요."}],"deeper":[{"heading":"내 PC 문제인지 서버 문제인지 구분하기","text":"같은 시간에 다른 사람도 같은 게임에서 연결 오류를 겪고 있다면 서버 측 장애일 가능성이 높으므로, 개인 네트워크 설정을 더 건드릴 필요는 없습니다."}],"decision":[{"heading":"내 PC에서만 반복될 때","text":"런처 캐시 삭제와 공유기 재시작을 먼저 시도하고, DNS·VPN 설정을 함께 점검하세요."},{"heading":"여러 사람이 동시에 겪을 때","text":"서버 측 장애일 가능성이 높으니 공식 서버 상태 페이지를 먼저 확인하세요."}],"examples":["배틀넷 오류(BLZBNTBNA0000)로 오버워치가 실행되지 않는다","런처가 서버 연결 중 상태에서 몇 분째 멈춰 있다"],"mistakes":["서버 장애 여부 확인 없이 네트워크 설정만 계속 바꾸는 것","VPN 사용 여부를 확인하지 않는 것"],"faq":[{"q":"인터넷은 되는데 게임만 연결이 안 됩니다.","a":"그렇다면 일반 네트워크 문제보다 런처 캐시나 해당 게임 서버 상태를 먼저 의심해야 합니다."},{"q":"다른 게임은 잘 되는데 특정 게임만 연결이 안 되면 인터넷 문제는 아닌가요?","a":"인터넷 자체보다는 해당 게임 서버 상태나 방화벽의 게임별 예외 설정 문제일 가능성이 높습니다."},{"q":"VPN을 쓰면 연결 오류가 줄어드나요?","a":"일부 지역 접속 문제에는 도움이 될 수 있지만, 게임사 약관상 VPN 사용이 제한되는 경우도 있어 먼저 공식 안내를 확인하는 것이 좋습니다."}]},"keyboard-mouse-not-detected":{"badge":"하드웨어","subtitle":"키보드와 마우스가 인식되지 않거나 갑자기 입력이 안 될 때","intro":["키보드·마우스 미인식 문제는 USB 포트 불량, 드라이버 충돌, Windows HID 서비스 오류, 또는 하드웨어 자체 결함 중 하나인 경우가 대부분입니다. 증상이 시작된 시점(업데이트 이후인지, 포트 교체 이후인지)을 먼저 떠올리면 원인을 빠르게 좁힐 수 있습니다.","일부 경우는 절전 모드 복귀 이후 USB 포트 전원이 제대로 공급되지 않아 발생합니다. 장치 관리자에서 USB 루트 허브의 절전 설정을 끄면 해결되는 경우가 많습니다.","무선 기기라면 배터리와 수신기 연결 상태를 먼저 확인하세요."],"warnings":["업데이트 직후 키보드·마우스가 모두 인식되지 않는다.","재부팅 후에는 잠깐 인식됐다가 다시 연결이 끊어진다.","특정 USB 포트에 꽂았을 때만 인식된다."],"checks":[{"title":"다른 USB 포트로 연결","why":"특정 포트의 전원 공급 문제나 물리적 결함일 수 있습니다.","how":"① USB 허브를 사용 중이라면 허브를 거치지 않고 케이블을 PC 본체 뒷면의 포트에 직접 꽂으세요. ② 그래도 인식이 안 되면 앞면과 뒷면의 다른 포트로 바꿔가며 꽂아보세요. ③ 특정 포트에서만 인식이 안 된다면 그 포트의 접촉 불량이나 고장을 의심하고 다른 포트를 사용하세요."},{"title":"다른 PC에서 동작 확인","why":"장치 자체 고장인지 PC 설정 문제인지 구분할 수 있습니다.","how":"① 문제의 키보드나 마우스를 다른 PC나 노트북에 연결해보세요. ② 다른 PC에서는 정상적으로 동작한다면 장치 자체는 고장이 아니고, 원래 PC의 드라이버나 설정 문제입니다. ③ 다른 PC에서도 전혀 반응이 없다면 장치 자체의 고장(케이블 단선, 리시버 고장 등)일 가능성이 크므로 교체를 고려하세요."},{"title":"장치 관리자에서 드라이버 재설치","why":"HID 장치 드라이버가 손상되면 인식에 실패합니다.","how":"① 문제없이 동작하는 다른 키보드나 마우스로 PC를 조작할 수 있는 상태를 먼저 확보하세요(터치스크린 노트북이면 화면 터치로도 가능합니다). ② Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ③ '휴먼 인터페이스 장치' 항목을 펼쳐 이름을 알아보기 어려운 장치들을 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택하세요('키보드'와 '마우스 및 기타 포인팅 장치' 항목도 함께 확인하세요). ④ 상단 메뉴의 '동작' → '하드웨어 변경 사항 검색'을 클릭해 Windows가 장치를 다시 인식하도록 하세요."},{"title":"USB 루트 허브 절전 해제","why":"절전 복귀 후 USB 포트 전원이 꺼진 채 유지될 수 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '범용 직렬 버스 컨트롤러' 항목을 펼치세요. ③ 'USB 루트 허브'로 시작하는 각 항목을 하나씩 더블클릭하세요. ④ '전원 관리' 탭을 클릭해 '전력을 절약하기 위해 컴퓨터에서 이 장치를 끌 수 있음' 체크박스가 있다면 해제하고 '확인'을 누르세요. ⑤ 모든 'USB 루트 허브' 항목에 대해 같은 작업을 반복한 뒤 재부팅하세요."}],"deeper":[{"heading":"부팅 시 BIOS에서는 인식될 때","text":"BIOS 화면에서는 키보드가 작동하지만 Windows 진입 후 안 된다면 드라이버 또는 HID 서비스 문제입니다. 안전 모드로 진입해 장치 관리자를 확인하세요."},{"heading":"Bluetooth 장치 연결 불안정","text":"Bluetooth 키보드·마우스는 드라이버 외에 Bluetooth 어댑터 펌웨어 문제나 다른 장치와의 주파수 충돌로 끊기는 경우가 있습니다. 2.4GHz 무선 장치와 같이 사용 중이라면 USB 수신기 위치를 바꿔 보세요."}],"decision":[{"heading":"드라이버 재설치 후 해결될 때","text":"HID 드라이버 손상이 원인이었습니다. 이후 업데이트 이후 재발 시 같은 방법으로 해결 가능합니다."},{"heading":"다른 PC에서도 인식 안 될 때","text":"장치 자체 고장입니다. 보증 기간 내라면 교체 요청, 아니라면 새 장치를 구매하는 것이 빠릅니다."}],"examples":["업데이트 후 USB 키보드가 인식되지 않는다","절전 모드 복귀 후 마우스가 움직이지 않는다"],"mistakes":["드라이버 확인 없이 새 장치부터 구매하는 것","USB 허브 경유 연결 상태에서 포트 불량으로 단정하는 것"],"faq":[{"q":"BIOS에서는 키보드가 작동하는데 Windows에서는 안 됩니다.","a":"드라이버 또는 HID 서비스 문제일 가능성이 높습니다. 안전 모드로 진입해 장치 관리자에서 HID 장치 드라이버를 재설치하세요."},{"q":"무선 마우스인데 수신기가 꽂혀 있어도 안 됩니다.","a":"배터리를 먼저 교체하고, 수신기를 뽑았다가 다시 꽂아 보세요. 수신기 자체 불량이라면 제조사에서 수신기만 별도 구입할 수 있습니다."}]},"copy-paste-not-working":{"badge":"Windows","subtitle":"Ctrl+C/V가 작동하지 않거나 클립보드 내용이 유지되지 않을 때","intro":["클립보드 오류는 rdpclip.exe 프로세스 충돌, 특정 앱의 클립보드 잠금, 또는 클립보드를 감시하는 보안·유틸리티 프로그램과의 충돌이 주요 원인입니다. 재부팅 없이 해당 프로세스만 재시작해 해결되는 경우가 많습니다.","원격 데스크톱(RDP) 환경에서는 클립보드 동기화 설정이 따로 있어 이 설정이 꺼져 있으면 복사·붙여넣기가 동작하지 않습니다.","메모장처럼 가장 단순한 앱에서 재현되는지 확인하면 앱 자체 문제와 시스템 전체 문제를 빠르게 구분할 수 있습니다."],"warnings":["Ctrl+C로 복사한 내용이 Ctrl+V로 붙여넣어지지 않는다.","클립보드 내용이 잠시 후 자동으로 지워진다.","특정 앱에서만 붙여넣기가 안 된다."],"checks":[{"title":"rdpclip.exe 재시작","why":"rdpclip 프로세스가 충돌하면 클립보드가 응답하지 않습니다.","how":"① 원격 데스크톱(RDP)으로 다른 PC에 접속한 상태에서 복사·붙여넣기가 안 되는 경우입니다. ② 원격 접속한 PC 안에서 Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ③ '프로세스' 탭에서 'rdpclip.exe' 또는 'RDP 클립보드 모니터'를 찾아 선택하고 '작업 끝내기'를 클릭하세요. ④ 상단 메뉴의 '파일' → '새 작업 실행'을 클릭하고 rdpclip 을 입력한 뒤 '확인'을 누르세요. ⑤ 다시 복사·붙여넣기를 시도해보세요."},{"title":"메모장에서 복사·붙여넣기 테스트","why":"특정 앱 문제인지 시스템 전체 문제인지 구분합니다.","how":"① Windows 로고 키를 누르고 '메모장'을 입력해 실행하세요. ② 아무 텍스트나 입력한 뒤 마우스로 드래그해 선택하세요. ③ Ctrl+C를 눌러 복사하세요. ④ 같은 메모장이나 다른 메모장 창에 커서를 놓고 Ctrl+V를 눌러 붙여넣기가 되는지 확인하세요. ⑤ 메모장에서는 정상적으로 되는데 특정 프로그램에서만 안 된다면, 그 프로그램의 문제이니 프로그램을 재시작하거나 업데이트해보세요."},{"title":"클립보드 기록 활성화 확인","why":"클립보드 기록이 꺼져 있으면 일부 기능이 정상 동작하지 않습니다.","how":"① Windows 로고 키를 누르고 '클립보드 설정'을 입력해 실행하세요. ② '클립보드 기록' 스위치를 켜세요. ③ 아무 텍스트나 복사(Ctrl+C)한 뒤 Windows 로고 키 + V를 눌러보세요. ④ 방금 복사한 항목이 목록에 나타나는지 확인하세요 — 나타나면 클립보드 자체는 정상 작동하는 것입니다."},{"title":"최근 설치한 프로그램 점검","why":"클립보드를 모니터링하는 유틸리티가 충돌을 일으킵니다.","how":"① Windows 로고 키를 누르고 '앱 및 기능'을 입력해 들어간 뒤 설치 날짜순으로 정렬하세요. ② 최근에 설치한 프로그램 중 클립보드를 감시하거나 확장하는 종류(비밀번호 관리자, 번역 프로그램, 클립보드 관리 도구, 화면 캡처 툴 등)가 있는지 확인하세요. ③ 의심되는 프로그램을 하나씩 완전히 종료(작업 관리자에서 확인)하거나 일시적으로 제거한 뒤, 그때마다 복사·붙여넣기가 정상으로 돌아오는지 테스트하세요. ④ 원인 프로그램을 찾았다면 그 프로그램의 설정에서 클립보드 관련 기능을 끄거나, 최신 버전으로 업데이트해보세요."}],"deeper":[{"heading":"모든 앱에서 안 되는 경우","text":"클립보드 서비스 자체 오류입니다. 관리자 권한 명령 프롬프트에서 sfc /scannow를 실행해 시스템 파일 손상을 점검하세요."},{"heading":"원격 데스크톱 환경","text":"RDP 연결에서 클립보드가 안 된다면 원격 데스크톱 연결 설정의 로컬 리소스 탭에서 클립보드 항목이 체크되어 있는지 확인하세요."}],"decision":[{"heading":"rdpclip 재시작 후 해결될 때","text":"일시적 충돌이었습니다. 반복 시 PC를 재부팅하면 해결됩니다."},{"heading":"특정 프로그램 삭제 후 해결될 때","text":"해당 프로그램이 클립보드를 독점하고 있었습니다. 대체 프로그램을 찾거나 설정을 조정하세요."}],"examples":["Chrome에서 Ctrl+C로 텍스트를 복사해도 Word에 붙여넣기가 안 된다","원격 데스크톱 연결 후 복사·붙여넣기가 동작하지 않는다"],"mistakes":["PC를 재부팅하기 전에 rdpclip 재시작을 시도하지 않는 것","클립보드 관련 소프트웨어 충돌 가능성을 확인하지 않는 것"],"faq":[{"q":"복사·붙여넣기가 갑자기 안 되면 어떻게 하나요?","a":"작업 관리자에서 rdpclip.exe를 종료하고 새 작업 실행에서 rdpclip을 다시 시작해 보세요."},{"q":"클립보드 내용이 계속 지워지면?","a":"백신이나 클립보드 모니터링 프로그램이 원인일 수 있습니다. Win+V로 클립보드 기록을 확인하고 최근 설치한 프로그램을 점검하세요."}]},"fan-noise":{"badge":"하드웨어","subtitle":"CPU 팬이나 케이스 팬이 갑자기 시끄러워지거나 항상 최고 속도로 도는 경우","intro":["팬 소음이 갑자기 커지는 원인은 크게 두 가지입니다. 발열이 높아져 팬이 정상적으로 빠르게 도는 경우와, 발열과 무관하게 팬 제어 설정이나 하드웨어 문제로 팬이 과도하게 도는 경우입니다. 온도를 먼저 측정해 어느 쪽인지 구분하는 것이 해결의 출발점입니다.","장기간 사용한 PC라면 쿨러와 방열판에 먼지가 쌓여 열 배출이 막혀 발열이 높아진 것이 원인인 경우가 많습니다. 서멀 구리스도 3~5년이 지나면 굳어 열전도율이 낮아집니다.","팬에서 드르륵, 끼익 같은 마찰음이 난다면 단순 소음 문제가 아닌 팬 베어링 마모 신호이므로 교체를 고려해야 합니다."],"warnings":["평소보다 팬 소리가 훨씬 크다.","부팅 직후부터 팬이 최고 속도로 돈다.","팬에서 드르륵, 끼익 같은 마찰음이 난다."],"checks":[{"title":"온도 측정","why":"팬이 빠른 것이 정상적인 발열 반응인지 비정상적 제어 문제인지 구분합니다.","how":"① 웹 브라우저에서 'HWiNFO' 공식 홈페이지에 접속해 무료 프로그램을 내려받아 설치하세요. ② 프로그램을 실행하고 'Sensors' 창을 열어 아무 작업도 하지 않는 유휴 상태의 CPU·GPU 온도를 확인하세요. ③ 게임이나 무거운 작업을 실행해 부하를 건 상태에서도 같은 방식으로 온도를 확인하세요. ④ 유휴 시 CPU가 50도를 넘거나 부하 시 90도 이상까지 오른다면 발열(쿨링) 문제로 판단하고 아래 먼지 청소 항목을 진행하세요."},{"title":"먼지 청소","why":"방열판 핀 사이의 먼지가 열 배출을 크게 막습니다.","how":"① PC 전원을 끄고 전원 케이블을 뽑으세요. ② 케이스 옆판을 열고 CPU 쿨러(방열판+팬), 그래픽카드 팬, 케이스에 달린 팬들에 먼지가 쌓여 있는지 눈으로 확인하세요. ③ 캔에어(압축공기 스프레이)로 각 팬 날개와 방열판 사이의 먼지를 불어내세요(팬이 빠르게 헛돌지 않도록 손가락으로 살짝 고정하고 뿌리는 것이 좋습니다). ④ 파워서플라이 뒷면의 통풍구도 캔에어로 청소하세요(파워 내부는 직접 열지 마세요). ⑤ 케이스를 닫고 전원을 켜 소음이 줄었는지 확인하세요."},{"title":"BIOS 팬 설정 확인","why":"팬 커브가 잘못 설정되면 온도와 무관하게 팬이 최고 속도로 돌 수 있습니다.","how":"① PC를 재부팅하며 부팅 직후 Delete 또는 F2 키를 연타해 BIOS 화면으로 들어가세요. ② 'Q-Fan', 'Smart Fan', 'Fan Xpert' 등의 이름으로 된 팬 제어 메뉴를 찾으세요(메인보드 제조사마다 이름이 다릅니다). ③ 팬 속도가 온도와 무관하게 '수동(Manual)' 100%로 고정되어 있지 않은지 확인하세요. ④ '표준(Standard)' 또는 '자동(Auto)' 모드로 바꾸거나, 낮은 온도에서는 팬이 천천히 돌도록 커브를 완만하게 조정하세요. ⑤ 저장 후 재부팅해 평소 소음이 줄었는지 확인하세요."},{"title":"소음 종류 구분","why":"마찰음은 베어링 마모 신호로 빠른 교체가 필요합니다.","how":"① 케이스 옆판을 열고 어느 팬에서 소리가 나는지 하나씩 손으로 살짝 멈춰보며(전원이 켜진 상태에서 손가락을 팬 날개에 대지 말고, 옆에서 진동만 확인하거나 잠시 전원을 끈 뒤 손으로 팬을 돌려보는 방식으로) 확인하세요. ② 소리가 단순히 '휘잉' 하는 바람 소리(회전 소음)라면 대부분 정상이며, 팬 속도 설정만 조정하면 됩니다. ③ '드르륵', '끼익' 하는 마찰음이나 덜컹거리는 소리가 난다면 팬 베어링이 마모된 신호입니다. ④ 마찰음이 확인된 팬은 계속 방치하면 완전히 멈춰 발열로 이어질 수 있으니, 같은 규격(mm 크기)의 새 팬으로 교체를 준비하세요."}],"deeper":[{"heading":"온도가 높을 때 순서","text":"먼지 청소 후에도 온도가 잡히지 않으면 서멀 구리스 재도포를 시도합니다. 그래도 개선되지 않으면 쿨러 마운트 불량이나 쿨링 솔루션 교체를 고려하세요."},{"heading":"온도가 정상인데 팬만 빠를 때","text":"BIOS 기본값 초기화 또는 팬 제어 소프트웨어(SpeedFan, Argus Monitor 등) 설정을 직접 조정해 보세요."}],"decision":[{"heading":"청소 후 온도가 내려갈 때","text":"먼지가 원인이었습니다. 6개월~1년에 한 번 정기 청소를 권장합니다."},{"heading":"마찰음이 날 때","text":"해당 팬을 동일 규격(크기, 핀 수)의 새 팬으로 교체합니다. 보증 기간 내라면 제조사 서비스 센터에 문의하세요."}],"examples":["갑자기 팬 소음이 심해져 거슬린다","게임 후 PC 전원을 꺼도 팬이 한참 돌다가 꺼진다"],"mistakes":["온도를 측정하지 않고 BIOS 팬 설정부터 건드리는 것","마찰음을 단순 소음으로 여겨 방치하는 것"],"faq":[{"q":"PC 팬이 갑자기 엄청 시끄러워지면 어떻게 하나요?","a":"HWiNFO64로 CPU·GPU 온도를 확인하세요. 80도 이상이라면 먼지 청소와 서멀 구리스 재도포를 고려해야 합니다. 온도가 정상인데 팬만 빠르다면 BIOS 팬 커브 설정을 점검하세요."},{"q":"팬에서 마찰음이 나면 교체해야 하나요?","a":"드르륵 또는 끼익 소리가 나는 팬은 베어링이 마모된 것으로 곧 고장날 수 있습니다. 동일 규격의 새 팬으로 교체하는 것이 좋습니다."}]},"network-drive-error":{"badge":"네트워크","subtitle":"연결된 네트워크 드라이브에 접근되지 않거나 재부팅 후 매핑이 사라질 때","intro":["네트워크 드라이브 오류는 자격 증명 만료, 네트워크 검색 설정, SMB 프로토콜 버전 불일치, 로그인 시 재연결 실패 중 하나인 경우가 대부분입니다. 증상이 처음 발생한 시점(Windows 업데이트 이후인지, 비밀번호 변경 이후인지)을 먼저 떠올리면 원인을 빠르게 좁힐 수 있습니다.","실제 현장에서는 NAS보다 오히려 '사무실 PC끼리 직접 공유하는 폴더'에서 이 문제가 더 자주 보고됩니다 — 회사 PC 한 대에 업데이트가 적용된 뒤 다른 동료 PC에서 그 PC의 공유폴더에 접속이 안 되는 경우가 대표적입니다.","Windows 10/11은 기본적으로 SMB1 프로토콜을 비활성화하고 있어, 구형 NAS나 서버에 접근할 때 이 설정 때문에 연결이 안 되는 사례가 늘고 있습니다.","Windows 11 24H2부터는 SMB 서명(signing)이 모든 연결에 기본으로 강제되고, 계정 없이 접속하는 게스트 폴백도 기본 비활성화됩니다. 이전까지 시놀로지 등 NAS의 '누구나 접근 가능' 공유 폴더로 잘 쓰던 환경이라면, 업데이트 이후 정상적인 계정·비밀번호를 입력해도 계속 거부되는 것처럼 보일 수 있습니다 — 이는 오류가 아니라 마이크로소프트의 의도된 보안 강화 조치입니다.","ping으로 서버 자체가 응답하는지 먼저 확인하면 네트워크 레이어와 SMB 레이어 문제를 빠르게 구분할 수 있습니다."],"warnings":["재부팅 후 네트워크 드라이브 문자(Z: 등)가 사라져 있다.","탐색기에서 네트워크 드라이브를 열면 액세스 거부 또는 경로 없음 오류가 난다.","특정 시점부터 NAS나 공유 폴더에 연결이 안 된다.","\\\\NAS이름(예: \\\\ITSVC)으로 접속하면 비밀번호 오류가 나지만 \\\\IP주소로는 정상 접속된다.","회사에서 동료 PC의 공유폴더에 접속하면 '네트워크 자격 증명' 입력창이 반복해서 뜨거나 '사용자 이름 또는 암호가 틀립니다'가 나온다(그 PC 자체 로그인은 정상).","PC 여러 대 중 일부는 NAS·공유폴더에 잘 접속되는데, 특정 PC들만 아예 응답이 없거나 시간 초과로 접속이 안 된다."],"checks":[{"title":"네트워크 검색 및 공유 설정 확인","why":"네트워크 검색이 꺼져 있으면 공유 폴더를 찾을 수 없고, '파일 및 프린터 공유'가 꺼져 있으면 내 PC의 폴더를 남에게 공유할 수 없습니다. 이 둘은 같은 화면에 있지만 서로 다른 토글입니다.","how":"① 키보드에서 Windows 로고 키를 누르고 '제어판'이라고 입력한 뒤 Enter를 누르세요. ② 제어판 창에서 '네트워크 및 인터넷'을 클릭하세요. ③ '네트워크 및 공유 센터'를 클릭하세요. ④ 왼쪽 메뉴에서 '고급 공유 설정 변경'을 클릭하세요. ⑤ 내 PC가 연결된 네트워크 프로필(보통 '개인' 또는 '사설') 항목을 펼치고, '네트워크 검색 켜기'와 '파일 및 프린터 공유 켜기'에 각각 동그라미(라디오 버튼)를 클릭해 선택하세요. ⑥ 화면 맨 아래 '변경 내용 저장' 버튼을 눌러 저장하세요. 공유하는 쪽 PC(폴더를 남에게 보여주는 PC)라면 '파일 및 프린터 공유'가 꺼져 있지 않은지 특히 확인하세요."},{"title":"자격 증명 관리자 점검","why":"비밀번호 변경 후 저장된 자격 증명이 갱신되지 않으면, 새로 입력한 값이 서버에 전달되지 않고 예전 값이 계속 재사용되어 실패합니다.","how":"① Windows 로고 키를 누르고 '자격 증명 관리자'라고 입력한 뒤 Enter를 누르세요. ② 화면 위쪽의 'Windows 자격 증명' 탭을 클릭하세요. ③ 목록을 살펴보며 접속하려는 NAS 이름이나 상대 PC 이름(또는 IP 주소)이 적힌 항목을 찾으세요. ④ 그 항목을 한 번 클릭하면 아래로 펼쳐지는데, 여기서 '제거' 버튼을 클릭해 삭제하세요. ⑤ 파일 탐색기 주소창에 다시 \\\\NAS이름 또는 \\\\IP주소를 입력해 접속을 시도하면, 사용자 이름과 비밀번호를 새로 입력하라는 창이 뜹니다. ⑥ 정확한 사용자 이름과 비밀번호를 입력하고 '자격 증명 저장'에 체크한 뒤 '확인'을 누르세요."},{"title":"NAS 계정 잠금(Auto Block) 여부 확인","why":"캐시된 예전 비밀번호로 반복 접속을 시도하면 NAS가 실패 횟수를 로그인 공격으로 인식해, 실제로는 비밀번호가 맞아도 계정이나 접속 IP를 일시 차단합니다.","how":"① 웹 브라우저 주소창에 시놀로지 NAS 주소(예: http://192.168.0.6:5000)를 입력해 접속하고 관리자 계정으로 로그인하세요. ② 왼쪽 위 시작 메뉴(네모 아이콘 여러 개가 모인 모양)를 클릭하고 '제어판'을 선택하세요. ③ '보안' 항목을 클릭하세요. ④ 위쪽 탭 중 '계정' 탭을 클릭하세요. ⑤ '계정 보호'(또는 'Auto Block') 항목에서 현재 차단된 IP나 계정이 있는지 확인하세요. ⑥ 차단된 항목이 있다면 체크한 뒤 '차단 해제' 버튼을 클릭하세요. 다른 NAS·서버 장비도 이름은 달라도 비슷한 '로그인 실패 차단' 메뉴가 있을 수 있습니다."},{"title":"드라이브 재매핑 옵션 확인","why":"'로그온 시 다시 연결' 옵션이 없으면 재부팅마다 드라이브가 사라집니다.","how":"① 작업 표시줄의 폴더 모양 아이콘을 클릭해 파일 탐색기를 여세요. ② 왼쪽 메뉴의 '내 PC'를 마우스 오른쪽 버튼으로 클릭한 뒤 '네트워크 드라이브 연결'을 선택하세요(Windows 11에서 이 메뉴가 안 보이면 위쪽의 '···' 더보기 버튼을 먼저 클릭하세요). ③ '드라이브' 항목에서 원하는 드라이브 문자를 하나 선택하세요(예: Z:). ④ '폴더' 입력란에 \\\\NAS이름(또는 IP주소)\\공유폴더이름 형식으로 정확히 입력하세요. ⑤ '로그인 시 다시 연결'과 '다른 자격 증명을 사용하여 연결' 두 항목에 모두 체크하세요. ⑥ '마침'을 클릭하면 사용자 이름과 비밀번호를 입력하는 창이 뜨니, 정확히 입력하고 확인을 누르세요."},{"title":"ping으로 서버 응답 확인","why":"서버 자체에 대한 네트워크 접근이 가능한지 확인합니다.","how":"① Windows 로고 키를 누르고 'cmd'라고 입력한 뒤 Enter를 누르세요. 검은 배경의 창(명령 프롬프트)이 열립니다. ② 커서가 깜빡이는 곳에 ping 이라고 입력하고 한 칸 띄운 뒤 NAS나 상대 PC의 IP 주소 또는 이름을 입력하고 Enter를 누르세요(예: ping 192.168.0.6). ③ '...의 응답: 바이트=...'라는 줄이 여러 번 뜨면 네트워크 연결 자체는 정상이니 다음 확인 항목으로 넘어가세요. ④ '요청 시간이 초과되었습니다' 또는 '대상 호스트에 연결할 수 없습니다'가 뜨면 네트워크 연결 자체가 안 되는 것이니, 랜선·Wi-Fi 연결·공유기 전원부터 확인하세요."},{"title":"NAS 쪽 게스트 접근 설정 확인(24H2 이후 핵심)","why":"NAS 공유 폴더가 계정 없이 접근 가능한 '게스트' 방식이면, Windows 11 24H2부터는 SMB 서명 요구 때문에 연결 자체가 거부됩니다.","how":"① 웹 브라우저에서 시놀로지 DSM에 관리자 계정으로 로그인하세요. ② 제어판을 연 뒤 '파일 서비스'를 클릭하세요. ③ 'SMB' 탭을 클릭하세요. ④ 왼쪽 메뉴나 '공유 폴더' 메뉴에서 문제가 되는 폴더를 찾아 '편집'(또는 권한 설정)으로 들어가세요. ⑤ '게스트'나 '누구나'로 설정된 접근 권한을 실제 계정 이름으로 바꾸고, 그 계정에 '읽기/쓰기' 권한을 체크하세요. ⑥ 저장한 뒤 Windows PC에서 다시 접속을 시도하면서, 이번엔 반드시 그 계정의 사용자 이름과 비밀번호를 입력하세요. 이것이 근본 해결책입니다."},{"title":"NAS 계정의 SMB 프로토콜 사용 권한 확인(웹 로그인은 되는데 SMB만 안 될 때 가장 흔한 원인)","why":"공유 폴더 권한과 계정 자체가 모두 정상이어도, 시놀로지 DSM은 계정별로 사용 가능한 프로토콜(SMB/AFP/NFS, FTP, WebDAV 등)을 개별적으로 허용·차단합니다. 이 계정의 SMB 권한만 꺼져 있으면 DSM 웹 로그인은 정상인데 네트워크 드라이브(SMB)만 계정·비밀번호 오류로 거부됩니다.","how":"① DSM에 로그인한 뒤 제어판을 열고 '사용자 및 그룹'을 클릭하세요. ② 목록에서 접속에 사용 중인 계정을 선택하고 '편집' 버튼을 클릭하세요. ③ 위쪽 탭 중 '응용 프로그램' 탭을 클릭하세요. ④ 목록에서 'SMB/AFP/NFS' 항목을 찾아 오른쪽 허용 체크박스가 켜져 있는지 확인하세요. ⑤ 꺼져 있다면 체크박스를 클릭해 켜고 '저장' 버튼을 누르세요."},{"title":"DSM의 최소·최대 SMB 프로토콜 버전 확인","why":"DSM에서 최소 프로토콜이 SMB1로 낮게 설정돼 있으면, Windows가 이미 SMB1을 사실상 사용하지 않는 상태와 맞물려 협상 자체가 꼬여 계정·비밀번호 오류로 나타나는 사례가 보고됩니다.","how":"① DSM에 로그인한 뒤 제어판을 열고 '파일 서비스'를 클릭하세요. ② 'SMB' 탭을 클릭하고 '고급 설정' 버튼을 클릭하세요. ③ '최소 SMB 프로토콜' 항목을 SMB2로, '최대 SMB 프로토콜' 항목을 SMB3로 선택하세요(구형 SMB1 전용 기기를 함께 쓰고 있다면 이 단계는 건너뛰세요). ④ '적용' 버튼을 눌러 저장하세요."},{"title":"이름 접속 시 ping으로 주소 확인(mDNS/IPv6)","why":"IP로는 되는데 이름으로만 실패하면, 위의 SMB 서명·계정 권한 문제와는 다른 원인입니다. mDNS(Bonjour)가 이름을 IPv6 링크-로컬 주소로 해석해 IP 접속과 다른 경로로 인증을 시도하고 있을 수 있습니다.","how":"① Windows 로고 키를 누르고 'cmd'라고 입력하세요. 검색 결과에 뜬 '명령 프롬프트'를 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② ping 이라고 입력하고 한 칸 띄운 뒤 접속에 실패하는 호스트 이름만 입력하고(예: ping ITSVC) Enter를 누르세요. ③ 응답 주소가 fe80:으로 시작하면 이 문제에 해당합니다(192.168로 시작하면 이 원인이 아닙니다). ④ 이 경우 Windows 로고 키를 누르고 '메모장'을 입력한 뒤 우클릭해 '관리자 권한으로 실행'하고, '파일' → '열기'에서 파일 형식을 '모든 파일'로 바꿔 C:\\Windows\\System32\\drivers\\etc\\hosts를 열어, 맨 아래 줄에 192.168.x.x 호스트이름 형식으로 한 줄 추가한 뒤(예: 192.168.0.6 ITSVC) Ctrl+S로 저장하세요. ⑤ cmd에서 ipconfig /flushdns, 이어서 net use * /delete /y를 입력해 캐시를 정리하고(기존 연결이 모두 끊기니 주의) \\\\호스트이름으로 다시 접속하세요."},{"title":"LAN Manager 인증 수준 확인(사무실 PC끼리 공유폴더 연결 시 흔함)","why":"NAS가 아니라 다른 PC의 공유폴더에 직접 접속하는 사무실 환경에서는, 두 PC의 'LAN Manager 인증 수준' 정책이 서로 다르면 실제로는 맞는 비밀번호도 협상 단계에서 거부될 수 있습니다. 한쪽 PC만 최근 업데이트·보안 정책이 적용됐을 때 자주 나타납니다.","how":"① Windows 로고 키를 누르고 'secpol.msc'라고 입력한 뒤 Enter를 누르세요(로컬 보안 정책 창이 열립니다). ② 왼쪽 목록에서 '로컬 정책' 폴더를 클릭해 펼치고, 그 안의 '보안 옵션'을 클릭하세요. ③ 오른쪽 목록을 아래로 스크롤해 '네트워크 보안: LAN Manager 인증 수준' 항목을 찾아 더블클릭하세요. ④ 현재 설정된 값을 메모해두고, 접속하려는 다른 PC에서도 같은 방법으로 이 값을 확인하세요. ⑤ 두 PC의 값이 다르다면 더 호환성이 높은 값(예: 'LM 및 NTLM 응답 보내기')으로 양쪽을 맞춰보세요. 사내 도메인 환경이라면 이 값이 그룹 정책으로 관리되고 있을 수 있으니, 임의로 바꾸기 전에 IT 담당자에게 확인하는 것이 안전합니다."},{"title":"여러 PC 중 일부만 안 될 때 IP 대역 비교(사무실·다수 PC 환경)","why":"규모 있는 사무실에서는 인터넷전화(VoIP) 등을 위해 데이터망과 전화망을 물리적으로 분리해둔 경우가 있는데, 두 네트워크의 허브가 랜선으로 실수로 연결돼 있으면 일부 PC가 DHCP로 전화망 쪽 IP 대역을 할당받아 NAS와 완전히 다른 네트워크에 놓이게 됩니다. 비밀번호나 SMB 설정과 무관하게 아예 통신 자체가 안 되는 것이라, 위의 자격 증명·SMB 관련 조치를 아무리 해도 소용없습니다.","how":"① 접속이 안 되는 PC에서 Windows 로고 키를 누르고 'cmd'라고 입력한 뒤 Enter를 누르세요. ② ipconfig 라고 입력하고 Enter를 누르세요. ③ 화면에 나온 'IPv4 주소'의 앞 세 자리 숫자(예: 192.168.0)를 확인하세요. ④ NAS에 정상 접속되는 다른 PC에서도 같은 방법으로 IPv4 주소를 확인해 앞 세 자리를 비교하세요. ⑤ 두 값이 다르면(예: 192.168.0 대 192.168.1) 네트워크 배선 문제입니다 — 사내 네트워크 담당자에게 '데이터망 허브와 전화망 허브가 랜선으로 서로 연결돼 있는지' 확인을 요청하세요. 직접 찾아야 한다면, 정상 PC 한 대를 고정 IP로 설정한 뒤 그 PC에서 NAS로 ping을 계속 보내면서 허브의 랜선을 하나씩 뽑아보고 ping이 끊기는 케이블을 찾으면 됩니다."}],"deeper":[{"heading":"오류 코드로 원인 구분","text":"0x80070035(네트워크 경로 없음)는 네트워크 검색 문제, 0x80070005(액세스 거부)는 자격 증명 문제, 0x80004005(지정되지 않은 오류)는 SMB 버전 불일치인 경우가 많습니다."},{"heading":"구형 NAS·서버 연결 시 SMB1","text":"SMB1만 지원하는 구형 장치라면 Windows 기능 켜기/끄기에서 'SMB 1.0/CIFS 파일 공유 지원'을 활성화해야 합니다. 단, SMB1은 보안 취약점이 있으므로 장기적으로 장치 업데이트 또는 교체를 권장합니다."},{"heading":"NAS 없이 PC끼리 공유폴더를 쓰는 사무실 환경","text":"특정 동료 PC 한 대의 공유폴더에만 접속이 안 되고 다른 동료의 공유폴더는 정상이라면, NAS 관련 원인은 해당하지 않습니다. 이 경우 ①그 PC에서 '파일 및 프린터 공유'가 꺼져 있는지, ②그 PC가 최근 Windows 업데이트로 SMB 서명·게스트 정책이 바뀌었는지, ③두 PC의 LAN Manager 인증 수준이 서로 다른지 순서로 좁혀가세요. 워크그룹 환경(도메인에 가입되지 않은 일반 사무실)에서는 공유하는 PC 쪽에 접속할 계정과 동일한 사용자 이름+비밀번호의 로컬 계정을 만들어 두는 것이 가장 안정적입니다.","relatedCheckIndex":9},{"heading":"PC 여러 대 중 일부만 안 될 때 — 네트워크 배선(데이터망·전화망 혼선)","text":"비밀번호나 SMB 설정을 아무리 손봐도 안 되고, 유독 특정 자리·특정 PC들에서만 증상이 난다면 원인이 아예 다를 수 있습니다. 사무실에서 인터넷전화(VoIP)를 쓰기 위해 데이터망과 전화망을 물리적으로 분리해 각각 별도의 공유기·허브로 구성한 경우, 두 허브가 랜선 한 가닥으로 실수로 연결돼 있으면 논리적으로 두 네트워크가 합쳐집니다. 이 상태에서는 어느 공유기가 DHCP로 IP를 먼저 내려주느냐에 따라 일부 PC가 전화망 대역의 IP를 받게 되고, 그 PC들은 NAS와 아예 다른 네트워크에 있는 것이 되어 접속 자체가 안 됩니다. 증상이 나는 PC가 그때그때 바뀌거나(재부팅마다 DHCP 임대가 달라짐), 특정 자리의 PC에서만 반복된다면 이 케이스를 의심하세요.","relatedCheckIndex":10},{"heading":"Windows 11 24H2의 SMB 서명·게스트 폴백 정책 변경","text":"24H2부터 모든 SMB 연결에 서명이 기본으로 요구되고, 계정 없는 게스트 접속은 서명을 쓸 수 없어 자동으로 차단됩니다. NAS 쪽에서 계정 인증으로 바꾸는 것이 정석이지만, 신뢰할 수 있는 가정 네트워크에서 당장 급하다면 관리자 권한 PowerShell에서 `Set-SmbClientConfiguration -EnableInsecureGuestLogons $true -Force`로 임시 허용할 수 있습니다. 이 명령은 보안을 낮추는 방법이라 회사망·공용망에서는 권장하지 않습니다. 자격 증명을 다시 입력할 때는 사용자 이름을 `NAS이름\\사용자명`, `NAS의IP주소\\사용자명`, 또는 `.\\사용자명` 형식으로 정확히 입력해야 인증이 통과되는 경우도 있습니다 — Windows가 자동으로 Microsoft 계정이나 PC 이름을 앞에 붙여 보내면서 NAS가 이를 알 수 없는 사용자로 인식해 거부하는 경우가 흔합니다."},{"heading":"그룹 정책·보안 소프트웨어로 NTLM 인증 자체를 막아둔 경우(드문 경우)","text":"'NTLM 인증이 사용하지 않도록 설정되어 인증에 실패했습니다' 같은 문구가 뜬다면, 위의 게스트 로그인·SMB 서명과는 다른 원인입니다. 회사 보안 정책이나 별도로 적용한 보안 강화 그룹 정책이 NTLM 자체를 차단하고 있을 수 있습니다. 다만 이 경우는 사용자마다 시도한 해결책(BlockNTLM 해제, LAN Manager 인증 수준 변경 등)이 통하지 않는 사례도 보고돼 있어, 확실한 해결책이 아직 정립되지 않은 드문 경우입니다. 가정용 PC라면 대부분 해당하지 않으니, 위 항목들을 먼저 확인하세요."},{"heading":"브라우저(웹 관리 페이지) 로그인은 되는데 네트워크 드라이브만 안 될 때","text":"NAS 웹 관리 화면 로그인과 SMB 네트워크 드라이브 인증은 완전히 별개의 경로입니다. 웹 로그인이 정상이라면 계정·비밀번호 자체는 맞다는 뜻이므로, 원인은 계정이 아니라 Windows에 저장된 자격 증명 캐시, SMB 프로토콜·서명 협상, 또는 SMB 전용 로그인 차단(계정 보호가 서비스별로 적용되는 경우) 쪽으로 좁혀서 확인해야 합니다."},{"heading":"NAS를 이름(예: \\\\ITSVC)으로 열면 비밀번호 오류, IP로는 정상일 때(mDNS/IPv6)","text":"\\\\192.168.x.x로는 정상 접속되는데 \\\\NAS이름(예: \\\\ITSVC)으로 접속하면 사용자 이름 또는 암호가 잘못되었다는 오류가 나고, 자격 증명을 삭제하고 다시 등록해도 같은 오류가 반복되는 경우입니다. 위에서 다룬 SMB 서명·계정 권한 문제와 달리, 원인은 이름 해석 방식 자체에 있습니다. 이름으로 접속을 시도하면 Windows가 Bonjour의 mDNS(.local)로 이름을 풀이하는데, 이때 IPv4가 아니라 fe80:으로 시작하는 IPv6 링크-로컬 주소로 응답하는 경우가 있습니다. 그러면 IP로 접속할 때와 완전히 다른 네트워크 경로(IPv6)를 타면서 SMB 인증이 다르게 동작해 비밀번호 오류로 나타납니다.","relatedCheckIndex":8}],"decision":[{"heading":"자격 증명 삭제·재입력 후 해결될 때","text":"비밀번호 변경 후 저장 자격 증명이 갱신되지 않은 것이 원인입니다. 이후 비밀번호 변경 시 자격 증명 관리자도 함께 업데이트하세요."},{"heading":"재부팅 후 드라이브가 계속 사라질 때","text":"로그인 시 네트워크 준비 전에 연결을 시도해 실패하는 경우입니다. 작업 스케줄러에서 로그인 후 일정 시간 뒤 드라이브를 재연결하는 스크립트 등록을 고려하세요."},{"heading":"Windows 업데이트 직후부터 갑자기 계정·비밀번호가 틀렸다고 나올 때","text":"비밀번호를 바꾼 적이 없는데도 특정 업데이트 이후부터 인증이 거부된다면 24H2의 SMB 서명·게스트 정책 변경이 원인일 가능성이 큽니다. NAS의 공유 폴더 인증 방식부터 확인하세요."},{"heading":"NAS 없이 동료 PC 한 대의 공유폴더에서만 이런 증상이 날 때","text":"그 PC에서 '파일 및 프린터 공유'가 켜져 있는지, 최근 그 PC에만 업데이트가 적용됐는지 먼저 확인하세요. 그래도 안 되면 두 PC의 LAN Manager 인증 수준(secpol.msc)이 서로 다른지 비교해보세요 — 사무실에서 PC끼리 직접 공유할 때 가장 자주 확인되는 원인입니다.","relatedCheckIndex":9},{"heading":"PC 여러 대 중 일부만, 자리나 PC를 바꿔가며 증상이 날 때","text":"비밀번호·SMB 설정을 다 확인했는데도 여전히 일부 PC만 안 된다면, ipconfig로 IP 대역부터 비교하세요. 정상 PC와 대역 자체가 다르면 네트워크 배선(데이터망·전화망 혼선) 문제이지 Windows나 NAS 설정 문제가 아닙니다. 이 경우는 사내 네트워크 담당자나 배선을 아는 사람에게 확인을 요청하는 것이 가장 빠릅니다.","relatedCheckIndex":10},{"heading":"NAS 웹 관리 페이지 로그인은 되는데 네트워크 드라이브만 계속 거부될 때","text":"계정·비밀번호는 정상이라는 뜻이므로 비밀번호를 계속 바꿔봐야 소용없습니다. 시놀로지 DSM이라면 제어판 → 사용자 및 그룹 → 해당 계정 → 응용 프로그램 탭에서 SMB 권한이 꺼져 있는지부터 확인하세요 — 이 조합(웹 로그인 정상, SMB만 거부)에서 가장 흔하고 확실한 원인입니다. 그래도 안 되면 자격 증명 관리자에서 저장된 항목을 삭제하고 다시 시도하고, NAS의 SMB 프로토콜·서명 설정이나 계정 보호(Auto Block)가 SMB 로그인만 차단하고 있지 않은지 확인하세요."},{"heading":"ping 결과가 fe80:으로 시작하는 IPv6일 때","text":"hosts 파일에 IPv4 주소를 고정하면 mDNS보다 우선 적용되어 확실하게 IPv4 경로로 붙습니다. ① Windows 로고 키를 누르고 '메모장'이라고 입력하세요. 검색 결과에 뜬 메모장을 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② 메모장 위쪽 메뉴에서 '파일' → '열기'를 클릭하세요. ③ 열기 창 아래쪽의 파일 형식을 '모든 파일'로 바꾸세요(안 바꾸면 hosts 파일이 목록에 안 보입니다). ④ 주소창에 C:\\Windows\\System32\\drivers\\etc\\hosts 를 입력하고 Enter를 누르세요. ⑤ 파일 맨 아래 줄로 커서를 옮기고 192.168.x.x 호스트이름 형식으로 한 줄을 추가하세요(예: 192.168.0.6 ITSVC — 앞부분은 NAS의 실제 IP 주소, 뒷부분은 접속할 때 쓰던 이름으로 바꿔서 입력). ⑥ Ctrl+S를 눌러 저장하세요. ⑦ Windows 로고 키를 누르고 'cmd'라고 입력해 명령 프롬프트를 여세요. ⑧ ipconfig /flushdns 라고 입력하고 Enter를 누르세요. ⑨ 이어서 net use * /delete /y 라고 입력하고 Enter를 누르세요(현재 연결된 네트워크 드라이브가 모두 끊기니, 저장 안 된 작업이 있다면 미리 마무리하세요). ⑩ 파일 탐색기 주소창에 \\\\호스트이름을 입력해 다시 접속해보세요. 참고로 NAS의 IP 주소가 고정 IP가 아니라면, 시놀로지 DSM의 제어판 → 네트워크 메뉴에서 먼저 고정 IP로 설정해 두세요 — 그래야 나중에 IP가 바뀌어 이 hosts 설정이 어긋나는 일이 없습니다.","relatedCheckIndex":8}],"examples":["재부팅 후 Z: 드라이브가 사라져 있다","NAS에 접근하면 0x80070035 오류가 뜬다","Windows 업데이트 이후부터 시놀로지 NAS에 접속하면 계정 또는 비밀번호가 잘못됐다고 나온다","\\\\NAS이름(예: \\\\ITSVC)으로 접속하면 비밀번호 오류, IP로는 정상 접속됨","회사에서 동료 PC의 공유폴더에 접속하면 '네트워크 자격 증명' 창이 계속 뜨거나 비밀번호가 틀렸다고 나온다","40대 규모 사무실에서 일부 PC만 NAS 접속이 안 되고, 나머지는 멀쩡하다"],"mistakes":["자격 증명 만료를 확인하지 않고 드라이브를 다시 매핑하는 것","SMB 버전 불일치를 모르고 보안 취약한 SMB1을 활성화해두는 것","ping 결과의 IPv6 주소는 확인하지 않고 자격 증명·SMB 권한만 반복해서 확인하는 것","NAS가 없는 사무실 환경인데도 NAS 관련 설정(DSM 등)부터 찾아보는 것 — PC끼리 직접 공유할 때는 원인이 다릅니다","일부 PC만 안 될 때 IP 대역을 확인하지 않고 비밀번호·SMB 설정만 반복해서 고치는 것"],"faq":[{"q":"재부팅 후 네트워크 드라이브가 사라지는 이유는?","a":"'로그온 시 다시 연결' 옵션이 체크되지 않았거나, 로그인 전에 네트워크가 준비되지 않아 연결에 실패하는 경우입니다. 드라이브를 다시 매핑할 때 해당 옵션을 체크하세요."},{"q":"0x80070035 오류가 뜨면?","a":"네트워크 검색이 꺼져 있거나 네트워크 프로파일이 공용으로 설정된 경우입니다. 고급 공유 설정에서 개인 네트워크의 네트워크 검색과 파일 공유를 켜세요."},{"q":"Windows 업데이트 이후부터 시놀로지 NAS 접속 시 계정·비밀번호가 틀렸다고 나옵니다.","a":"Windows 11 24H2부터 SMB 서명이 기본으로 강제되고 게스트 접속이 차단되면서, 계정 없이 쓰던 NAS 공유가 막히는 경우입니다. 버그가 아니라 보안 강화 조치이며, NAS 쪽 공유 폴더를 실제 계정+비밀번호 인증으로 바꾸는 것이 근본 해결책입니다."},{"q":"NAS 공유 폴더가 이미 실제 계정 인증으로 설정돼 있는데도 계정·비밀번호가 틀렸다고 나옵니다.","a":"Windows 자격 증명 관리자에 저장된 예전 비밀번호가 캐시되어 계속 재사용되고 있을 가능성이 가장 큽니다. 자격 증명 관리자에서 해당 NAS 항목을 완전히 삭제한 뒤 다시 시도하세요. 그래도 안 되면 반복 실패로 NAS의 계정 보호(Auto Block) 기능이 계정이나 IP를 차단했을 수 있으니 NAS 보안 설정에서 차단 목록을 확인하세요."},{"q":"NAS 웹 관리 페이지 로그인은 잘 되는데 네트워크 드라이브 연결만 안 됩니다.","a":"웹 로그인과 SMB 네트워크 드라이브 인증은 별개의 경로라서, 웹 로그인이 된다면 계정·비밀번호 자체는 문제가 아닙니다. 시놀로지 DSM이라면 제어판 → 사용자 및 그룹 → 해당 계정 → 응용 프로그램 탭에서 SMB 권한이 꺼져 있는 경우가 가장 흔한 원인입니다. 그래도 안 되면 Windows 자격 증명 캐시나 SMB 프로토콜·서명 설정, 계정 보호 설정을 확인하세요."},{"q":"\\\\NAS이름(예: \\\\ITSVC)으로는 비밀번호 오류가 나는데 IP로는 되는 이유는?","a":"이름으로 접속할 때 mDNS가 IPv6 링크-로컬 주소(fe80:)로 응답해 IP 접속과 다른 인증 경로를 타기 때문인 경우가 많습니다. 관리자 권한 명령 프롬프트에서 ping 호스트이름을 실행해 IPv6 응답이 나오면, hosts 파일에 NAS의 IPv4 주소를 직접 등록하세요."},{"q":"NAS 없이 사무실 PC끼리 공유폴더를 쓰는데 특정 PC 한 대만 접속이 안 됩니다.","a":"그 PC에서 '파일 및 프린터 공유'가 켜져 있는지부터 확인하세요. 그래도 안 되면 그 PC와 접속하는 PC의 LAN Manager 인증 수준(secpol.msc → 로컬 정책 → 보안 옵션 → 네트워크 보안: LAN Manager 인증 수준)이 서로 다른지 비교해보세요. 최근 한쪽 PC에만 Windows 업데이트나 보안 정책이 적용된 경우 이 값이 달라져 정상적인 비밀번호도 거부될 수 있습니다."},{"q":"PC가 여러 대인 사무실에서 일부 PC만 NAS 접속이 안 됩니다. 비밀번호도 맞는데 계속 안 됩니다.","a":"비밀번호나 SMB 설정 문제가 아니라 네트워크 배선 문제일 수 있습니다. 안 되는 PC에서 ipconfig로 IP 주소 대역을 확인해, 정상 접속되는 PC와 대역 자체가 다른지(예: 192.168.0.x vs 192.168.1.x) 비교하세요. 인터넷전화(VoIP) 등을 위해 데이터망과 전화망을 분리해 쓰는 사무실에서, 두 망의 허브가 랜선으로 잘못 연결돼 일부 PC가 엉뚱한 대역의 IP를 받는 경우가 실제로 보고됩니다."}]},"phone-link-not-working":{"badge":"Windows","subtitle":"PC와 스마트폰을 연결하는 '휴대폰과 연결'(Phone Link) 앱이 페어링되지 않거나, 연결은 됐는데 알림·사진·메시지가 동기화되지 않을 때","intro":["휴대폰과 연결 오류는 대부분 계정 불일치, 배터리 절약 모드, Wi-Fi·공유기 설정, 앱 버전 불일치 중 하나가 원인입니다. Microsoft 공식 지원 문서 기준으로 확인된 원인과 해결 순서를 정리했습니다.","PC와 스마트폰 양쪽에서 반드시 같은 Microsoft 계정으로 로그인돼 있어야 하며, 배터리 절약 기능이 백그라운드 연결을 차단하는 경우가 가장 흔한 원인 중 하나입니다.","같은 Wi-Fi에 연결돼 있어도 안 될 때는 앱 자체의 문제가 아니라 공유기의 '무선(AP) 격리' 기능 때문인 경우가 있어, 흔히 간과됩니다."],"warnings":["QR 코드를 다시 스캔하라는 화면이 반복해서 뜬다.","연결은 됐다고 나오는데 알림·문자·사진이 PC에 동기화되지 않는다.","'업데이트가 필요합니다' 페이지에서 더 이상 진행되지 않는다."],"checks":[{"title":"Microsoft 계정 일치 확인","why":"PC와 스마트폰이 서로 다른 Microsoft 계정으로 로그인돼 있으면 페어링 자체가 되지 않습니다.","how":"① 스마트폰에서 '설정' 앱을 열고 '고급 기능'(또는 제조사에 따라 '연결된 기기')으로 들어가 'Windows와 연결'(또는 'Windows에 연결')을 선택하세요. ② 화면에 표시된 로그인 계정의 이메일 주소를 확인하세요. ③ PC에서 '휴대폰과 연결' 앱을 열고 오른쪽 위 계정 아이콘을 클릭해 로그인된 이메일을 확인하세요. ④ 두 계정이 다르다면, 스마트폰 쪽 설정에서 로그아웃한 뒤 PC와 같은 Microsoft 계정으로 다시 로그인하세요."},{"title":"배터리 절약 모드·배터리 최적화 해제","why":"배터리 절약 기능이 백그라운드 연결을 차단해 동기화가 끊기는 가장 흔한 원인입니다.","how":"① 스마트폰 '설정' 앱에서 '배터리'로 들어가세요. ② '배터리 사용량 관리' 또는 '앱별 배터리 사용'을 선택하세요. ③ 목록에서 '휴대폰과 연결'(또는 'Windows와 연결', 제조사에 따라 이름이 다릅니다) 앱을 찾으세요. ④ 해당 앱을 선택해 '최적화하지 않음' 또는 '제한 없음'으로 설정하세요. ⑤ 스마트폰 상단 알림창을 내려 '배터리 절약 모드' 아이콘이 켜져 있지 않은지 확인하고, 켜져 있다면 끄세요. ⑥ PC에서도 설정 → 시스템 → 전원에서 절전 모드에 들어가지 않도록 확인하세요."},{"title":"같은 Wi-Fi인데도 연결 안 될 때 공유기 무선 격리 확인","why":"일부 공유기의 '무선(AP) 격리' 기능이 켜져 있으면 같은 Wi-Fi에 연결된 기기끼리도 서로 통신이 차단됩니다.","how":"① 웹 브라우저 주소창에 공유기 관리 페이지 주소(보통 192.168.0.1 또는 192.168.1.1)를 입력해 로그인하세요. ② '무선 설정' 또는 'Wi-Fi 설정' 메뉴로 들어가세요. ③ '고급 설정' 안에서 'AP 격리', '무선 격리', 'Client Isolation' 같은 이름의 항목을 찾으세요(공유기 제조사마다 이름과 위치가 다릅니다). ④ 이 옵션이 켜져 있다면 꺼서 저장하세요(이 옵션은 같은 Wi-Fi에 연결된 기기끼리 서로 통신하지 못하게 막는 보안 기능이라, 켜져 있으면 PC와 스마트폰이 같은 Wi-Fi여도 서로 연결되지 않습니다)."},{"title":"앱 최소 버전 확인","why":"PC 또는 안드로이드 한쪽이 구버전이면 '업데이트가 필요합니다' 페이지에서 멈춥니다.","how":"① PC에서 Microsoft Store 앱을 열고 검색창에 '휴대폰과 연결'(Phone Link)을 입력하세요. ② 검색 결과에서 앱을 클릭한 뒤 '업데이트' 버튼이 있다면 클릭해 최신 버전으로 업데이트하세요. ③ 스마트폰에서 Play 스토어(또는 갤럭시 스토어)를 열고 'Windows와 연결' 앱을 검색하세요. ④ 업데이트 버튼이 있다면 눌러 최신 버전으로 업데이트하세요. ⑤ 양쪽 모두 업데이트한 뒤 앱을 재실행해 연결을 다시 시도하세요."},{"title":"안드로이드 권한 확인(안드로이드 10 이상)","why":"알림·사진·메시지 권한이 하나라도 거부돼 있으면 해당 기능만 조용히 안 뜹니다.","how":"① 스마트폰 '설정' 앱에서 '앱' 또는 '애플리케이션'으로 들어가세요. ② '모든 앱 표시'를 누른 뒤 'Windows와 연결' 앱을 찾아 선택하세요. ③ '권한'을 클릭하고 저장공간, 연락처, SMS(메시지), 전화 권한이 모두 '허용'으로 되어 있는지 확인하고, 거부되어 있다면 허용으로 바꾸세요. ④ 알림 기능이 안 된다면 설정 앱에서 '알림' → '앱 알림 액세스'(또는 유사한 메뉴)로 들어가 'Windows와 연결'의 알림 액세스를 껐다가 다시 켜보세요."},{"title":"삼성 DeX 동시 실행 여부 확인","why":"삼성 DeX와 휴대폰과 연결을 동시에 열면 두 앱 모두 오작동할 수 있습니다.","how":"① 삼성 DeX를 실행 중이라면 PC의 '휴대폰과 연결' 앱을 완전히 종료하세요(작업 관리자에서 확인 가능). ② DeX 사용을 마친 뒤에 '휴대폰과 연결' 앱을 다시 실행하세요. ③ 두 기능을 동시에 쓰지 말고, 필요할 때마다 하나씩만 켜서 사용하세요."}],"deeper":[{"heading":"'업데이트가 필요합니다' 페이지가 계속 뜰 때","text":"버전을 최신으로 올렸는데도 계속 뜬다면, PC와 안드로이드 양쪽 앱 설정 화면에서 실제 버전 번호를 직접 확인해 최신인지 재확인하세요. 그래도 해결되지 않으면 Windows 피드백 허브에 진단 데이터와 함께 보고하는 것이 공식 권장 절차입니다."},{"heading":"한국에서만 있는 '두 전화 모드' 제약","text":"이동통신사에서 두 회선을 하나로 쓰는 '두 전화 모드'를 사용 중이라면, 휴대폰과 연결은 기본값이 아닌 프로필로는 연결을 지원하지 않습니다. 연결하려는 번호가 기본 프로필로 설정돼 있는지 확인하세요."},{"heading":"이전에 연결했던 장치를 못 찾을 때","text":"앱에서 로그아웃 후 재로그인하거나, 기존 연결을 지우고 새 장치로 다시 추가하는 방식으로 초기화하면 해결되는 경우가 많습니다."}],"decision":[{"heading":"계정을 맞췄는데도 안 될 때","text":"배터리 절약 모드와 Wi-Fi 상태부터 확인하세요. 대부분 이 두 가지가 원인입니다."},{"heading":"같은 Wi-Fi인데 연결이 안 될 때","text":"공유기의 무선(AP) 격리 기능부터 의심하세요 — 스마트폰이나 PC가 아니라 네트워크 장비 설정 문제입니다."},{"heading":"권한을 다 허용했는데도 알림만 안 뜰 때","text":"'알림 액세스' 권한은 일반 앱 권한 목록과 별도 메뉴에 있습니다. 설정에서 '알림 액세스'를 검색해 Windows와 연결 항목을 껐다 다시 켜보세요."}],"examples":["같은 Wi-Fi에 연결했는데도 '연결할 수 없음' 오류가 반복된다","연결은 됐다고 나오는데 알림이나 사진이 PC에서 안 보인다","업데이트를 다 했는데도 '업데이트가 필요합니다' 화면에서 멈춰 있다"],"mistakes":["PC와 폰의 Microsoft 계정이 같은지 확인하지 않고 재설치만 반복하는 것","공유기 설정은 확인하지 않고 스마트폰 쪽 문제로만 생각하는 것"],"faq":[{"q":"PC와 스마트폰 Microsoft 계정이 다르면 어떻게 되나요?","a":"페어링 자체가 되지 않습니다. 안드로이드에서 설정 → 고급 기능 → Windows와 연결로 들어가 로그인된 계정 이메일을 PC 쪽과 동일하게 맞추세요."},{"q":"같은 와이파이에 연결돼 있는데도 안 되는 이유는?","a":"공유기의 무선(AP) 격리 기능이 켜져 있으면 같은 네트워크에 있어도 기기끼리 통신이 차단됩니다. 공유기 관리 페이지의 무선 고급 설정에서 AP 격리를 꺼보세요."},{"q":"삼성 DeX를 쓰는데 휴대폰과 연결이 자꾸 끊깁니다.","a":"DeX와 휴대폰과 연결을 동시에 켜두면 두 앱 모두 문제가 생길 수 있습니다. 한 번에 하나만 실행하세요."}]},"kakaotalk-pc-not-launching":{"badge":"프로그램","subtitle":"카카오톡 PC 버전이 실행되지 않거나, 로그인 중 오류 코드와 함께 접속이 계속 실패할 때","intro":["카카오톡 PC 실행·로그인 오류는 방화벽 차단, 백그라운드에 남은 이전 프로세스, 손상된 설치 파일, 카카오 서버 자체 장애 중 하나인 경우가 대부분입니다. 가장 먼저 모바일 카카오톡이나 다른 PC에서는 정상 접속되는지 확인해, 내 PC만의 문제인지 카카오 서버 전체 문제인지부터 구분하세요.","오류 창에 10060·10061·10054·10013 같은 숫자 코드가 뜬다면, 이는 카카오톡 자체 오류 코드가 아니라 Microsoft가 정의한 Windows 소켓(Winsock) 표준 네트워크 오류 코드입니다. 10060은 연결 시간 초과, 10061은 연결 거부, 10013은 권한 거부(주로 방화벽 차단)를 뜻하며, 카카오톡뿐 아니라 인터넷에 접속하는 모든 프로그램에서 같은 원인(네트워크·방화벽 문제)으로 나타날 수 있습니다.","반면 50113·50150·70103·997처럼 Winsock 범위(10000번대)를 벗어난 코드는 카카오톡 자체 서비스 오류로 추정되지만 코드별 공식 설명 문서는 없습니다. 대부분 서버 임시 점검이나 계정·네트워크 문제로, 재로그인·재설치로 해결되는 경우가 많습니다."],"warnings":["실행 아이콘을 눌러도 아무 반응이 없다.","'알 수 없는 오류로 카카오톡을 종료합니다' 창이 뜬다.","로그인 시도 중 숫자로 된 오류 코드와 함께 접속이 끊긴다."],"checks":[{"title":"백그라운드 프로세스 완전 종료","why":"이전 실행이 비정상 종료되며 KakaoTalk.exe 프로세스가 남아있으면 새로 실행해도 충돌합니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ② '프로세스' 탭에서 'KakaoTalk' 또는 'KakaoTalk.exe'로 시작하는 항목이 있는지 확인하세요(여러 개 있을 수 있습니다). ③ 각 항목을 선택해 '작업 끝내기' 버튼을 클릭해 모두 종료하세요. ④ 바탕화면이나 시작 메뉴에서 카카오톡 아이콘을 다시 클릭해 실행해보세요."},{"title":"내 PC만의 문제인지 서버 문제인지 구분","why":"카카오 서버 자체 장애라면 PC에서 무엇을 해도 해결되지 않습니다.","how":"① 스마트폰에서 모바일 카카오톡 앱을 실행해 정상적으로 로그인되는지 확인하세요. ② 다른 PC가 있다면 같은 계정으로 PC 카카오톡을 실행해보세요. ③ 스마트폰이나 다른 PC에서도 접속이 안 된다면 카카오 서버 자체의 일시적 장애일 가능성이 크므로, 몇 분~몇 시간 뒤 다시 시도하세요. ④ 스마트폰에서는 되는데 이 PC에서만 안 된다면 아래 항목들을 이어서 진행하세요."},{"title":"방화벽·백신 차단 여부 확인","why":"회사·공용 PC나 보안 프로그램이 엄격한 환경에서는 카카오톡의 네트워크 통신 자체가 차단될 수 있습니다.","how":"① Windows 로고 키를 누르고 'Windows 보안'을 입력해 실행하세요. ② '방화벽 및 네트워크 보호'를 클릭한 뒤 '앱이 방화벽을 통과하도록 허용'을 클릭하세요. ③ 목록에서 'KakaoTalk'을 찾아 '개인' 및 '공용' 항목에 체크가 되어 있는지 확인하세요(체크박스를 바꾸려면 위쪽 '설정 변경' 버튼을 먼저 클릭해야 합니다). ④ 목록에 카카오톡이 아예 없다면 '다른 앱 허용'을 클릭해 카카오톡 실행 파일을 직접 추가하세요. ⑤ 별도 백신 프로그램(V3, 알약 등)을 쓰고 있다면 그 프로그램을 열어 네트워크 차단 로그나 예외 설정에 카카오톡이 있는지 확인하세요."},{"title":"완전 삭제 후 재설치","why":"설치 파일이나 캐시 손상은 단순 재실행으로 해결되지 않는 경우가 많습니다.","how":"① Windows 로고 키를 누르고 '앱 및 기능'을 입력해 실행하세요. ② 'KakaoTalk'을 찾아 클릭한 뒤 '제거'를 선택하세요. ③ 웹 브라우저에서 카카오톡 공식 홈페이지(PC용 다운로드 페이지)에 접속하세요. ④ 최신 버전의 설치 파일을 내려받아 실행하고 안내에 따라 새로 설치하세요. ⑤ 설치 후 기존 계정으로 다시 로그인해보세요."},{"title":"호환 모드로 실행(구형 PC·특수 환경)","why":"일부 환경에서는 호환 모드로 실행하면 정상화되는 사례가 보고됩니다.","how":"① 바탕화면이나 시작 메뉴의 카카오톡 아이콘을 마우스 오른쪽 버튼으로 클릭해 '속성'을 선택하세요. ② '호환성' 탭을 클릭하세요. ③ '호환 모드로 이 프로그램 실행'에 체크한 뒤, 드롭다운에서 'Windows 8' 또는 'Windows 10'을 선택하세요. ④ '적용' → '확인'을 누르고 카카오톡을 다시 실행해보세요. ⑤ 효과가 없다면 체크를 해제해 원래대로 되돌리세요."}],"deeper":[{"heading":"오류 코드 10060·10061·10054·10013의 의미(Microsoft 공식 정의)","text":"이 코드들은 카카오톡이 아니라 Windows의 네트워크 소켓(Winsock) 계층에서 정의한 표준 오류입니다. 10060(WSAETIMEDOUT)은 연결 시도가 응답 시간 안에 완료되지 않음, 10061(WSAECONNREFUSED)은 상대 서버가 연결을 거부함, 10054(WSAECONNRESET)는 연결이 상대방에 의해 강제 종료됨, 10013(WSAEACCES)은 권한 문제(주로 방화벽 차단)를 의미합니다. 카카오톡뿐 아니라 인터넷에 연결하는 모든 Windows 프로그램에서 같은 번호로 나타날 수 있는 범용 코드입니다."},{"heading":"50000·70000번대·997 코드","text":"이런 코드는 Winsock 표준 범위를 벗어나 있어 카카오톡 자체 서비스 오류로 추정되지만, 카카오 고객센터에 코드별 공식 설명 문서는 없습니다. 대부분 서버 임시 점검, 계정 인증 문제, 네트워크 불안정 중 하나로 보고되며 재로그인·재설치로 해결되는 사례가 많습니다."},{"heading":"회사·기관 PC에서만 유독 안 될 때","text":"사내망은 보안 정책으로 특정 포트나 도메인을 차단하는 경우가 흔합니다. 개인 PC나 휴대폰 핫스팟으로 테스트해 동일 계정이 정상 접속되면, 네트워크 관리자에게 카카오톡 관련 통신 허용을 문의해야 합니다."}],"decision":[{"heading":"모바일·다른 PC는 정상인데 이 PC만 안 될 때","text":"PC 로컬 문제입니다. 프로세스 완전 종료 → 방화벽 확인 → 재설치 순서로 진행하세요."},{"heading":"모바일에서도 동일하게 안 될 때","text":"카카오 서버 자체 장애일 가능성이 큽니다. PC를 손대지 말고 잠시 기다린 뒤 재시도하세요."},{"heading":"회사·기관 PC에서만 안 될 때","text":"네트워크 정책상 차단일 가능성이 큽니다. 개인 회선에서 테스트해 확인한 뒤 네트워크 관리자에게 문의하세요."}],"examples":["카카오톡 아이콘을 눌러도 아무 반응이 없다","'알 수 없는 오류로 카카오톡을 종료합니다' 메시지가 뜬다","로그인 시도 중 10060·10061 같은 오류 코드와 함께 접속이 끊긴다"],"mistakes":["백그라운드에 남은 이전 프로세스를 확인하지 않고 재설치부터 반복하는 것","서버 장애인지 확인하지 않고 방화벽 설정만 계속 바꾸는 것"],"faq":[{"q":"오류 코드 10060·10061은 카카오톡 자체 오류인가요?","a":"아닙니다. Microsoft가 정의한 Windows 네트워크 소켓(Winsock) 표준 오류 코드로, 카카오톡뿐 아니라 인터넷에 연결하는 모든 프로그램에서 같은 번호로 나타날 수 있습니다. 10060은 연결 시간 초과, 10061은 연결 거부를 뜻하며 대부분 방화벽이나 네트워크 문제입니다."},{"q":"재설치해도 계속 안 되면요?","a":"모바일 카카오톡이나 다른 PC에서도 같은 계정으로 접속이 안 되는지 먼저 확인하세요. 거기서도 안 된다면 내 PC 문제가 아니라 카카오 서버 자체 장애일 가능성이 큽니다."},{"q":"회사 PC에서만 유독 안 됩니다.","a":"사내 네트워크 정책이 카카오톡 통신을 차단하고 있을 가능성이 큽니다. 개인 회선(휴대폰 핫스팟 등)에서 정상 접속되는지 확인한 뒤, 필요하면 네트워크 관리자에게 문의하세요."}]},"certificate-not-recognized":{"badge":"보안","subtitle":"은행·정부 사이트 등에서 공동인증서가 검색되지 않거나, 등록·로그인 중 오류가 날 때","intro":["공동인증서(옛 공인인증서) 오류는 인증서 파일 위치 문제, 사이트별 보안 프로그램 미설치·충돌, 인증서 자체의 유효기간·비밀번호 문제, 타 기관 인증서의 사전 등록 누락 중 하나인 경우가 대부분입니다. '인증서가 없습니다'인지, '등록에 실패했습니다'인지, 로그인 버튼을 눌렀을 때만 안 되는지에 따라 원인이 달라집니다.","2020년 공인인증서 제도 폐지 이후 각 기관이 발급하는 인증서를 '공동인증서'라 부르지만, 저장 방식(NPKI 폴더)과 발생하는 오류 유형은 예전 공인인증서 시절과 거의 동일합니다.","인증기관에 따르면 인증서 인식 실패의 상당수는 사이트별 전용 보안 프로그램이 설치되지 않았거나 다른 보안 프로그램과 충돌하는 경우입니다 — 사이트를 새로 이용할 때마다 그 사이트가 요구하는 보안 프로그램을 따로 설치해야 하는 경우가 많습니다."],"warnings":["인증서를 선택하는 창에 아무 인증서도 뜨지 않는다.","'등록에 실패했습니다' 또는 '인증서 등록 오류'가 뜬다.","로그인 시도 중 알 수 없는 오류로 접속이 끊긴다."],"checks":[{"title":"인증서 저장 위치 확인","why":"인증서 파일이 기본 경로에 없으면 사이트가 아예 목록에 표시하지 못합니다.","how":"① Windows 로고 키를 누르고 '이 PC'를 입력해 파일 탐색기를 여세요. ② 주소창에 %USERPROFILE%\\Documents 를 입력하고 Enter를 눌러 '문서' 폴더로 이동하세요. ③ 그 안에 'NPKI'라는 이름의 폴더가 있는지 확인하세요. ④ 있다면 폴더를 열어 안에 알아보기 어려운 이름의 파일 몇 개(인증서 파일)가 들어있는지 확인하세요. ⑤ USB나 외장 디스크에 인증서를 저장해 쓰고 있다면, 해당 USB를 꽂은 뒤 그 드라이브 안에서도 'NPKI' 폴더를 같은 방식으로 확인하세요."},{"title":"사이트 전용 보안 프로그램 재설치","why":"은행·정부 사이트마다 별도의 공동인증 보안 모듈을 요구하며, 이게 설치되지 않았거나 오래되면 인증서를 인식하지 못합니다.","how":"① 인증서를 사용하려는 사이트(은행, 정부24 등)에 접속하세요. ② 로그인 화면이나 하단에서 '보안 프로그램 설치', '전자 서명 프로그램', '보안 진단' 등의 이름으로 된 링크를 찾으세요. ③ 클릭해 안내에 따라 필요한 보안 모듈을 새로 설치하세요(설치 도중 여러 프로그램의 설치 확인 창이 순서대로 뜰 수 있으니 하나씩 진행하세요). ④ 설치가 모두 끝나면 PC를 재부팅한 뒤 사이트에 다시 접속해 인증서 로그인을 시도하세요."},{"title":"타 기관 인증서 사전 등록(연동)","why":"다른 은행이나 기관에서 갱신·재발급받은 인증서는 새로 이용하려는 사이트에 자동으로 연결되지 않습니다.","how":"① 다른 기관(다른 은행 등)에서 발급받은 인증서를 새로운 사이트에서 처음 쓰는 경우입니다. ② 이용하려는 사이트에 접속해 '인증센터', '공동인증서 관리' 등의 메뉴를 찾으세요. ③ '타 기관 인증서 등록' 또는 '인증서 가져오기(연동)' 항목을 클릭하세요. ④ 화면 안내에 따라 기존 인증서를 선택하고 비밀번호를 입력해 등록을 완료하세요. ⑤ 등록이 끝난 뒤 다시 로그인을 시도해보세요."},{"title":"브라우저 호환성 확인","why":"일부 구형 공공 사이트는 Edge의 IE 모드처럼 특정 호환 모드에서만 정상 동작합니다.","how":"① 현재 쓰는 브라우저(크롬 등)에서 안 된다면, 다른 브라우저(Edge, 웨일 등)를 설치해 같은 사이트에 접속해보세요. ② 다른 브라우저에서는 정상적으로 인증서가 인식되는지 확인하세요. ③ 사이트 하단이나 고객센터 안내에서 '권장 브라우저'가 무엇인지 확인하세요. ④ Edge를 쓰는 경우, 오래된 정부·공공 사이트라면 주소창 오른쪽의 '…' 메뉴에서 'Internet Explorer 모드로 다시 로드'를 선택해보세요."},{"title":"USB 매체 확인","why":"USB에 인증서를 저장해 쓰는 경우, USB 자체의 손상이나 인식 불량이 원인일 수 있습니다.","how":"① USB를 뽑았다가 PC의 다른 USB 포트에 다시 꽂아보세요. ② 파일 탐색기에서 USB 드라이브가 정상적으로 인식되는지, 안의 파일들이 보이는지 확인하세요. ③ 같은 USB를 다른 PC에 꽂아 그 PC에서도 인증서 파일이 보이고 로그인에 사용할 수 있는지 확인하세요. ④ 다른 PC에서도 인식이 안 된다면 USB 자체의 손상 가능성이 크므로, 인증서를 재발급받거나 새 USB로 옮기는 것을 고려하세요."}],"deeper":[{"heading":"인증서가 아예 안 보일 때 vs 등록은 됐는데 로그인만 안 될 때","text":"인증서 목록 자체가 비어 있다면 저장 위치나 NPKI 폴더 문제일 가능성이 큽니다. 반대로 인증서는 보이는데 로그인 단계에서만 오류가 난다면 비밀번호, 유효기간, 또는 그 사이트의 보안 프로그램 충돌 쪽을 먼저 의심하세요."},{"heading":"연말정산·세금 신고 시즌에 몰리는 이유","text":"국세청 홈택스, 정부24처럼 특정 시즌에 접속이 몰리는 사이트는 평소 안 쓰던 PC에서 인증서를 처음 등록하려다 이 오류를 겪는 경우가 많습니다. 평소 쓰던 은행 사이트에서는 문제없이 되는데 새 사이트에서만 안 된다면, 대부분 그 사이트에 인증서를 아직 등록하지 않은 것이 원인입니다."},{"heading":"PC를 바꾸거나 재설치한 직후","text":"새 PC나 윈도우 재설치 직후라면 NPKI 폴더 자체가 없는 것이 당연합니다. 기존 PC나 백업 USB에서 인증서 파일(폴더째로)을 복사해 오거나, 발급 기관 사이트에서 인증서 복사·이전 기능을 이용하세요."}],"decision":[{"heading":"인증서 목록이 아예 비어 있을 때","text":"NPKI 폴더 위치부터 확인하세요. 폴더 자체가 없다면 다른 PC·매체에서 인증서를 복사해 와야 합니다."},{"heading":"다른 사이트에서는 되는데 특정 사이트에서만 안 될 때","text":"그 사이트에 인증서를 사전 등록하지 않았거나, 그 사이트 전용 보안 프로그램이 없는 경우입니다. 해당 사이트의 인증센터·보안 프로그램 설치부터 진행하세요."},{"heading":"모든 사이트에서 동시에 안 될 때","text":"PC 공통 원인(NPKI 폴더 자체 문제, USB 손상, 브라우저 전역 설정)일 가능성이 큽니다."}],"examples":["은행 사이트에서 인증서를 선택하려는데 목록이 텅 비어 있다","정부24에서 '인증서 등록에 실패했습니다'가 뜬다","다른 은행에서는 잘 되는데 새로 쓰는 사이트에서만 인증서가 안 보인다"],"mistakes":["NPKI 폴더 위치를 확인하지 않고 인증서를 무작정 재발급받는 것","새 사이트에 인증서 사전 등록이 필요하다는 걸 모르고 기존 인증서만 계속 재설치하는 것"],"faq":[{"q":"인증서 목록에 아무것도 안 뜹니다.","a":"대부분 NPKI 폴더 위치 문제입니다. 탐색기에서 '문서\\NPKI' 또는 USB 안의 NPKI 폴더가 실제로 있는지 먼저 확인하세요. 새 PC나 재설치 직후라면 다른 PC나 백업 매체에서 인증서 파일을 복사해 와야 합니다."},{"q":"다른 은행에서는 인증서가 잘 되는데 이번에 처음 쓰는 사이트에서만 안 됩니다.","a":"인증서 자체 문제가 아니라, 그 사이트에 인증서를 아직 사전 등록(연동)하지 않은 경우가 대부분입니다. 해당 사이트의 인증센터에서 등록 절차를 먼저 진행하세요."},{"q":"PC를 새로 사거나 재설치했는데 인증서가 안 보입니다.","a":"정상입니다. 새 PC에는 NPKI 폴더 자체가 없습니다. 기존 PC나 백업 USB에서 NPKI 폴더를 통째로 복사해 오거나, 발급 기관의 인증서 복사·이전 기능을 이용하세요."}]},"remote-desktop-not-connecting":{"badge":"네트워크","subtitle":"다른 PC에 원격 데스크톱으로 연결이 안 되거나, 연결 시도 중 오류가 날 때","intro":["원격 데스크톱(RDP) 연결 오류는 호스트 PC의 에디션·설정 문제, 방화벽, 네트워크 경로, 로그인 방식 중 하나인 경우가 대부분입니다. 가장 먼저 확인할 것은 연결받는 쪽(호스트) PC가 Windows Pro 이상인지입니다 — 이 조건을 놓쳐서 헤매는 경우가 매우 흔합니다.","Microsoft 공식 문서에 따르면 원격 데스크톱으로 '연결받는' PC는 반드시 Windows Pro 버전이어야 합니다. 연결하는 쪽(클라이언트) PC는 Home이어도 상관없습니다 — 이 방향을 혼동하기 쉽습니다.","같은 사무실 안에서도 안 되는 경우와 외부(집·다른 사무실)에서 안 되는 경우는 원인이 다릅니다. 같은 네트워크 안에서부터 먼저 되는지 확인하면 네트워크 경로 문제인지 PC 자체 설정 문제인지 빠르게 구분할 수 있습니다."],"warnings":["원격 데스크톱 연결 시 '원격 컴퓨터를 찾을 수 없습니다' 또는 '연결할 수 없습니다' 오류가 뜬다.","PC 이름이나 IP를 정확히 입력해도 응답이 없다.","로그인 화면까지는 뜨는데 PIN을 입력하면 인증에 실패한다."],"checks":[{"title":"호스트 PC의 Windows 에디션 확인(가장 흔한 원인)","why":"원격 데스크톱을 '받는' 기능은 Windows Pro·Enterprise·Education에서만 지원됩니다. Home 에디션은 설정 화면에 원격 데스크톱 메뉴 자체가 없거나 켤 수 없습니다.","how":"① 원격으로 접속받을 PC(호스트 PC)에서 Windows 로고 키를 누르고 '정보'를 입력해 '이 PC의 이름 및 사양 정보 보기'를 실행하세요. ② 화면 아래쪽 'Windows 사양'에서 '에디션' 항목을 확인하세요. ③ 'Windows 11 Home' 또는 'Windows 10 Home'으로 표시되어 있다면, 이 PC는 원격 접속을 '받는' 기능 자체를 지원하지 않습니다(Pro/Enterprise/Education만 지원). ④ Home 에디션이라면 설정 → 시스템 → 정품 인증에서 Pro로 업그레이드를 구매하거나, 대신 Windows 기본 '빠른 지원' 앱(도와주는 사람이 화면을 보며 원격으로 조작)을 사용하세요."},{"title":"호스트 PC의 원격 데스크톱 설정 확인","why":"에디션 조건을 충족해도 기능 자체가 꺼져 있으면 연결할 수 없습니다.","how":"① 호스트 PC(Pro 이상 에디션 확인 완료)에서 Windows 로고 키를 누르고 '원격 데스크톱 설정'을 입력해 실행하세요. ② '원격 데스크톱' 스위치를 켜세요. ③ 확인 창이 뜨면 '확인'을 클릭하세요. ④ 같은 화면에서 'PC 이름' 항목에 표시된 이름을 메모해두세요 — 다른 PC에서 접속할 때 이 이름을 입력해야 합니다."},{"title":"방화벽에서 원격 데스크톱 허용 여부 확인","why":"Windows Defender 방화벽이 기본적으로 원격 데스크톱(포트 3389)을 허용하지만, 보안 프로그램을 따로 설치했거나 방화벽 규칙을 수정한 적이 있다면 차단될 수 있습니다.","how":"① 호스트 PC에서 Windows 로고 키를 누르고 'Windows Defender 방화벽'을 입력해 실행하세요. ② 왼쪽 메뉴에서 'Windows Defender 방화벽을 통한 앱 또는 기능 허용'을 클릭하세요. ③ 오른쪽 위 '설정 변경' 버튼을 클릭하세요(관리자 권한 필요). ④ 목록에서 '원격 데스크톱'을 찾아 '개인'과 '공용' 열 체크박스가 모두 체크되어 있는지 확인하고, 안 되어 있다면 체크하세요. ⑤ '확인'을 눌러 저장하세요."},{"title":"PC 이름·IP 주소와 네트워크 경로 확인","why":"같은 사무실(같은 네트워크) 안에서는 PC 이름만으로 연결되지만, 외부망에서 접속하려면 공유기 포트포워딩이나 VPN 같은 별도 설정이 필요합니다.","how":"① 접속하려는 PC(클라이언트)에서 Windows 로고 키를 누르고 '원격 데스크톱 연결'을 입력해 실행하세요. ② 컴퓨터 이름 칸에 위에서 메모해둔 호스트 PC의 이름을 입력하고 '연결'을 클릭하세요. ③ 같은 사무실·같은 공유기 네트워크 안에서 이 방법으로 연결되는지 먼저 확인하세요. ④ 다른 장소(외부망)에서 접속해야 한다면 PC 이름만으로는 연결되지 않습니다 — 회사에서 제공하는 VPN 프로그램을 먼저 연결한 뒤 같은 방법으로 시도하거나, 회사 IT 담당자에게 외부 접속 설정(포트포워딩 등)을 문의하세요."},{"title":"호스트 PC의 절전 설정 확인","why":"호스트 PC가 절전 모드에 들어가면 네트워크 응답 자체가 끊겨 연결이 실패합니다.","how":"① 호스트 PC에서 Windows 로고 키를 누르고 '전원 및 절전 설정'을 입력해 실행하세요. ② '화면' 항목의 시간과 '절전' 항목의 시간이 따로 설정되어 있는지 확인하세요. ③ '절전' 시간을 '안 함'으로 바꾸세요(화면만 꺼지고 PC 자체는 계속 켜져 있도록). ④ 원격으로만 접속해 쓰는 PC라면, 화면 끄기 시간은 짧게 두어도 되지만 절전(잠자기)만큼은 반드시 '안 함'으로 설정해야 언제든 원격 접속이 가능합니다."},{"title":"PIN 대신 비밀번호로 로그인","why":"Windows Hello PIN은 기본적으로 원격 데스크톱 로그인에서 지원되지 않아, PIN을 입력하면 인증에 실패하는 경우가 있습니다.","how":"① 원격 데스크톱 연결 시도 시 로그인 화면에서 '다른 계정 사용' 또는 '자격 증명 다시 입력'을 클릭하세요. ② PIN 대신, Microsoft 계정의 실제 비밀번호나 로컬 계정 비밀번호를 입력하세요(PIN은 그 PC에서만 유효하며 원격 로그인에서는 지원되지 않는 경우가 많습니다). ③ Microsoft 계정 비밀번호를 잊었다면 account.microsoft.com에서 미리 재설정한 뒤 시도하세요."}],"deeper":[{"heading":"클라이언트(연결하는 쪽) PC는 에디션 제약이 없음","text":"Windows Pro 조건은 '연결받는' 호스트 PC에만 적용됩니다. 연결을 시도하는 쪽(클라이언트) PC는 Home이든 Pro든 상관없고, macOS·iOS·Android에서도 'Windows 앱'(구 원격 데스크톱 앱)으로 접속할 수 있습니다. 반대로 착각해서 클라이언트 PC의 에디션만 확인하다가 시간을 허비하는 경우가 많습니다."},{"heading":"사무실 안에서는 되는데 집·외부에서는 안 될 때","text":"이는 네트워크 경로 문제입니다. 회사 네트워크는 보통 외부에서 직접 PC 이름으로 접근할 수 없도록 막혀 있으므로, 회사 VPN에 먼저 연결한 뒤 원격 데스크톱을 시도해야 합니다. 공유기에서 직접 포트포워딩을 설정하는 방법도 있지만, 보안 위험이 있어 회사 환경에서는 VPN 경유를 권장합니다."},{"heading":"원격 데스크톱과 원격 지원(빠른 지원)의 차이","text":"원격 데스크톱은 Pro 이상에서만 '받을' 수 있는 반면, Windows에 내장된 '빠른 지원' 앱은 Home 에디션에서도 화면을 남에게 보여주고 제어를 맡길 수 있습니다. Home PC를 원격으로 도와줘야 한다면 원격 데스크톱 대신 빠른 지원이나 TeamViewer 같은 별도 프로그램을 사용하세요."}],"decision":[{"heading":"호스트 PC가 Home 에디션일 때","text":"원격 데스크톱 자체를 켤 수 없습니다. Pro로 업그레이드하거나, 빠른 지원 같은 다른 원격 지원 도구를 사용하세요."},{"heading":"같은 네트워크 안에서는 되는데 외부에서는 안 될 때","text":"네트워크 경로 문제입니다. 회사 VPN을 먼저 연결한 뒤 시도하거나, IT 담당자에게 외부 접속 방법을 문의하세요."},{"heading":"PIN 입력 시에만 실패할 때","text":"PIN이 아니라 비밀번호로 로그인하세요. 원격 데스크톱은 PIN 로그인을 기본 지원하지 않습니다."}],"examples":["원격 데스크톱 연결 시 '원격 컴퓨터를 찾을 수 없습니다' 오류가 뜬다","PC 이름을 정확히 입력했는데도 연결이 안 된다","회사에서는 원격 데스크톱이 잘 되는데 집에서 접속하면 안 된다"],"mistakes":["연결하는 쪽(클라이언트) PC의 에디션만 확인하고 정작 호스트 PC가 Home인 것은 놓치는 것","외부에서 접속이 안 될 때 VPN 없이 방화벽·포트 설정만 계속 건드리는 것"],"faq":[{"q":"원격 데스크톱을 쓰려면 두 PC 모두 Windows Pro여야 하나요?","a":"아닙니다. 연결받는 쪽(호스트) PC만 Pro 이상이면 됩니다. 연결하는 쪽(클라이언트)은 Home이어도 상관없고, macOS·iOS·Android에서도 접속할 수 있습니다."},{"q":"집에 있는 Home 에디션 PC를 원격으로 제어하려면 어떻게 하나요?","a":"원격 데스크톱으로는 안 됩니다. Windows에 내장된 '빠른 지원' 앱이나 TeamViewer, AnyDesk 같은 별도 원격 지원 프로그램을 사용하세요."},{"q":"PIN으로 로그인했더니 원격 데스크톱 연결에 실패합니다.","a":"원격 데스크톱은 PIN 로그인을 기본적으로 지원하지 않습니다. 연결 화면에서 '다른 계정 사용'을 선택해 비밀번호로 로그인하세요."}]},"store-error":{"badge":"Windows","subtitle":"마이크로소프트 스토어가 열리지 않거나 앱 설치·업데이트가 안 될 때","intro":["마이크로소프트 스토어 오류는 캐시 손상, 계정 인증 오류, 날짜·시간 불일치로 인한 인증서 검증 실패, Windows Update 구성 요소 오류 중 하나인 경우가 대부분입니다. WSReset으로 캐시를 초기화하는 것이 가장 먼저 시도해볼 방법입니다.","스토어는 Windows Update 인프라와 연결되어 있어, Windows Update 오류가 있으면 스토어도 함께 문제가 생기는 경우가 있습니다.","오류 코드를 메모해두면 원인 방향을 빠르게 잡을 수 있습니다."],"warnings":["마이크로소프트 스토어 아이콘을 눌러도 열리지 않는다.","앱 설치나 업데이트 중 오류 코드가 표시된다.","다운로드가 시작되지 않거나 중간에 멈춘다."],"checks":[{"title":"WSReset으로 캐시 초기화","why":"캐시 손상이 스토어 오류의 가장 흔한 원인입니다.","how":"① 키보드에서 Windows 로고 키와 R 키를 동시에 눌러 '실행' 창을 여세요. ② wsreset.exe 를 입력하고 Enter를 누르거나 '확인'을 클릭하세요. ③ 검은색 명령 창이 잠시 나타났다가 사라지고, 약 10초 후 Microsoft Store 앱이 자동으로 열립니다. ④ 스토어가 자동으로 열리면 캐시 초기화가 정상적으로 완료된 것입니다 — 스토어에서 다시 검색이나 다운로드를 시도해보세요."},{"title":"날짜·시간 동기화","why":"시스템 시간이 실제와 크게 다르면 인증서 검증에 실패해 스토어가 작동하지 않습니다.","how":"① 화면 오른쪽 아래 시계를 클릭한 뒤 '날짜 및 시간 설정'을 선택하세요. ② '시간 자동 설정'이 켜져 있는지 확인하고, 꺼져 있다면 켜세요. ③ 그 아래 '지금 동기화' 버튼을 클릭하세요. ④ 표시된 날짜와 시간이 실제와 맞는지 확인한 뒤 Microsoft Store 앱을 다시 열어보세요."},{"title":"Microsoft 계정 재로그인","why":"계정 인증 오류가 스토어 오류로 이어질 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정'을 실행한 뒤 '계정'으로 들어가세요. ② 화면 상단의 계정 이름을 클릭해 '로그아웃'을 선택하세요. ③ PC를 재시작하세요. ④ Microsoft Store 앱을 다시 열고 왼쪽 아래(또는 오른쪽 위) 계정 아이콘을 클릭해 같은 Microsoft 계정으로 다시 로그인하세요."},{"title":"스토어 앱 초기화","why":"복구보다 한 단계 강력하게 앱 데이터를 초기화합니다.","how":"① Windows 로고 키를 누르고 '설치된 앱'(또는 '앱 및 기능')을 입력해 실행하세요. ② 목록에서 'Microsoft Store'를 찾아 점 3개(⋮)를 클릭해 '고급 옵션'을 선택하세요. ③ 아래로 스크롤해 먼저 '복구' 버튼을 클릭해보세요. ④ 복구로 해결되지 않으면 같은 화면의 '초기화' 버튼을 클릭하세요(스토어의 로그인 정보와 설정이 초기화되며, 이미 설치된 다른 앱에는 영향이 없습니다). ⑤ 초기화 후 Microsoft Store를 다시 열어 정상 작동하는지 확인하세요."}],"deeper":[{"heading":"오류 코드별 원인","text":"0x80072EFD(서버 연결 불가)는 네트워크 또는 날짜·시간 문제, 0x80070005(액세스 거부)는 계정 권한 문제, 0x803FB005는 스토어 캐시 손상인 경우가 많습니다."},{"heading":"PowerShell로 스토어 재등록","text":"위 방법으로 해결되지 않으면 PowerShell(관리자)에서 Get-AppxPackage -allusers Microsoft.WindowsStore | Foreach {Add-AppxPackage -DisableDevelopmentMode -Register \"$($_.InstallLocation)\\AppXManifest.xml\"} 명령으로 스토어를 재등록합니다."}],"decision":[{"heading":"WSReset 후 해결될 때","text":"캐시 손상이 원인이었습니다. 이후 재발 시 같은 방법으로 해결 가능합니다."},{"heading":"위 방법으로 해결 안 될 때","text":"Windows Update 구성 요소 오류와 함께 발생하는 경우 DISM /Online /Cleanup-Image /RestoreHealth 명령으로 시스템 이미지를 복구하세요."}],"examples":["스토어 아이콘을 눌러도 앱이 실행되지 않는다","앱 다운로드 중 0x80072EFD 오류가 뜬다"],"mistakes":["WSReset 없이 스토어를 제거하고 재설치하려는 것","날짜·시간 동기화 문제를 확인하지 않는 것"],"faq":[{"q":"마이크로소프트 스토어가 열리지 않으면 어떻게 하나요?","a":"Win+R을 눌러 wsreset.exe를 실행하면 스토어 캐시가 초기화되고 스토어가 자동으로 열립니다. 그래도 안 된다면 PowerShell에서 스토어 앱을 재등록하는 명령을 실행하세요."},{"q":"스토어에서 앱 다운로드가 멈추면?","a":"다운로드 중인 앱을 일시 중지하고 다시 시작해 보세요. 그래도 안 된다면 설정 → 앱 → 마이크로소프트 스토어 고급 옵션에서 초기화를 실행합니다."}]},"laptop-battery-not-charging":{"badge":"배터리","subtitle":"충전기를 꽂아도 배터리가 늘지 않을 때","intro":["'충전 중 아님(플러그가 꽂혀 있음)'이라는 메시지는 배터리 고장을 뜻하지 않습니다. Windows가 전원은 공급되고 있지만 배터리로 충전 전류가 흐르지 않는다고 판단했을 때 이 메시지를 표시하며, 원인은 소프트웨어(드라이버·전원 설정)일 수도, 하드웨어(어댑터·포트·배터리)일 수도 있습니다.","특히 제조사 유틸리티(Lenovo Vantage, Dell Power Manager, ASUS MyASUS 등)에는 배터리 수명을 늘리기 위해 충전을 80~90%에서 멈추는 기능이 있습니다. 이 설정이 켜져 있으면 정상 동작인데도 '충전 중 아님'으로 표시될 수 있어, 가장 먼저 확인해야 합니다.","어댑터·포트·드라이버 점검으로도 해결되지 않으면 powercfg 배터리 보고서로 실제 배터리 열화 정도를 수치로 확인하는 것이 다음 단계입니다."],"warnings":["충전기를 꽂아도 배터리 잔량이 전혀 늘지 않는다.","배터리가 0%에서 고정되어 어댑터를 뽑으면 바로 꺼진다.","배터리가 부풀어 오르거나(팽창) 케이스가 들뜬 흔적이 있다."],"checks":[{"title":"제조사 유틸리티의 충전 한도 설정 확인","why":"배터리 보호를 위해 충전을 일부러 80~90%에서 멈추는 기능이 기본으로 켜져 있는 경우가 흔합니다.","how":"① 시작 메뉴에서 노트북 제조사가 설치한 프로그램(Lenovo Vantage, Dell Power Manager, ASUS MyASUS, 삼성 설정 등)을 찾아 실행하세요(없다면 제조사 홈페이지에서 내려받을 수 있습니다). ② 프로그램 안에서 '배터리' 또는 '전원' 메뉴를 찾으세요. ③ '배터리 충전 임계값', '배터리 보호 모드', '충전 한도' 같은 항목이 80~90%로 설정되어 있는지 확인하세요(이 기능은 배터리 수명 연장을 위해 일부러 완충을 막는 정상 기능입니다). ④ 100%까지 충전하고 싶다면 이 설정을 '전체 용량 모드' 또는 '100%'로 바꾸세요."},{"title":"다른 정품 어댑터로 교체 테스트","why":"어댑터나 케이블 자체의 고장이 충전 안 됨의 흔한 원인입니다.","how":"① 노트북 밑면이나 어댑터 본체에서 요구 전압(V)과 전류(A) 규격을 확인하세요. ② 같은 규격의 다른 정품(또는 정품 인증) 어댑터가 있다면 바꿔 연결해 충전이 되는지 확인하세요. ③ USB-C로 충전하는 노트북이라면 케이블을 다른 USB-C 케이블로도 바꿔 시험하세요(모든 USB-C 케이블이 고전력 충전을 지원하는 것은 아닙니다). ④ 다른 어댑터·케이블에서는 충전된다면 기존 어댑터나 케이블의 고장으로 확정할 수 있습니다."},{"title":"배터리 드라이버 재설치","why":"드라이버가 일시적으로 오작동해 충전 상태를 잘못 인식하는 경우가 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '배터리' 항목을 펼치세요. ③ 'Microsoft ACPI 규격 준수 제어 방법 배터리'를 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택하세요(다른 배터리 관련 항목이 있다면 그대로 두세요). ④ PC를 재부팅하면 Windows가 배터리 드라이버를 자동으로 다시 설치합니다. ⑤ 재부팅 후 충전 상태 아이콘이 정상으로 표시되는지 확인하세요."}],"deeper":[{"heading":"powercfg 배터리 보고서로 실제 열화 확인하기","text":"관리자 권한 명령 프롬프트에서 powercfg /batteryreport를 실행하면 배터리의 설계 용량과 현재 완전 충전 용량을 비교한 보고서(HTML)가 생성됩니다. 완전 충전 용량이 설계 용량의 60% 이하로 떨어졌다면 배터리 자체의 수명이 다한 것으로 보고 교체를 고려해야 합니다."}],"decision":[{"heading":"어댑터를 바꿔도 안 될 때","text":"충전 포트 접촉 불량이나 배터리 자체 고장 가능성이 높으니 제조사·서비스센터 점검을 고려하세요."},{"heading":"충전은 되는데 금방 닳을 때","text":"이 페이지보다 배터리 수명(용량 저하) 문제에 가까우니 powercfg 배터리 보고서로 열화 정도부터 확인하세요."}],"examples":["충전기를 꽂아도 배터리 아이콘에 번개 표시 없이 그대로","배터리 잔량이 0%에서 올라가지 않고 어댑터를 뽑으면 즉시 꺼짐"],"mistakes":["제조사 충전 한도 설정 확인 없이 바로 배터리를 분해·교체하는 것","정품이 아닌 저가 어댑터로 계속 테스트하며 원인을 어댑터로 단정하지 않는 것"],"faq":[{"q":"'충전 중 아님'이 뜨면 배터리를 바로 교체해야 하나요?","a":"아닙니다. 제조사 유틸리티의 충전 한도 설정 때문에 정상적으로 표시되는 경우가 많습니다. powercfg 배터리 보고서로 실제 열화 정도를 확인한 뒤 판단하세요."},{"q":"배터리 없이 어댑터만 꽂아 써도 되나요?","a":"임시방편으로는 가능하지만, 정전이나 전원 순간 끊김에 그대로 노출되고 제조사에 따라 권장하지 않는 경우도 있습니다. 근본 원인을 확인해 배터리나 어댑터를 교체하는 것이 안전합니다."},{"q":"배터리가 부풀어 있는데 계속 써도 되나요?","a":"안전하지 않습니다. 배터리가 부풀거나 케이스가 들뜬 경우 화재 위험이 있으니 즉시 사용을 중단하고 제조사·서비스센터에 문의하세요."}],"communityCases":[{"title":"충전 한도 설정 해제로 해결","summary":"새 노트북에서 배터리가 80%를 넘지 않고 '충전 중 아님'으로 표시되던 사례가 있습니다. 제조사 유틸리티에 기본으로 켜져 있던 배터리 보호(충전 한도) 기능을 확인하고 필요에 따라 껐다 켜자 정상적으로 100%까지 충전됐습니다.","insight":"충전이 특정 퍼센트에서 멈춘다면 고장이 아니라 배터리 보호 기능일 가능성이 높습니다. 분해·교체 전에 제조사 유틸리티부터 확인하세요."}]},"laptop-touchpad-not-working":{"badge":"터치패드","subtitle":"노트북 터치패드가 반응하지 않을 때","intro":["노트북 터치패드가 갑자기 반응하지 않으면 고장처럼 느껴지지만, 실제로는 대부분 소프트웨어적인 원인입니다. 가장 흔한 원인은 키보드의 터치패드 잠금 단축키(Fn 조합)를 실수로 눌렀거나, 마우스를 연결하면 터치패드를 자동으로 끄도록 설정된 제조사 유틸리티 때문입니다.","이런 설정 확인으로 해결되지 않는다면 장치 관리자에서 드라이버 상태를 확인해야 합니다. Windows 업데이트 이후 정밀 터치패드(Precision Touchpad) 드라이버가 충돌하거나 자동으로 비활성화되는 사례가 보고되고 있습니다.","위 방법으로도 해결되지 않고 외부 마우스는 정상 작동한다면, 터치패드 자체나 내부 연결 케이블의 물리적 고장 가능성을 열어두고 서비스센터 점검을 고려해야 합니다."],"warnings":["터치패드를 만져도 커서가 전혀 움직이지 않는다.","장치 관리자에서 터치패드 항목 자체가 보이지 않는다.","외부 마우스는 정상 작동하지만 터치패드만 반응이 없다."],"checks":[{"title":"터치패드 잠금 단축키 확인","why":"Fn 조합키로 터치패드를 실수로 꺼버린 경우가 가장 흔합니다.","how":"① 키보드의 F1~F12 키를 살펴보며 터치패드 모양(사각형에 손가락 또는 X 표시) 아이콘이 그려진 키를 찾으세요(보통 F5~F9 사이에 있습니다). ② Fn 키를 누른 상태로 그 키를 함께 눌러보세요. ③ 화면에 터치패드 켜짐/꺼짐 알림이 잠깐 나타나는지 확인하세요. ④ 터치패드에 손가락을 대고 반응하는지 확인하세요."},{"title":"마우스 연결 시 자동 비활성화 설정 확인","why":"일부 제조사는 마우스를 연결하면 터치패드를 자동으로 끄도록 기본 설정되어 있습니다.","how":"① 문제없이 동작하는 마우스나 키보드로 PC를 조작할 수 있는 상태를 확보하세요. ② Windows 로고 키를 누르고 '터치패드 설정'을 입력해 실행하세요. ③ 화면을 아래로 스크롤해 '마우스가 연결되어 있으면 터치패드를 그대로 사용' 옵션을 확인하세요. ④ 체크가 해제되어 있다면(즉 마우스 연결 시 터치패드가 자동으로 꺼지도록 설정되어 있다면) 체크해서 켜세요. ⑤ USB 마우스나 블루투스 마우스가 연결되어 있지 않은지도 확인하세요 — 연결되어 있다면 뽑거나 페어링을 해제해보세요."},{"title":"터치패드 드라이버 재설치","why":"드라이버가 손상되거나 업데이트 이후 충돌하는 경우가 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '마우스 및 기타 포인팅 장치' 항목을 펼치세요. ③ 터치패드 이름(제조사 이름이 포함된 경우가 많습니다)을 찾아 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택하세요. ④ PC를 재부팅하면 Windows가 터치패드를 다시 인식해 드라이버를 자동으로 설치합니다. ⑤ 여전히 안 되면 노트북 제조사 홈페이지에서 정확한 모델명으로 검색해 전용 터치패드 드라이버를 내려받아 설치하세요."}],"deeper":[{"heading":"정밀 터치패드(Precision Touchpad) 설정 확인하기","text":"설정 > 블루투스 및 장치 > 터치패드 화면 상단에 '정밀 터치패드 지원 장치'라는 문구가 보이면 Windows 표준 드라이버로 동작 중인 것입니다. 이 문구가 없고 제조사 전용 드라이버만 표시된다면 제조사 홈페이지에서 최신 터치패드 드라이버를 다시 받아 설치하는 것이 더 확실합니다."}],"decision":[{"heading":"단축키·설정 확인으로 해결되지 않을 때","text":"장치 관리자에서 드라이버 상태부터 확인하고, 드라이버 재설치로도 안 되면 제조사 최신 드라이버를 직접 받아 설치하세요."},{"heading":"드라이버 재설치로도 안 될 때","text":"외부 마우스가 정상이라면 터치패드 자체나 케이블의 물리적 고장 가능성이 높으니 서비스센터 점검을 고려하세요."}],"examples":["터치패드를 문질러도 커서가 전혀 반응하지 않음","노트북을 켤 때마다 터치패드가 꺼진 상태로 부팅됨"],"mistakes":["단축키·설정 확인 없이 바로 서비스센터에 수리를 맡기는 것","드라이버 재설치 없이 운영체제를 재설치하는 것"],"faq":[{"q":"터치패드 잠금 단축키는 노트북마다 다른가요?","a":"네, 제조사와 모델에 따라 위치가 다릅니다. 보통 F5~F9 사이에 터치패드 아이콘이 그려진 키가 있으며, Fn과 함께 눌러야 동작합니다."},{"q":"터치패드 드라이버를 제거해도 괜찮나요?","a":"네, 장치 관리자에서 드라이버를 제거하고 재부팅하면 Windows가 기본 드라이버를 자동으로 재설치합니다. 데이터 손실 없이 안전하게 시도할 수 있는 방법입니다."},{"q":"외부 마우스를 뽑아도 터치패드가 안 켜지면요?","a":"설정 > 블루투스 및 장치 > 터치패드에서 켜짐 상태인지 다시 확인하고, 안 되면 장치 관리자에서 드라이버를 재설치해보세요. 그래도 안 되면 하드웨어 고장 가능성을 고려해야 합니다."}],"communityCases":[{"title":"마우스 자동 비활성화 설정 해제로 해결","summary":"마우스를 연결한 뒤로 터치패드가 계속 꺼진 채로 있던 사례가 있습니다. 설정에서 '마우스 연결 시 터치패드 끄기' 옵션이 켜져 있던 것을 확인하고 끄자 마우스를 연결해도 터치패드가 정상 작동했습니다.","insight":"터치패드가 항상 꺼져 있다면 고장이 아니라 자동 비활성화 설정 때문일 가능성이 높습니다."}]},"external-drive-not-detected":{"badge":"외장하드","subtitle":"외장하드·USB 저장장치가 인식되지 않을 때","intro":["외장하드가 인식되지 않을 때 가장 먼저 나눠야 할 것은 '연결 문제'인지 '데이터 손상'인지입니다. USB 케이블을 바꾸거나 다른 포트에 연결했을 때 인식된다면 단순 접촉 불량이지만, 여러 포트·여러 PC에서 모두 인식되지 않는다면 외장하드 자체의 고장 가능성이 높습니다.","디스크 관리(diskmgmt.msc)에서는 보이는데 탐색기에는 안 보인다면, 드라이브 문자가 할당되지 않았거나 파티션이 초기화되지 않은 상태일 수 있습니다. 이 경우는 새 드라이브 문자를 할당하거나 파티션을 만들면 해결되지만, 이미 저장된 데이터가 있는 외장하드라면 함부로 초기화하면 데이터가 손실될 수 있으니 주의해야 합니다.","디스크 관리에도 전혀 나타나지 않는다면 전원 공급 부족이나 하드웨어 고장 가능성이 높으므로, 무리하게 여러 번 재연결하기보다 전문 복구 업체 점검을 고려하는 것이 안전합니다."],"warnings":["디스크 관리(diskmgmt.msc)에도 외장하드가 전혀 나타나지 않는다.","연결할 때마다 인식 소리(연결음)만 나고 탐색기에는 나타나지 않는다.","연결 시 이상한 소음(클릭음, 반복적인 스핀업/다운)이 난다."],"checks":[{"title":"다른 포트·다른 케이블로 연결 테스트","why":"USB 포트나 케이블의 접촉 불량이 가장 흔한 원인입니다.","how":"① USB 허브를 거치고 있다면 허브 없이 PC 본체 뒷면 포트에 케이블을 직접 꽂으세요. ② 앞면과 뒷면의 다른 포트로도 바꿔가며 인식되는지 비교하세요. ③ 다른 USB 케이블(같은 규격)이 있다면 교체해보세요. ④ 외장하드가 자체 전원 어댑터를 쓰는 제품이라면 어댑터가 콘센트에 제대로 연결되어 있는지 확인하세요."},{"title":"디스크 관리에서 드라이브 문자 확인","why":"디스크는 인식되지만 드라이브 문자가 없어 탐색기에 안 보이는 경우가 있습니다.","how":"① Windows 로고 키를 누르고 'diskmgmt.msc'를 입력한 뒤 Enter를 누르세요. ② 화면 아래쪽 목록에서 연결한 외장하드가 '디스크 1', '디스크 2' 등으로 표시되는지 확인하세요. ③ 표시는 되는데 드라이브 문자(D:, E: 등)가 없다면, 해당 영역을 마우스 오른쪽 버튼으로 클릭해 '드라이브 문자 및 경로 변경'을 선택하고 '추가'를 눌러 문자를 할당하세요. ④ 디스크 자체가 목록에 아예 없다면 하드웨어 인식 문제이니 위의 케이블·포트 확인 항목을 다시 진행하세요."},{"title":"다른 PC에서 연결 테스트","why":"특정 PC만의 문제인지 외장하드 자체의 문제인지 구분할 수 있습니다.","how":"① 같은 외장하드를 다른 PC나 노트북에 연결하세요. ② 그 PC에서도 인식이 안 된다면 외장하드 자체의 고장일 가능성이 크므로 데이터가 중요하다면 전문 복구 업체 문의를 고려하세요. ③ 다른 PC에서는 정상적으로 인식된다면 원래 PC의 USB 포트, 드라이버, 또는 전원 설정 문제이므로 그 PC에서 장치 관리자를 통한 드라이버 재설치를 시도하세요."}],"deeper":[{"heading":"디스크 관리에서 보이지만 초기화되지 않았다고 나올 때","text":"이미 데이터가 저장된 외장하드에서 '초기화되지 않음' 메시지가 나타난다면 절대 초기화하지 마세요. 초기화하면 파티션 테이블이 새로 만들어지며 기존 데이터에 접근할 수 없게 됩니다. 이 경우 데이터 복구가 필요한 상태일 수 있으므로 전문 업체 점검을 먼저 고려해야 합니다."}],"decision":[{"heading":"다른 포트·PC에서는 정상 인식될 때","text":"원래 PC의 USB 포트나 드라이버 문제이니 장치 관리자에서 USB 컨트롤러 드라이버를 점검하세요."},{"heading":"어떤 포트·PC에서도 인식되지 않을 때","text":"외장하드 자체의 고장 가능성이 높습니다. 데이터가 중요하다면 함부로 재시도하지 말고 복구 업체에 먼저 문의하세요."}],"examples":["연결하면 인식음은 나는데 탐색기에 드라이브가 안 보임","디스크 관리에도 아예 나타나지 않고 장치 관리자에 느낌표로 표시됨"],"mistakes":["인식이 안 된다고 여러 번 반복해서 연결을 껐다 켰다 하는 것(물리적 고장 시 손상 악화 가능)","데이터가 있는 상태에서 '초기화되지 않음' 메시지가 뜬다고 바로 초기화하는 것"],"faq":[{"q":"외장하드에서 클릭음이 나는데 계속 연결해도 되나요?","a":"아닙니다. 클릭음은 하드디스크 내부 헤드 고장의 대표적인 신호로, 계속 시도하면 데이터 복구 가능성이 낮아질 수 있습니다. 즉시 전원을 분리하고 복구 업체에 문의하세요."},{"q":"디스크 관리에서 '초기화되지 않음'이라고 뜨면 초기화해야 하나요?","a":"기존에 저장된 중요 데이터가 없다면 초기화해도 되지만, 데이터가 있었다면 초기화 전에 반드시 데이터 복구 가능성부터 확인해야 합니다."},{"q":"USB 허브에 연결하면 왜 인식이 안 되나요?","a":"외장하드, 특히 2.5인치 외장 HDD는 소비 전력이 커서 전원 공급이 부족한 허브를 거치면 인식이 불안정할 수 있습니다. 가능하면 본체에 직접 연결하세요."}],"communityCases":[{"title":"USB 허브 대신 직결로 해결","summary":"멀티탭형 USB 허브에 연결했을 때만 외장하드가 인식되지 않던 사례가 있습니다. 본체 후면 USB 포트에 직접 연결하자 정상적으로 인식되었고, 원인은 허브를 통한 전원 공급 부족으로 확인되었습니다.","insight":"USB 허브 경유 시에만 인식이 안 된다면 케이블이나 하드 자체보다 전원 공급 부족을 먼저 의심하세요."}]},"display-driver-crash":{"badge":"그래픽","subtitle":"화면이 깜빡이며 복구되거나, 신호없음으로 완전히 꺼질 때","intro":["'디스플레이 드라이버가 응답을 중지했다가 복구됨' 메시지는 그래픽카드가 완전히 고장났다는 뜻이 아니라, Windows의 TDR(Timeout Detection and Recovery) 기능이 정상 동작한 결과입니다. 그래픽카드가 정해진 시간 안에 응답하지 못하면 Windows가 드라이버만 재시작해 화면이 잠깐 깜빡이는 것으로 보통 복구됩니다.","문제는 이 TDR 복구 자체가 실패하는 경우입니다. 화면이 깜빡이다 돌아오는 게 아니라 모니터에 아예 '신호없음'이 뜨고, 소리나 다른 프로그램은 계속 동작하는데 화면만 안 돌아와 강제로 재부팅해야 하는 경우가 있습니다. 이때도 시스템 자체는 살아있으므로 재부팅·다운 증상과는 접근 방법이 다릅니다.","가끔 한 번 발생하는 정도라면 큰 문제가 아닐 수 있지만, 특정 게임이나 작업 중 반복적으로 발생한다면 드라이버 호환성, 오버클럭 불안정, 발열, 전원 공급 부족, 케이블·포트 접촉 불량 중 하나일 가능성이 높습니다.","원인을 좁히려면 오버클럭 여부, 온도, 전원, 케이블·포트 순서로 하나씩 확인하는 것이 효율적입니다."],"warnings":["게임이나 영상 재생 중 화면이 잠깐 검게 변했다가 알림과 함께 복구된다.","특정 게임에서만 반복적으로 발생하고 다른 프로그램에서는 발생하지 않는다.","복구 후에도 화면이 완전히 정상으로 돌아오지 않고 깨짐이 남는다.","화면이 깜빡이지 않고 아예 신호없음으로 꺼지며, 소리는 정상인데 재부팅해야만 화면이 돌아온다."],"checks":[{"title":"오버클럭 설정 초기화","why":"GPU나 메모리 클럭을 과도하게 올린 상태가 불안정해 타임아웃을 유발하는 경우가 흔합니다.","how":"① MSI 애프터버너나 그래픽카드 제조사의 튜닝 프로그램을 실행하세요. ② 코어 클럭, 메모리 클럭, 전압 슬라이더를 모두 기본값(0 또는 'Reset' 버튼)으로 되돌리세요. ③ 오른쪽 아래 체크(적용) 버튼을 클릭해 적용하세요. ④ 프로그램을 Windows 시작 시 자동 실행하도록 설정해뒀다면 해제하는 것도 고려하세요. ⑤ 이전에 화면이 꺼지던 작업을 다시 해보며 재현되는지 확인하세요."},{"title":"그래픽 드라이버 완전 재설치","why":"드라이버 자체의 버그나 이전 버전과의 충돌이 원인일 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정' → '시스템' → '복구'에서 안전 모드로 진입하세요(문제 해결 → 고급 옵션 → 시작 설정 → 다시 시작 → F4). ② 안전 모드에서 'Display Driver Uninstaller(DDU)' 프로그램을 실행해 제조사(NVIDIA/AMD)를 선택하고 '지우기 및 다시 시작'을 클릭하세요. ③ 재부팅 후 그래픽카드 제조사 공식 홈페이지에서 최신 안정 버전 드라이버를 내려받아 설치하세요. ④ 이전에 화면이 꺼지던 작업을 다시 해보며 재현되는지 확인하세요."},{"title":"GPU 온도·전원 상태 확인","why":"과열이나 전원 공급 부족도 순간적인 응답 지연을 유발할 수 있습니다.","how":"① 웹 브라우저에서 'GPU-Z' 공식 홈페이지에 접속해 무료 프로그램을 내려받아 실행하세요. ② 화면이 꺼지던 작업을 다시 하며 'Sensors' 탭에서 GPU 온도를 지켜보세요. ③ 90도 이상까지 치솟은 뒤 화면이 꺼진다면 과열이 원인일 가능성이 크므로, 케이스를 열어 그래픽카드 팬과 방열판의 먼지를 청소하세요. ④ PC 전원을 끄고 그래픽카드에 연결된 6핀/8핀 보조전원 케이블이 완전히 꽂혔는지 다시 확인하세요."},{"title":"케이블·포트, PCIe 전원 관리 확인 (복구 없이 신호없음일 때)","why":"깜빡이다 돌아오지 않고 아예 신호없음으로 꺼진다면 드라이버 타임아웃보다 케이블·포트 접촉이나 PCIe 절전(ASPM) 문제로 출력 자체가 끊겼을 가능성이 큽니다.","how":"① 사용 중인 HDMI/DP 케이블을 다른 케이블로 교체해 같은 증상이 재현되는지 확인하세요. ② 그래픽카드의 다른 출력 포트로도 옮겨 연결해보세요. ③ Windows 로고 키를 누르고 '전원 모드'를 입력해 들어간 뒤 '전원 관련 추가 설정' → '고급 전원 관리 설정 변경'을 클릭하세요. ④ 'PCI Express' 항목을 펼쳐 '링크 상태 전원 관리'를 '꺼짐'으로 바꾸고 저장하세요. ⑤ 재부팅 후 같은 작업을 반복해 신호 끊김이 줄었는지 확인하세요."},{"title":"이벤트 뷰어에서 WHEA-Logger 확인","why":"화면이 꺼진 정확한 시각에 WHEA-Logger 이벤트가 남아있는지가 소프트웨어·연결 문제와 실제 하드웨어(CPU·메인보드·GPU) 문제를 구분하는 가장 확실한 단서입니다.","how":"① Windows 로고 키를 누르고 'eventvwr.msc'를 입력한 뒤 Enter를 누르세요. ② 왼쪽 트리에서 'Windows 로그' → '시스템'을 클릭하세요. ③ 화면이 꺼졌던 정확한 시각을 기억해두고, 오른쪽 목록에서 그 시각 근처에 원본이 'WHEA-Logger'로 표시된 항목이 있는지 확인하세요. ④ 있다면 더블클릭해 이벤트 ID를 확인하세요. <a href=\"event-whea-logger-17.html\">WHEA-Logger 17(PCIe 오류)</a>이나 <a href=\"event-whea-logger-18.html\">18·19·20(하드웨어 오류)</a> 계열 이벤트가 같이 남아있다면 하드웨어 쪽 원인일 가능성이 높고, 아무 이벤트도 없다면 소프트웨어·연결 문제일 가능성이 더 큽니다."}],"deeper":[{"heading":"TDR이란 무엇인가","text":"TDR(Timeout Detection and Recovery)은 Windows가 그래픽 드라이버의 응답을 감시하다가 기본값인 2초 안에 응답이 없으면 드라이버를 강제로 재시작하는 보호 기능입니다. 이 덕분에 그래픽카드가 멈춰도 시스템 전체가 블루스크린으로 이어지지 않고 화면만 복구되는 것입니다. 즉 이 메시지 자체는 '보호 기능이 작동했다'는 신호이지, 그래픽카드가 완전히 망가졌다는 뜻은 아닙니다."},{"heading":"깜빡였다가 복구됨 vs 신호없음, 재부팅 필요","text":"화면이 잠깐 깜빡이고 알림과 함께 정상으로 돌아온다면 TDR이 의도대로 동작한 것이라 큰 문제가 아닐 수 있습니다. 반면 화면이 신호없음으로 완전히 꺼지고 사운드 등 나머지는 정상 동작하는데 재부팅해야만 복구된다면, TDR 복구 자체가 실패한 것이거나 애초에 드라이버 문제가 아니라 케이블·포트·PCIe 전원 관리 쪽에서 출력이 끊긴 것일 가능성이 더 높습니다. 이 경우는 순서를 바꿔 케이블·포트·전원 관리부터 먼저 확인하는 것이 효율적입니다."},{"heading":"RTX 5060·5060 Ti 재부팅 시 블랙스크린이라면 (펌웨어 업데이트)","text":"RTX 5060·5060 Ti는 구형 메인보드 SBIOS와의 호환성 문제로 재부팅할 때 블랙스크린이 뜨는 사례가 NVIDIA에서 공식 확인됐고, 전용 펌웨어(vBIOS) 업데이트 도구가 배포돼 있습니다. 이 픽스는 '재부팅 시점'의 블랙스크린에 해당하는 것으로, 사용 중 갑자기 신호없음이 되는 경우와는 발생 시점이 다르니 참고용으로만 확인하세요. <a href=\"https://nvidia.custhelp.com/app/answers/detail/a_id/5665/~/nvidia-gpu-uefi-firmware-update-tool-for-rtx-5060-series\" target=\"_blank\" rel=\"noopener noreferrer\">NVIDIA 공식 안내 페이지</a>에서 설명을 확인하거나, <a href=\"https://www.nvidia.com/content/DriverDownloads/confirmation.php?url=/Windows/uefi/firmware/2.0/NVIDIA_UEFI_Firmware_Updater_2.0-x64.exe&firmware=1&lang=us&type=Other\" target=\"_blank\" rel=\"noopener noreferrer\">GPU UEFI Firmware Update Tool v2.0 바로 다운로드</a>로 바로 받을 수 있습니다. 도구를 실행하면 필요 없는 경우엔 그대로 종료되고 필요한 경우에만 업데이트를 제안하므로 실행 자체는 안전합니다. 적용 전 메인보드 최신 BIOS 설치와 UEFI 부팅 모드(Legacy/CSM 아님) 확인이 필요합니다."},{"heading":"CPU·메인보드 불량일 가능성은?","text":"화면 출력만 죽고 사운드·나머지 프로그램은 정상 동작한다면, CPU나 메인보드 전체 불량보다는 GPU 출력 경로(케이블·드라이버·PCIe 전원 관리) 문제일 가능성이 더 높습니다. CPU·메인보드가 실제로 불량이면 보통 무작위 재부팅, 블루스크린, USB 장치 끊김처럼 증상이 훨씬 광범위하게 나타나기 때문입니다. 다만 AM5처럼 메인보드 칩셋이 아니라 CPU가 직접 GPU 슬롯의 PCIe 레인을 처리하는 플랫폼에서는 CPU의 PCIe 컨트롤러나 슬롯 접촉이 약해도 GPU만 콕 집어 출력이 끊기는 것처럼 보일 수 있어 완전히 배제할 수는 없습니다. 가장 확실한 구분법은 화면이 꺼진 시각에 <a href=\"event-whea-logger-17.html\">WHEA-Logger</a> 이벤트가 남아있는지 확인하는 것입니다."}],"decision":[{"heading":"특정 게임에서만 발생할 때","text":"해당 게임과 현재 드라이버 버전의 호환성 문제일 가능성이 높으니, 게임 커뮤니티에서 안정적이라고 알려진 이전 드라이버 버전으로 낮춰보는 것도 방법입니다."},{"heading":"온도·전원 점검 후에도 반복될 때","text":"그래픽카드 자체의 결함 가능성을 열어두고, 가능하다면 다른 PC에 꽂아 동일 증상이 재현되는지 확인해보세요."},{"heading":"신호없음으로 꺼지고 재부팅해야만 복구될 때","text":"케이블·포트 교체와 PCIe 링크 상태 전원 관리 끄기부터 먼저 시도하세요. 최근 출시된 GPU(RTX 5060·5060 Ti 등)를 쓴다면 제조사 홈페이지에서 해당 모델의 vBIOS·펌웨어 관련 공지가 있는지도 확인해볼 가치가 있습니다."}],"examples":["게임 도중 화면이 1~2초 깜빡이며 '디스플레이 드라이버가 응답을 중지하고 복구됨' 알림이 뜸","오버클럭 적용 후부터 특정 프로그램에서만 반복적으로 화면이 깜빡임","사용 중 화면이 신호없음으로 완전히 꺼지고, 사운드는 계속 나오는데 재부팅해야만 화면이 돌아옴"],"mistakes":["오버클럭 여부를 확인하지 않고 바로 그래픽카드를 교체하는 것","드라이버를 덮어씌우기만 하고 이전 버전을 완전히 제거하지 않은 채 재설치하는 것"],"faq":[{"q":"이 메시지가 뜨면 그래픽카드가 고장난 건가요?","a":"꼭 그렇지는 않습니다. Windows의 TDR 보호 기능이 정상 동작한 결과일 수 있으며, 오버클럭·드라이버·발열 문제로도 흔히 발생합니다. 반복 빈도와 다른 증상을 함께 확인해야 합니다."},{"q":"한 번만 발생했는데 그냥 둬도 되나요?","a":"가끔 한 번 정도라면 큰 문제가 아닐 수 있습니다. 하지만 반복된다면 오버클럭 초기화, 드라이버 재설치, 온도 확인 순서로 점검하는 것이 좋습니다."},{"q":"DDU는 어떻게 사용하나요?","a":"안전 모드에서 DDU(Display Driver Uninstaller)를 실행해 기존 그래픽 드라이버를 완전히 제거한 뒤, 재부팅하고 제조사 홈페이지에서 최신 드라이버를 새로 설치하면 됩니다."},{"q":"화면이 깜빡이지 않고 아예 꺼져서 재부팅해야 해요. 소리는 정상인데도요.","a":"이 경우는 TDR 복구가 실패했거나 처음부터 드라이버 문제가 아닐 가능성이 큽니다. 케이블·포트를 바꿔보고, 전원 옵션에서 PCI Express 링크 상태 전원 관리를 꺼보세요. 최근 출시된 GPU라면 제조사의 vBIOS·펌웨어 관련 공지도 확인해보는 것이 좋습니다."},{"q":"RTX 5060·5060 Ti인데 재부팅할 때만 블랙스크린이 떠요. 펌웨어 업데이트는 어떻게 하나요?","a":"구형 메인보드 SBIOS와의 호환성 문제로 NVIDIA가 공식 확인하고 전용 펌웨어 업데이트 도구를 배포했습니다. <a href=\"https://www.nvidia.com/content/DriverDownloads/confirmation.php?url=/Windows/uefi/firmware/2.0/NVIDIA_UEFI_Firmware_Updater_2.0-x64.exe&firmware=1&lang=us&type=Other\" target=\"_blank\" rel=\"noopener noreferrer\">GPU UEFI Firmware Update Tool v2.0 다운로드</a>(<a href=\"https://nvidia.custhelp.com/app/answers/detail/a_id/5665/~/nvidia-gpu-uefi-firmware-update-tool-for-rtx-5060-series\" target=\"_blank\" rel=\"noopener noreferrer\">공식 안내 페이지</a>)에서 받아 실행하면 됩니다. 실행 전 메인보드 최신 BIOS 설치와 UEFI 부팅 모드 확인이 필요하며, 도구가 필요 여부를 자동으로 판단하므로 실행 자체는 안전합니다."},{"q":"CPU나 메인보드 불량 가능성도 있나요?","a":"가능성은 있지만 우선순위는 낮습니다. CPU·메인보드가 실제로 불량이면 무작위 재부팅, 블루스크린처럼 증상이 훨씬 광범위한 경우가 많고, 지금처럼 화면 출력만 죽고 나머지는 멀쩡한 증상은 케이블·드라이버·PCIe 전원 관리 쪽일 때가 더 흔합니다. 확실히 구분하려면 화면이 꺼진 시각에 이벤트 뷰어에서 <a href=\"event-whea-logger-17.html\">WHEA-Logger</a> 이벤트가 남아있는지 확인하세요. 있다면 하드웨어 쪽 문제일 가능성이 높습니다."}],"communityCases":[{"title":"오버클럭 초기화로 해결","summary":"특정 게임 실행 중에만 반복적으로 화면이 깜빡이며 드라이버 복구 알림이 뜨던 사례가 있습니다. GPU 오버클럭 설정을 기본값으로 되돌리자 더 이상 재현되지 않아, 원인이 불안정한 오버클럭이었음을 확인했습니다.","insight":"특정 게임에서만 반복된다면 그래픽카드 고장보다 오버클럭 불안정성을 먼저 의심하세요."}]},"c-drive-storage-full":{"badge":"저장공간","subtitle":"C드라이브 여유 공간이 부족할 때","intro":["C드라이브 용량 부족은 단순히 불편한 정도가 아니라 Windows 업데이트 실패, 프로그램 설치 오류, 시스템 속도 저하로 이어질 수 있는 문제입니다. Windows는 정상 동작을 위해 C드라이브에 최소한의 여유 공간(보통 몇 GB 이상)이 필요하기 때문입니다.","가장 먼저 확인할 것은 '무엇이 용량을 차지하고 있는가'입니다. 설정 > 시스템 > 저장공간에서 항목별 용량을 확인하면 Windows Update 파일, 임시 파일, 휴지통 중 어느 것이 원인인지 파악할 수 있습니다.","정리로 어느 정도 해결되더라도 SSD 용량 자체가 작다면(128GB 이하) 근본적으로는 저장장치 용량 업그레이드가 더 확실한 해결책입니다.","디스크 정리 도구로 보이지 않는 공간 소비자도 있습니다. WinSxS 폴더(구성 요소 저장소)는 업데이트 이력이 쌓일수록 수십 GB까지 커질 수 있고, 최대 절전 모드 파일(hiberfil.sys)은 설치된 램 용량만큼 통째로 차지합니다. 단순히 큰 파일을 지우는 것보다 디스크 정리에서 '시스템 파일 정리'를 선택해야 이런 항목들까지 확인할 수 있습니다."],"warnings":["C드라이브 표시줄이 빨간색으로 바뀌고 '이 드라이브의 공간이 부족합니다' 경고가 뜬다.","Windows Update 설치가 '디스크 공간이 부족합니다' 오류로 실패한다.","프로그램 설치나 파일 저장이 갑자기 안 된다."],"checks":[{"title":"저장공간 항목별 확인","why":"무엇이 용량을 차지하는지 알아야 올바른 정리 방법을 선택할 수 있습니다.","how":"① Windows 로고 키를 누르고 '저장소 설정'을 입력해 실행하세요. ② 'C 드라이브(로컬 디스크)'를 클릭하면 임시 파일, 앱 및 기능, 문서, 사진 등 항목별로 얼마나 용량을 차지하는지 막대그래프로 표시됩니다. ③ 가장 큰 비중을 차지하는 항목을 확인해, 그 항목부터 우선적으로 정리하세요(예: '앱 및 기능'이 크다면 안 쓰는 프로그램 삭제, '임시 파일'이 크다면 아래 디스크 정리 항목 진행)."},{"title":"디스크 정리로 시스템 파일 제거","why":"Windows 업데이트 찌꺼기와 이전 버전 백업이 수 GB에서 수십 GB까지 차지할 수 있습니다.","how":"① Windows 로고 키를 누르고 'cleanmgr'을 입력한 뒤 Enter를 누르세요(디스크 정리 프로그램이 실행됩니다). ② 드라이브 선택 창이 뜨면 'C:'를 선택하고 '확인'을 누르세요. ③ 잠시 후 뜨는 창에서 '시스템 파일 정리' 버튼을 클릭하세요(관리자 권한이 필요할 수 있습니다). ④ 다시 C 드라이브를 선택해 분석이 끝나면, 목록에서 'Windows Update 정리', '이전 Windows 설치', '전송 최적화 파일' 등에 체크하세요(체크 전 각 항목 설명을 읽어 필요한 파일은 남겨두세요). ⑤ '확인'을 누르고 삭제를 진행하세요."},{"title":"저장 공간 센스 자동 정리 설정","why":"매번 수동으로 정리하지 않아도 임시 파일이 주기적으로 자동 삭제됩니다.","how":"① Windows 로고 키를 누르고 '저장소 설정'을 입력해 실행하세요. ② '저장 공간 센스' 스위치를 켜세요. ③ '저장 공간 센스 구성 또는 지금 실행'을 클릭하세요. ④ '임시 파일 자동 정리' 항목을 켜고, 실행 주기(매일/매주/매월)와 다운로드 폴더의 파일 보관 기간을 원하는 대로 설정하세요. ⑤ 저장하면 이후로는 Windows가 주기적으로 알아서 임시 파일을 정리해줍니다."}],"deeper":[{"heading":"hiberfil.sys가 용량을 많이 차지하는 이유","text":"최대 절전 모드를 사용하면 시스템 메모리 내용을 저장하기 위한 hiberfil.sys 파일이 C드라이브에 생성되며, 보통 설치된 RAM 용량의 상당 부분(많게는 75% 이상)을 차지합니다. 최대 절전 모드를 쓰지 않는다면 관리자 권한 명령 프롬프트에서 powercfg /hibernate off를 실행해 이 파일을 완전히 제거하고 공간을 확보할 수 있습니다."}],"decision":[{"heading":"정리 후에도 금방 다시 차는 경우","text":"일회성 정리보다 저장 공간 센스로 자동 정리를 설정하는 것이 근본적인 해결에 가깝습니다."},{"heading":"정리로도 여유 공간이 크게 부족한 경우","text":"SSD 용량 자체가 작은 것이 원인일 가능성이 높으니 파티션 조정이나 저장장치 업그레이드를 고려하세요."}],"examples":["Windows Update 도중 '이 업데이트를 설치할 디스크 공간이 부족합니다' 오류 발생","C드라이브가 빨간색으로 표시되고 용량이 1GB 미만으로 남음"],"mistakes":["용량이 뭘 차지하는지 확인하지 않고 무작정 개인 파일부터 지우는 것","Windows.old 폴더를 탐색기에서 직접 삭제하려다 권한 오류로 실패하는 것(디스크 정리 도구를 통해 삭제해야 함)"],"faq":[{"q":"Windows.old 폴더는 지워도 되나요?","a":"이전 Windows 버전으로 되돌릴 계획이 없다면 지워도 됩니다. 단, 탐색기에서 직접 삭제하지 말고 디스크 정리(cleanmgr)의 '시스템 파일 정리' 기능을 사용해야 안전하게 삭제됩니다."},{"q":"hiberfil.sys를 지우면 절전 기능을 못 쓰나요?","a":"네, powercfg /hibernate off를 실행하면 최대 절전 모드 자체가 비활성화됩니다. 절전(Sleep) 모드는 별도 기능이라 영향받지 않습니다."},{"q":"C드라이브만 작게 나뉘어 있고 D드라이브는 여유가 많은데 어떻게 하나요?","a":"디스크 관리에서 D드라이브의 여유 공간 일부를 줄여 C드라이브에 붙이는 파티션 확장이 가능합니다. 단, 데이터 손실 위험이 있으니 작업 전 반드시 백업하세요."}],"communityCases":[{"title":"저장 공간 센스로 반복 문제 해결","summary":"디스크 정리를 할 때마다 며칠 뒤 다시 용량 부족 경고가 뜨던 사례가 있습니다. 저장 공간 센스를 켜서 임시 파일이 주기적으로 자동 삭제되도록 설정하자 이후로는 경고가 다시 나타나지 않았습니다.","insight":"정리를 반복해도 금방 다시 차오른다면 일회성 정리보다 자동화 설정이 더 효과적입니다."}]},"pc-overall-slow":{"badge":"속도 저하","subtitle":"부팅 이후에도 평소 내내 느릴 때","intro":["컴퓨터가 느려졌다고 느껴질 때는 원인이 하나로 정해져 있지 않습니다. CPU, 메모리, 디스크, 저장공간, 온도 중 어느 쪽이 병목인지에 따라 점검 방법이 완전히 달라지므로, 무작정 포맷하거나 램부터 늘리기 전에 먼저 원인을 구분하는 것이 순서입니다.","가장 빠른 구분 방법은 작업 관리자(Ctrl+Shift+Esc)의 '성능' 탭입니다. CPU, 메모리, 디스크 사용률을 몇 분간 지켜보면서 어느 항목이 평소에도 계속 높게 유지되는지 확인하세요.","부팅할 때만 유독 오래 걸리고 로그인 이후에는 정상이라면, 이 페이지보다 부팅 속도 저하 페이지에서 시작 프로그램 위주로 확인하는 것이 더 정확합니다."],"warnings":["웹 서핑처럼 가벼운 작업에서도 버벅임이 느껴진다.","프로그램을 두세 개만 동시에 켜도 전체적으로 느려진다.","예전보다 확실히 느려졌다는 느낌이 몇 주 이상 계속된다."],"checks":[{"title":"작업 관리자로 병목 구분","why":"CPU·메모리·디스크 중 무엇이 원인인지에 따라 이후 점검 방향이 완전히 달라집니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ② '성능' 탭을 클릭하세요. ③ 왼쪽의 CPU, 메모리, 디스크 항목을 하나씩 클릭하며 각각의 사용률이 몇 %인지 확인하세요. ④ 평소 PC가 느려지는 작업을 하며 몇 분간 지켜보고, 어느 항목이 계속 90~100%에 가깝게 유지되는지 확인하세요 — 이것이 병목(느려지는 주된 원인)입니다."},{"title":"디스크 사용률 확인","why":"디스크가 상시 100%에 가깝다면 백그라운드 작업이나 저장장치 자체 지연이 원인일 가능성이 큽니다.","how":"① 작업 관리자의 '프로세스' 탭에서 '디스크' 열을 클릭해 사용량이 높은 순서로 정렬하세요. ② 상위 프로세스가 무엇인지 확인하세요(Windows 업데이트, 백신 검사, 클라우드 동기화 등이 흔한 원인입니다). ③ 원인으로 짐작되는 프로그램(원드라이브 등)을 일시 중지하거나 종료해 디스크 사용률이 내려가는지 확인하세요. ④ 이유 없이 계속 높게 유지된다면 디스크 자체의 노후화나 이상일 수 있으니, 제조사 진단 프로그램(CrystalDiskInfo 등)으로 건강 상태를 확인하세요."},{"title":"저장공간 여유 확인","why":"C드라이브 여유 공간이 부족하면 Windows가 임시 파일을 쓸 공간이 부족해 전반적으로 느려집니다.","how":"① Windows 로고 키를 누르고 '이 PC'를 입력해 C 드라이브의 여유 공간을 확인하세요. ② 여유 공간이 전체 용량의 10% 미만이라면 디스크 정리와 저장 공간 센스로 공간을 확보하세요(설정 → 저장소 설정에서 진행). ③ 공간을 확보한 뒤 재부팅해 체감 속도가 나아졌는지 확인하세요."},{"title":"온도·발열 확인","why":"부하가 없는데도 온도가 높게 유지되면 성능이 자동으로 제한(스로틀링)되어 느려질 수 있습니다.","how":"① 게임이나 무거운 프로그램을 실행하지 않은, 그냥 바탕화면만 보고 있는 상태에서 팬 소음이 심하거나 본체가 뜨겁게 느껴지는지 확인하세요. ② HWiNFO 같은 프로그램으로 이 유휴 상태의 CPU 온도를 확인하세요(50도를 넘으면 이상 신호입니다). ③ 온도가 높다면 먼지 청소나 서멀 재도포가 필요한 신호이므로, 케이스를 열어 팬과 방열판의 먼지를 캔에어로 청소하세요. ④ 발열로 인한 성능 제한(스로틀링)이 해소되면 전반적인 체감 속도도 함께 개선됩니다."}],"deeper":[{"heading":"부팅 지연과 사용 중 저하는 다른 문제","text":"부팅 시간만 길고 로그인 이후에는 문제가 없다면 시작 프로그램이 핵심 원인입니다. 반대로 로그인 이후에도 계속 느리다면 상시 실행 중인 프로세스나 하드웨어 자체의 병목을 봐야 합니다."},{"heading":"체감 저하와 실제 병목은 다를 수 있음","text":"\"예전보다 느려졌다\"는 체감은 실제로는 백그라운드 업데이트, 백신 검사, 클라우드 동기화처럼 일시적인 원인 때문인 경우도 많습니다. 며칠에 걸쳐 반복되는지, 특정 시점에만 나타나는지 구분하세요."}],"decision":[{"heading":"CPU가 상시 높게 유지될 때","text":"작업 관리자에서 어떤 프로세스가 CPU를 많이 쓰는지 확인하고, 불필요한 시작 프로그램과 백그라운드 앱을 정리하세요."},{"heading":"디스크가 상시 100%에 가까울 때","text":"디스크 사용률 100% 가이드에서 원인별 점검 순서를 확인하세요."},{"heading":"저장공간이 부족할 때","text":"C드라이브 용량 부족 가이드에서 정리 순서를 확인하세요."},{"heading":"온도가 높게 유지될 때","text":"쿨링 상태를 먼저 점검하고, 필요하면 과열 관련 가이드를 참고하세요."}],"examples":["인터넷 브라우저 탭을 몇 개만 열어도 전체적으로 느려짐","예전에는 문제없던 작업이 최근 몇 주 사이 계속 버벅임"],"mistakes":["원인을 구분하지 않고 곧바로 포맷·초기화부터 진행하는 것","디스크나 저장공간 문제인데 램부터 늘리는 것","일시적인 업데이트·백신 검사 중 저하를 영구적인 고장으로 오인하는 것"],"faq":[{"q":"포맷하면 확실히 빨라지나요?","a":"저장공간 부족이나 불필요한 프로그램 누적이 원인이라면 효과가 있지만, 저장장치 노후화나 하드웨어 자체의 한계가 원인이라면 포맷 후에도 다시 느려질 수 있습니다. 먼저 병목을 구분하는 것이 순서입니다."},{"q":"SSD로 바꾸면 해결되나요?","a":"아직 HDD를 쓰고 있다면 체감 개선이 크지만, 이미 SSD를 쓰는데도 느리다면 디스크가 원인이 아닐 가능성이 높아 다른 항목부터 확인해야 합니다."},{"q":"램을 늘리면 확실히 빨라지나요?","a":"작업 관리자에서 메모리 사용률이 상시 90% 이상이라면 효과가 있지만, CPU나 디스크가 병목이라면 램을 늘려도 체감 차이가 크지 않을 수 있습니다."}]},"microphone-not-detected":{"badge":"오디오","subtitle":"마이크가 인식되지 않거나 프로그램에서만 안 될 때","intro":["마이크 인식 문제는 하드웨어 고장보다 Windows의 마이크 권한 설정이나 기본 장치 지정 문제인 경우가 훨씬 많습니다. 먼저 Windows 자체의 소리 설정에서 마이크 입력이 잡히는지부터 확인하는 것이 순서입니다.","Windows 설정에서는 마이크가 잡히는데 특정 게임이나 디스코드, 줌 같은 프로그램에서만 안 된다면, 그 프로그램 내부의 마이크 장치 선택이 실제 사용 중인 장치와 다르게 지정된 경우가 대부분입니다.","Windows 설정에서도 전혀 반응이 없다면 개인정보 보호 설정에서 마이크 접근이 앱에 허용되어 있는지, 또는 여러 대의 마이크(웹캠 내장 마이크, 헤드셋 마이크 등)가 동시에 연결되어 있어 다른 장치가 기본으로 지정된 것은 아닌지 확인해야 합니다."],"warnings":["마이크 아이콘에 빨간 사선이 표시되거나 음소거로 고정되어 있다.","설정의 입력 장치 테스트에서는 반응하는데 특정 프로그램에서만 안 된다.","다른 컴퓨터에 연결하면 정상 작동한다."],"checks":[{"title":"마이크 접근 권한 확인","why":"Windows 개인정보 설정에서 앱의 마이크 접근이 꺼져 있으면 하드웨어가 멀쩡해도 인식되지 않습니다.","how":"① Windows 로고 키를 누르고 '마이크 개인정보 설정'을 입력해 실행하세요. ② '마이크 접근'이 켜져 있는지 확인하고, 꺼져 있다면 켜세요. ③ 그 아래 '앱이 마이크에 액세스하도록 허용' 스위치도 켜세요. ④ 화면을 아래로 스크롤해 사용하려는 프로그램(Zoom, Discord, 크롬 등)의 개별 스위치도 켜져 있는지 확인하세요."},{"title":"기본 입력 장치 확인","why":"여러 마이크 장치가 함께 연결되어 있으면 원하지 않는 장치가 기본으로 지정될 수 있습니다.","how":"① Windows 로고 키를 누르고 '소리 설정'을 입력해 실행하세요. ② '입력' 항목의 드롭다운 목록을 클릭하세요. ③ 여러 마이크 장치가 나열되어 있다면, 실제로 사용하려는 마이크(헤드셋, USB 마이크 등)를 선택하세요. ④ 선택 후 아래쪽 '마이크 테스트'에서 말할 때 막대가 움직이는지 확인하세요."},{"title":"시스템 레벨에서 입력 테스트","why":"프로그램 문제인지 하드웨어 문제인지 구분하는 가장 확실한 방법입니다.","how":"① Windows 로고 키를 누르고 '소리 설정'을 입력해 실행하세요. ② '입력' 항목 아래 '마이크 테스트' 막대를 보면서 마이크에 대고 말해보세요. ③ 막대가 소리에 반응해 움직이면 Windows는 마이크를 정상적으로 인식하고 있는 것이므로, 특정 프로그램(게임, 디스코드 등)에서만 안 된다면 그 프로그램의 마이크 설정 문제입니다. ④ 막대가 전혀 움직이지 않는다면 Windows 자체에서 마이크를 인식하지 못하는 것이므로, 위의 권한 확인·기본 장치 지정 항목을 다시 확인하거나 아래 드라이버 재설치를 진행하세요."},{"title":"프로그램별 마이크 장치 설정 확인","why":"Windows에서는 잡히는데 게임·디스코드에서만 안 된다면 그 프로그램의 마이크 장치 지정이 다른 경우가 많습니다.","how":"① 디스코드를 사용 중이라면, 왼쪽 아래 톱니바퀴(사용자 설정)를 클릭해 '음성 및 비디오'로 들어가세요. ② '입력 장치' 드롭다운에서 실제 사용 중인 마이크가 선택되어 있는지 확인하고, 다르다면 맞게 바꾸세요. ③ 게임의 경우 게임 안 설정 메뉴에서 '오디오' 또는 '사운드' 탭을 찾아 같은 방식으로 입력 장치를 확인하세요. ④ Windows의 소리 설정에서 확인한 마이크 이름과 프로그램 안의 설정이 같은 장치를 가리키는지 맞춰보세요."},{"title":"드라이버 재설치","why":"드라이버가 손상되면 마이크가 아예 목록에 나타나지 않을 수 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '오디오 입력 및 출력' 항목을 펼치세요. ③ 마이크 이름을 찾아(안 보인다면 마이크 자체가 인식되지 않는 상태입니다) 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택하세요. ④ PC를 재부팅해 Windows가 마이크를 다시 인식하는지 확인하세요. ⑤ 여전히 목록에 없다면 물리적 연결(케이블, USB 포트)을 다시 확인하세요."}],"deeper":[{"heading":"Windows에서는 되는데 특정 프로그램에서만 안 될 때","text":"이 경우는 하드웨어나 드라이버 문제가 아니라 프로그램 내부의 마이크 장치 지정 문제일 가능성이 매우 높습니다. 프로그램을 재설치하기보다 프로그램의 오디오 설정 메뉴에서 입력 장치를 다시 선택하세요."},{"heading":"여러 마이크 장치가 충돌하는 경우","text":"웹캠 내장 마이크, 헤드셋 마이크, USB 마이크가 동시에 연결되어 있으면 Windows나 프로그램이 의도하지 않은 장치를 기본으로 선택할 수 있습니다. 사용하지 않는 장치는 설정에서 사용 안 함으로 비활성화해 혼선을 줄이세요."}],"decision":[{"heading":"시스템 테스트에서도 반응이 없을 때","text":"권한·기본 장치 설정을 확인한 뒤에도 안 되면 드라이버를 재설치하고, 그래도 안 되면 다른 컴퓨터에 연결해 하드웨어 자체 고장인지 구분하세요."},{"heading":"특정 프로그램에서만 안 될 때","text":"시스템은 정상이므로 해당 프로그램의 마이크 장치 설정만 다시 지정하면 대부분 해결됩니다."}],"examples":["디스코드에서는 마이크가 안 되는데 Windows 녹음기에서는 정상 작동함","헤드셋을 새로 사서 꽂았는데 소리는 들리는데 마이크만 인식 안 됨"],"mistakes":["특정 프로그램에서만 안 되는데 드라이버부터 삭제하는 것","권한 설정 확인 없이 바로 새 마이크를 구매하는 것"],"faq":[{"q":"마이크 접근 권한은 어디서 확인하나요?","a":"설정 > 개인정보 및 보안 > 마이크에서 확인할 수 있습니다. '마이크 접근'이 꺼져 있으면 모든 앱에서 마이크를 사용할 수 없습니다."},{"q":"노트북 내장 마이크만 안 되고 외장 마이크는 되면요?","a":"내장 마이크 드라이버 문제일 가능성이 높습니다. 장치 관리자에서 내장 마이크를 제거한 뒤 재부팅해 재설치를 시도하세요."},{"q":"게임 중에만 마이크가 끊기면요?","a":"게임 내 오디오 설정에서 마이크 감도(노이즈 게이트)가 너무 높게 설정되어 있지 않은지 확인하세요. 조용히 말할 때 소리가 감지되지 않아 끊기는 것처럼 느껴질 수 있습니다."}]},"webcam-not-detected":{"badge":"주변장치","subtitle":"웹캠이 인식되지 않거나 화상 프로그램에서 화면이 안 나올 때","intro":["웹캠 인식 문제는 하드웨어 고장보다 Windows 카메라 권한, 다른 프로그램의 장치 점유, USB 연결 문제인 경우가 대부분입니다. Windows 기본 카메라 앱에서 먼저 웹캠이 보이는지 확인하는 것이 가장 빠른 구분법입니다.","카메라 앱에서는 정상적으로 보이는데 화상회의 프로그램에서만 안 된다면, 다른 프로그램이 이미 웹캠을 사용 중이거나 그 프로그램의 카메라 장치 설정이 다르게 지정된 경우가 많습니다. 웹캠은 대부분 한 번에 하나의 프로그램만 사용할 수 있습니다.","카메라 앱에서조차 전혀 반응이 없다면 개인정보 보호 설정에서 카메라 접근이 꺼져 있거나, USB 연결 자체의 문제, 또는 드라이버 문제일 가능성을 봐야 합니다."],"warnings":["장치 관리자에 카메라 자체가 보이지 않는다.","USB에 연결해도 인식음이 나지 않는다.","Windows 기본 카메라 앱에서도 화면이 나오지 않는다."],"checks":[{"title":"카메라 접근 권한 확인","why":"카메라 접근 권한이 꺼져 있으면 하드웨어가 정상이어도 어떤 프로그램에서도 화면이 나오지 않습니다.","how":"① Windows 로고 키를 누르고 '카메라 개인정보 설정'을 입력해 실행하세요. ② '카메라 접근'이 켜져 있는지 확인하고, 꺼져 있다면 켜세요. ③ '앱이 카메라에 액세스하도록 허용' 스위치도 켜세요. ④ 화면을 아래로 스크롤해 사용하려는 프로그램(Zoom, Teams, 크롬 등)의 개별 스위치도 켜져 있는지 확인하세요."},{"title":"Windows 기본 카메라 앱으로 선(先) 테스트","why":"프로그램 문제인지 하드웨어·드라이버 문제인지 가장 빠르게 구분할 수 있습니다.","how":"① Windows 로고 키를 누르고 '카메라'를 입력해 Windows 기본 카메라 앱을 실행하세요. ② 화면에 웹캠 영상이 나오는지 확인하세요. ③ 여기서 정상적으로 나온다면 웹캠 하드웨어와 드라이버는 정상이고, 특정 프로그램(줌 등)에서만 안 된다면 그 프로그램의 설정이나 카메라 점유 문제입니다. ④ 여기서도 화면이 안 나온다면 시스템 전체의 문제이므로 위의 권한 확인과 아래 항목들을 이어서 진행하세요."},{"title":"다른 프로그램의 웹캠 점유 확인","why":"웹캠은 보통 한 번에 하나의 프로그램만 사용할 수 있어, 백그라운드에 켜진 다른 화상 프로그램이 원인일 수 있습니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ② '프로세스' 탭에서 Zoom, Teams, Discord, OBS 등 웹캠을 사용할 수 있는 프로그램들이 백그라운드에 실행 중인지 확인하세요. ③ 사용하지 않는 프로그램을 선택해 '작업 끝내기'로 완전히 종료하세요. ④ 이제 사용하려는 프로그램만 실행한 상태에서 웹캠이 정상적으로 잡히는지 확인하세요."},{"title":"USB 연결 방식 확인","why":"허브를 거치면 전력 부족이나 대역폭 문제로 인식이 불안정할 수 있습니다.","how":"① 외장 웹캠을 USB 허브에 연결하고 있다면 허브를 거치지 않고 PC 본체나 노트북의 USB 포트에 직접 꽂으세요. ② 이 상태로 카메라 앱을 다시 실행해 화면이 나오는지 확인하세요. ③ 직접 연결에서 정상적으로 작동한다면 허브의 전력 공급이나 대역폭 문제이니, 앞으로는 직접 연결해 사용하거나 전원 공급이 있는(유전원) 허브로 교체하는 것을 고려하세요."},{"title":"드라이버 재설치","why":"장치 관리자에 웹캠이 느낌표와 함께 표시되거나 아예 보이지 않으면 드라이버 문제일 가능성이 큽니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행하세요. ② '카메라' 또는 '이미징 장치' 항목을 펼치세요(노트북 내장 웹캠은 이 이름으로 표시되는 경우가 많습니다). ③ 웹캠 이름을 찾아(느낌표가 있는지도 확인) 마우스 오른쪽 버튼으로 클릭해 '디바이스 제거'를 선택하세요. ④ 외장 웹캠이라면 케이블을 뽑았다가 다시 꽂고, 내장 웹캠이라면 PC를 재부팅하세요. ⑤ Windows가 자동으로 드라이버를 재설치하는지, 카메라 앱에서 다시 화면이 나오는지 확인하세요."}],"deeper":[{"heading":"카메라 앱은 되는데 화상회의 프로그램만 안 될 때","text":"웹캠 자체와 Windows 인식은 정상이라는 뜻이므로, 해당 프로그램의 카메라 장치 설정에서 다른 장치가 선택되어 있거나 다른 프로그램이 웹캠을 점유하고 있는지 확인하세요."},{"heading":"노트북 내장 카메라가 물리적으로 꺼져 있는 경우","text":"일부 노트북은 개인정보 보호를 위한 물리적 셔터나 Fn 단축키로 카메라를 꺼둘 수 있습니다. 키보드에 카메라 아이콘이 있는 기능키를 확인하세요."}],"decision":[{"heading":"카메라 앱에서도 화면이 안 나올 때","text":"권한·드라이버·USB 연결을 순서대로 확인하고, 그래도 안 되면 다른 컴퓨터에 연결해 하드웨어 고장 여부를 구분하세요."},{"heading":"카메라 앱은 되는데 특정 프로그램만 안 될 때","text":"그 프로그램의 카메라 설정과 다른 프로그램의 웹캠 점유 여부만 확인하면 대부분 해결됩니다."}],"examples":["화상수업 사이트에서만 웹캠 인식 안 되고 다른 사이트에서는 정상 작동","노트북 카메라 앱에서는 보이는데 줌에서는 카메라를 찾을 수 없다고 뜸"],"mistakes":["다른 프로그램의 웹캠 점유 확인 없이 바로 드라이버를 재설치하는 것","카메라 앱 테스트 없이 바로 웹캠을 교체 구매하는 것"],"faq":[{"q":"온라인 시험·화상수업에서만 웹캠이 안 잡히면요?","a":"브라우저의 카메라 권한을 별도로 확인해야 합니다. 브라우저 주소창 왼쪽의 자물쇠 아이콘을 눌러 카메라 권한이 허용되어 있는지 확인하세요."},{"q":"웹캠 LED는 켜지는데 화면이 안 나오면요?","a":"LED는 전원 공급만으로도 켜질 수 있어 정상 작동의 증거가 아닙니다. Windows 기본 카메라 앱에서 실제 화면이 나오는지 확인하세요."},{"q":"USB 허브에 꽂으면 계속 인식이 끊기면요?","a":"허브의 전력 공급이 부족한 경우가 많습니다. 전원이 별도로 공급되는 유전원 허브를 사용하거나 본체에 직접 연결하세요."}]},"keyboard-specific-keys-not-working":{"badge":"입력장치","subtitle":"키보드 전체는 정상인데 특정 키만 안 눌릴 때","intro":["키보드 전체가 먹통이 아니라 특정 키 한두 개만 안 눌린다면, 원인은 크게 두 갈래로 나뉩니다. 하나는 Windows의 필터 키 같은 접근성 설정, 다른 하나는 여러 키를 동시에 누를 때 일부가 무시되는 '고스팅' 현상입니다.","혼자 눌렀을 때도 특정 키만 반응이 없다면 소프트웨어 설정보다 물리적인 문제(이물질, 스위치 마모)일 가능성이 큽니다. 반대로 여러 키를 동시에 누를 때만 문제가 생긴다면 고스팅 현상으로, 게임에서 특정 키 조합(예: W+A+Q)이 눌리지 않는 형태로 흔히 나타납니다.","간헐적으로 눌렸다 안 눌렸다 한다면 키 내부 접점의 접촉 불량으로, 청소로 일시적으로 나아질 수 있지만 근본적으로는 키캡·스위치 교체나 키보드 자체 교체가 필요할 수 있습니다."],"warnings":["특정 키 한두 개만 혼자 눌러도 입력이 안 된다.","여러 키를 동시에 누르면 그중 일부가 인식되지 않는다.","필터 키·고정 키 같은 접근성 기능을 건드린 적이 없는데도 갑자기 시작됐다."],"checks":[{"title":"필터 키·고정 키 설정 확인","why":"Windows 접근성 기능이 켜져 있으면 짧게 누른 키 입력이 무시되거나 반복 입력으로 인식될 수 있습니다.","how":"① Windows 로고 키를 누르고 '접근성 키보드 설정'을 입력해 실행하세요. ② '필터 키' 항목의 스위치가 켜져 있다면 끄세요(이 기능은 짧게 누른 키나 반복 입력을 무시하도록 설계되어, 켜져 있으면 정상 입력도 무시될 수 있습니다). ③ 같은 화면에서 '고정 키' 스위치도 확인해 켜져 있다면 끄세요. ④ 설정을 끈 뒤 문제였던 키가 정상적으로 눌리는지 메모장에서 테스트하세요."},{"title":"단독 입력과 동시 입력 구분","why":"혼자 눌러도 안 되는지, 여러 키를 함께 누를 때만 안 되는지에 따라 원인이 완전히 다릅니다.","how":"① Windows 로고 키를 누르고 '메모장'을 입력해 실행하세요. ② 문제가 되는 키 하나만 눌러 글자가 입력되는지 확인하세요. ③ 이번엔 그 키를 다른 키(예: Shift, Ctrl 등)와 동시에 눌러보고 입력이 되는지 확인하세요. ④ 혼자 눌렀을 때는 안 되고 조합해서 누를 때만 되거나 그 반대라면, 키보드의 '고스팅'(동시 입력 인식 한계) 문제일 수 있습니다 — 특히 게임 중 여러 키를 동시에 눌러야 하는 상황에서 흔합니다."},{"title":"물리적 청소","why":"키 아래에 먼지나 이물질이 끼면 눌림이 불완전해질 수 있습니다.","how":"① 키보드 전원을 끄거나 PC에서 케이블을 뽑으세요(무선이면 전원을 끄세요). ② 데스크톱용 분리형 키보드라면 뒤집어서 가볍게 흔들어 먼지나 이물질을 털어내세요. ③ 캔에어(압축공기 스프레이)로 키 사이사이를 불어 남은 이물질을 제거하세요. ④ 노트북 키보드는 키캡이 얇고 분리 시 부품이 튕겨 나가거나 파손되기 쉬우므로, 무리해서 키캡을 분리하지 말고 캔에어로 키 틈새만 청소하세요."},{"title":"다른 프로그램·다른 컴퓨터에서 재현 확인","why":"특정 게임에서만 문제라면 게임 설정이나 고스팅 문제이고, 모든 곳에서 재현되면 하드웨어 문제입니다.","how":"① 웹 브라우저에서 '키보드 테스터' 또는 'keyboard tester online'을 검색해 나오는 사이트에 접속하세요. ② 화면에 표시되는 가상 키보드에서 문제의 키를 눌러 초록색으로 반응하는지 확인하세요(특정 게임에서만 문제라면 그 게임의 키 설정을 별도로 확인해야 합니다). ③ 가능하다면 같은 키보드를 다른 PC에 연결해 같은 증상이 재현되는지 비교하세요. ④ 다른 PC에서도 같은 키가 안 눌린다면 키보드 자체의 고장(스위치 마모 등)일 가능성이 크고, 다른 PC에서는 정상이라면 원래 PC의 드라이버나 설정 문제입니다."}],"deeper":[{"heading":"고스팅(Ghosting)이란?","text":"저가형 키보드는 회로 구조상 특정 키 조합을 동시에 누르면 일부 입력이 인식되지 않는 경우가 있습니다. 이를 고스팅이라 하며, 게임처럼 여러 키를 동시에 눌러야 하는 상황에서 자주 발견됩니다. N키 롤오버(NKRO)를 지원하는 키보드는 이 문제가 없습니다."},{"heading":"간헐적으로 눌렸다 안 눌렸다 하는 경우","text":"완전히 죽은 키가 아니라 눌릴 때도 있고 안 눌릴 때도 있다면, 스위치나 러버돔의 접점이 마모되어 접촉이 불안정해진 상태일 가능성이 높습니다. 청소로 일시 개선될 수 있지만 재발한다면 물리적 교체가 필요합니다."}],"decision":[{"heading":"동시 입력에서만 문제가 생길 때","text":"고스팅 현상일 가능성이 높으므로, 게임 내 키 배치를 서로 간섭하지 않는 조합으로 바꾸거나 NKRO를 지원하는 키보드로 교체를 고려하세요."},{"heading":"혼자 눌러도 특정 키만 안 될 때","text":"청소로도 해결되지 않으면 스위치·러버돔 자체의 물리적 고장이므로 키보드 수리나 교체가 필요합니다."}],"examples":["게임에서 W와 Q를 동시에 누르면 Q가 눌리지 않음","스페이스바가 어떤 날은 되고 어떤 날은 반응이 없음"],"mistakes":["혼자 눌러도 안 되는 물리적 문제인데 접근성 설정만 계속 확인하는 것","청소 없이 바로 키보드를 새로 사는 것"],"faq":[{"q":"노트북 키보드도 고스팅이 있나요?","a":"네, 저가형 노트북 키보드에서도 발생할 수 있습니다. 다만 노트북은 키보드 전체 교체가 데스크탑 키보드보다 번거로우므로, 문제 조합을 피하는 것이 우선입니다."},{"q":"특정 키만 교체할 수 있나요?","a":"기계식 키보드는 스위치 단위로 교체가 가능한 경우가 많지만, 멤브레인·노트북 키보드는 부분 교체가 어려워 전체 교체나 전문 수리가 필요할 수 있습니다."},{"q":"USB 포트를 바꾸면 나아지나요?","a":"일부 구형 키보드는 USB 2.0에서 더 안정적으로 동작하는 경우가 있어 시도해볼 만하지만, 근본적인 고스팅·접점 마모 문제는 포트를 바꿔도 해결되지 않습니다."}]},"hdd-clicking-noise":{"badge":"저장장치","subtitle":"하드디스크에서 평소와 다른 소리가 날 때","intro":["하드디스크(HDD)는 내부에서 플래터가 회전하고 헤드가 움직이며 데이터를 읽고 쓰는 기계 장치라 어느 정도의 작동음은 정상입니다. 문제는 '평소와 다른' 소리, 특히 규칙적으로 반복되는 딸깍거리는 소리입니다.","일정한 간격으로 반복되는 '딸깍딸깍' 소리는 헤드가 정상 위치를 찾지 못해 반복 시도하는 소리로, 흔히 'Click of Death'라 불리는 하드디스크 고장의 대표적인 초기 신호입니다. 이 소리가 들리면 데이터 손실 위험이 매우 높으므로 진단보다 백업을 먼저 해야 합니다.","반대로 일정한 '웅~' 하는 회전음이나 절전 모드에서 깨어날 때 나는 스핀업 소리는 정상적인 작동음이므로, 소리의 규칙성과 반복 패턴을 구분하는 것이 가장 중요합니다."],"warnings":["딸깍거리는 소리가 일정한 간격으로 계속 반복된다.","파일 탐색기에서 폴더가 열리지 않거나 응답 없음이 자주 발생한다.","PC를 켤 때 인식이 되었다 안 되었다 하며 드라이브 문자가 사라진다."],"checks":[{"title":"즉시 백업 여부 판단","why":"딸깍거리는 소리가 반복되면 하드디스크가 언제 완전히 인식 불가 상태가 될지 알 수 없습니다.","how":"① 지금 하드디스크에서 규칙적인 '딸깍딸깍' 소리가 들린다면, 다른 작업보다 먼저 중요한 사진·문서·파일이 무엇인지 목록을 정리하세요. ② 외장하드나 USB, 또는 구글 드라이브·원드라이브 같은 클라우드 저장 공간을 준비하세요. ③ 가장 중요한 파일부터 순서대로 복사해 백업하세요(전체를 한 번에 복사하려 하지 말고 중요도 순으로 진행하는 것이 안전합니다). ④ 백업이 끝나기 전까지는 디스크 조각 모음, 전체 검사 같은 무거운 작업을 하지 마세요 — 디스크에 더 부담을 줄 수 있습니다."},{"title":"소리 종류 구분","why":"정상 작동음과 고장 신호를 구분해야 불필요한 걱정이나 반대로 늦은 대응을 피할 수 있습니다.","how":"① 하드디스크가 작동할 때 나는 소리에 귀를 기울여보세요. ② 일정하고 조용한 '웅~' 하는 회전음이나 가끔 나는 '사각사각' 헤드 이동음은 정상적인 작동 소음입니다. ③ 일정한 간격으로 반복되는 '딸깍딸깍' 소리, 또는 이전에 없던 '드르륵' 긁는 소리가 새로 들리기 시작했다면 고장 신호일 가능성이 큽니다. ④ 고장 신호로 판단되면 위의 즉시 백업 항목을 최우선으로 진행하세요."},{"title":"SMART 상태 확인","why":"하드디스크 자체 진단 정보로 배드섹터, 재할당 섹터 수 등 건강 상태를 미리 확인할 수 있습니다.","how":"① 웹 브라우저에서 'CrystalDiskInfo' 공식 홈페이지에 접속해 무료 프로그램을 내려받아 설치하세요. ② 프로그램을 실행하면 연결된 디스크들의 상태가 파란색('정상'), 노란색('주의'), 빨간색('경고')으로 표시됩니다. ③ 소리가 나는 하드디스크의 상태 색상을 확인하세요. ④ 노란색이나 빨간색으로 표시된다면 배드섹터나 재할당 섹터 수 항목의 수치도 함께 확인해, 위의 백업 항목을 서둘러 진행하세요."},{"title":"물리적 진동·나사 확인","why":"고정이 풀리면 케이스와 공진해 실제 고장이 아닌데도 소음이 커질 수 있습니다.","how":"① PC 전원을 끄고 전원 케이블을 뽑으세요. ② 케이스 옆판을 열고 하드디스크를 고정하는 나사가 헐겁지 않은지 손으로 살짝 흔들어 확인하세요. ③ 헐겁다면 드라이버로 나사를 다시 조이세요. ④ 하드디스크 주변의 케이블(SATA, 전원 케이블)이 팬이나 다른 부품에 닿아 있지 않은지 확인하고, 닿아 있다면 케이블 타이 등으로 정리해 떨어뜨려 놓으세요. ⑤ 전원을 켜서 소음이 줄었는지 확인하세요(단, 이 작업 전에 위의 백업은 반드시 먼저 진행하세요)."}],"deeper":[{"heading":"Click of Death(딸깍거림)가 위험한 이유","text":"헤드가 플래터 위 정상 위치를 찾지 못해 반복적으로 재시도하는 소리로, 헤드나 플래터 자체의 손상을 의미하는 경우가 많습니다. 이 상태에서 계속 전원을 켜고 끄면 오히려 손상이 진행되어 복구 가능성이 낮아지므로, 데이터가 중요하다면 추가 사용을 최소화하고 전문 복구 업체 상담을 고려하세요."},{"heading":"SSD로 교체하면 이런 소음 걱정이 없나요?","text":"SSD는 기계적으로 움직이는 부품이 없어 이런 소음 자체가 발생하지 않습니다. 이미 오래된 HDD를 계속 쓰고 있다면 백업 습관과 함께 SSD 교체도 장기적으로 고려할 만합니다."}],"decision":[{"heading":"규칙적인 딸깍 소리일 때","text":"지금 바로 백업부터 하고, SMART 상태가 나쁘면 추가 사용을 최소화하며 데이터 복구나 하드디스크 교체를 준비하세요."},{"heading":"일정한 웅 소리·스핀업 소리일 때","text":"대부분 정상 작동음이므로 SMART 상태만 주기적으로 확인하면 됩니다."},{"heading":"진동·공진이 원인일 때","text":"고정 나사를 조이고 케이블 배치를 정리하면 소음이 줄어듭니다."}],"examples":["컴퓨터를 켤 때마다 딸깍딸깍 소리가 몇 초간 반복되다가 부팅됨","평소보다 파일 복사 속도가 느려지면서 드르륵거리는 소리가 커짐"],"mistakes":["딸깍거리는 소리를 듣고도 백업 없이 계속 사용하는 것","고장 초기 신호인데 재부팅만 반복하며 상태를 악화시키는 것","중요한 데이터가 있는데 스스로 하드디스크를 분해해 보는 것"],"faq":[{"q":"딸깍 소리가 나는데 아직 파일은 다 열려요. 괜찮은 건가요?","a":"지금 열린다고 안심할 수 없습니다. 딸깍거리는 소리는 언제 완전히 인식 불가 상태가 될지 예측하기 어려운 신호이므로, 지금 열리는 지금 바로 백업하는 것이 가장 안전합니다."},{"q":"SMART 상태가 정상인데도 소리가 나면요?","a":"SMART는 참고 지표일 뿐 모든 고장을 미리 알려주지 못합니다. 소리가 명백히 딸깍거리는 패턴이라면 SMART가 정상이어도 백업을 우선하세요."},{"q":"이미 딸깍거리는 하드에서 데이터를 옮기려면 어떻게 하나요?","a":"전원을 켜고 끄는 횟수를 최소화하고, 한 번에 중요한 파일부터 순서대로 복사하세요. 소리가 심하거나 데이터가 매우 중요하다면 직접 시도보다 전문 복구 업체에 맡기는 것이 안전합니다."}]},"monitor-color-abnormal":{"badge":"디스플레이","subtitle":"화면이 깜빡이진 않지만 색상만 이상하게 보일 때","intro":["화면 깜빡임이나 블랙아웃 없이 색상만 이상하다면, 가장 먼저 확인할 것은 Windows의 야간 모드나 색 온도 설정입니다. 의외로 실수로 켜둔 야간 모드 때문에 화면 전체가 누렇게 보이는 경우가 매우 흔합니다.","설정을 확인해도 그대로라면 케이블 연결 문제일 가능성이 높습니다. HDMI·DP 케이블이 헐겁거나 손상되면 색 정보의 일부 채널만 제대로 전달되지 않아 특정 색이 빠지거나 화면에 얼룩이 생긴 것처럼 보일 수 있습니다.","케이블을 바꿔도 같은 증상이 특정 위치에 고정되어 나타난다면(예: 화면 모서리만 변색) 모니터 패널이나 백라이트 자체의 물리적 손상일 가능성이 크므로, 다른 PC에 같은 모니터를 연결해 교차 테스트하는 것이 원인을 가장 확실히 구분하는 방법입니다."],"warnings":["화면 전체가 누렇거나 칙칙하게 보인다.","모니터 모서리나 특정 영역에만 색이 번지거나 얼룩이 보인다.","케이블을 만지거나 각도를 바꾸면 색이 바뀐다."],"checks":[{"title":"야간 모드·색 온도 설정 확인","why":"Windows의 야간 모드는 눈 보호를 위해 화면을 의도적으로 따뜻한 색(누런 톤)으로 바꾸는 기능으로, 켜져 있으면 고장처럼 보일 수 있습니다.","how":"① Windows 로고 키를 누르고 '야간 모드'를 입력해 설정 화면을 여세요. ② '지금 켜기' 스위치가 켜져 있다면 꺼보세요. ③ 화면 오른쪽 아래 알림 센터(시계 옆)를 클릭했을 때도 '야간 모드' 아이콘이 켜져 있지 않은지 확인하세요. ④ 색상이 정상(누런 톤이 사라짐)으로 돌아오는지 확인하세요."},{"title":"케이블 재연결·교체","why":"HDMI·DP 케이블이 헐겁거나 손상되면 색 정보 일부가 누락되어 특정 색만 이상하게 보일 수 있습니다.","how":"① PC와 모니터 양쪽의 케이블을 완전히 뽑았다가 딸깍 소리가 나도록 다시 꽂으세요. ② 여분의 HDMI 또는 DP 케이블이 있다면 교체해 색상이 정상으로 돌아오는지 확인하세요. ③ 그래픽카드의 다른 포트로도 옮겨 연결해 비교하세요."},{"title":"다른 PC로 교차 테스트","why":"모니터 자체 문제인지 PC·그래픽카드 출력 문제인지 가장 확실하게 구분하는 방법입니다.","how":"① 같은 모니터를 노트북이나 다른 PC에 연결하세요. ② 다른 기기에서도 같은 색상 이상이 나타나는지 확인하세요. ③ 다른 기기에서도 나타난다면 모니터 자체의 패널·보드 문제이고, 다른 기기에서는 정상이라면 원래 PC의 그래픽카드나 설정 쪽 문제입니다."},{"title":"그래픽 드라이버 색상 설정 확인","why":"드라이버 제어판에서 채도·색 관리 설정이 잘못 적용되면 전체 색감이 왜곡될 수 있습니다.","how":"① 바탕화면을 마우스 오른쪽 버튼으로 클릭해 'NVIDIA 제어판'(또는 'AMD Software')을 여세요. ② NVIDIA라면 '데스크톱 색상 설정 조정'에서 채도·명암·감마 값이 기본값(50, 중간)인지 확인하세요. ③ '디지털 색상 형식' 항목이 'RGB'로, '동적 범위'가 '전체'로 되어 있는지 확인하세요(일부 설정에서 '제한'으로 되어 있으면 색이 탁하게 보입니다). ④ 값을 기본값으로 되돌리고 저장한 뒤 색상이 정상으로 돌아오는지 확인하세요."}],"deeper":[{"heading":"특정 영역에만 고정된 변색은 패널 손상 신호","text":"화면 전체가 아니라 모서리나 특정 부분에만 변색·얼룩이 고정되어 나타나고 각도나 설정을 바꿔도 사라지지 않는다면, 모니터 패널이나 백라이트의 물리적 손상일 가능성이 높습니다. 이 경우 PC 쪽 조치로는 해결되지 않습니다."},{"heading":"케이블 종류에 따라 증상이 다를 수 있음","text":"HDMI는 케이블 손상 시 특정 색 채널이 아예 빠지며 눈에 띄는 얼룩·줄무늬로 나타나는 경우가 많고, DP는 연결이 불안정하면 화면이 순간적으로 꺼졌다 켜지는 형태로 나타나는 경우가 더 흔합니다."}],"decision":[{"heading":"설정 확인으로 해결될 때","text":"야간 모드나 드라이버 색상 설정이 원인이었다면 별도 조치 없이 설정만 되돌리면 됩니다."},{"heading":"케이블 교체로 해결될 때","text":"케이블 자체의 노후화나 손상이 원인이므로 케이블을 교체해 사용하세요."},{"heading":"다른 PC에서도 같은 증상이 나타날 때","text":"모니터 자체의 패널·백라이트 고장이므로 서비스센터 점검이나 모니터 교체를 고려하세요."}],"examples":["저녁에 야간 모드가 자동으로 켜지면서 화면이 누렇게 변한 것을 고장으로 오인함","HDMI 케이블 각도를 바꿀 때마다 화면 오른쪽에 붉은 줄무늬가 나타났다 사라짐"],"mistakes":["야간 모드 설정 확인 없이 바로 모니터 A/S를 접수하는 것","케이블 교체 테스트 없이 바로 그래픽카드를 의심하는 것"],"faq":[{"q":"화면이 갑자기 누렇게 보이는데 고장인가요?","a":"가장 먼저 Windows 야간 모드(나이트 라이트)가 켜져 있는지 확인하세요. 저녁 시간대에 자동으로 켜지도록 설정된 경우가 많아 고장으로 오인하기 쉽습니다."},{"q":"케이블을 바꿔도 특정 부분만 계속 색이 이상하면요?","a":"모니터 패널이나 백라이트 자체의 손상일 가능성이 높습니다. 다른 PC에 연결해도 같은 위치에서 증상이 반복되면 모니터 자체 문제로 보고 서비스센터 점검을 받으세요."},{"q":"그래픽카드 드라이버를 재설치하면 해결될까요?","a":"드라이버의 색상 설정이 잘못 적용된 경우라면 도움이 될 수 있지만, 케이블이나 모니터 패널 자체의 문제라면 드라이버 재설치로는 해결되지 않습니다. 케이블 교체와 교차 테스트를 먼저 해보세요."}]},"windows-search-not-working":{"badge":"시스템","subtitle":"검색창에 입력해도 결과가 안 나올 때","intro":["윈도우 검색이 안 될 때는 먼저 '전혀 반응이 없는 것'과 '검색은 되는데 원하는 결과만 안 나오는 것'을 구분해야 합니다. 전자는 검색 서비스 자체의 문제, 후자는 인덱싱(색인) 범위나 진행 상태의 문제인 경우가 많습니다.","가장 흔한 원인은 검색 인덱싱이 아직 완료되지 않았거나 중단된 경우입니다. 파일을 대량으로 옮기거나 새 드라이브를 추가한 직후라면 인덱스가 다시 만들어지는 중이라 일시적으로 검색이 부정확할 수 있습니다.","설정을 확인해도 계속 안 된다면 Windows Search 서비스 자체가 멈춰 있거나 시스템 파일 손상이 원인일 수 있어, 서비스 재시작과 인덱스 재구성을 순서대로 시도해야 합니다."],"warnings":["검색창에 아무것도 입력해도 결과가 전혀 뜨지 않는다.","분명히 설치된 앱인데 이름을 쳐도 검색되지 않는다.","파일 탐색기에서 특정 폴더만 검색이 안 된다."],"checks":[{"title":"반응 없음과 일부 미검색 구분","why":"완전히 죽은 것과 인덱싱 범위 문제는 해결 방법이 다릅니다.","how":"① 작업표시줄의 검색창(돋보기 아이콘)을 클릭하고 'notepad'처럼 확실히 있는 프로그램 이름을 입력해보세요. ② 검색창 자체가 클릭해도 안 열리거나 입력해도 아무 반응이 없다면 검색 기능 자체가 멈춘 것입니다 — Windows Search 서비스 확인 항목으로 넘어가세요. ③ 검색창은 열리고 타이핑도 되는데 분명히 있는 파일이나 프로그램이 검색 결과에 안 나온다면, 인덱싱(색인) 범위나 진행 상태의 문제입니다 — 색인 옵션 확인 항목으로 넘어가세요."},{"title":"색인 옵션 확인","why":"검색 대상에서 제외된 폴더나 진행 중인 인덱싱 상태를 확인할 수 있습니다.","how":"① Windows 로고 키를 누르고 '색인 옵션'을 입력해 실행하세요. ② 화면 하단에 '인덱싱 완료' 또는 '항목 인덱싱 중...'이라는 문구가 표시됩니다 — 인덱싱 중이라면 완료될 때까지 기다려보세요(파일이 많으면 시간이 걸립니다). ③ '수정' 버튼을 클릭해 찾고 싶은 파일이 있는 폴더(문서, 바탕화면, 다운로드 등)에 체크가 되어 있는지 확인하세요. ④ 체크되어 있지 않다면 체크한 뒤 '확인'을 눌러 저장하고, 해당 폴더가 다시 인덱싱되기를 기다리세요."},{"title":"Windows Search 서비스 확인","why":"이 서비스가 중지되어 있으면 검색 기능 자체가 동작하지 않습니다.","how":"① Windows 로고 키를 누르고 'services.msc'를 입력해 실행하세요. ② 목록에서 'Windows Search'를 찾아 더블클릭하세요. ③ '서비스 상태'가 '중지됨'이면 '시작' 버튼을 클릭하세요. ④ '시작 유형'이 '자동' 또는 '자동(지연 시작)'으로 되어 있는지 확인하고 '확인'을 눌러 저장하세요. ⑤ PC를 재시작한 뒤 검색 기능이 정상적으로 동작하는지 확인하세요."},{"title":"인덱스 재구성","why":"인덱스 자체가 손상되면 앞의 방법으로도 해결되지 않을 수 있습니다.","how":"① Windows 로고 키를 누르고 '색인 옵션'을 입력해 실행하세요. ② '고급' 버튼을 클릭하세요(관리자 권한 확인 창이 뜨면 '예'를 클릭). ③ '문제 해결' 항목 아래 '다시 빌드' 버튼을 클릭하세요. ④ 확인 창이 뜨면 '확인'을 눌러 인덱스 재구성을 시작하세요. ⑤ 파일과 폴더가 많을수록 재구성에 수십 분에서 몇 시간까지 걸릴 수 있으니, PC를 계속 켜둔 채로 기다리세요. ⑥ 완료 후 검색 기능이 정상적으로 동작하는지 확인하세요."}],"deeper":[{"heading":"인덱싱 중에는 검색이 불완전할 수 있음","text":"대용량 파일 이동, 새 드라이브 추가, Windows 업데이트 직후에는 인덱스가 다시 만들어지는 중이라 일시적으로 검색 결과가 누락될 수 있습니다. 색인 옵션에서 진행 상태를 확인하고 완료될 때까지 기다려보세요."},{"heading":"특정 폴더만 검색이 안 되는 경우","text":"색인 옵션의 대상 폴더 목록에 해당 폴더가 포함되어 있지 않으면 아무리 파일이 있어도 검색되지 않습니다. 폴더를 목록에 추가해야 합니다."}],"decision":[{"heading":"완전히 반응이 없을 때","text":"Windows Search 서비스 실행 상태부터 확인하고, 꺼져 있으면 시작한 뒤 재부팅하세요."},{"heading":"일부 항목만 안 나올 때","text":"색인 옵션에서 대상 폴더와 인덱싱 진행 상태를 확인하세요."},{"heading":"위 방법으로도 안 될 때","text":"인덱스를 다시 빌드하거나, 그래도 안 되면 시스템 파일 검사(SFC/DISM)를 진행하세요."}],"examples":["시작 메뉴에서 설치된 프로그램 이름을 쳐도 검색 결과에 안 나옴","파일 탐색기에서 특정 폴더 안 파일만 검색이 안 됨"],"mistakes":["인덱싱 진행 상태 확인 없이 바로 초기화나 재설치를 진행하는 것","특정 폴더가 색인 대상에서 빠진 것을 모르고 검색 기능 자체가 고장났다고 판단하는 것"],"faq":[{"q":"인덱스를 다시 만들면 파일이 삭제되나요?","a":"아닙니다. 인덱스는 검색을 빠르게 하기 위한 목록일 뿐이며, 다시 만들어도 실제 파일에는 영향이 없습니다."},{"q":"외장하드나 USB의 파일도 검색되게 하려면요?","a":"기본적으로 이동식 드라이브는 색인 대상에서 제외되는 경우가 많습니다. 색인 옵션에서 해당 드라이브를 대상 폴더로 직접 추가해야 합니다."},{"q":"재부팅하면 검색이 다시 되나요?","a":"일시적으로 서비스가 멈춘 경우라면 재부팅으로 해결되기도 합니다. 하지만 반복된다면 서비스 상태와 인덱스 손상 여부를 확인하는 것이 근본적입니다."}]},"login-screen-freeze":{"badge":"부팅·로그인","subtitle":"로그인 화면에서 넘어가지 않거나 로그인 후 멈춰 있을 때","intro":["로그인 화면에서 멈추는 증상은 크게 두 시점으로 나뉩니다. 암호를 입력하기 전 화면 자체가 멈춘 경우와, 암호를 입력하고 로그인을 시도한 이후 넘어가지 않는 경우입니다. 후자가 훨씬 흔하며, 대부분 업데이트 설치나 프로필 로드 지연이 원인입니다.","화면의 시계가 계속 움직이고 마우스 커서도 반응한다면 시스템 자체가 멈춘 것이 아니라 특정 작업(업데이트 설치, 프로필 로드)이 오래 걸리고 있는 것입니다. 이 경우 무작정 강제 종료하기보다 디스크 사용량을 먼저 확인하는 것이 안전합니다.","반대로 마우스도 전혀 반응하지 않고 Ctrl+Alt+Delete에도 응답이 없다면 시스템 자체가 멈춘 상태이므로, 충분히 기다려도 변화가 없을 때 강제 종료 후 안전 모드로 재현 여부를 확인해야 합니다."],"warnings":["화면 시간은 계속 가는데 로그인 화면이 넘어가지 않는다.","암호를 입력하고 엔터를 눌러도 그대로 멈춰 있다.","마우스 커서는 움직이는데 클릭에 반응이 없다."],"checks":[{"title":"업데이트 설치 진행 여부 확인","why":"Windows 업데이트가 백그라운드에서 설치되는 중이면 로그인 과정이 평소보다 훨씬 오래 걸릴 수 있습니다.","how":"① PC 본체나 노트북에 있는 디스크 액세스 표시등(LED)이 계속 깜빡이는지 확인하세요(깜빡이면 뭔가 작업이 진행 중이라는 뜻입니다). ② 화면에 '업데이트 구성 중입니다' 같은 문구가 있다면 절대 강제 종료하지 말고 최소 10~20분은 기다리세요(업데이트 설치 도중 강제 종료하면 시스템이 손상될 수 있습니다). ③ 문구도 없고 LED도 반응이 없는 상태로 20분 이상 멈춰 있다면 업데이트 설치는 아니라고 보고 아래 항목을 진행하세요."},{"title":"Ctrl+Alt+Delete 반응 확인","why":"이 조합키에 반응이 있으면 시스템 자체는 살아있고 특정 프로세스만 멈춘 것입니다.","how":"① 화면이 멈춘 상태에서 Ctrl+Alt+Delete를 눌러보세요. ② 잠금·로그아웃 등의 옵션이 있는 화면이 뜨면 시스템은 살아있는 것이니, 옵션 화면에서 '작업 관리자'를 클릭하세요. ③ 작업 관리자에서 'Windows 탐색기(explorer.exe)'를 찾아 마우스 오른쪽 버튼으로 클릭해 '다시 시작'을 선택해보세요. ④ 이 조합키에도 전혀 반응이 없다면 전원 버튼을 4초 이상 길게 눌러 강제 종료한 뒤 다시 켜보세요."},{"title":"강제 종료 후 안전 모드로 재현 확인","why":"안전 모드는 최소한의 드라이버·프로그램만 불러오므로, 여기서 정상 로그인되면 원인이 특정 프로그램이나 드라이버에 있다는 뜻입니다.","how":"① 전원 버튼을 4초 이상 눌러 PC를 강제로 완전히 종료하세요. ② 다시 전원을 켜고, Windows 로고가 뜨는 순간 전원 버튼을 다시 3~4초 눌러 강제 종료하는 것을 2~3번 반복하면 '자동 복구' 화면으로 진입합니다. ③ '고급 옵션' → '문제 해결' → '고급 옵션' → '시작 설정' → '다시 시작'을 차례로 선택하세요. ④ 목록에서 '4' 또는 'F4' 키를 눌러 안전 모드로 부팅하세요. ⑤ 안전 모드에서 로그인이 정상적으로 되면 원인은 특정 프로그램이나 드라이버이고, 안전 모드에서도 멈춘다면 더 근본적인 시스템 문제를 의심해야 합니다."},{"title":"시작 프로그램·최근 설치 항목 점검","why":"안전 모드에서는 정상인데 일반 부팅에서만 멈춘다면 시작 프로그램 중 하나가 원인일 가능성이 큽니다.","how":"① 안전 모드에서 정상적으로 로그인됐다면, 그 상태에서 Ctrl+Shift+Esc로 작업 관리자를 열고 '시작프로그램' 탭을 확인하세요. ② '시작 시 영향'이 '높음'인 항목들을 하나씩 '사용 안 함'으로 바꾸세요. ③ 최근 며칠 사이에 새로 설치한 프로그램이 있다면 '앱 및 기능'에서 제거하세요. ④ 정상 모드로 재부팅해 로그인이 정상적으로 되는지 확인하고, 여전히 멈춘다면 항목을 하나씩 다시 활성화하며 원인을 좁혀가세요."}],"deeper":[{"heading":"암호 입력 전 vs 입력 후, 멈추는 시점이 다른 이유","text":"암호 입력 화면 자체가 안 뜨는 경우는 그래픽 드라이버나 디스플레이 쪽 문제일 가능성이 크고, 암호를 입력한 뒤 데스크톱으로 넘어가지 않는 경우는 사용자 프로필 로드나 시작 프로그램 쪽 문제일 가능성이 큽니다."},{"heading":"디스크 문제로 인한 지연도 의심할 것","text":"저장장치 접촉 불량이나 초기 고장 징후가 있으면 로그인 과정에서 필요한 파일을 읽는 데 시간이 오래 걸려 멈춘 것처럼 보일 수 있습니다. 평소에도 파일 로딩이 느렸다면 저장장치 상태도 함께 확인하세요."}],"decision":[{"heading":"기다리면 결국 넘어갈 때","text":"업데이트 설치나 프로필 로드 지연이 원인이었을 가능성이 높습니다. 다음 로그인부터는 시간이 단축되는지 확인하세요."},{"heading":"안전 모드에서는 정상일 때","text":"시작 프로그램이나 최근 설치한 소프트웨어가 원인이므로 하나씩 비활성화하며 범위를 좁히세요."},{"heading":"안전 모드에서도 반복될 때","text":"시스템 파일 손상이나 저장장치 문제일 가능성이 높으므로 복구 환경에서 점검을 진행하세요."}],"examples":["업데이트 설치 후 재부팅했더니 로그인 화면에서 20분 넘게 멈춰 있음","암호 입력 후 '환영합니다' 화면에서 그대로 멈춤"],"mistakes":["업데이트 설치 중일 가능성을 확인하지 않고 바로 강제 종료하는 것","안전 모드 테스트 없이 바로 시스템을 초기화하는 것"],"faq":[{"q":"강제 종료해도 괜찮나요?","a":"업데이트 설치 중이라면 강제 종료 시 시스템 파일이 손상될 위험이 있으므로, 최소 10분 이상은 기다려보고 그래도 변화가 없을 때만 강제 종료하세요."},{"q":"매번 로그인할 때마다 오래 걸리면요?","a":"시작 프로그램이 너무 많거나 사용자 프로필이 비대해진 경우입니다. 작업 관리자의 시작프로그램 탭에서 불필요한 항목을 사용 안 함으로 바꿔보세요."},{"q":"안전 모드에는 어떻게 들어가나요?","a":"로그인 화면에서 Shift 키를 누른 채 전원 버튼의 다시 시작을 누르거나, 강제 종료를 3번 반복하면 자동으로 복구 환경(고급 옵션)이 뜨고 여기서 안전 모드를 선택할 수 있습니다."}]},"laptop-battery-drains-fast":{"badge":"배터리","subtitle":"충전은 되는데 사용 시간이 눈에 띄게 짧아졌을 때","intro":["배터리가 빨리 닳는 증상은 충전이 안 되는 문제와는 원인이 다릅니다. 충전 자체는 정상인데 완충 후 사용 시간만 짧아졌다면, 배터리 노후화, 백그라운드 프로그램, 화면 설정 중 어디가 원인인지 순서대로 좁혀야 합니다.","가장 먼저 확인할 것은 실제로 배터리의 최대 용량이 줄었는지입니다. 리튬이온 배터리는 충전 주기가 쌓일수록 최대 용량이 자연스럽게 줄어들며, 이는 고장이 아니라 소모품의 정상적인 노후화입니다. powercfg /batteryreport 명령으로 설계 용량 대비 현재 최대 용량을 직접 확인할 수 있습니다.","배터리 상태가 정상인데도 사용 시간이 짧다면 백그라운드 프로그램이나 화면 설정, 게이밍 노트북의 경우 그래픽카드 전환 설정을 의심해야 합니다."],"warnings":["완충해도 사용 시간이 예전보다 눈에 띄게 짧아졌다.","사용하지 않고 덮어놨는데도 배터리가 많이 줄어 있다.","특정 작업을 하지 않아도 배터리가 빠르게 줄어든다."],"checks":[{"title":"배터리 최대 용량 확인","why":"배터리 자체의 노후화인지, 다른 원인인지 가장 먼저 구분해야 합니다.","how":"① Windows 로고 키를 누르고 'cmd'를 입력한 뒤 검색 결과를 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② powercfg /batteryreport 를 입력하고 Enter를 누르세요. ③ 화면에 표시되는 저장 경로(보통 C:Users사용자이름\battery-report.html)를 확인하세요. ④ 파일 탐색기에서 그 경로로 이동해 battery-report.html 파일을 더블클릭해 웹 브라우저로 여세요. ⑤ 보고서 안의 'Battery Capacity History' 항목에서 '설계 용량(Design Capacity)'과 '전체 충전 용량(Full Charge Capacity)'을 비교하세요 — 현재 용량이 설계 용량의 70% 미만이라면 배터리 노후화가 원인입니다."},{"title":"배터리 사용량이 높은 앱 확인","why":"특정 프로그램이 백그라운드에서 계속 리소스를 쓰면 체감 사용 시간이 크게 줄어듭니다.","how":"① Windows 로고 키를 누르고 '배터리 사용량'을 입력해 실행하세요. ② 화면에 앱별 배터리 소비 비율이 나열됩니다. ③ 평소 잘 쓰지 않는데도 소비량이 높은 앱이 있는지 확인하세요. ④ 그런 앱을 찾았다면 작업 관리자에서 '시작프로그램' 탭을 확인해 자동 실행을 꺼두거나, 사용하지 않을 때는 완전히 종료하는 습관을 들이세요."},{"title":"화면 밝기·주사율 조정","why":"화면은 노트북에서 배터리를 가장 많이 소비하는 부품 중 하나입니다.","how":"① 화면 오른쪽 아래 알림 센터를 열어 밝기 슬라이더를 평소보다 낮춰보세요(50% 이하 권장). ② Windows 로고 키를 누르고 '디스플레이 설정'을 입력해 들어간 뒤 '고급 디스플레이'로 이동하세요. ③ 새로 고침 빈도(Hz)가 90Hz나 120Hz 같은 고주사율로 설정되어 있다면, 배터리로만 작동할 때는 60Hz로 낮추세요(고주사율은 배터리를 더 많이 소모합니다)."},{"title":"전원 관리 모드 확인","why":"'최고 성능' 모드는 절전을 거의 하지 않아 배터리 소모가 빠릅니다.","how":"① Windows 로고 키를 누르고 '전원 모드'를 입력해 실행하세요. ② 현재 '최고의 성능'으로 설정되어 있다면 '균형' 또는 '최고의 절전' 옵션으로 바꾸세요. ③ 배터리로 작동 중일 때 화면 오른쪽 아래 배터리 아이콘을 클릭하면 빠르게 전원 모드를 바꿀 수 있는 슬라이더도 있으니 활용하세요."},{"title":"그래픽카드 전환 설정 확인(게이밍 노트북)","why":"배터리 사용 중에도 고성능 그래픽카드가 계속 켜져 있으면 배터리가 매우 빠르게 소모됩니다.","how":"① 게이밍 노트북이라면 제조사 유틸리티(ASUS Armoury Crate, MSI Center 등)를 실행해 '그래픽 모드' 또는 '하이브리드 모드' 설정을 확인하세요. ② '고성능 모드'로 고정되어 있다면 '하이브리드' 또는 '자동 전환' 모드로 바꾸세요(배터리 사용 시 자동으로 내장 그래픽을 쓰도록). ③ NVIDIA 그래픽카드가 있다면 NVIDIA 제어판 → '3D 설정 관리'에서 전원 관리 모드가 '최적 전력 절약'으로 되어 있는지도 확인하세요."}],"deeper":[{"heading":"배터리 노후화는 고장이 아니라 소모품 특성","text":"리튬이온 배터리는 충전 주기가 쌓일수록(보통 300~500회 완충 기준) 최대 용량이 줄어드는 것이 정상입니다. 설계 용량 대비 현재 최대 용량이 80% 이하로 떨어졌다면 교체를 고려할 시점입니다."},{"heading":"게이밍 노트북은 배터리 소모가 원래 빠름","text":"고성능 CPU·GPU를 탑재한 게이밍 노트북은 사무용 노트북보다 배터리 소모가 훨씬 빠른 것이 일반적입니다. 배터리 사용 중 성능이 자동으로 제한되거나 그래픽카드가 전환되는 설정이 있는지 먼저 확인하세요."}],"decision":[{"heading":"최대 용량이 많이 줄었을 때","text":"배터리 자체의 노후화이므로 교체를 고려하세요. 자가 교체가 어려운 모델이 많아 서비스센터 상담을 권장합니다."},{"heading":"최대 용량은 정상인데 사용 시간만 짧을 때","text":"백그라운드 앱, 화면 설정, 전원 모드를 순서대로 확인하고 조정하세요."},{"heading":"게이밍 노트북에서 유독 빠를 때","text":"그래픽카드 자동 전환 설정과 성능 모드를 확인하세요."}],"examples":["1년 전에는 6시간 가던 노트북이 지금은 2시간도 안 감","덮어놓고 안 썼는데 하루 지나니 배터리가 절반 넘게 줄어 있음"],"mistakes":["배터리 최대 용량 확인 없이 바로 배터리를 교체하는 것","덮어놨을 때 절전 모드로 제대로 전환되는지 확인하지 않는 것"],"faq":[{"q":"powercfg 명령은 어떻게 실행하나요?","a":"시작 메뉴에서 '명령 프롬프트'를 검색해 관리자 권한으로 실행한 뒤 powercfg /batteryreport를 입력하면 지정된 경로에 HTML 보고서가 생성됩니다."},{"q":"배터리를 100%로 항상 유지하는 게 좋나요, 아니면 80%로 제한하는 게 좋나요?","a":"제조사가 배터리 보호 기능(충전 제한)을 제공한다면 80~90%로 제한하는 것이 장기적인 배터리 수명에 유리합니다. 특히 항상 전원을 연결해 사용하는 경우 효과가 큽니다."},{"q":"덮어놨는데도 배터리가 계속 줄어들면요?","a":"절전 모드로 제대로 전환되지 않고 있을 가능성이 있습니다. 전원 옵션에서 덮개를 닫았을 때의 동작이 절전으로 설정되어 있는지 확인하세요."}]},"monitor-refresh-rate-stuck":{"badge":"디스플레이","subtitle":"고주사율 모니터인데 설정이 60Hz에서 안 바뀔 때","intro":["모니터가 144Hz 등 고주사율을 지원한다고 표기되어 있어도, Windows나 그래픽 제어판에서는 케이블·드라이버·모니터 OSD 설정 중 하나라도 맞지 않으면 60Hz로만 표시되거나 옵션 자체가 비활성화될 수 있습니다.","가장 흔한 원인은 케이블입니다. HDMI 1.4처럼 오래된 규격은 고해상도에서 고주사율을 지원하지 못해 자동으로 60Hz로 제한됩니다. DP 케이블이나 HDMI 2.0 이상 케이블로 바꾸는 것만으로 해결되는 경우가 많습니다.","케이블이 맞는데도 안 된다면 그래픽 드라이버가 오래되었거나, 모니터 자체 OSD 메뉴에서 고주사율 모드가 꺼져 있을 수 있습니다. 특히 일부 모니터는 '오버클럭' 이름의 별도 메뉴에서 고주사율을 수동으로 켜야 합니다."],"warnings":["설정에서 주사율 옵션에 60Hz만 표시되거나 다른 값이 회색으로 비활성화되어 있다.","케이블을 바꾸지 않았는데 이사·자리 이동 후 갑자기 60Hz로 고정됐다.","다른 모니터나 다른 PC에 연결하면 고주사율이 정상적으로 표시된다."],"checks":[{"title":"케이블 규격 확인","why":"오래된 HDMI 케이블은 고해상도에서 고주사율 대역폭을 지원하지 못해 자동으로 60Hz로 제한됩니다.","how":"① 모니터 제조사 홈페이지나 박스 사양표에서 고주사율(예: 144Hz, 165Hz)을 내려면 어떤 케이블 규격이 필요한지 확인하세요(예: HDMI 2.0 이상, 또는 DisplayPort). ② 현재 쓰는 케이블 겉면에 인쇄된 규격 표시(있다면)를 확인하세요. ③ 오래된 케이블(HDMI 1.4 등)을 쓰고 있었다면 DP 케이블이나 HDMI 2.0 이상 케이블로 교체하세요. ④ 교체 후 디스플레이 설정에서 고주사율 옵션을 다시 선택할 수 있는지 확인하세요."},{"title":"그래픽 드라이버 업데이트","why":"드라이버가 오래되면 모니터의 EDID(지원 사양 정보)를 제대로 읽지 못해 고주사율 옵션이 안 뜰 수 있습니다.","how":"① NVIDIA 그래픽카드라면 GeForce Experience 프로그램을 열어 '드라이버' 탭에서 업데이트를 확인하세요. ② AMD 그래픽카드라면 AMD Software를 열어 '업데이트' 메뉴에서 확인하세요. ③ 프로그램이 없다면 제조사 공식 홈페이지에서 그래픽카드 모델을 검색해 최신 드라이버를 내려받아 설치하세요. ④ 설치 후 재부팅하고, 바탕화면 우클릭 → '디스플레이 설정' → '고급 디스플레이'에서 고주사율 옵션이 나타나는지 확인하세요."},{"title":"모니터 OSD 설정 확인","why":"일부 모니터는 고주사율(오버클럭) 모드가 기본적으로 꺼져 있어 수동으로 켜야 합니다.","how":"① 모니터 전면 버튼(또는 리모컨)으로 OSD 메뉴를 여세요. ② '게이밍', '오버클럭(OC)', '고급 설정' 등의 메뉴 안에서 주사율 관련 항목을 찾으세요(모니터 브랜드마다 메뉴 이름이 다릅니다). ③ 해당 항목이 꺼져 있다면 켜세요. ④ 모니터 메뉴를 닫고 PC의 디스플레이 설정에서 새로 고침 빈도 목록에 원하는 고주사율이 나타나는지 다시 확인하세요."},{"title":"듀얼 모니터 구성 확인","why":"두 모니터를 같은 케이블이나 허브로 연결하면 대역폭이 나뉘어 주사율이 제한될 수 있습니다.","how":"① 다른 모니터의 케이블을 잠시 뽑아 문제되는 모니터 하나만 연결된 상태로 만드세요. ② 디스플레이 설정 → 고급 디스플레이에서 고주사율이 정상적으로 선택 가능한지 확인하세요. ③ 하나만 연결했을 때 정상이라면, 두 모니터를 같은 케이블 허브나 도킹 스테이션으로 연결했을 때 대역폭이 나뉘어 제한되는 것이 원인입니다 — 가능하면 각 모니터를 그래픽카드의 서로 다른 포트에 직접 연결하세요."}],"deeper":[{"heading":"옵션 자체가 회색으로 막혀 있는 경우","text":"설정 화면에서 원하는 주사율이 아예 목록에 없거나 선택할 수 없게 되어 있다면, Windows가 해당 주사율을 지원 가능한 조합으로 인식하지 못하고 있다는 뜻입니다. 케이블·드라이버·해상도 조합을 하나씩 바꿔가며 다시 인식시켜야 합니다."},{"heading":"케이블을 바꾸지 않았는데 갑자기 안 될 때","text":"이사나 자리 이동 후 케이블 연결 순서가 바뀌었거나(그래픽카드 포트가 아닌 메인보드 포트에 연결), 케이블이 미세하게 손상된 경우가 흔합니다. 연결 포트부터 다시 확인하세요."}],"decision":[{"heading":"케이블 교체로 해결될 때","text":"케이블 규격이 원인이었으므로 고주사율을 지원하는 케이블을 계속 사용하세요."},{"heading":"드라이버 업데이트로 해결될 때","text":"이후에도 드라이버를 최신 상태로 유지하면 재발을 막을 수 있습니다."},{"heading":"OSD 설정으로 해결될 때","text":"모니터 자체의 오버클럭 모드를 켜둔 상태로 유지하면 됩니다."},{"heading":"위 방법으로도 해결되지 않을 때","text":"다른 PC에 연결해 모니터 자체의 문제인지, 원래 PC의 그래픽카드 포트 문제인지 교차 테스트하세요."}],"examples":["144Hz 모니터인데 설정에는 60Hz만 선택 가능하게 뜸","이사 후 자리를 옮기고 나서부터 계속 60Hz로 고정됨"],"mistakes":["케이블 규격 확인 없이 바로 그래픽카드를 의심하는 것","모니터 OSD의 오버클럭 메뉴를 확인하지 않고 드라이버만 계속 재설치하는 것"],"faq":[{"q":"HDMI로도 144Hz가 되나요?","a":"HDMI 2.0 이상이라면 해상도에 따라 가능합니다. 다만 HDMI 1.4처럼 오래된 규격은 풀HD에서도 144Hz를 지원하지 못하는 경우가 많아 DP 케이블을 우선 권장합니다."},{"q":"그래픽카드 제어판과 Windows 설정 중 어디서 바꿔야 하나요?","a":"두 곳 모두 확인해야 합니다. 그래픽카드 제어판에서 먼저 원하는 주사율을 사용자 지정으로 만든 뒤, Windows 디스플레이 설정에서 실제 적용 여부를 확인하는 것이 안전합니다."},{"q":"케이블도 바꾸고 드라이버도 최신인데 안 되면요?","a":"모니터 OSD의 오버클럭 관련 메뉴를 확인하세요. 일부 모니터는 이 메뉴가 꺼져 있으면 케이블·드라이버가 완벽해도 고주사율을 아예 표시하지 않습니다."}]},"earphone-one-side-no-sound":{"badge":"오디오","subtitle":"이어폰 한쪽에서만 소리가 나거나 유독 작게 들릴 때","intro":["이어폰 한쪽만 소리가 안 나는 문제는 대부분 이어폰 자체의 물리적 문제(단선, 유닛 고장)이지만, PC 쪽 설정(밸런스, 모노 오디오)이 원인인 경우도 적지 않아 순서대로 구분하는 것이 좋습니다.","가장 먼저 확인할 것은 PC의 소리 밸런스 설정입니다. 실수로 좌우 밸런스가 한쪽으로 치우쳐 있으면 멀쩡한 이어폰도 한쪽에서만 소리가 나는 것처럼 들립니다.","PC 설정이 정상인데도 같은 증상이 반복된다면, 같은 이어폰을 휴대폰 등 다른 기기에 연결해 봐서 이어폰 자체의 문제인지 PC의 문제인지 구분해야 합니다."],"warnings":["한쪽 이어폰에서만 소리가 나거나 한쪽이 유독 작게 들린다.","이어폰 케이블을 만지거나 구부리면 소리가 들렸다 안 들렸다 한다.","다른 기기에 연결해도 같은 증상이 반복된다."],"checks":[{"title":"소리 밸런스 설정 확인","why":"밸런스가 한쪽으로 치우쳐 있으면 하드웨어가 멀쩡해도 한쪽에서만 소리가 나는 것처럼 들립니다.","how":"① Windows 로고 키를 누르고 '소리 설정'을 입력해 실행하세요. ② '출력' 항목에서 사용 중인 이어폰/스피커를 선택한 뒤 '장치 속성'을 클릭하세요. ③ '추가 장치 속성' 링크를 클릭하세요. ④ '수준' 탭에서 '밸런스' 버튼을 클릭하세요. ⑤ 왼쪽(L)과 오른쪽(R) 슬라이더가 둘 다 100(또는 같은 값)으로 맞춰져 있는지 확인하고, 다르다면 같은 값으로 맞춘 뒤 '확인'을 누르세요."},{"title":"잭 연결 상태 확인","why":"3.5mm 잭이 완전히 꽂히지 않으면 한쪽 채널 접점이 닿지 않아 소리가 끊길 수 있습니다.","how":"① 이어폰 3.5mm 잭을 완전히 뽑았다가 딸깍 걸리는 느낌이 들 때까지 끝까지 다시 꽂으세요. ② 음악이나 영상을 재생한 상태에서 잭을 손으로 살짝 눌러보거나 조금씩 돌려보며 소리가 양쪽에서 모두 나는 순간이 있는지 확인하세요. ③ 눌렀을 때만 정상적으로 들린다면 잭이나 이어폰 단자 접촉 불량이 원인입니다."},{"title":"다른 기기와 교차 테스트","why":"이어폰 자체 문제인지 PC 문제인지 가장 확실하게 구분하는 방법입니다.","how":"① 같은 이어폰을 스마트폰이나 다른 PC의 3.5mm 단자에 연결하세요. ② 음악을 재생해 양쪽에서 모두 소리가 나는지 확인하세요. ③ 다른 기기에서도 한쪽만 들린다면 이어폰 자체(케이블 단선 등)의 고장이고, 다른 기기에서는 정상이라면 원래 PC의 오디오 포트나 설정 문제입니다."},{"title":"모노 오디오 설정 확인","why":"모노 오디오가 켜져 있으면 원래 양쪽에 나뉘어야 할 소리가 한쪽으로 합쳐질 수 있습니다.","how":"① Windows 로고 키를 누르고 '접근성 오디오 설정'을 입력해 실행하세요. ② '모노 오디오 켜기' 스위치를 확인하세요. ③ 켜져 있다면 꺼보세요(이 옵션이 켜져 있으면 원래 양쪽으로 나뉘어야 할 좌우 소리가 하나로 합쳐져 재생됩니다). ④ 이어폰을 다시 착용해 좌우가 구분되어 들리는지 확인하세요."}],"deeper":[{"heading":"케이블을 구부릴 때만 소리가 나면 단선 가능성","text":"이어폰 케이블의 특정 지점을 구부리거나 당길 때만 소리가 들렸다 안 들렸다 한다면, 그 지점의 내부 전선이 단선되었을 가능성이 높습니다. 이 경우 PC 설정과 무관하게 이어폰 자체 수리나 교체가 필요합니다."},{"heading":"블루투스 이어폰의 경우","text":"블루투스 이어폰은 좌우 유닛이 각각 별도로 배터리·연결 상태를 가지는 경우가 많아, 한쪽 유닛의 배터리 방전이나 페어링 문제로 한쪽만 소리가 안 날 수 있습니다. 양쪽을 케이스에 다시 넣고 재충전한 뒤 재연결해보세요."}],"decision":[{"heading":"PC 설정으로 해결될 때","text":"밸런스나 모노 오디오 설정이 원인이었으므로 이후에도 실수로 바뀌지 않았는지 가끔 확인하세요."},{"heading":"다른 기기에서도 같은 증상일 때","text":"이어폰 자체의 고장이므로 A/S나 교체를 고려하세요."},{"heading":"PC에서만 증상이 나타날 때","text":"PC의 사운드 드라이버를 재설치하거나 다른 오디오 포트로 연결해 비교해보세요."}],"examples":["유선 이어폰을 꽂았는데 오른쪽에서만 소리가 남","블루투스 이어폰 한쪽만 배터리가 유독 빨리 닳고 소리도 끊김"],"mistakes":["밸런스 설정 확인 없이 바로 이어폰을 새로 사는 것","다른 기기 교차 테스트 없이 PC나 이어폰 중 한쪽만 계속 의심하는 것"],"faq":[{"q":"새 이어폰인데도 한쪽만 소리가 안 나면요?","a":"새 제품이라도 불량일 수 있습니다. 다른 기기에서도 같은 증상이면 구매처에 교환·환불을 요청하세요."},{"q":"블루투스 이어폰 한쪽만 안 들리면 페어링을 다시 해야 하나요?","a":"네, 양쪽을 케이스에 넣고 충전한 뒤 기존 페어링 기록을 삭제하고 새로 연결해보는 것이 가장 확실한 방법입니다."},{"q":"밸런스를 어디서 확인하나요?","a":"설정 > 시스템 > 소리 > 사용 중인 출력 장치를 클릭한 뒤 장치 속성에서 확인할 수 있습니다."}]},"windows-shell-multiple-apps-not-opening":{"badge":"시스템","subtitle":"프로그램 하나가 아니라 여러 개가 동시에 안 열릴 때","intro":["특정 프로그램 하나만 안 열리는 것이 아니라 exe 실행 파일, 사진 뷰어, 작업 관리자 같은 기본 앱까지 함께 안 열린다면, 개별 프로그램의 문제가 아니라 Windows의 파일 연결이나 셸 자체가 손상됐을 가능성이 큽니다.","가장 흔한 원인은 exe 파일의 확장자 연결이 깨진 경우입니다. 원래 exe 파일을 더블클릭하면 그 프로그램이 바로 실행되어야 하는데, 이 연결 정보가 손상되면 아무 반응이 없거나 엉뚱한 프로그램이 열립니다.","파일 연결 문제가 아니라면 시스템 파일 손상이나 악성코드가 원인일 수 있어, SFC와 DISM 명령으로 시스템을 복구하고 백신 검사를 진행하는 것이 다음 순서입니다."],"warnings":["exe 파일, 이미지 뷰어, 작업 관리자 등 여러 프로그램이 동시에 반응이 없다.","같은 파일을 여러 번 클릭해야 겨우 한 번 열린다.","최근 출처가 불분명한 파일을 실행한 이후 증상이 시작됐다."],"checks":[{"title":"시스템 파일 검사(SFC)","why":"시스템 파일 손상이 여러 프로그램에 동시에 영향을 줄 수 있습니다.","how":"① Windows 로고 키를 누르고 'cmd'를 입력한 뒤 검색 결과를 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② sfc /scannow 를 입력하고 Enter를 누르세요. ③ 검사가 완료될 때까지 기다리세요(보통 10~20분 정도 걸립니다. 중간에 창을 닫지 마세요). ④ 완료 메시지에서 '손상된 파일을 찾았고 복구했습니다'라고 나오면 재부팅해 문제가 해결됐는지 확인하세요."},{"title":"Windows 구성 요소 복구(DISM)","why":"SFC로 복구되지 않는 손상은 DISM으로 먼저 복구해야 할 수 있습니다.","how":"① 관리자 권한 명령 프롬프트를 여세요(위 항목 참고). ② DISM /Online /Cleanup-Image /RestoreHealth 를 입력하고 Enter를 누르세요(인터넷 연결이 필요하며 완료까지 시간이 걸릴 수 있습니다). ③ 완료되면 sfc /scannow 를 다시 한번 실행하세요. ④ 재부팅 후 문제가 해결됐는지 확인하세요."},{"title":"백신 전체 검사","why":"악성코드가 exe 파일 연결을 가로채는 경우가 있습니다.","how":"① Windows 로고 키를 누르고 'Windows 보안'을 입력해 실행하세요. ② '바이러스 및 threat 방지' → '검사 옵션'을 클릭하세요. ③ '전체 검사'를 선택하고 '지금 검사'를 클릭하세요(완료까지 30분~수 시간 걸릴 수 있습니다). ④ 다른 백신을 쓰고 있다면 그 프로그램의 전체 검사 기능을 대신 사용하세요. ⑤ 발견된 악성코드가 있다면 안내에 따라 제거하고 재부팅하세요."},{"title":"계정 권한·그룹 정책 확인","why":"회사·학교 PC는 관리자가 특정 앱 실행을 제한해둔 경우가 있습니다.","how":"① 다른 관리자 계정이 있다면 그 계정으로 로그인해 같은 프로그램이 정상적으로 실행되는지 확인하세요. ② 회사나 학교에서 지급한 PC라면, 전산 담당자에게 특정 프로그램 실행이 그룹 정책으로 제한되어 있는지 문의하세요. ③ 개인 PC인데 관리자 계정에서도 안 된다면 위의 SFC·DISM·백신 검사 항목을 먼저 진행하세요."}],"deeper":[{"heading":"exe 파일 연결이 깨졌는지 확인하는 방법","text":"정상적인 exe 파일 아이콘이 흰 종이 모양으로 바뀌어 보이거나, 더블클릭 시 '연결 프로그램 선택' 창이 뜬다면 파일 연결 자체가 깨진 것입니다. 레지스트리를 직접 수정하기보다 시스템 복원 지점이 있다면 먼저 복원을 시도하는 것이 안전합니다."},{"heading":"한 번에 여러 증상이 겹칠 때","text":"exe뿐 아니라 이미지 뷰어, 캡처 도구, 작업 관리자까지 함께 안 열린다면 개별 파일 연결보다 Windows 셸 자체나 사용자 프로필 손상 범위가 더 넓을 가능성이 있습니다. 새 사용자 계정을 만들어 같은 증상이 재현되는지 확인해보세요."}],"decision":[{"heading":"SFC/DISM으로 해결될 때","text":"시스템 파일 손상이 원인이었으므로 복구 후에도 문제가 재발하는지 몇 차례 더 지켜보세요."},{"heading":"백신 검사에서 악성코드가 발견될 때","text":"발견된 항목을 격리·삭제한 뒤 exe 파일 연결이 정상으로 돌아왔는지 확인하세요."},{"heading":"새 계정에서는 정상일 때","text":"기존 사용자 프로필 손상이 원인이므로, 새 계정으로 이전하거나 프로필 복구를 진행하세요."}],"examples":["exe 파일을 더블클릭해도 반응이 없고 작업 관리자도 안 열림","출처가 불분명한 파일을 실행한 뒤부터 여러 프로그램이 안 열리기 시작함"],"mistakes":["원인 파악 없이 레지스트리를 직접 수정해 파일 연결을 고치려는 것","백신 검사 없이 SFC/DISM만 반복 실행하는 것"],"faq":[{"q":"sfc /scannow는 어떻게 실행하나요?","a":"시작 메뉴에서 '명령 프롬프트'를 검색해 관리자 권한으로 실행한 뒤 sfc /scannow를 입력하고 엔터를 누르면 됩니다."},{"q":"여러 번 클릭해야 겨우 열리는 것도 같은 문제인가요?","a":"네, 파일 연결이나 셸이 불안정할 때 흔히 나타나는 증상입니다. SFC/DISM 복구를 먼저 시도해보세요."},{"q":"초기화(재설치)까지 해야 하나요?","a":"SFC/DISM 복구와 백신 검사, 새 계정 테스트로도 해결되지 않을 때 마지막 수단으로 고려하세요. 그 전에 중요한 파일은 반드시 백업하세요."}]},"external-monitor-connect-blackout":{"badge":"디스플레이","subtitle":"외부 모니터를 연결하면 두 화면이 모두 꺼질 때","intro":["외부 모니터를 연결했는데 노트북 화면과 외부 화면이 모두 꺼진다면, 대부분 디스플레이 모드 설정이 원인입니다. Windows가 '두 번째 화면에만 표시' 모드로 전환됐는데 외부 화면이 신호를 받지 못하면 결과적으로 양쪽 다 검은 화면이 됩니다.","Windows 키 + P를 누르면 화면에 나타나지 않아도 디스플레이 모드 선택 메뉴가 뜨는 경우가 많습니다. 방향키와 엔터로 '복제' 또는 '확장'을 선택해 화면이 돌아오는지 먼저 확인하세요.","모드 전환으로 해결되지 않으면 케이블 규격·접촉 불량이나 외부 화면의 입력 소스 설정을 다음으로 확인해야 합니다."],"warnings":["외부 모니터를 연결하는 순간 노트북 화면도 함께 꺼진다.","케이블을 뽑으면 노트북 화면은 다시 정상으로 돌아온다.","외부 모니터의 입력 소스가 자동으로 바뀌지 않는다."],"checks":[{"title":"디스플레이 모드 재선택","why":"'두 번째 화면에만 표시' 모드에서 외부 화면이 신호를 못 받으면 양쪽 다 꺼진 것처럼 보입니다.","how":"① 화면이 검게 보이는 상태에서도 Windows 로고 키 + P를 누르세요(화면이 안 보여도 명령은 대부분 정상 작동합니다). ② 방향키로 아래로 이동해 '복제'를 선택하고 Enter를 누르세요. ③ 잠시 기다린 뒤 화면이 나타나는지 확인하세요. ④ 여전히 안 보이면 Windows 로고 키 + P를 다시 누르고 이번엔 '컴퓨터 화면만'을 선택해보세요."},{"title":"외부 화면 입력 소스 확인","why":"모니터·TV가 연결한 포트를 보고 있지 않으면 신호가 와도 화면에 나타나지 않습니다.","how":"① 모니터나 TV의 리모컨(또는 본체 버튼)에서 'Input' 또는 '입력' 버튼을 누르세요. ② 화면에 뜨는 입력 소스 목록(HDMI1, HDMI2, DP 등)을 확인하세요. ③ 실제로 케이블을 꽂은 포트 번호와 일치하는 입력 소스를 선택하세요(예: 뒷면 HDMI 1번에 꽂았다면 'HDMI1' 선택). ④ 화면이 나타나는지 확인하세요."},{"title":"케이블·포트 교차 테스트","why":"케이블이나 포트의 접촉 불량이 원인일 수 있습니다.","how":"① 사용 중인 케이블을 다른 HDMI/DP 케이블로 교체해보세요. ② PC나 그래픽카드의 다른 출력 포트로도 옮겨 연결해보세요. ③ 모니터·TV의 다른 입력 포트로도 바꿔 연결해보세요. ④ 특정 케이블이나 포트에서만 화면이 안 나온다면 그 케이블·포트의 접촉 불량이나 고장으로 확정할 수 있습니다."},{"title":"그래픽 드라이버 업데이트","why":"드라이버가 오래되면 외부 출력 전환 과정에서 오작동할 수 있습니다.","how":"① Windows 로고 키를 누르고 '장치 관리자'를 입력해 실행한 뒤 '디스플레이 어댑터'에서 그래픽카드 이름을 확인하세요. ② 그래픽카드 제조사(NVIDIA/AMD/Intel) 공식 홈페이지에서 정확한 모델명으로 검색해 최신 드라이버를 내려받으세요. ③ 내려받은 설치 파일을 실행해 설치하고 재부팅하세요. ④ 외부 화면을 다시 연결해 정상적으로 표시되는지 확인하세요."}],"deeper":[{"heading":"Windows 키 + P가 눈에 안 보여도 동작함","text":"화면이 검게 나온 상태에서도 Windows 키 + P를 누르면 메뉴 자체는 백그라운드에서 뜹니다. 화면을 보지 않고도 P 키를 누른 뒤 방향키로 첫 번째 옵션(PC 화면만)으로 이동해 엔터를 누르면 최소한 노트북 화면은 돌아오는 경우가 많습니다."},{"heading":"도킹 스테이션을 쓰는 경우","text":"도킹 스테이션이나 허브를 거쳐 연결한다면 도킹 스테이션 자체의 펌웨어 업데이트나 재연결이 필요할 수 있습니다. 도킹 스테이션 없이 케이블을 노트북에 직접 연결해 같은 증상이 재현되는지 먼저 비교하세요."}],"decision":[{"heading":"Windows 키 + P로 해결될 때","text":"디스플레이 모드 설정이 원인이었으므로 이후 연결 시 모드가 유지되는지 확인하세요."},{"heading":"케이블·포트 교체로 해결될 때","text":"기존 케이블이나 포트에 문제가 있었으므로 정상 작동하는 쪽을 계속 사용하세요."},{"heading":"위 방법으로도 해결되지 않을 때","text":"다른 PC나 다른 모니터로 교차 테스트해 노트북 출력 포트 자체의 고장 여부를 확인하세요."}],"examples":["회의실 프로젝터에 연결하는 순간 노트북 화면까지 꺼짐","HDMI로 TV에 연결했는데 TV도 노트북도 화면이 안 나옴"],"mistakes":["Windows 키 + P를 시도하지 않고 바로 드라이버를 재설치하는 것","외부 화면의 입력 소스 확인 없이 케이블만 계속 바꿔보는 것"],"faq":[{"q":"화면이 안 보이는데 Windows 키 + P가 정말 동작하나요?","a":"네, 화면 출력과 무관하게 메뉴 자체는 항상 뜹니다. 방향키 두 번과 엔터로 'PC 화면만'을 선택하면 최소한 노트북 화면은 돌아오는 경우가 많습니다."},{"q":"회의실이나 강의실에서만 이 문제가 생기면요?","a":"그 장소의 프로젝터·모니터 입력 소스 설정이나 케이블 자체의 문제일 가능성이 높습니다. 다른 장소에서는 정상인지 비교해보세요."},{"q":"도킹 스테이션을 쓰는데 이 문제가 자주 생기면요?","a":"도킹 스테이션의 펌웨어를 최신 버전으로 업데이트하거나, 케이블을 노트북에 직접 연결해 도킹 스테이션 자체의 문제인지 먼저 확인하세요."}]},"gpu-artifacts":{"badge":"그래픽카드","subtitle":"화면에 이상한 줄무늬·반점(아티팩트)이 나타날 때","intro":["화면에 색이 깨진 줄무늬, 블록 형태의 노이즈, 초록색이나 보라색 반점이 나타나는 현상을 아티팩트(Artifact)라고 부릅니다. 대부분 그래픽카드가 화면 데이터를 처리하는 과정에서 오류가 생겨 깨진 신호를 모니터로 보내고 있다는 신호입니다.","가장 먼저 구분해야 할 것은 특정 게임이나 무거운 작업에서만 나타나는지, BIOS 화면이나 부팅 로고에서도 나타나는지입니다. 부팅 초기 화면에서부터 아티팩트가 보인다면 소프트웨어(드라이버·게임)가 원인일 가능성은 배제되고, 그래픽카드·케이블 등 하드웨어 쪽 문제로 좁혀집니다.","온도와 오버클럭 설정도 반드시 함께 확인해야 합니다. 과열이나 불안정한 오버클럭이 원인이라면 냉각 개선이나 설정을 기본값으로 되돌리는 것만으로 해결되지만, 그렇지 않다면 그래픽카드 자체의 하드웨어 손상을 의심해야 합니다."],"warnings":["게임이나 영상 재생 중 화면에 이상한 줄무늬나 깨진 블록이 나타난다.","BIOS 화면이나 부팅 로고에서도 같은 노이즈가 보인다.","초록색·보라색 반점이 화면 일부에 고정되어 나타난다."],"checks":[{"title":"발생 시점 구분","why":"BIOS 단계에서도 나타나면 소프트웨어가 아닌 하드웨어·케이블 문제로 범위가 좁혀집니다.","how":"① 화면이 깨지는 증상(줄무늬, 깨진 텍스처, 이상한 색 블록 등)이 특정 게임 하나에서만 나타나는지 확인하세요. ② PC를 재부팅해 BIOS 화면(부팅 직후 로고 화면)에서도 같은 깨짐이 보이는지 확인하세요 — BIOS 화면은 게임 소프트웨어와 무관하게 그래픽카드가 직접 출력하는 화면입니다. ③ 유튜브 재생이나 바탕화면에서도 깨짐이 나타나는지 확인하세요. ④ 특정 게임에서만 나타난다면 그 게임이나 그래픽 설정 쪽 문제일 가능성이 크고, BIOS 화면에서도 나타난다면 그래픽카드나 케이블 등 하드웨어 문제일 가능성이 큽니다."},{"title":"온도 확인","why":"과열은 그래픽카드가 일시적으로 오작동하는 흔한 원인입니다.","how":"① 웹 브라우저에서 'GPU-Z' 공식 홈페이지에 접속해 무료 프로그램을 내려받아 설치하세요(설치 없이 실행 파일만으로도 동작합니다). ② GPU-Z를 실행한 상태에서 화면이 깨지던 게임이나 작업을 그대로 진행하세요. ③ GPU-Z의 'Sensors' 탭에서 'GPU Temperature' 값이 얼마까지 올라가는지 확인하세요. ④ 90도 이상까지 올라간 뒤 화면 깨짐이 나타난다면 과열이 원인일 가능성이 크므로, 쿨링(먼지 제거, 서멀 재도포)을 점검하세요."},{"title":"오버클럭·XMP 설정 초기화","why":"불안정한 오버클럭이나 메모리 타이밍 설정이 아티팩트를 유발할 수 있습니다.","how":"① PC를 재부팅하면서 부팅 직후 Delete 또는 F2 키를 연타해 BIOS 화면으로 들어가세요. ② 'Ai Tweaker', 'OC(오버클럭)', 'Extreme Tweaker' 등의 이름으로 된 메뉴를 찾으세요(메인보드 제조사마다 이름이 다릅니다). ③ CPU나 램의 오버클럭 설정, 'XMP' 또는 'EXPO' 프로파일이 켜져 있다면 '기본값(Auto/Disabled)'으로 되돌리세요. ④ 그래픽카드 자체를 오버클럭하는 프로그램(MSI 애프터버너 등)을 사용 중이라면 그 프로그램에서도 설정을 기본값으로 초기화하세요. ⑤ 저장 후 재부팅해 화면 깨짐이 줄어드는지 확인하세요."},{"title":"케이블·다른 그래픽카드로 교차 테스트","why":"케이블 문제인지, 그래픽카드 자체의 하드웨어 손상인지 가장 확실하게 구분할 수 있습니다.","how":"① 사용 중인 HDMI/DP 케이블을 다른 케이블로 교체해 같은 증상이 재현되는지 확인하세요. ② CPU에 내장그래픽이 있다면(인텔 대부분), 모니터 케이블을 메인보드 자체 포트로 옮겨 연결해 내장그래픽으로도 화면이 깨지는지 확인하세요. ③ 내장그래픽에서는 깨짐이 없다면 원인은 그래픽카드 쪽으로 좁혀집니다. ④ 여유가 있다면 다른 그래픽카드로 교체해 같은 증상이 재현되는지 비교하는 것이 가장 확실한 진단 방법입니다."}],"deeper":[{"heading":"VRAM 손상은 되돌릴 수 없는 경우가 많음","text":"비디오 메모리(VRAM)가 열 손상으로 불량이 생기면 특정 색이나 텍스처 영역에서 반복적으로 아티팩트가 나타납니다. 이 경우 드라이버 재설치나 설정 변경으로는 해결되지 않으며, 서비스센터 점검이나 그래픽카드 교체가 필요합니다."},{"heading":"케이블 문제와 하드웨어 손상 구분법","text":"케이블이 원인이라면 다른 케이블로 바꿨을 때 증상이 즉시 사라져야 합니다. 케이블을 바꿔도 똑같이 재현된다면 그래픽카드나 모니터 자체의 문제일 가능성이 높습니다."}],"decision":[{"heading":"특정 게임에서만 나타날 때","text":"드라이버 재설치나 오버클럭 설정 초기화를 먼저 시도하세요."},{"heading":"BIOS 화면에서도 나타날 때","text":"그래픽카드·케이블 하드웨어 문제이므로 교차 테스트로 범위를 좁히고, 재현되면 서비스센터 점검을 고려하세요."},{"heading":"온도가 비정상적으로 높을 때","text":"쿨링을 개선하거나 서멀 페이스트 재도포를 고려하세요."}],"examples":["게임 중 캐릭터 텍스처에 초록색 노이즈가 반복적으로 나타남","부팅 로고 화면부터 화면에 세로 줄무늬가 보임"],"mistakes":["발생 시점(BIOS vs 게임 중) 구분 없이 바로 그래픽카드를 교체하는 것","온도 확인 없이 드라이버만 반복해서 재설치하는 것"],"faq":[{"q":"드라이버를 재설치하면 확실히 해결되나요?","a":"드라이버 손상이 원인이라면 해결되지만, 하드웨어 손상이 원인이라면 드라이버를 아무리 재설치해도 재발합니다. BIOS 화면에서도 나타나는지 먼저 확인하세요."},{"q":"아티팩트가 가끔 한 번씩만 나타나도 걱정해야 하나요?","a":"일회성으로 잠깐 나타났다가 사라진다면 일시적인 오류일 수 있지만, 반복되거나 점점 심해진다면 하드웨어 손상 초기 신호일 수 있어 온도와 발생 시점을 계속 관찰해야 합니다."},{"q":"그래픽카드 교체 전에 마지막으로 확인할 것은?","a":"케이블 교체와 내장 그래픽·다른 그래픽카드로의 교차 테스트입니다. 이것만으로도 원인을 상당히 좁힐 수 있습니다."}]},"gamepad-controller-not-detected":{"badge":"입력장치","subtitle":"게임패드가 Windows나 게임에서 인식되지 않을 때","intro":["게임패드 인식 문제는 Windows 자체에서 인식이 안 되는 경우와, Windows에서는 인식되는데 특정 게임에서만 안 되는 경우로 나뉩니다. 이 둘은 원인과 해결 방법이 완전히 다릅니다.","Windows의 게임 컨트롤러 설정이나 블루투스 장치 목록에서 먼저 패드가 인식되는지 확인하세요. 여기서 인식되지 않는다면 드라이버, 배터리, 케이블·동글 문제일 가능성이 큽니다.","Windows에서는 인식되는데 특정 게임에서만 조작이 안 된다면, 그 게임의 입력 장치 설정이 키보드로 고정되어 있거나 컨트롤러 방식(XInput/DirectInput)이 맞지 않는 경우가 대부분입니다."],"warnings":["Windows 설정에서 패드 자체가 목록에 보이지 않는다.","Windows에서는 인식되는데 게임 안에서는 키보드로만 조작된다.","블루투스 연결은 되는데 게임에서 반응이 없다."],"checks":[{"title":"Windows 인식 여부 확인","why":"Windows에서부터 인식이 안 되면 게임 설정을 아무리 바꿔도 소용없습니다.","how":"① 컨트롤러를 USB 케이블로 연결하거나 블루투스로 페어링하세요. ② Windows 로고 키를 누르고 '게임 컨트롤러 설정'을 입력해 실행하세요(제어판의 '장치 및 프린터'에서도 확인할 수 있습니다). ③ 목록에 컨트롤러 이름이 나타나는지 확인하세요. ④ 목록에 있다면 '속성'을 클릭해 스틱을 움직이거나 버튼을 눌렀을 때 화면의 표시도 함께 반응하는지 확인하세요."},{"title":"게임 내 입력 장치 설정 확인","why":"많은 게임이 키보드를 기본 입력으로 고정해두고 있어 패드 입력을 무시할 수 있습니다.","how":"① Windows에서는 정상 인식되는데 게임에서만 반응이 없다면, 게임을 실행해 설정(옵션) 메뉴로 들어가세요. ② '조작' 또는 '입력' 탭을 찾아 입력 장치가 '키보드/마우스'로 고정되어 있지 않은지 확인하세요. ③ '컨트롤러' 또는 '게임패드'로 직접 전환하세요. ④ 일부 게임은 컨트롤러를 연결한 상태에서 아무 버튼이나 눌러야 자동으로 전환되기도 하니, 게임 화면에서 컨트롤러 버튼을 한번 눌러보세요."},{"title":"블루투스 페어링 재설정","why":"오래된 페어링 기록이 남아있으면 연결은 되어도 입력이 제대로 전달되지 않을 수 있습니다.","how":"① 설정 → '블루투스 및 장치'에서 기존 컨트롤러 페어링 기록을 찾아 '장치 제거'를 클릭하세요. ② 컨트롤러의 배터리가 충분한지 확인하고, 필요하면 충전하거나 새 배터리로 교체하세요. ③ 컨트롤러의 페어링 버튼을 눌러 페어링 모드로 만드세요(표시등이 빠르게 깜빡입니다). ④ PC에서 '장치 추가'로 처음부터 새로 페어링을 진행하세요."},{"title":"다른 게임·테스트 화면으로 교차 확인","why":"특정 게임만의 문제인지 패드·Windows 전체의 문제인지 구분할 수 있습니다.","how":"① Windows 로고 키를 누르고 '게임 컨트롤러 설정'을 입력해 실행하세요. ② 컨트롤러를 선택하고 '속성'을 클릭하면 나오는 테스트 화면에서 스틱과 버튼이 화면에도 반응하는지 확인하세요. ③ 여기서 정상 반응한다면 컨트롤러와 Windows 연결은 문제없는 것이므로, 특정 게임에서만 안 된다면 그 게임의 설정 문제입니다. ④ 다른 게임을 실행해서도 같은 컨트롤러가 인식되는지 비교해보세요."}],"deeper":[{"heading":"XInput과 DirectInput 차이","text":"Xbox 계열 패드는 대부분 XInput 방식이고, 일부 서드파티 패드나 오래된 게임은 DirectInput을 사용합니다. 두 방식이 게임과 맞지 않으면 패드가 인식되어도 특정 키가 작동하지 않을 수 있습니다. 이럴 때는 Steam 같은 플랫폼의 컨트롤러 호환 설정에서 방식을 전환해볼 수 있습니다."},{"heading":"키보드와 패드가 동시에 인식될 때","text":"일부 게임은 키보드와 패드 입력이 동시에 감지되면 키보드를 우선하도록 설계되어 있습니다. 이 경우 키보드 입력을 끊거나 게임 설정에서 패드를 우선 장치로 지정해야 합니다."}],"decision":[{"heading":"Windows에서부터 인식이 안 될 때","text":"드라이버, 배터리, 케이블·동글 순서로 확인하세요."},{"heading":"Windows에서는 되는데 게임에서만 안 될 때","text":"그 게임의 입력 장치 설정과 XInput/DirectInput 호환 여부를 확인하세요."},{"heading":"블루투스 연결 자체가 불안정할 때","text":"페어링을 삭제하고 새로 연결하거나, 유선(USB)으로 바꿔 안정성을 비교하세요."}],"examples":["엑스박스 패드가 블루투스로는 연결되는데 게임에서 키보드로만 조작됨","스팀 게임에서 패드 진동은 되는데 방향키 입력이 인식 안 됨"],"mistakes":["Windows 인식 여부 확인 없이 바로 게임 설정만 계속 바꿔보는 것","배터리 부족 가능성을 확인하지 않고 드라이버만 재설치하는 것"],"faq":[{"q":"유선으로 연결하면 항상 더 안정적인가요?","a":"일반적으로 유선 연결이 블루투스보다 지연과 연결 끊김이 적어 문제 발생 시 비교 기준으로 유용합니다."},{"q":"패드가 진동은 되는데 버튼 입력이 안 되면요?","a":"진동 신호와 버튼 입력 신호가 다른 경로로 처리되는 경우가 있어, 이 경우 게임의 컨트롤러 설정에서 입력 방식(XInput/DirectInput)을 바꿔보는 것이 효과적입니다."},{"q":"여러 게임에서 동시에 문제가 있으면요?","a":"게임보다 Windows나 패드 자체의 문제일 가능성이 높습니다. Windows의 게임 컨트롤러 테스트 화면에서 먼저 확인하세요."}]},"file-in-use-cannot-delete":{"badge":"시스템","subtitle":"삭제하려는 파일이 다른 프로그램에서 사용 중이라고 뜰 때","intro":["'다른 사람이나 다른 프로그램에서 이 파일을 사용하고 있습니다'라는 메시지는 Windows가 해당 파일에 대한 핸들(사용 권한)이 아직 열려 있다고 판단했다는 뜻입니다. 실제로 그 프로그램을 눈으로 보고 있지 않아도 백그라운드에서 파일을 붙잡고 있는 경우가 많습니다.","가장 흔한 원인은 그 파일을 열어본 적 있는 프로그램이 완전히 종료되지 않고 백그라운드에 남아 있는 경우입니다. 작업 관리자에서 관련 프로그램을 찾아 완전히 종료한 뒤 다시 시도하는 것이 첫 단계입니다.","프로그램을 모두 종료해도 안 된다면 원드라이브 같은 클라우드 동기화 프로그램이나 백신이 파일을 검사·동기화하느라 붙잡고 있을 수 있습니다. 이런 프로그램을 일시적으로 중지한 뒤 다시 시도하세요."],"warnings":["삭제·이동을 시도하면 '다른 프로그램에서 사용 중'이라는 메시지가 뜬다.","관련 프로그램을 껐다고 생각했는데도 계속 같은 메시지가 뜬다.","재부팅해도 같은 파일에서 반복적으로 문제가 생긴다."],"checks":[{"title":"관련 프로그램 완전 종료","why":"파일을 열어본 프로그램이 백그라운드에 남아 핸들을 붙잡고 있는 경우가 가장 흔합니다.","how":"① 삭제하려는 파일이 어떤 프로그램의 파일인지 확인하세요(예: .docx면 워드, .jpg면 사진 뷰어). ② Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ③ '프로세스' 탭에서 해당 프로그램을 찾아 선택하고 '작업 끝내기'를 클릭하세요(창을 닫았어도 백그라운드에 남아있는 경우가 있습니다). ④ 파일 탐색기로 돌아가 삭제를 다시 시도하세요."},{"title":"재부팅 직후 시도","why":"재부팅하면 대부분의 프로그램이 파일 핸들을 해제한 상태로 초기화됩니다.","how":"① 열려 있는 모든 프로그램을 저장하고 닫으세요. ② PC를 재부팅하세요. ③ 재부팅 후 다른 프로그램은 실행하지 말고, 파일 탐색기만 열어 문제의 파일을 바로 삭제해보세요."},{"title":"클라우드 동기화·백신 일시 중지","why":"원드라이브나 백신이 파일을 검사·동기화하는 중이면 삭제가 거부될 수 있습니다.","how":"① 화면 오른쪽 아래 작업 표시줄에서 원드라이브(구름 모양) 아이콘을 클릭하세요. ② 톱니바퀴(설정) 아이콘을 클릭해 '동기화 일시 중지'를 선택하고 시간을 선택하세요(예: 2시간). ③ 백신 프로그램을 열어 실시간 감시를 잠시 꺼보세요(끈 채로 오래 두지 말고, 삭제 시도 후 바로 다시 켜세요). ④ 이 상태에서 파일 삭제를 다시 시도하세요."},{"title":"파일 잠금 해제 도구 사용","why":"위 방법으로도 안 되면 어떤 프로세스가 파일을 잡고 있는지 직접 찾아야 합니다.","how":"① 웹 브라우저에서 신뢰할 수 있는 출처의 'Unlocker' 같은 파일 잠금 해제 도구를 검색해 공식 홈페이지에서 내려받아 설치하세요. ② 삭제하려는 파일을 마우스 오른쪽 버튼으로 클릭하면 메뉴에 'Unlocker' 항목이 추가되어 있습니다. ③ 클릭하면 현재 그 파일을 잡고 있는 프로세스 목록이 표시됩니다. ④ 목록에서 해당 프로세스를 선택해 '잠금 해제' 후 삭제하거나, 프로그램의 '잠금 해제 후 삭제' 옵션을 바로 사용하세요."}],"deeper":[{"heading":"탐색기 자체가 파일을 붙잡고 있는 경우","text":"때로는 탐색기(explorer.exe)가 미리보기나 썸네일 생성을 위해 파일을 열어둔 상태로 남아있을 수 있습니다. 작업 관리자에서 explorer.exe를 다시 시작하면 이런 경우 해결되기도 합니다."},{"heading":"네트워크 공유 파일인 경우","text":"네트워크 드라이브나 공유 폴더의 파일이라면 다른 사용자가 실제로 그 파일을 열어보고 있을 수 있습니다. 공유 설정에서 현재 파일을 사용 중인 세션을 확인해야 할 수도 있습니다."}],"decision":[{"heading":"프로그램 종료로 해결될 때","text":"다음부터는 프로그램을 완전히 종료한 뒤 파일을 삭제하는 습관을 들이세요."},{"heading":"클라우드 동기화 중지로 해결될 때","text":"동기화가 완료된 후 삭제를 진행하면 이런 충돌을 줄일 수 있습니다."},{"heading":"위 방법으로도 안 될 때","text":"파일 잠금 해제 도구를 사용하거나, 안전 모드에서 삭제를 시도하세요."}],"examples":["동영상 플레이어로 본 적 있는 파일을 지우려는데 계속 사용 중이라고 뜸","원드라이브 동기화 중인 폴더를 삭제하려다 실패함"],"mistakes":["관련 프로그램 종료 없이 강제 삭제 도구부터 사용하는 것","네트워크 공유 파일인데 로컬 파일처럼 취급해 원인을 잘못 짚는 것"],"faq":[{"q":"작업 관리자에서 어떤 프로그램을 찾아야 하나요?","a":"그 파일 형식과 관련된 프로그램(예: 동영상이면 미디어 플레이어, 문서면 워드·한글)을 먼저 확인하고, 명확하지 않다면 탐색기(explorer.exe)를 재시작해보세요."},{"q":"Unlocker 같은 프로그램은 안전한가요?","a":"널리 쓰이는 검증된 파일 잠금 해제 도구는 대체로 안전하지만, 출처가 불분명한 사이트에서 받지 말고 공식 배포처를 이용하세요."},{"q":"재부팅해도 매번 같은 파일에서 반복되면요?","a":"특정 프로그램이 시작 프로그램으로 등록되어 있어 부팅 직후 자동으로 그 파일을 여는 경우일 수 있습니다. 시작 프로그램 목록을 확인해보세요."}]},"cpu-usage-100":{"badge":"성능","subtitle":"특정 작업 없이도 CPU 사용률이 100%에 가깝게 유지될 때","intro":["CPU 사용률이 계속 높게 유지되는 문제는 디스크 사용률 100%와는 원인이 다릅니다. 먼저 작업 관리자에서 어떤 프로세스가 CPU를 많이 쓰는지부터 확인하는 것이 순서입니다.","특정 프로세스 하나가 확실히 높다면 그 프로그램을 재설치하거나 업데이트하는 것으로 해결되는 경우가 많습니다. 반면 여러 프로세스가 조금씩 나눠서 전체를 채우고 있다면 백그라운드에 실행 중인 프로그램 자체가 너무 많다는 신호입니다.","전체 사용률은 낮아 보이는데 유독 버벅인다면, 코어 하나만 100%에 붙어 있는 경우일 수 있습니다. 이런 경우는 멀티코어를 제대로 활용하지 못하는 프로그램이나 드라이버 문제인 경우가 많습니다."],"warnings":["웹 서핑처럼 가벼운 작업에서도 CPU 사용률이 계속 90~100%를 유지한다.","특정 프로그램을 실행하지 않았는데도 팬 소음과 발열이 심해진다.","작업 관리자를 열지 않았을 때 유독 컴퓨터가 느려진다."],"checks":[{"title":"가장 CPU를 많이 쓰는 프로세스 확인","why":"원인이 되는 프로세스를 정확히 지목해야 이후 대응이 명확해집니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ② '프로세스' 탭에서 'CPU' 열 머리글을 클릭해 사용량이 높은 순서로 정렬하세요. ③ 맨 위에 있는 프로세스 이름을 확인하세요 — 알고 있는 프로그램(브라우저, 게임 등)이면 해당 프로그램을 종료하거나 업데이트해보고, 처음 보는 이름이거나 'svchost.exe' 같은 시스템 프로세스라면 이름을 검색해 무엇인지 먼저 확인하세요."},{"title":"코어별 사용률 확인","why":"전체 사용률은 낮아도 특정 코어 하나가 100%면 버벅임의 원인이 됩니다.","how":"① 작업 관리자의 '성능' 탭을 클릭하고 왼쪽 목록에서 'CPU'를 선택하세요. ② 그래프 위에서 마우스 오른쪽 버튼을 클릭해 '그래프 변경 종류' → '논리 프로세서'를 선택하세요. ③ 코어(논리 프로세서)별로 나뉜 작은 그래프들이 나타납니다 — 특정 코어 한두 개만 계속 100%에 붙어 있고 나머지는 낮다면, 멀티코어를 제대로 활용하지 못하는 특정 프로그램이나 백그라운드 작업이 원인일 가능성이 큽니다."},{"title":"안전 모드에서 재현 확인","why":"백그라운드 프로그램이 원인인지, 시스템 자체의 문제인지 구분할 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정'을 실행한 뒤 '시스템' → '복구'로 들어가세요. ② '고급 시작'의 '지금 다시 시작'을 클릭하세요. ③ 재부팅 후 '문제 해결' → '고급 옵션' → '시작 설정' → '다시 시작'을 차례로 선택하세요. ④ 목록에서 '4' 또는 'F4' 키를 눌러 안전 모드로 부팅하세요. ⑤ 안전 모드에서 작업 관리자를 열어 CPU 사용률을 확인하세요 — 안전 모드에서는 정상(낮은 사용률)이라면 원인은 백그라운드 프로그램이고, 안전 모드에서도 100%가 유지된다면 시스템 자체나 하드웨어 쪽 원인을 의심해야 합니다."},{"title":"백신 전체 검사","why":"일부 악성코드는 몰래 CPU를 점유해 채굴 등에 사용합니다.","how":"① Windows 로고 키를 누르고 'Windows 보안'을 입력해 실행하세요. ② '바이러스 및 threat 방지'를 클릭한 뒤 '검사 옵션'을 선택하세요. ③ '전체 검사'를 선택하고 '지금 검사'를 클릭하세요(전체 검사는 파일 양에 따라 30분~수 시간이 걸릴 수 있습니다). ④ 다른 백신 프로그램을 이미 설치해 사용 중이라면 그 프로그램의 전체 검사 기능을 대신 사용하세요. ⑤ 검사 후 발견된 악성코드가 있다면 안내에 따라 격리 또는 제거를 진행하고 재부팅하세요."}],"deeper":[{"heading":"특정 프로세스 하나가 원인일 때","text":"해당 프로그램을 최신 버전으로 업데이트하거나 재설치해보세요. 특히 브라우저나 백신, 클라우드 동기화 프로그램이 버그로 CPU를 과도하게 쓰는 경우가 흔합니다."},{"heading":"System Idle Process가 낮고 여러 프로세스가 나눠 쓸 때","text":"시작 프로그램이 너무 많이 등록되어 있을 가능성이 큽니다. 작업 관리자의 시작프로그램 탭에서 불필요한 항목을 정리하세요."}],"decision":[{"heading":"특정 프로세스가 확실히 높을 때","text":"그 프로그램을 업데이트·재설치하거나, 필요 없다면 제거하세요."},{"heading":"안전 모드에서는 정상일 때","text":"시작 프로그램이나 백그라운드 서비스를 하나씩 비활성화하며 범위를 좁히세요."},{"heading":"백신 검사에서 악성코드가 발견될 때","text":"즉시 격리·삭제한 뒤 CPU 사용률이 정상으로 돌아왔는지 확인하세요."}],"examples":["인터넷 창 하나만 열어도 CPU 사용률이 90% 이상 유지됨","특정 코어 하나만 100%이고 나머지는 한 자릿수%로 유휴 상태"],"mistakes":["어떤 프로세스가 원인인지 확인하지 않고 바로 재설치·초기화하는 것","전체 사용률만 보고 코어별 사용률은 확인하지 않는 것"],"faq":[{"q":"System Idle Process가 CPU를 많이 쓰는데 이게 문제인가요?","a":"아닙니다. System Idle Process는 CPU가 쉬고 있는 시간을 나타내는 항목이라 오히려 수치가 높을수록 정상입니다."},{"q":"svchost.exe가 CPU를 많이 쓰면요?","a":"여러 Windows 서비스를 묶어서 실행하는 프로세스라 특정하기 어려울 수 있습니다. 작업 관리자에서 세부 정보를 펼쳐 어떤 서비스인지 확인하거나, Windows Update 관련 서비스가 아닌지 확인해보세요."},{"q":"재부팅하면 일시적으로 괜찮아지는데 다시 반복되면요?","a":"시작 프로그램에 등록된 백그라운드 프로그램이 원인일 가능성이 높습니다. 시작프로그램 목록을 정리해보세요."}]},"specific-website-not-loading":{"badge":"네트워크","subtitle":"다른 사이트는 되는데 특정 사이트만 안 될 때","intro":["다른 사이트는 잘 열리는데 유독 한두 곳만 안 된다면, 인터넷 연결 자체보다 그 사이트로 가는 경로(DNS·차단·캐시) 쪽 문제일 가능성이 큽니다.","가장 먼저 다른 기기나 다른 네트워크(휴대폰 데이터)에서 같은 사이트에 접속해보세요. 거기서도 안 된다면 사이트 자체의 문제이고, 내 PC나 네트워크에서만 안 된다면 DNS 캐시나 차단 설정을 의심해야 합니다.","회사·학교·카페 와이파이라면 네트워크 관리자가 특정 사이트를 의도적으로 차단해뒀을 가능성도 있습니다."],"warnings":["다른 사이트는 잘 열리는데 특정 사이트만 '사이트에 연결할 수 없음'이 뜬다.","새로고침을 여러 번 하면 가끔 열리기도 한다.","휴대폰 데이터로는 같은 사이트가 정상적으로 열린다."],"checks":[{"title":"다른 기기·다른 네트워크로 교차 테스트","why":"사이트 자체 문제인지 내 PC·네트워크 문제인지 가장 확실하게 구분하는 방법입니다.","how":"① 스마트폰의 Wi-Fi를 끄고 이동통신 데이터(LTE/5G)로 전환한 뒤 같은 사이트에 접속해보세요. ② 다른 PC나 노트북이 있다면 같은 사이트에 접속해 비교하세요. ③ 휴대폰 데이터나 다른 기기에서는 정상적으로 열린다면 사이트 자체 문제가 아니라 내 PC나 네트워크 쪽 문제로 좁혀집니다."},{"title":"DNS 캐시 초기화","why":"오래된 DNS 정보가 캐시에 남아있으면 사이트의 새 주소를 찾지 못할 수 있습니다.","how":"① Windows 로고 키를 누르고 'cmd'를 입력한 뒤 검색 결과를 마우스 오른쪽 버튼으로 클릭해 '관리자 권한으로 실행'을 선택하세요. ② ipconfig /flushdns 를 입력하고 Enter를 누르세요. ③ '성공적으로 DNS 확인자 캐시를 지웠습니다' 메시지를 확인하세요. ④ 브라우저를 완전히 종료했다가 다시 열어 같은 사이트에 접속해보세요."},{"title":"다른 네트워크에서 접속 확인","why":"지금 쓰는 와이파이·공유기에서만 차단되어 있을 수 있습니다.","how":"① 스마트폰에서 '개인용 핫스팟' 또는 '테더링'을 켜세요. ② PC의 Wi-Fi 목록에서 스마트폰의 핫스팟에 연결하세요. ③ 이 상태로 같은 사이트에 접속해보세요. ④ 핫스팟에서는 정상적으로 열린다면 원래 쓰던 공유기나 통신사 네트워크에서 그 사이트를 차단하고 있을 가능성이 큽니다(공유기의 URL 차단 설정이나 통신사의 유해 사이트 차단 등을 확인하세요)."},{"title":"브라우저 쿠키·캐시 삭제","why":"그 사이트에 대한 손상된 쿠키·캐시가 오류를 유발할 수 있습니다.","how":"① 크롬 기준, 문제의 사이트에 접속한 상태에서 주소창 왼쪽의 자물쇠(또는 정보) 아이콘을 클릭하세요. ② '쿠키 및 사이트 데이터' 또는 '사이트 설정'을 클릭하세요. ③ '데이터 삭제' 또는 '권한 재설정'을 클릭해 이 사이트에 대한 정보만 삭제하세요. ④ 페이지를 새로고침(F5)해 정상적으로 열리는지 확인하세요."}],"deeper":[{"heading":"회사·학교 네트워크의 의도적 차단","text":"네트워크 관리자가 특정 사이트를 정책적으로 차단해둔 경우, 개인 PC에서 아무리 설정을 바꿔도 해결되지 않습니다. 이런 경우 다른 네트워크에서는 정상적으로 열리는지로 판단할 수 있습니다."},{"heading":"DNS 서버를 바꿔보는 것도 방법","text":"공유기나 통신사의 DNS 서버 자체에 일시적인 문제가 있을 수 있습니다. 네트워크 어댑터 설정에서 DNS 서버 주소를 8.8.8.8(구글) 같은 공용 DNS로 바꿔 비교해볼 수 있습니다."}],"decision":[{"heading":"다른 네트워크에서도 안 될 때","text":"사이트 자체의 장애이거나 지역 차단일 가능성이 높으므로 시간을 두고 다시 시도하세요."},{"heading":"지금 네트워크에서만 안 될 때","text":"DNS 캐시 초기화나 공용 DNS 변경을 시도하고, 회사·학교망이라면 관리자에게 차단 여부를 문의하세요."},{"heading":"쿠키·캐시 삭제로 해결될 때","text":"브라우저의 저장된 데이터가 손상되어 있었던 것이므로 이후 비슷한 증상이 다른 사이트에서도 생기면 같은 방법을 시도하세요."}],"examples":["은행·증권사 사이트 한 곳만 '사이트에 연결할 수 없음'이 반복됨","학교 와이파이에서 특정 커뮤니티 사이트만 안 열림"],"mistakes":["교차 테스트 없이 바로 공유기를 초기화하는 것","회사·학교망의 의도적 차단을 PC 고장으로 오인하는 것"],"faq":[{"q":"ipconfig /flushdns는 어떻게 실행하나요?","a":"시작 메뉴에서 명령 프롬프트를 검색해 실행한 뒤 ipconfig /flushdns를 입력하고 엔터를 누르면 됩니다."},{"q":"VPN을 쓰면 해결되나요?","a":"지역 차단이나 네트워크 차단이 원인이라면 VPN으로 우회할 수 있지만, 회사·학교망에서는 VPN 사용 자체가 정책 위반일 수 있으니 먼저 확인하세요."},{"q":"한참 뒤에 다시 해보니 되던데요?","a":"그 사이트 자체의 일시적인 서버 장애였을 가능성이 높습니다. 이런 경우는 PC나 네트워크 설정과 무관합니다."}]},"screen-tearing":{"badge":"디스플레이","subtitle":"화면이 위아래로 어긋나며 찢어진 것처럼 보일 때","intro":["화면 티어링은 그래픽카드가 그리는 속도와 모니터가 화면을 표시하는 속도가 서로 맞지 않아 한 화면에 두 개의 다른 장면이 겹쳐 보이는 현상입니다. 고장이 아니라 동기화 설정의 문제인 경우가 대부분입니다.","가장 효과적인 해결책은 V-Sync나 G-Sync·FreeSync 같은 동기화 기술을 켜는 것입니다. 이 기능들은 그래픽카드의 출력을 모니터의 주사율에 맞춰 조절해 티어링을 방지합니다.","동기화 기능을 켜면 티어링은 해결되지만 입력 지연이 약간 늘어날 수 있어, 경쟁적인 게임에서는 대신 프레임 제한(FPS Cap)만 걸어 사용하는 경우도 많습니다."],"warnings":["화면 상단과 하단이 서로 다른 장면으로 어긋나 보인다.","화면을 빠르게 회전하거나 움직일 때 특히 심하게 나타난다.","특정 게임이나 고프레임 상황에서만 나타난다."],"checks":[{"title":"V-Sync 켜기","why":"그래픽카드의 출력을 모니터 주사율에 맞춰 티어링을 방지합니다.","how":"① 티어링이 발생하는 게임을 실행해 설정(옵션) 메뉴로 들어가세요. ② '그래픽' 또는 '디스플레이' 탭에서 'V-Sync' 또는 '수직 동기화' 항목을 찾아 '켜짐'으로 바꾸세요. ③ 게임 자체에 옵션이 없다면 NVIDIA 제어판(바탕화면 우클릭 → NVIDIA 제어판) 또는 AMD Software를 열어 '3D 설정 관리' → '수직 동기화'를 '켜짐'으로 설정하세요. ④ 게임을 다시 실행해 화면이 잘리는 티어링 현상이 사라졌는지 확인하세요(입력 지연이 약간 늘어날 수 있습니다)."},{"title":"G-Sync·FreeSync 활성화 확인","why":"지원 모니터라면 V-Sync보다 지연이 적으면서도 티어링을 방지할 수 있습니다.","how":"① 모니터 전면 버튼(또는 리모컨)으로 OSD 메뉴를 열어 'G-Sync', 'FreeSync', 'Adaptive-Sync' 같은 항목을 찾아 켜세요(모니터가 이 기능을 지원해야 합니다). ② NVIDIA 그래픽카드라면 NVIDIA 제어판 → 'G-Sync 설정'에서 사용을 체크하세요. ③ AMD 그래픽카드라면 AMD Software → '디스플레이' 탭에서 'AMD FreeSync'를 켜세요. ④ 모니터 쪽과 드라이버 쪽 둘 다 켜져 있어야 정상 작동하니 양쪽을 모두 확인하세요."},{"title":"프레임 제한(FPS Cap) 설정","why":"모니터 주사율보다 훨씬 높은 프레임이 출력되면 티어링이 심해집니다.","how":"① 모니터의 주사율(Hz)을 먼저 확인하세요(디스플레이 설정 → 고급 디스플레이에서 확인 가능). ② NVIDIA 제어판 → '3D 설정 관리' → '최대 프레임 속도'에서 모니터 주사율과 비슷한 값(예: 144Hz 모니터면 141~144)으로 설정하세요. ③ AMD라면 AMD Software → '성능' → '튜닝'에서 'Frame Rate Target Control'을 켜고 같은 방식으로 제한하세요. ④ 게임을 실행해 티어링이 줄었는지 확인하세요."},{"title":"발생 범위 확인","why":"특정 게임만의 문제인지 시스템 전체의 문제인지 구분할 수 있습니다.","how":"① 문제가 되는 게임 외에 다른 게임을 실행해 같은 티어링 현상이 나타나는지 확인하세요. ② 유튜브나 동영상 재생 프로그램에서도 화면이 잘리는 현상이 있는지 확인하세요. ③ 특정 게임에서만 나타난다면 그 게임의 설정(V-Sync 꺼짐 등)이나 최적화 문제일 가능성이 크고, 여러 프로그램에서 공통으로 나타난다면 시스템 전체의 그래픽 설정(주사율, 드라이버) 문제일 가능성이 큽니다."}],"deeper":[{"heading":"V-Sync와 입력 지연의 트레이드오프","text":"V-Sync는 화면을 안정시키지만 그래픽카드가 다음 프레임을 준비하고도 모니터 갱신 시점까지 대기해야 해서 약간의 입력 지연이 생깁니다. 반응 속도가 중요한 경쟁 게임에서는 이 지연이 부담스러울 수 있어 G-Sync·FreeSync나 프레임 제한을 더 선호하기도 합니다."},{"heading":"특정 게임에서만 나타난다면","text":"그 게임의 자체 그래픽 설정에서 동기화 옵션이 꺼져 있거나 그래픽 드라이버의 전역 설정과 충돌하고 있을 가능성이 있습니다. 게임 내 설정을 직접 확인하세요."}],"decision":[{"heading":"V-Sync로 해결될 때","text":"입력 지연이 거슬리지 않는다면 계속 사용하고, 거슬린다면 G-Sync·FreeSync나 프레임 제한으로 대체해보세요."},{"heading":"G-Sync·FreeSync 지원 모니터일 때","text":"V-Sync보다 이 기능을 우선 사용하는 것이 일반적으로 더 낫습니다."},{"heading":"여러 프로그램에서 나타날 때","text":"그래픽 드라이버의 전역 설정을 확인하고 드라이버를 최신 버전으로 업데이트하세요."}],"examples":["1인칭 슈팅 게임에서 화면을 빠르게 돌릴 때 화면이 어긋나 보임","고프레임이 나오는 가벼운 게임에서 유독 티어링이 심함"],"mistakes":["V-Sync를 켜보지 않고 바로 모니터나 그래픽카드를 의심하는 것","프레임 제한 없이 무조건 최고 성능만 추구해 불필요하게 높은 프레임을 유지하는 것"],"faq":[{"q":"티어링이 하드웨어 고장 신호인가요?","a":"아닙니다. 대부분 동기화 설정의 문제이며 고장과는 무관합니다. V-Sync나 프레임 제한으로 대부분 해결됩니다."},{"q":"V-Sync를 켜면 프레임이 떨어지는 것 같아요.","a":"정상입니다. V-Sync는 모니터 주사율에 맞춰 프레임을 제한하는 방식으로 동작하므로, 원래 프레임이 그보다 낮으면 절반으로 뚝 떨어지는 경우도 있습니다. 이때는 G-Sync·FreeSync가 더 나은 대안입니다."},{"q":"모니터가 G-Sync를 지원하는지 어떻게 아나요?","a":"모니터 사양표나 제조사 홈페이지에서 확인할 수 있으며, NVIDIA 제어판의 'G-Sync 설정' 메뉴에 지원 모니터가 자동으로 표시되기도 합니다."}]},"print-spooler-stuck":{"badge":"주변장치","subtitle":"인쇄 대기열에 문서가 걸려 진행되지 않을 때","intro":["인쇄를 눌러도 진행되지 않고 대기열에 계속 쌓이기만 하거나, 취소를 눌러도 문서가 지워지지 않는다면 대부분 인쇄 스풀러(Print Spooler) 서비스의 문제입니다. 프린터 자체의 하드웨어 문제보다 Windows의 인쇄 관리 서비스가 멈춘 경우가 훨씬 흔합니다.","가장 먼저 시도할 것은 Print Spooler 서비스를 다시 시작하는 것입니다. 이것만으로 해결되지 않는다면 스풀 폴더에 남은 손상된 인쇄 작업 파일이 원인일 수 있어, 서비스를 멈춘 뒤 해당 폴더의 파일을 직접 삭제해야 합니다.","서비스 재시작과 스풀 폴더 정리로도 해결되지 않는다면 프린터 드라이버나 연결 자체의 문제로 범위를 넓혀야 합니다."],"warnings":["인쇄를 눌러도 대기열에 문서만 쌓이고 실제로 인쇄되지 않는다.","대기열의 문서를 취소해도 계속 남아있다.","다른 문서를 인쇄하려 해도 이전 대기열 때문에 진행되지 않는다."],"checks":[{"title":"Print Spooler 서비스 재시작","why":"이 서비스가 멈추거나 응답하지 않으면 인쇄 작업 전체가 대기열에 걸립니다.","how":"① Ctrl+Shift+Esc를 눌러 작업 관리자를 여세요. ② '서비스' 탭을 클릭하세요. ③ 목록에서 'Spooler'(Print Spooler)를 찾아 마우스 오른쪽 버튼으로 클릭하세요. ④ '다시 시작'을 선택하세요(이미 중지된 상태라면 '시작'을 선택하세요). ⑤ 인쇄를 다시 시도해보세요."},{"title":"스풀 폴더 파일 삭제","why":"손상된 이전 인쇄 작업 파일이 스풀 폴더에 남아있으면 이후 작업까지 막을 수 있습니다.","how":"① 작업 관리자의 '서비스' 탭에서 'Spooler'를 마우스 오른쪽 버튼으로 클릭해 '중지'를 선택하세요. ② Windows 로고 키를 누르고 '이 PC'를 입력해 파일 탐색기를 연 뒤 주소창에 C:\\Windows\\System32\\spool\\PRINTERS 를 입력하고 Enter를 누르세요. ③ 폴더 안의 모든 파일을 선택(Ctrl+A)해 삭제하세요(폴더 자체는 남겨두세요). ④ 다시 작업 관리자의 '서비스' 탭에서 'Spooler'를 마우스 오른쪽 버튼으로 클릭해 '시작'을 선택하세요. ⑤ 인쇄를 다시 시도해보세요."},{"title":"프린터 드라이버 재설치","why":"드라이버 손상이 스풀러 오류를 반복적으로 유발할 수 있습니다.","how":"① Windows 로고 키를 누르고 '설정' → '블루투스 및 장치' → '프린터 및 스캐너'로 들어가세요. ② 문제의 프린터를 클릭해 '제거'를 선택하세요. ③ 프린터 제조사(HP, Canon, Epson, 삼성 등) 공식 홈페이지에서 정확한 모델명으로 검색해 최신 드라이버 설치 파일을 내려받으세요. ④ 설치 파일을 실행해 안내에 따라 프린터를 다시 추가하세요."},{"title":"프린터 연결 상태 확인","why":"연결이 불안정하면 인쇄 작업이 프린터로 제대로 전달되지 않습니다.","how":"① USB로 연결한 프린터라면 케이블이 양쪽 다 확실히 꽂혀 있는지 확인하고, 다른 포트나 케이블로도 바꿔보세요. ② 네트워크(Wi-Fi) 프린터라면 프린터 자체 화면에서 같은 공유기에 연결되어 있는지 확인하세요. ③ 프린터 전원을 껐다가 다시 켜보세요. ④ 연결이 안정된 상태에서 인쇄를 다시 시도해보세요."}],"deeper":[{"heading":"서비스 재시작만으로 해결되지 않는 이유","text":"서비스를 재시작해도 스풀 폴더에 손상된 파일이 그대로 남아있으면 서비스가 다시 그 파일을 읽으려다 같은 문제를 반복할 수 있습니다. 이 경우 반드시 서비스를 완전히 중지한 상태에서 폴더의 파일을 삭제해야 합니다."},{"heading":"반복적으로 이 문제가 생긴다면","text":"특정 문서(대용량 파일, 손상된 PDF 등)를 인쇄할 때마다 반복된다면, 그 문서 자체가 원인일 수 있습니다. 다른 형식으로 저장하거나 다른 프로그램에서 인쇄를 시도해보세요."}],"decision":[{"heading":"서비스 재시작으로 해결될 때","text":"일시적인 서비스 오류였으므로 이후 재발하는지 지켜보세요."},{"heading":"스풀 폴더 정리가 필요했을 때","text":"특정 문서에서 반복된다면 그 문서 자체의 손상 여부도 확인하세요."},{"heading":"위 방법으로도 해결되지 않을 때","text":"드라이버 재설치와 연결 상태 점검으로 범위를 넓히세요."}],"examples":["여러 페이지 문서를 인쇄하다 하나가 걸린 뒤로 계속 대기열만 쌓임","대기열의 문서를 취소해도 상태가 '삭제 중'에서 멈춰 있음"],"mistakes":["서비스 재시작 없이 스풀 폴더 파일만 삭제하려는 것(파일이 사용 중이라 삭제 안 됨)","드라이버 문제 확인 없이 프린터를 반복 재설치하는 것"],"faq":[{"q":"스풀 폴더 파일을 삭제해도 안전한가요?","a":"네, 이 폴더에는 대기 중인 인쇄 작업의 임시 파일만 저장되어 있어 삭제해도 시스템이나 문서 원본에는 영향이 없습니다."},{"q":"Print Spooler 서비스는 어떻게 찾나요?","a":"작업 관리자를 열고 '서비스' 탭으로 이동한 뒤 이름순으로 Print Spooler를 찾으면 됩니다."},{"q":"매번 이 문제가 반복되면요?","a":"프린터 드라이버를 최신 버전으로 재설치하거나, 특정 문서에서만 반복된다면 그 문서 자체의 손상 여부를 확인하세요."}]},"windows-11-24h2-update-fail":{"badge":"업데이트","subtitle":"Windows 11 24H2로 업데이트가 설치되지 않고 오류 코드와 함께 실패할 때","intro":["Windows 11 24H2는 매달 나오는 일반 누적 업데이트가 아니라 버전 자체를 올리는 대규모 기능 업데이트라, 설치에 필요한 조건이 훨씬 까다롭습니다. 다운로드까지는 되는데 설치 단계에서 되돌아가거나, 아예 시작 화면에서 \"이 PC는 아직 준비되지 않았습니다\" 같은 문구와 함께 막히는 경우가 많습니다.","가장 흔한 오류 코드는 0xc1900201(시스템 요구사항 미충족)과 0x80240069(설치 실패)입니다. 0xc1900201은 대부분 여유 저장공간 부족이나 TPM 2.0·보안 부팅 같은 하드웨어 조건이 원인이고, 0x80240069는 업데이트 구성 요소 손상이나 외부 장치 간섭으로 발생하는 경우가 많습니다.","일반 월간 업데이트가 반복 실패하는 것과는 원인이 다르므로, 이 페이지는 24H2처럼 버전을 올리는 대규모 업데이트에 특화된 점검 순서를 다룹니다. 매달 나오는 누적 업데이트가 반복 실패한다면 업데이트 반복 실패 가이드를 먼저 확인하세요."],"warnings":["설치 진행률이 어느 지점에서 항상 되돌아간다.","\"이 PC는 아직 Windows 11, 버전 24H2를 사용할 준비가 되지 않았습니다\" 문구가 뜬다.","0xc1900201 또는 0x80240069 코드가 표시된다."],"checks":[{"title":"여유 저장공간 확보","why":"기능 업데이트는 이전 버전을 임시로 함께 보관하기 때문에 일반 업데이트보다 훨씬 많은 여유 공간이 필요합니다.","how":"① Windows 로고 키를 누르고 '저장소 설정'을 입력해 실행하세요. ② 'C 드라이브'를 클릭해 현재 여유 공간을 확인하세요. ③ 20~30GB 미만이라면 '임시 파일' 항목에 들어가 다운로드 폴더, 휴지통, 이전 Windows 설치 파일 등을 정리하세요. ④ 여유 공간을 충분히 확보한 뒤 설정 → Windows Update에서 '업데이트 확인'을 눌러 24H2 업데이트를 다시 시도하세요."},{"title":"TPM 2.0·보안 부팅 상태 확인","why":"24H2도 Windows 11의 하드웨어 요구사항을 그대로 따르므로, TPM이나 보안 부팅이 꺼져 있으면 0xc1900201로 막힙니다.","how":"① Windows 로고 키를 누르고 'tpm.msc'를 입력한 뒤 Enter를 누르세요. ② '사양 버전'이 2.0으로 표시되는지 확인하세요('TPM을 사용할 수 없습니다'라고 나오면 BIOS에서 꺼져 있는 상태입니다). ③ PC를 재부팅하며 Delete 또는 F2 키를 연타해 BIOS 화면으로 들어가세요. ④ 'Security' 메뉴에서 'TPM', 'PTT'(인텔), 'fTPM'(AMD) 항목과 'Secure Boot' 항목을 모두 '사용(Enabled)'으로 바꾸세요. ⑤ 저장 후 재부팅하고 업데이트를 다시 시도하세요."},{"title":"외장 장치 모두 분리","why":"프린터, 외장 하드, 일부 USB 장치가 설치 도중 드라이버 충돌을 일으켜 0x80240069로 이어지는 경우가 보고됩니다.","how":"① 업데이트를 시도하기 전에 프린터, 외장하드, USB 메모리, 도킹 스테이션 등 필수적이지 않은 모든 USB 장치를 뽑으세요(마우스·키보드는 남겨도 됩니다). ② 설정 → Windows Update에서 '업데이트 확인'을 눌러 다시 시도하세요. ③ 업데이트가 성공적으로 완료된 뒤에 장치들을 다시 연결하세요."},{"title":"업데이트 문제 해결사 실행","why":"구성 요소 손상은 수동으로 하나씩 찾기보다 자동 진단 도구가 더 빠르게 잡아내는 경우가 많습니다.","how":"① Windows 로고 키를 누르고 '문제 해결 설정'을 입력해 실행하세요. ② '기타 문제 해결사'를 클릭하세요. ③ 목록에서 'Windows Update'를 찾아 '실행' 버튼을 클릭하세요. ④ 문제 해결사가 자동으로 진단하고 발견된 문제를 수정하는 것을 기다리세요. ⑤ 완료 후 재부팅하고 업데이트를 다시 시도하세요."}],"deeper":[{"heading":"0xc1900201과 0x80240069는 원인이 다릅니다","text":"0xc1900201은 설치를 시작하기 전 '자격 검사'에서 걸리는 코드로 저장공간·TPM·보안 부팅 같은 하드웨어·용량 조건 문제입니다. 0x80240069는 실제 설치가 진행되다 실패하는 코드로, 업데이트 구성 요소 손상이나 외부 장치 간섭 쪽을 먼저 봐야 합니다."},{"heading":"설치 미디어로 직접 올리는 방법도 있습니다","text":"Windows Update로 계속 실패한다면, Microsoft 공식 설치 관리자나 미디어 생성 도구로 24H2를 직접 설치하는 방법이 있습니다. 이 경우 Windows Update 경로의 일부 검사를 우회하지만, 시스템 최소 요구사항(TPM 2.0 등) 자체는 여전히 충족해야 합니다."}],"decision":[{"heading":"0xc1900201이 뜰 때","text":"저장공간과 TPM·보안 부팅부터 확인하세요. 대부분 이 둘 중 하나가 원인입니다."},{"heading":"0x80240069가 뜰 때","text":"외장 장치를 분리하고 업데이트 문제 해결사를 실행한 뒤 재시도하세요. 그래도 안 되면 설치 미디어로 직접 업그레이드하는 방법을 검토하세요."}],"examples":["설치 진행률 20~30%대에서 항상 되돌아감","\"이 PC는 아직 준비되지 않았습니다\" 문구와 함께 대기 상태로 멈춤"],"mistakes":["저장공간 확인 없이 재시도만 반복하는 것","TPM·보안 부팅을 끈 채로 레지스트리 우회 방법부터 찾는 것 — 요구사항을 우회해 설치해도 이후 다른 업데이트에서 계속 문제가 생길 수 있습니다"],"faq":[{"q":"24H2 업데이트를 꼭 지금 해야 하나요?","a":"당장 필수는 아닙니다. 다만 이전 버전은 지원 종료일이 정해져 있으므로, 지금 실패한다고 무한정 미루기보다 원인(저장공간·TPM)을 먼저 해결해두는 것이 안전합니다."},{"q":"TPM 2.0이 없는 PC인데 24H2를 설치할 방법이 있나요?","a":"레지스트리 우회로 강제 설치하는 방법이 커뮤니티에 공유되어 있지만, Microsoft가 공식 지원하지 않는 방식이라 이후 업데이트나 보안 기능에서 문제가 생길 수 있습니다. 신중하게 판단하세요."},{"q":"설치 미디어로 업그레이드하면 데이터가 지워지나요?","a":"'업그레이드' 방식(기존 Windows 실행 중 설치 관리자·미디어 생성 도구를 실행)을 선택하면 파일과 앱을 유지한 채 진행됩니다. 다만 예기치 못한 상황에 대비해 중요한 파일은 미리 백업해두세요."}]},"nas-quickconnect-slow":{"badge":"네트워크","subtitle":"QuickConnect로 외부에서 NAS에 접속하면 속도가 느리거나 자주 끊기는 경우","intro":["QuickConnect는 공유기에서 별도 포트포워딩 설정 없이도 외부에서 NAS에 접속할 수 있게 해주는 편의 기능입니다. 다만 직접 연결 경로를 만들지 못하면 시놀로지의 중계(릴레이) 서버를 거치게 되는데, 이 릴레이 서버는 대역폭이 제한돼 있어 파일 전송이나 스트리밍이 눈에 띄게 느려집니다.","집에서 로컬 네트워크로 접속할 때는 빠른데 외부(모바일 데이터, 다른 Wi-Fi)에서만 느리다면 이 릴레이 경유 여부부터 확인하는 것이 첫 단계입니다."],"warnings":["집 안 네트워크에서는 빠른데 외부에서만 느리다.","대용량 파일을 다운로드하면 예상 시간이 비정상적으로 길게 표시된다.","DS file·Synology Drive 모바일 앱에서 스트리밍이 자주 끊긴다."],"checks":[{"title":"연결 방식 확인","why":"릴레이로 연결돼 있다면 속도 제한이 구조적인 원인입니다.","how":"① 웹 브라우저에서 NAS의 DSM(관리 화면)에 로그인하세요. ② 왼쪽 위 시작 메뉴(네모 4개 아이콘)를 클릭해 '제어판'을 여세요. ③ '외부 액세스' → 'QuickConnect' 탭을 클릭하세요. ④ 화면에 표시되는 연결 상태를 확인하세요 — '릴레이(Relay)'로 표시되면 시놀로지 중계 서버를 거쳐 느리게 연결되는 상태이고, '직접 연결(P2P)'이면 정상적으로 빠르게 연결된 상태입니다. ⑤ 릴레이 상태라면 아래 포트포워딩 항목을 진행하세요."},{"title":"공유기 포트포워딩 설정","why":"포트포워딩이 되어 있어야 릴레이 없이 직접 연결됩니다.","how":"① 웹 브라우저 주소창에 공유기 관리 페이지 주소(보통 192.168.0.1 또는 192.168.1.1)를 입력해 로그인하세요. ② 'NAT/라우터 관리', '포트포워딩', '가상 서버' 등의 이름으로 된 메뉴를 찾으세요(공유기 제조사·모델마다 메뉴 이름과 위치가 다릅니다). ③ 새 규칙을 추가해 외부 포트 5000(HTTP)과 5001(HTTPS)을, NAS의 내부 IP 주소(DSM 제어판 → 네트워크에서 확인 가능)의 같은 포트로 전달하도록 설정하세요. ④ 설정을 저장하고, DSM의 QuickConnect 화면으로 돌아가 연결 상태가 '직접 연결'로 바뀌었는지 확인하세요(변경 후 몇 분 정도 걸릴 수 있습니다)."},{"title":"DDNS로 직접 연결 구성","why":"포트포워딩이 어려운 환경(이중 NAT, 회사망)에서는 DDNS+포트포워딩 조합이 QuickConnect보다 안정적입니다.","how":"① DSM에서 제어판 → 외부 액세스 → 'DDNS' 탭을 클릭하세요. ② '추가' 버튼을 클릭하고 서비스 제공자로 'Synology'를 선택하세요. ③ 원하는 호스트 이름(예: mynas)을 입력하고 사용 가능 여부를 확인한 뒤 저장하세요 — 이제 mynas.synology.me 같은 주소로 접속할 수 있게 됩니다. ④ 위에서 진행한 포트포워딩(외부 포트 5000/5001)이 함께 설정되어 있어야 DDNS 주소로도 직접 연결이 됩니다."},{"title":"이중 NAT 여부 확인","why":"공유기가 2대 이상 직렬로 연결된 환경(통신사 모뎀+개인 공유기)이면 포트포워딩을 해도 릴레이를 벗어나지 못할 수 있습니다.","how":"① 인터넷 회선이 연결된 통신사 모뎀(단말기)이 있고 그 뒤에 개인 공유기를 별도로 연결해 쓰고 있다면 이중 NAT 환경일 가능성이 있습니다. ② 통신사 모뎀의 관리 페이지에 접속해(주소는 통신사 안내 스티커나 설명서 참고) '브리지 모드' 또는 '공유기 모드 끄기' 옵션이 있는지 확인하세요. ③ 브리지 모드로 전환하면 통신사 모뎀은 단순 회선 연결만 담당하고, 개인 공유기에서 포트포워딩이 정상적으로 동작하게 됩니다. ④ 브리지 모드 전환이 어렵다면, 개인 공유기뿐 아니라 통신사 모뎀에서도 똑같이 포트 5000/5001을 전달하도록 이중으로 설정하세요."}],"deeper":[{"heading":"QuickConnect vs DDNS, 뭐가 더 안전한가요","text":"QuickConnect는 설정이 간단하지만 릴레이 경유 시 느리고, 시놀로지 서버 상태에 영향을 받습니다. DDNS+포트포워딩은 설정이 조금 더 필요하지만 속도가 안정적입니다. 자주 대용량 파일을 주고받는다면 DDNS 방식을 권장합니다."},{"heading":"포트포워딩이 보안상 괜찮은가요","text":"불특정 다수에 노출되는 것이므로, DSM 자체 비밀번호를 강력하게 설정하고 2단계 인증을 켜는 것이 좋습니다. 가능하면 기본 포트(5000/5001) 대신 다른 포트로 변경해 자동화된 스캔을 피하는 것도 방법입니다."}],"decision":[{"heading":"포트포워딩 후 속도가 개선될 때","text":"릴레이 경유가 원인이었던 것이 확인된 것입니다. 공유기 재부팅 후에도 설정이 유지되는지 한 번 더 확인하세요."},{"heading":"포트포워딩을 해도 여전히 릴레이로 표시될 때","text":"이중 NAT 환경일 가능성이 큽니다. 통신사 모뎀의 브리지 모드 전환을 고려하세요."}],"examples":["집에서는 빠른데 외부에서 QuickConnect로 접속하면 파일 하나 받는 데 몇 분씩 걸린다","DSM 외부 액세스 화면에 연결 상태가 '릴레이'로 표시된다"],"mistakes":["포트포워딩 없이 QuickConnect만 켜두고 느리다고 NAS 자체를 의심하는 것","이중 NAT 환경을 모르고 포트포워딩만 반복 시도하는 것"],"faq":[{"q":"QuickConnect 연결이 왜 이렇게 느린가요?","a":"포트포워딩이나 DDNS가 설정돼 있지 않으면 시놀로지 릴레이 서버를 거쳐 연결되는데, 이 릴레이는 대역폭이 제한돼 있어 느립니다. 공유기에서 포트포워딩을 설정하면 직접 연결로 전환되어 속도가 개선됩니다."},{"q":"포트포워딩을 했는데도 계속 느립니다.","a":"이중 NAT(통신사 모뎀+개인 공유기가 함께 연결된 환경)일 가능성이 있습니다. 통신사 모뎀을 브리지 모드로 전환하거나 모뎀에서도 같은 포트를 전달하도록 설정해야 합니다."}]},"nas-boot-fail":{"badge":"하드웨어","subtitle":"전원은 들어오는데 DSM이 시작되지 않거나, 전원 LED가 계속 깜빡이며 부팅이 완료되지 않는 경우","intro":["DSM은 장착된 디스크 전체에 설치되므로, 디스크 중 하나만 정상이어도 이론적으로는 부팅이 가능합니다. 하지만 시스템 파티션이 손상되거나 여러 디스크가 동시에 문제를 일으키면 전원은 들어와도 DSM 화면까지 도달하지 못합니다.","가장 먼저 할 일은 '전원이 아예 안 들어오는 것'과 '전원은 들어오는데 DSM만 안 뜨는 것'을 구분하는 것입니다. 전원 LED가 켜지고 팬이 도는데 웹 화면만 안 뜬다면 대부분 아래 절차로 해결됩니다."],"warnings":["전원 LED가 1~2분이 지나도 계속 파란색으로 깜빡이기만 한다.","DSM 웹 관리 화면(https://NAS주소:5001)에 접속이 안 된다.","Synology Assistant나 find.synology.com에서 NAS가 검색되지 않는다."],"checks":[{"title":"부팅 상태 정확히 확인","why":"정상 부팅은 LED가 깜빡이다가 고정으로 바뀝니다. 계속 깜빡인다면 부팅 실패 상태입니다.","how":"① NAS 전면의 상태 LED(보통 'STATUS'라고 표시)를 육안으로 확인하세요. ② 전원을 켠 직후에는 LED가 주황색이나 초록색으로 깜빡이는 것이 정상입니다. ③ 최소 5분간 기다리며 LED가 계속 깜빡이는지, 아니면 고정된 초록색으로 바뀌는지 관찰하세요(모델에 따라 초기 부팅에 10분 이상 걸리기도 합니다). ④ 5분이 지나도 계속 깜빡이기만 하고 고정되지 않는다면 부팅 실패 상태로 보고 아래 항목을 진행하세요."},{"title":"웹 어시스턴트로 검색","why":"네트워크 설정 문제인지 하드웨어 문제인지 구분할 수 있습니다.","how":"① NAS와 같은 공유기(같은 Wi-Fi 또는 같은 유선 네트워크)에 연결된 PC에서 웹 브라우저를 여세요. ② 주소창에 https://finds.synology.com 을 입력하고 Enter를 누르세요. ③ 페이지가 자동으로 네트워크를 검색해 연결된 NAS 장치를 찾아 보여줍니다. ④ NAS가 검색되면 화면에 표시되는 안내(복구, 마이그레이션 등)를 그대로 따라가세요. ⑤ 검색되지 않으면 아래 Synology Assistant 항목을 진행하세요."},{"title":"Synology Assistant 사용","why":"웹 브라우저로 검색이 안 될 때 더 낮은 수준에서 장치를 찾을 수 있습니다.","how":"① 웹 브라우저에서 시놀로지 공식 다운로드 센터에 접속해 'Synology Assistant' 프로그램을 내려받으세요. ② 내려받은 설치 파일을 실행해 PC에 설치하세요. ③ Synology Assistant를 실행하면 자동으로 같은 네트워크를 검색해 연결된 NAS 목록을 보여줍니다. ④ 목록에 NAS가 나타나면 더블클릭해 상태를 확인하고, 관리 화면 접속이나 복구를 시도하세요. ⑤ 여기서도 검색되지 않는다면 네트워크 문제가 아니라 하드웨어 문제일 가능성이 크므로 아래 디스크 분리 테스트를 진행하세요."},{"title":"디스크 분리 테스트","why":"여러 디스크 중 하나가 문제를 일으켜 전체 부팅을 막는 경우가 흔합니다.","how":"① NAS 전원을 완전히 끄고 전원 케이블을 뽑으세요. ② 디스크를 빼기 전에 각 디스크가 몇 번 베이(슬롯)에 있었는지 스마트폰으로 사진을 찍어 기록해두세요(원상복구 시 순서가 매우 중요합니다). ③ 디스크를 모두 뺀 뒤, 베이 1번 디스크만 다시 꽂고 전원을 켜 부팅되는지 확인하세요. ④ 부팅되지 않으면 전원을 끄고 다음 베이의 디스크로 바꿔가며 하나씩 테스트하세요. ⑤ 특정 디스크(또는 조합)를 꽂았을 때만 부팅이 안 된다면 그 디스크가 원인일 가능성이 크므로, 데이터가 중요하다면 전문 복구 업체에 문의하는 것을 고려하세요."}],"deeper":[{"heading":"디스크 하나가 문제라면 데이터는 안전한가요","text":"RAID 구성(SHR, RAID 1 이상)이라면 디스크 하나가 빠져도 나머지로 복구가 가능한 경우가 많습니다. 다만 부팅이 안 되는 상태에서 임의로 디스크를 재포맷하거나 초기화하면 복구가 어려워지므로, 확신이 없다면 디스크를 그대로 둔 채 시놀로지 공식 지원에 먼저 문의하는 것이 안전합니다."},{"heading":"웹 어시스턴트에서도 안 잡힐 때","text":"네트워크 케이블·포트 자체의 문제일 수 있습니다. 다른 랜 포트(듀얼랜 모델)나 다른 케이블로 교체해보고, 그래도 안 되면 전원 어댑터 자체의 고장 가능성도 확인해야 합니다."}],"decision":[{"heading":"특정 디스크를 뺐을 때만 부팅될 때","text":"그 디스크가 원인입니다. 데이터가 있다면 무리하게 재장착하지 말고, RAID 상태를 확인한 뒤 디스크 교체를 진행하세요."},{"heading":"디스크를 모두 빼도 부팅이 안 될 때","text":"메인보드나 전원부 자체의 하드웨어 고장 가능성이 큽니다. 시놀로지 공식 A/S 문의를 권장합니다."}],"examples":["전원을 켰는데 LED가 파란색으로 계속 깜빡이기만 하고 DSM 화면이 안 뜬다","find.synology.com에서 NAS가 검색되지 않는다"],"mistakes":["부팅이 안 된다고 바로 디스크를 초기화하거나 재포맷하는 것(데이터 손실 위험)","전원 LED 상태를 확인하지 않고 무작정 재부팅만 반복하는 것"],"faq":[{"q":"전원 LED만 깜빡이고 DSM이 안 뜨면 고장인가요?","a":"꼭 고장은 아닙니다. 디스크 인식 문제나 시스템 파티션 손상으로도 같은 증상이 나타납니다. find.synology.com으로 먼저 검색되는지 확인하고, 안 되면 디스크를 하나씩 분리해 원인을 좁혀보세요."},{"q":"디스크를 분리해서 테스트해도 데이터에 영향이 없나요?","a":"분리 자체는 데이터에 영향을 주지 않습니다. 다만 부팅 테스트 중에 화면에서 '초기화'나 '포맷'을 진행하라는 안내가 나와도, 데이터가 있는 디스크라면 그대로 진행하지 말고 먼저 백업 여부와 RAID 상태를 확인하세요."}]},"nas-storage-not-freed":{"badge":"저장공간","subtitle":"파일을 삭제하고 휴지통까지 비웠는데도 사용 중인 저장 공간이 줄어들지 않는 경우","intro":["파일을 삭제하고 휴지통도 비웠는데 저장 공간 사용량이 그대로라면, 대부분 '스냅샷'이 원인입니다. 스냅샷은 특정 시점의 데이터 상태를 통째로 보관하는 기능이라, 스냅샷을 찍은 이후에 삭제한 파일이라도 스냅샷 안에는 그대로 남아있어 실제 디스크 공간을 계속 차지합니다.","탐색기(파일 마우스 우클릭 삭제)에서 지운 것과 공유 폴더 자체의 네트워크 휴지통을 비우는 것은 별개인 경우도 있어, 이 둘을 구분해서 확인해야 합니다."],"warnings":["파일을 삭제하고 휴지통도 비웠는데 저장 공간 사용량이 줄지 않는다.","스토리지 관리자의 사용량이 실제 남아있는 파일보다 훨씬 크게 표시된다.","Synology Drive를 쓰는데 오래된 파일 버전이 계속 쌓인다."],"checks":[{"title":"스냅샷 확인·정리","why":"스냅샷이 남아있으면 그 시점 이후 삭제한 파일도 계속 용량을 차지합니다.","how":"① DSM에 로그인한 뒤 '패키지 센터'에서 'Snapshot Replication'이 설치되어 있는지 확인하세요(설치되어 있어야 스냅샷 기능이 동작합니다). ② 시작 메뉴에서 'Snapshot Replication'을 여세요. ③ 왼쪽에서 용량이 줄지 않는 공유 폴더를 선택하면 그동안 생성된 스냅샷 목록이 보입니다. ④ 더 이상 필요 없는 오래된 스냅샷을 선택해 '삭제'를 클릭하세요(스냅샷을 삭제하면 그 시점으로 되돌릴 수 없게 되니, 정말 필요 없는 것만 삭제하세요). ⑤ 스토리지 관리자에서 용량이 회수됐는지 확인하세요."},{"title":"네트워크 휴지통 비우기","why":"탐색기에서 삭제해도 공유 폴더 자체의 휴지통(#recycle)에는 파일이 남아있을 수 있습니다.","how":"① DSM 시작 메뉴에서 'File Station'을 여세요. ② 용량이 줄지 않는 공유 폴더로 이동하세요. ③ 상단 메뉴의 '보기' → '숨긴 파일 표시'를 체크하면 '#recycle'이라는 폴더가 보입니다(공유 폴더 자체의 휴지통입니다). ④ #recycle 폴더 안으로 들어가 파일들을 전체 선택한 뒤 마우스 오른쪽 버튼을 클릭해 '영구 삭제'를 선택하세요(일반 삭제가 아니라 완전 삭제를 선택해야 용량이 실제로 회수됩니다)."},{"title":"Synology Drive 버전 관리 확인","why":"버전 관리가 켜져 있으면 파일을 덮어쓰거나 삭제해도 이전 버전이 계속 보관됩니다.","how":"① DSM 시작 메뉴에서 'Synology Drive Admin Console'을 여세요. ② 왼쪽 메뉴에서 '팀 폴더'를 클릭하고, 용량이 줄지 않는 폴더를 선택하세요. ③ '버전 관리' 설정에서 현재 보관 기간(예: 무제한, 30일 등)과 최대 버전 개수를 확인하세요. ④ 필요 이상으로 길게 설정되어 있다면 보관 기간을 줄이거나, 버전 관리 자체가 필요 없다면 기능을 꺼서 저장하세요 — 이후 오래된 버전들이 정리되며 용량이 회수됩니다."},{"title":"용량 재계산 대기","why":"휴지통을 비운 직후에는 시스템이 실제 공간을 회수하는 데 시간이 걸릴 수 있습니다.","how":"① 위 항목들(스냅샷, 휴지통, 버전 관리)을 모두 정리했다면 DSM 시작 메뉴에서 '스토리지 관리자'를 여세요. ② '개요' 화면에서 현재 사용 중인 용량을 확인하세요. ③ 정리 직후에는 시스템이 실제 디스크 공간을 회수하는 데 시간이 걸릴 수 있으니, 대용량을 정리했다면 몇 시간(많으면 하루) 정도 기다린 뒤 같은 화면에서 사용량이 줄었는지 다시 확인하세요."}],"deeper":[{"heading":"스냅샷을 지워도 되나요","text":"스냅샷은 실수로 삭제한 파일을 복구하는 안전장치이기도 합니다. 무작정 전부 지우기보다, 보관 정책(예: 최근 7일치만 유지)을 설정해 오래된 스냅샷만 자동으로 정리되도록 하는 것이 안전합니다."},{"heading":"Synology Drive 휴지통은 계정별로 따로 있습니다","text":"Synology Drive를 여러 계정이 함께 쓰는 경우, 각 계정의 개인 휴지통은 따로 관리됩니다. 관리자 계정에서만 비웠다면 다른 계정의 휴지통에 파일이 남아있을 수 있습니다."}],"decision":[{"heading":"스냅샷 삭제로 용량이 회수될 때","text":"스냅샷이 원인이었던 것이 확인된 것입니다. 앞으로는 보관 기간을 정책으로 설정해 스냅샷이 무한정 쌓이지 않도록 관리하세요."},{"heading":"스냅샷도 없는데 용량이 그대로일 때","text":"Synology Drive 버전 관리나 다른 계정의 개인 휴지통을 확인하세요. 그래도 원인을 못 찾으면 스토리지 관리자에서 폴더별 사용량 분석 기능으로 실제로 용량을 차지하는 위치를 찾아보세요."}],"examples":["10GB 넘는 파일을 삭제하고 휴지통도 비웠는데 사용량이 그대로다","스토리지 관리자의 사용 용량이 File Station에서 보이는 실제 파일 크기보다 훨씬 크다"],"mistakes":["스냅샷 존재 여부를 확인하지 않고 무작정 파일을 더 지우는 것","관리자 계정의 휴지통만 비우고 다른 계정의 개인 휴지통은 확인하지 않는 것"],"faq":[{"q":"스냅샷이 뭔지 몰랐는데 어떻게 확인하나요?","a":"DSM → 제어판 → 스냅샷 복제(또는 패키지 센터에서 Snapshot Replication 설치 후)에서 공유 폴더별로 찍힌 스냅샷 목록을 볼 수 있습니다. 자동으로 주기적으로 찍히도록 설정돼 있는 경우가 많으니 먼저 확인해보세요."},{"q":"스냅샷을 다 지우면 데이터가 위험해지나요?","a":"스냅샷은 백업이 아니라 같은 볼륨 내 복구용 스냅이라, 디스크 자체가 고장 나면 스냅샷도 함께 사라집니다. 중요한 데이터는 스냅샷과 별개로 외부 백업(다른 NAS, 클라우드 등)을 권장합니다."}]},"nas-usb-not-detected":{"badge":"하드웨어","subtitle":"NAS의 USB 포트에 외장하드나 USB 메모리를 연결해도 저장소 관리자에 나타나지 않는 경우","intro":["NAS의 USB 포트는 외장하드 백업이나 USB Copy 기능에 흔히 쓰이는데, 연결해도 저장소 관리자나 File Station에 나타나지 않는 경우가 있습니다. 가장 흔한 원인은 파일 시스템 미지원(특히 exFAT)이고, 그다음으로 흔한 것은 전원이 부족한 연결 경로(무전원 허브, 전면 포트)입니다.","DSM은 Btrfs, ext4, FAT/FAT32, exFAT(별도 패키지 필요), NTFS, HFS+ 등을 지원하지만, 일부는 읽기 전용으로만 지원되거나 패키지를 추가로 설치해야 합니다."],"warnings":["외장하드를 연결해도 저장소 관리자나 File Station에 아무것도 나타나지 않는다.","장치는 인식되는데(제어판 → 외부 장치) 파티션·파일에는 접근이 안 된다.","USB Copy 버튼을 눌러도 아무 반응이 없다."],"checks":[{"title":"파일 시스템 확인·exFAT 패키지 설치","why":"exFAT은 DSM 기본 기능이 아니라 별도 유료 패키지(exFAT Access)를 설치해야 인식됩니다.","how":"① 외장하드를 PC에 연결한 뒤 '이 PC'에서 해당 드라이브를 마우스 오른쪽 버튼으로 클릭해 '속성'을 열면 '파일 시스템' 항목에서 포맷 방식(NTFS, exFAT, FAT32 등)을 확인할 수 있습니다. ② exFAT으로 표시된다면, DSM에 로그인해 시작 메뉴에서 '패키지 센터'를 여세요. ③ 검색창에 'exFAT'을 입력해 'exFAT Access' 패키지를 찾아 '설치'를 클릭하세요(시놀로지 계정 로그인이 필요할 수 있습니다). ④ 설치가 끝난 뒤 외장하드를 NAS에 다시 연결해 인식되는지 확인하세요."},{"title":"연결 위치 변경","why":"무전원 허브나 일부 전면 포트는 전력 공급이 부족해 대용량 외장하드를 구동하지 못할 수 있습니다.","how":"① USB 허브를 거쳐 연결하고 있다면 허브를 빼고 NAS 뒷면의 USB 포트에 케이블을 직접 꽂으세요. ② 외장하드가 별도의 전원 어댑터(콘센트에 꽂는 케이블)를 쓰는 제품이라면, 어댑터를 반드시 연결한 상태로 시도하세요(USB 전원만으로는 구동이 안 되는 모델이 있습니다). ③ 다시 연결한 뒤 DSM에서 인식되는지 확인하세요."},{"title":"장치 인식 여부와 파티션 인식 여부 구분","why":"장치 자체는 인식되는데 파티션만 못 읽는 경우와, 장치 자체가 아예 안 잡히는 경우는 원인이 다릅니다.","how":"① DSM에서 제어판 → '외부 장치(External Devices)'를 클릭하세요. ② 목록에 연결한 외장하드 이름이 나타나는지 확인하세요. ③ 장치 이름이 나타난다면 하드웨어 연결 자체는 정상이고, 파일 시스템(포맷) 문제일 가능성이 큽니다 — 위 exFAT 패키지 설치 항목을 확인하세요. ④ 장치 이름 자체가 아예 나타나지 않는다면 케이블·포트·전원 연결 문제이니 위의 '연결 위치 변경' 항목을 먼저 시도하세요."},{"title":"다른 포트·다른 PC에서 교차 확인","why":"외장하드 자체의 고장인지 NAS 쪽 문제인지 구분해야 합니다.","how":"① 같은 외장하드를 PC(Windows)에 직접 연결해 '이 PC'에서 정상적으로 인식되는지 확인하세요. ② PC에서도 인식되지 않는다면 외장하드 자체의 고장일 가능성이 큽니다. ③ PC에서는 정상 인식되는데 NAS에서만 안 된다면, NAS의 다른 USB 포트(앞면/뒷면)에 번갈아 연결해보며 특정 포트의 문제인지 확인하세요."}],"deeper":[{"heading":"왜 exFAT은 기본 지원이 안 되나요","text":"exFAT은 마이크로소프트의 특허 기술이라 시놀로지가 별도 라이선스 패키지(exFAT Access)로 제공합니다. Windows에서 포맷한 대용량 USB 메모리나 외장하드는 exFAT인 경우가 많아 이 패키지 설치가 필요한 경우가 흔합니다."},{"heading":"NTFS 외장하드는 쓰기가 되나요","text":"DSM은 NTFS를 지원하지만 일부 구성에서는 읽기 전용으로 동작할 수 있습니다. 데이터를 자주 쓰기·수정할 계획이라면 처음부터 NAS와 궁합이 좋은 파일 시스템(exFAT+패키지, 또는 ext4)으로 포맷하는 것을 고려하세요."}],"decision":[{"heading":"exFAT 패키지 설치 후 인식될 때","text":"파일 시스템 미지원이 원인이었던 것입니다. 앞으로 새 외장하드를 NAS용으로 쓸 계획이라면 포맷 시점부터 이 점을 고려하세요."},{"heading":"포트를 바꿔도 장치 자체가 안 잡힐 때","text":"외장하드 또는 케이블 자체의 고장일 가능성이 큽니다. PC에 연결해 정상 인식되는지 먼저 확인하세요."}],"examples":["exFAT으로 포맷된 외장하드를 연결했는데 저장소 관리자에 아무것도 안 뜬다","USB 허브를 거쳐 연결한 외장하드가 인식되다 안 되다를 반복한다"],"mistakes":["exFAT Access 패키지 설치 여부를 확인하지 않고 외장하드 고장으로 단정하는 것","무전원 허브를 거쳐 연결해두고 전원 문제를 의심하지 않는 것"],"faq":[{"q":"exFAT Access 패키지는 무료인가요?","a":"모델과 시기에 따라 다를 수 있어 패키지 센터에서 정확한 가격 정책을 확인해야 합니다. 유료인 경우가 많으므로, 자주 쓸 계획이 아니라면 NAS에서 직접 포맷(ext4 등)하는 것도 대안입니다."},{"q":"장치 관리자에는 나오는데 파일이 안 보입니다.","a":"장치는 인식됐지만 파일 시스템을 DSM이 읽지 못하는 상태입니다. exFAT이라면 패키지를 설치하고, 그래도 안 되면 파티션 방식(GPT/MBR)이나 포맷 손상 여부를 PC에서 먼저 확인하세요."}]},"nas-drive-sync-fail":{"badge":"저장공간","subtitle":"PC나 폴더에서 파일을 옮기거나 지워도 Synology Drive에 반영되지 않거나, 반대로 NAS 쪽 변경이 클라이언트에 동기화되지 않는 경우","intro":["Synology Drive는 File Station(웹 파일 관리)과 별도의 동기화 엔진으로 동작합니다. File Station에서 파일을 옮기거나 지워도 그 변경이 Drive의 동기화 대상으로 자동 반영되지 않는 경우가 있어, \"파일은 지웠는데 Drive에는 그대로 보인다\" 같은 혼란이 자주 생깁니다.","동기화가 안 될 때는 먼저 어느 쪽(PC→NAS, NAS→PC) 방향이 안 되는지, 특정 파일만 그런지 폴더 전체가 그런지부터 구분하면 원인을 좁히기 쉽습니다."],"warnings":["PC에서 파일을 옮기거나 지웠는데 Synology Drive(또는 File Station)에서 반영되지 않는다.","Drive Client 트레이 아이콘에 동기화 오류·보류 표시가 떠 있다.","같은 파일 이름 뒤에 conflicted copy가 붙은 파일이 생긴다."],"checks":[{"title":"동기화 상태 아이콘 확인","why":"오류·보류 상태를 먼저 확인해야 원인을 좁힐 수 있습니다.","how":"① PC 화면 오른쪽 아래 작업 표시줄에서 시놀로지 Drive Client 아이콘(파란색 원형 아이콘)을 찾아 클릭하세요. ② 열리는 창에서 동기화 대기 중이거나 오류로 표시된 파일이 있는지 확인하세요(빨간색 느낌표나 경고 아이콘으로 표시됩니다). ③ 오류가 표시된 항목을 클릭하면 구체적인 원인(파일 잠김, 권한 부족, 용량 초과 등)이 텍스트로 표시됩니다. ④ 표시된 원인에 따라 아래 해당 항목을 진행하세요."},{"title":"동기화 작업(태스크) 포함 여부 확인","why":"File Station에서 새로 만든 폴더는 자동으로 Drive 동기화 대상에 추가되지 않을 수 있습니다.","how":"① Drive Client 트레이 아이콘을 클릭한 뒤 오른쪽 위 톱니바퀴(설정) 아이콘을 클릭하세요. ② '동기화 작업' 또는 '작업 관리' 메뉴를 클릭하세요. ③ 동기화되지 않는 폴더가 목록에 포함되어 있는지 확인하세요. ④ 포함되어 있지 않다면 '추가' 버튼을 눌러 해당 공유 폴더나 하위 폴더를 동기화 대상으로 새로 지정하세요."},{"title":"파일 잠금·사용 중 여부 확인","why":"다른 프로그램이 파일을 열어둔 상태면 동기화가 보류됩니다.","how":"① 동기화가 안 되는 파일이 워드, 엑셀, PDF 뷰어 등 다른 프로그램에서 열려 있는지 확인하세요(작업 표시줄이나 작업 관리자에서 확인 가능). ② 해당 프로그램을 모두 완전히 닫으세요(최소화가 아니라 종료해야 합니다). ③ 2~3분 정도 기다린 뒤 Drive Client 아이콘을 다시 확인해 동기화가 정상적으로 진행되는지 확인하세요."},{"title":"파일 충돌(conflicted copy) 정리","why":"여러 기기에서 같은 파일을 동시에 수정하면 두 버전이 모두 보존되어 동기화가 혼란스러워집니다.","how":"① 파일 탐색기에서 동기화 폴더를 열고 파일 이름에 'conflicted copy'라는 문구가 포함된 파일이 있는지 확인하세요(보통 파일명 뒤에 날짜와 함께 붙습니다). ② 원본 파일과 conflicted copy 파일을 각각 열어 어느 쪽이 최신 내용인지 확인하세요. ③ 필요한 내용을 하나의 파일로 정리한 뒤, 필요 없는 사본은 삭제하세요. ④ 여러 사람이 같은 파일을 동시에 편집하는 일이 잦다면, 앞으로는 온라인 공동 편집이 가능한 도구(Synology Office 등)를 사용하는 것을 고려하세요."}],"deeper":[{"heading":"File Station 변경이 Drive에 안 보일 때","text":"File Station과 Synology Drive는 같은 파일을 다르게 취급할 수 있습니다. File Station에서 옮기거나 지운 파일은 Drive의 동기화 이력에 반영되기까지 시간이 걸리거나, 동기화 작업에 포함되지 않은 경로라면 아예 반영되지 않습니다."},{"heading":"Drive Client와 DSM 버전 불일치","text":"DSM의 Synology Drive Server 패키지와 PC의 Drive Client 버전 차이가 크면 동기화 오류가 발생할 수 있습니다. 둘 다 최신 버전으로 맞추는 것이 안전합니다."}],"decision":[{"heading":"동기화 작업에 폴더를 추가한 뒤 해결될 때","text":"새 폴더가 동기화 대상에서 빠져 있던 것이 원인입니다. 앞으로 공유 폴더를 새로 만들 때는 Drive 동기화 작업에도 함께 추가하는 습관을 들이세요."},{"heading":"파일 잠금 해제 후에도 계속 실패할 때","text":"Drive Client와 Drive Server 버전 불일치나 네트워크 문제일 수 있습니다. 두 버전을 모두 최신으로 업데이트한 뒤 Client를 재시작해보세요."}],"examples":["PC에서 파일을 삭제했는데 Synology Drive 웹에는 계속 남아있다","같은 파일에 (사용자이름의 conflicted copy)가 붙은 사본이 여러 개 생겼다"],"mistakes":["동기화 작업 목록에 폴더가 포함돼 있는지 확인하지 않고 무작정 재설치부터 하는 것","충돌 사본이 여러 개 쌓였는데 어느 게 최신인지 확인하지 않고 임의로 삭제하는 것"],"faq":[{"q":"File Station에서 지운 파일이 Drive에서는 왜 안 지워지나요?","a":"File Station과 Synology Drive의 동기화 대상 경로가 다르거나, 반영에 시간이 걸리는 경우입니다. 먼저 Drive Client 설정에서 해당 폴더가 동기화 작업에 포함돼 있는지 확인하세요."},{"q":"conflicted copy 파일은 지워도 되나요?","a":"최신 버전을 먼저 확인한 뒤에 지우세요. 여러 기기에서 동시에 수정된 경우 어느 쪽이 최신인지 파일을 열어 직접 비교해야 안전합니다."}]},"nas-hdd-compatibility":{"badge":"구매/호환성","subtitle":"NAS 전용 하드디스크가 아닌 일반 PC용 하드디스크를 장착해도 문제없는지, 호환성과 안정성 차이가 궁금한 경우","intro":["결론부터 말하면, NAS 전용 하드디스크가 아니어도 규격만 맞으면 대부분의 시놀로지 NAS에 장착해 쓸 수 있습니다. 다만 일반 PC용 하드디스크는 24시간 연속 가동, 여러 디스크가 동시에 도는 진동 환경, RAID 재구성 시의 높은 부하에 최적화되어 설계되지 않아, 장기적으로는 NAS 전용 하드에 비해 고장 위험이 높아질 수 있습니다.","2025년 이후 출시된 최신 모델부터는 DSM 업데이트로 하드디스크 제한 정책이 완화되어, 예전보다 훨씬 다양한 제조사·모델의 하드를 문제없이 쓸 수 있게 되었습니다. 그래도 구매 전에는 공식 호환성 목록을 확인하는 것이 안전합니다."],"warnings":["이미 있는 일반 하드디스크를 NAS에 재활용해도 되는지 궁금하다.","NAS용 하드와 일반 하드의 실제 차이가 가격만큼 있는지 궁금하다.","호환성 목록에 없는 하드디스크를 장착했더니 경고 메시지가 뜬다."],"checks":[{"title":"공식 호환성 목록 확인","why":"모델별로 지원 여부가 다르며, 목록에 없으면 일부 기능이 제한될 수 있습니다.","how":"① 웹 브라우저에서 시놀로지 공식 홈페이지에 접속해 '호환성 목록(Compatibility List)' 페이지를 찾으세요. ② 보유한 NAS의 정확한 모델명(예: DS923+)을 입력해 검색하세요. ③ 결과 목록에서 '드라이브' 또는 'HDD/SSD' 카테고리를 선택하세요. ④ 사용하려는(또는 이미 장착한) 하드디스크의 정확한 모델명을 목록에서 찾아, 지원 여부와 제한 사항(용량, RAID 유형 등)을 확인하세요."},{"title":"이미 장착한 디스크의 상태 모니터링","why":"일반 하드는 장기 안정성 데이터가 NAS용보다 적어, 상태를 더 자주 확인하는 것이 안전합니다.","how":"① DSM 시작 메뉴에서 '스토리지 관리자'를 여세요. ② 왼쪽 메뉴에서 'HDD/SSD'를 클릭하고 확인하려는 디스크를 선택하세요. ③ 'S.M.A.R.T' 탭을 클릭하고 '테스트 예약'을 클릭해 매주 또는 매월 자동으로 검사가 실행되도록 설정하세요. ④ 같은 화면에서 '재할당된 섹터 수' 항목의 값이 0에 가까운지, 시간이 지나며 계속 늘어나지는 않는지 주기적으로 확인하세요 — 값이 계속 늘어나면 디스크 교체를 준비해야 합니다."},{"title":"용도에 맞는 선택","why":"단순 백업용 보조 NAS와 24시간 가동하는 메인 NAS는 요구되는 내구성이 다릅니다.","how":"① 사용 목적을 먼저 정리해보세요 — NAS를 24시간 켜두고 여러 베이로 RAID를 구성해 쓰는지, 아니면 가끔 켜서 백업 용도로만 쓰는지가 기준입니다. ② 상시 가동하며 여러 디스크로 RAID를 구성한다면, 진동 보정 기능과 더 긴 보증을 제공하는 NAS 전용 하드디스크(시놀로지 HAT 시리즈, WD Red Plus/Pro, Seagate IronWolf 등)를 선택하는 것이 안전합니다. ③ 가끔 켜서 단순 백업용으로만 쓴다면 일반 PC용 하드디스크로도 충분한 경우가 많습니다. ④ 구매 전 위의 호환성 목록에서 해당 모델이 지원되는지 다시 한번 확인하세요."}],"deeper":[{"heading":"NAS 전용 하드(WD Red, IronWolf)가 비싼 이유","text":"NAS 전용 하드는 진동 보정 기술, 24시간 연속 가동 내구성 인증, RAID 환경에 맞춘 오류 복구 시간(TLER) 설정 등이 추가되어 있습니다. IronWolf는 자체 상태 모니터링(IHM) 기능도 제공합니다."},{"heading":"2025년 이후 모델의 정책 변화","text":"시놀로지가 일부 최신 모델부터 자사 인증 디스크로 제한하던 정책을 완화하면서, DSM 7.3 이상에서는 더 많은 제조사의 NAS용 하드를 자유롭게 쓸 수 있게 되었습니다. 다만 모델별로 적용 시점이 다르므로 구매 전 확인이 필요합니다."}],"decision":[{"heading":"여유 있는 예산으로 새로 구매한다면","text":"장기 가동을 계획한다면 처음부터 NAS 전용 하드를 선택하는 것이 이후 고장·데이터 손실 위험을 줄이는 길입니다."},{"heading":"이미 있는 일반 하드를 재활용하고 싶다면","text":"당장 문제가 없다면 계속 써도 되지만, S.M.A.R.T 상태를 더 자주 확인하고 중요한 데이터는 반드시 별도로 백업하세요."}],"examples":["예전에 PC에서 쓰던 하드디스크를 NAS에 재활용해도 되는지 궁금하다","호환성 목록에 없는 하드디스크를 장착했더니 DSM에서 경고 메시지가 뜬다"],"mistakes":["가격만 보고 무조건 저렴한 일반 하드를 사서 24시간 가동 RAID에 바로 쓰는 것","호환성 목록을 확인하지 않고 구매한 뒤 인식 문제를 NAS 고장으로 오해하는 것"],"faq":[{"q":"일반 하드디스크를 쓰면 NAS가 고장 나나요?","a":"바로 고장 나지는 않습니다. 다만 24시간 연속 가동이나 다중 베이 RAID 환경에서는 NAS 전용 하드보다 장기 고장률이 높아질 수 있어, 중요한 데이터라면 정기 백업과 S.M.A.R.T 모니터링을 더 신경 써야 합니다."},{"q":"WD Red와 IronWolf 중 뭐가 더 좋나요?","a":"둘 다 NAS 전용 하드로 기본 성능은 비슷합니다. IronWolf는 자체 상태 모니터링(IHM) 기능이 추가로 제공되는 정도의 차이가 있어, 취향이나 가격에 따라 선택하면 됩니다."}]},"nas-shared-folder-permission":{"badge":"계정/권한","subtitle":"일부 계정이나 PC에서만 공유폴더 접근이 안 되거나, 상위 폴더는 보이는데 하위 폴더는 열리지 않는 경우","intro":["NAS를 처음 설정할 때 가장 흔히 헷갈리는 부분이 권한 구조입니다. 공유폴더 자체의 권한과 그 안의 하위 폴더 권한이 따로 관리되고, 사용자와 그룹의 권한이 겹칠 때는 \"가장 제한적인 쪽\"이 최종 적용됩니다. 이 구조를 모르면 \"권한을 줬는데도 왜 안 되지\" 하는 혼란이 반복됩니다.","특정 PC에서만 안 되는지, 특정 계정으로 로그인했을 때만 안 되는지부터 구분하면 권한 문제인지 다른 원인(자격 증명 캐시 등)인지 빠르게 좁힐 수 있습니다."],"warnings":["특정 계정으로 접속하면 공유폴더 자체가 안 보이거나 열리지 않는다.","상위 폴더는 보이는데 그 안의 특정 하위 폴더만 접근이 안 된다.","권한을 준 것 같은데도 여전히 읽기만 되고 쓰기가 안 된다."],"checks":[{"title":"공유폴더 자체 권한 확인","why":"폴더 목록에 아예 안 보인다면 최상위 공유폴더 권한부터 막혀 있는 것입니다.","how":"① DSM에 관리자 계정으로 로그인하세요. ② 제어판 → '공유 폴더'를 클릭하세요. ③ 문제가 되는 폴더를 선택하고 '편집' 버튼을 클릭하세요. ④ '권한' 탭을 클릭하세요. ⑤ 상단에서 '사용자' 또는 '그룹'을 선택한 뒤, 문제를 겪는 계정을 찾아 권한이 '읽기/쓰기', '읽기 전용' 중 하나로 설정되어 있는지, 혹시 '거부'로 되어 있지는 않은지 확인하세요. ⑥ 필요한 권한으로 바꾸고 저장한 뒤 해당 계정으로 다시 접속을 시도해보세요."},{"title":"하위 폴더 개별 권한 확인","why":"상위 폴더는 열리는데 특정 하위 폴더만 안 된다면 그 폴더에 별도 권한이 걸려 있을 가능성이 큽니다.","how":"① DSM에서 'File Station'을 여세요. ② 문제가 있는 하위 폴더까지 이동한 뒤 폴더를 마우스 오른쪽 버튼으로 클릭해 '속성'을 선택하세요. ③ '권한' 탭을 클릭하세요. ④ 상위 폴더와 다른 권한이 별도로 설정되어 있지 않은지 확인하세요 — 하위 폴더는 상위 폴더 권한을 그대로 물려받거나, 별도로 재정의될 수 있습니다. ⑤ 필요한 사용자·그룹에 알맞은 권한을 추가하고 저장하세요."},{"title":"그룹 간 권한 충돌 확인","why":"한 사용자가 여러 그룹에 속해 있으면 그룹마다 다른 권한이 동시에 적용되어 예상과 다르게 동작할 수 있습니다.","how":"① 제어판 → '사용자 및 그룹'을 클릭하세요. ② 문제를 겪는 계정을 더블클릭해 속성을 여세요. ③ '그룹' 탭을 클릭해 이 계정이 소속된 모든 그룹 이름을 확인하세요. ④ 각 그룹을 하나씩 클릭해 '권한' 탭에서 해당 공유 폴더에 대해 어떤 권한이 설정되어 있는지 비교하세요 — 한 그룹은 '읽기/쓰기'인데 다른 그룹은 '거부'로 되어 있으면 '거부'가 우선 적용되어 접근이 막힙니다. ⑤ 충돌하는 그룹 설정을 찾았다면 불필요한 '거부' 설정을 해제하거나, 해당 계정을 문제되는 그룹에서 제외하세요."},{"title":"'접근 거부' 기본값 확인","why":"명시적으로 권한을 주지 않은 사용자는 기본적으로 접근이 거부됩니다.","how":"① 제어판 → '사용자 및 그룹'에서 새로 만든 계정을 확인하세요. ② 계정을 더블클릭해 '권한' 탭으로 들어가세요(또는 위의 '공유 폴더 자체 권한 확인' 항목처럼 폴더 쪽에서 접근할 수도 있습니다). ③ 새 계정은 기본적으로 아무 폴더에도 접근 권한이 없는 상태이므로, 필요한 각 공유 폴더마다 '읽기/쓰기' 또는 '읽기 전용' 권한을 직접 체크해 부여해야 합니다. ④ 권한을 부여한 뒤 저장하고, 해당 계정으로 로그인해 폴더가 정상적으로 보이는지 확인하세요."}],"deeper":[{"heading":"권한 우선순위: 가장 제한적인 쪽이 이긴다","text":"시놀로지 DSM은 한 사용자가 여러 그룹에 속해 서로 다른 권한을 받을 경우, 그중 가장 제한적인 권한(예: 거부)을 최종적으로 적용합니다. 특정 그룹에서만 '거부'로 설정했다면 다른 그룹에서 '읽기/쓰기'를 줘도 결과적으로 접근이 막힙니다."},{"heading":"하위 폴더 숨기기 옵션","text":"제어판 → 공유 폴더에서 '권한 없는 사용자에게 하위 폴더 및 파일 숨기기' 옵션을 켜면, 권한이 없는 사용자에게는 애초에 폴더 목록 자체가 보이지 않아 혼란을 줄일 수 있습니다."}],"decision":[{"heading":"특정 계정만 안 될 때","text":"그 계정이 속한 그룹의 권한을 확인하세요. 다른 그룹에 '거부'가 걸려 있으면 그 계정에는 아무리 개별 권한을 줘도 소용없습니다."},{"heading":"특정 하위 폴더만 안 될 때","text":"상위 폴더 권한이 아니라 그 하위 폴더 자체에 별도로 걸린 권한을 확인하세요."}],"examples":["관리자 계정으로는 보이는데 새로 만든 직원 계정으로는 공유폴더가 아예 안 보인다","상위 폴더는 열리는데 그 안의 '기밀' 하위 폴더만 접근이 거부된다"],"mistakes":["그룹 권한 충돌을 모르고 개별 계정 권한만 계속 수정하는 것","'접근 거부'가 기본값이라는 것을 모르고 새 계정에 권한을 아예 부여하지 않는 것"],"faq":[{"q":"권한을 분명히 줬는데도 왜 접근이 안 되나요?","a":"그 계정이 속한 다른 그룹에 '거부' 권한이 걸려 있을 수 있습니다. 시놀로지는 여러 권한이 충돌할 때 가장 제한적인 쪽을 우선 적용하므로, 소속된 모든 그룹의 권한을 함께 확인해야 합니다."},{"q":"하위 폴더마다 권한을 따로 설정할 수 있나요?","a":"네. File Station에서 개별 폴더의 속성 → 권한에서 상위 폴더와 별개로 설정할 수 있습니다. 상위 폴더 권한과 하위 폴더 권한이 다르면 더 구체적으로 설정된 하위 폴더 권한이 적용됩니다."}]},"nas-hyper-backup-fail":{"badge":"백업","subtitle":"Hyper Backup으로 예약한 백업이 실패하거나, 작업 상태가 '복원 전용'으로 바뀌어 더 이상 백업이 진행되지 않는 경우","intro":["Hyper Backup은 한 번 설정해두면 알아서 예약 실행되기 때문에, 오히려 오랫동안 방치하다가 실제로 필요한 순간에야 '몇 년째 백업이 안 되고 있었다'는 것을 뒤늦게 발견하는 사례가 흔합니다. 정기적으로 작업 상태를 확인하는 습관이 무엇보다 중요합니다.","실패 상태와 '복원 전용' 상태는 원인이 다릅니다. 실패는 대개 공간·연결 문제로 재시도하면 해결되지만, '복원 전용'은 원본과 백업본의 구조가 어긋나 더 이상 새 백업을 추가할 수 없는 상태로, 새 작업을 다시 만들어야 합니다."],"warnings":["백업 작업 목록에서 상태가 실패(빨간색)로 계속 표시된다.","작업 상태가 '복원 전용(Restore Only)'으로 바뀌어 있다.","알림을 꺼두거나 확인하지 않아 백업이 오랫동안 중단된 걸 몰랐다."],"checks":[{"title":"백업 대상 여유 공간 확인","why":"대상 볼륨·디스크의 용량이 부족하면 백업이 중단됩니다.","how":"① DSM에서 'Hyper Backup' 앱을 여세요. ② 실패한 백업 작업을 클릭하고 백업 대상(외장하드, 원격 NAS, 클라우드 등)이 무엇인지 확인하세요. ③ 대상이 외장하드나 다른 NAS라면 해당 장치의 스토리지 관리자나 '이 PC'에서 여유 공간을 확인하세요. ④ 공간이 부족하다면 Hyper Backup 작업의 '백업 버전 관리' 설정에서 오래된 백업 버전을 수동으로 삭제하거나, 자동 정리 정책(예: 최근 10개만 보관)을 설정하세요. ⑤ 공간을 확보한 뒤 백업 작업을 다시 실행해보세요."},{"title":"실패 로그 확인","why":"정확한 실패 원인(연결 끊김, 권한 오류, 파일 잠김 등)을 알아야 원인에 맞게 대응할 수 있습니다.","how":"① DSM에서 'Hyper Backup' 앱을 여세요. ② 실패한 백업 작업을 선택하세요. ③ 하단 또는 오른쪽의 '로그' 탭을 클릭하세요. ④ 가장 최근 실패 기록을 클릭해 상세 메시지(연결 끊김, 권한 오류, 파일 잠김 등)를 확인하세요. ⑤ 표시된 메시지에 따라 알맞은 항목(아래 여유 공간, 복원 전용 상태 등)을 진행하세요."},{"title":"'복원 전용' 상태 확인 및 재구성","why":"이 상태에서는 기존 작업으로 새 백업을 추가할 수 없습니다.","how":"① Hyper Backup에서 문제가 있는 작업을 클릭했을 때 상태가 '복원 전용(Restore only)'으로 표시되는지 확인하세요. ② 이 상태는 보통 백업 대상 저장소의 데이터 구조가 손상되었거나 호환되지 않을 때 나타나며, 기존 작업으로는 더 이상 새 백업을 추가할 수 없습니다. ③ 기존 작업은 삭제하지 말고 남겨두세요 — 과거에 백업된 데이터를 복원할 때 필요합니다. ④ Hyper Backup에서 '+' 버튼을 눌러 새 백업 작업을 처음부터 다시 생성하고, 백업 대상과 일정을 새로 설정하세요."},{"title":"백업 알림 설정 확인","why":"알림이 꺼져 있으면 백업이 실패해도 알아채지 못한 채 오랫동안 방치될 수 있습니다.","how":"① DSM에서 제어판 → '알림'을 클릭하세요. ② '이메일' 탭에서 알림을 받을 이메일 주소를 입력하고 '활성화'에 체크하세요. ③ 'DSM 알림 규칙' 또는 유사한 항목에서 'Hyper Backup' 관련 항목을 찾아 '백업 실패' 알림에 체크하세요. ④ 스마트폰에 시놀로지 DS finder 앱을 설치해두면 푸시 알림으로도 받을 수 있습니다 — 앱 설정에서 알림 권한을 허용하세요. ⑤ 설정 후 테스트 알림을 보내 정상적으로 수신되는지 확인하세요."}],"deeper":[{"heading":"'복원 전용' 상태가 생기는 이유","text":"백업 작업을 오래 방치하거나 원본 볼륨을 재구성·재설치하면 백업본의 증분 체인이 원본과 어긋나게 됩니다. 이 경우 시놀로지는 데이터 손실을 막기 위해 해당 작업을 복원 전용으로 전환하고, 더 이상 그 작업으로는 새 백업을 쌓지 못하게 합니다."},{"heading":"백업이 '되고 있는 줄 알았던' 사고를 막는 법","text":"백업은 설정하는 것보다 '되고 있는지 주기적으로 확인하는 것'이 더 중요합니다. 알림을 켜두고, 분기에 한 번 정도는 실제로 복원 테스트를 해보는 것이 안전합니다."}],"decision":[{"heading":"용량 확보 후 정상화될 때","text":"저장 공간 부족이 원인이었던 것입니다. 앞으로는 백업 대상 용량에 여유를 두고, 보관 버전 수를 정책으로 관리하세요."},{"heading":"'복원 전용' 상태일 때","text":"기존 작업 수정으로는 해결되지 않습니다. 기존 백업은 복원용으로 보관하고, 새 백업 작업을 만들어 처음부터 다시 시작하세요."}],"examples":["몇 년 전에 설정해둔 백업이 실제로는 오래전부터 실패 상태였다","백업 작업 상태가 '복원 전용'으로 바뀌어 더 이상 새로 백업되지 않는다"],"mistakes":["백업을 설정만 해두고 알림 없이 방치해 실패를 뒤늦게 발견하는 것","'복원 전용' 상태에서 기존 작업을 억지로 수정하려고 시간을 쓰는 것(새 작업 생성이 공식 권장 절차)"],"faq":[{"q":"몇 년간 백업이 안 되고 있었다는 걸 뒤늦게 알았어요. 지금이라도 고칠 수 있나요?","a":"가능합니다. 먼저 실패 로그로 원인을 확인하고, 용량·연결 문제를 해결한 뒤에도 계속 실패하거나 '복원 전용' 상태라면 새 백업 작업을 다시 만드는 것이 가장 확실합니다. 이후에는 알림을 켜서 같은 일이 반복되지 않게 하세요."},{"q":"'복원 전용' 상태인 작업은 그냥 삭제해도 되나요?","a":"기존 백업 데이터로 복원할 계획이 없다면 삭제해도 됩니다. 다만 과거 데이터가 필요할 수 있다면 삭제하지 말고 복원 전용으로 남겨둔 채, 새 백업 작업을 별도로 만드세요."}]}}});
